Object.assign(window.TEM8_DICTIONARY, {"grubby":{"oxford":{"phon":"ˈɡrʌbi","pos":"adjective","senses":[{"en":"rather dirty, usually because it has not been washed or cleaned","cn":"肮脏的；邋遢的；污秽的","ex":{"en":"grubby hands/clothes","cn":"脏手；脏衣服"}},{"en":"unpleasant because it involves activities that are not honest or moral","cn":"卑鄙的；可鄙的","ex":{"en":"a grubby scandal","cn":"丑闻"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"肮脏的；污秽的","en":"A grubby person or object is rather dirty.","ex":{"en":"His white coat was grubby and stained.","cn":"他的白色外套污迹斑斑，简直脏透了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"卑鄙的；可鄙的","en":"If you call an activity or someone's behaviour grubby, you mean that it is not completely honest or respectable.","ex":{"en":"...the grubby business of politics.","cn":"肮脏的政治活动"}}]},"media":{"uk":"media/uk/grubby__gb_1.mp3","us":"media/us/grubby__us_1.mp3"},"examples":[{"en":"grubby hands/clothes","cn":"脏手/衣服"},{"en":"a grubby scandal","cn":"丑闻"}]},"glory":{"media":{"uk":"media/uk/glory__gb_1.mp3","us":"media/us/glory__us_1.mp3"},"oxford":{"phon":"ˈɡlɔːri","pos":"noun","senses":[{"en":"great success that brings somebody praise and honour and makes them famous","cn":"荣誉；光荣；桂冠","g":"[uncountable]","ex":{"en":"Olympic glory in the 100 metres","cn":"奥林匹克 100 米赛跑的桂冠"}},{"en":"praise and worship of God","cn":"（对上帝的）赞颂，赞美，崇拜","g":"[uncountable]","ex":{"en":"‘Glory to God in the highest’","cn":"“荣耀归于至高无上的上帝”"}},{"en":"great beauty","cn":"壮丽；辉煌；灿烂","g":"[uncountable]","ex":{"en":"The city was spread out beneath us in all its glory.","cn":"这座城市绚丽多彩地展现在我们下方。"}},{"en":"something that is beautiful, impressive, or deserves praise","cn":"优美之物；骄人之处","g":"[countable]","ex":{"en":"The temple is one of the glories of ancient Greece.","cn":"这座神殿是古希腊的一大骄傲。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"光荣；荣耀","en":"Glory is the fame and admiration that you gain by doing something impressive.","ex":{"en":"Walsham had his moment of glory when he won a 20km race.","cn":"沃尔沙姆夺得20公里比赛冠军的那一刻无比荣耀。"}},{"pos":"N-PLURAL 复数名词","cn":"辉煌时刻；巅峰","en":"A person's glories are the occasions when they have done something people greatly admire which makes them famous.","ex":{"en":"The album sees them reliving past glories but not really breaking any new ground.","cn":"这张专辑使他们重温了昔日的辉煌，但实际上没有任何新的突破。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"壮丽；壮观","en":"The glory of something is its great beauty or impressive nature.","ex":{"en":"The glory of the idea blossomed in his mind.","cn":"在他的脑海中这一想法变得越来越宏大。"}},{"pos":"N-COUNT 可数名词","cn":"引以为荣的事物","en":"The glories of a culture or place are the things that people admire most about it.","ex":{"en":"...a tour of Florence, to enjoy the artistic glories of the Italian Renaissance","cn":"领略意大利文艺复兴时期伟大艺术成就的佛罗伦萨之旅"}},{"pos":"VERB 动词","cn":"因…而欣喜；为…而喜悦","en":"If you glory in a situation or activity, you enjoy it very much.","ex":{"en":"The workers were glorying in their new-found freedom","cn":"工人们因才获得的自由而无比喜悦。"}},{"pos":"PHRASE 短语","cn":"一举成名","en":"If you go out in a blaze of glory, you do something very dramatic at the end of your career or your life which makes you famous.","ex":{"en":"I am never going back to prison. I am going to make national news headlines and go out in a blaze of glory.","cn":"我将永远告别监狱，我会成为全国报纸的头条新闻，从此扬名天下。"}}]},"examples":[{"en":"The city was spread out beneath us in all its glory.","cn":"这座城市绚丽多彩地展现在我们下方。"},{"en":"Olympic glory in the 100 metres","cn":"奥林匹克 100 米赛跑的桂冠"}]},"gratify":{"media":{"uk":"media/uk/gratify__gb_1.mp3","us":"media/us/gratify__us_1.mp3"},"oxford":{"phon":"ˈɡrætɪfaɪ","pos":"verb","senses":[{"en":"to please or satisfy somebody","cn":"使高兴；使满意","lab":"formal","ex":{"en":"It gratified him to think that it was all his work.","cn":"他想到这都是他的工作成果，感到十分欣慰。"}},{"en":"to satisfy a wish, need, etc.","cn":"满足（愿望、需要等）","lab":"formal","ex":{"en":"He only gave his consent in order to gratify her wishes.","cn":"他只是为满足她的愿望才同意的。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使高兴；令人满意","en":"If you are gratified by something, it gives you pleasure or satisfaction.","ex":{"en":"Mr. Dambar was gratified by his response.","cn":"丹巴尔先生对他的回答感到满意。"}},{"pos":"VERB 动词","cn":"满足（愿望等）","en":"If you gratify your own or another person's desire, you do what is necessary to please yourself or them.","ex":{"en":"We gratified our friend's curiosity","cn":"我们满足了朋友的好奇心。"}}]},"examples":[{"en":"It gratified him to think that it was all his work.","cn":"他想到这都是他的工作成果，感到十分欣慰。"},{"en":"She was gratified to find that they had followed her advice.","cn":"她看到他们听从了自己的建议，感到很欣慰。"}]},"gestures":{"lemma":"gesture","media":{"uk":"media/uk/gesture__gb_1.mp3","us":"media/us/gesture__us_1.mp3"}},"goats":{"lemma":"goat","media":{"uk":"media/uk/goat__gb_1.mp3","us":"media/us/goat__us_1.mp3"}},"guest":{"media":{"uk":"media/uk/guest__gb_1.mp3","us":"media/us/guest__us_1.mp3"},"oxford":{"phon":"ɡest","pos":"noun","senses":[{"en":"a person that you have invited to your house or to a particular event that you are paying for","cn":"客人；宾客","ex":{"en":"They only use the dining room when they have guests.","cn":"他们只在有客人时才使用餐厅。"}},{"en":"a person who is staying at a hotel, etc.","cn":"旅客；房客","ex":{"en":"We have accommodation for 500 guests.","cn":"我们有可供 500 位客人住宿的房间。"}},{"en":"a customer in a restaurant","cn":"（餐馆的）客人；食客","lab":"especially North American English","ex":{"en":"Restaurant guests can enjoy superb views across the bay as they dine.","cn":"餐厅的客人可以在用餐时欣赏海湾的壮丽景色。"}},{"en":"a famous person or performer who takes part in a television show, concert or other entertainment","cn":"特别嘉宾；客串演员","ex":{"en":"a guest star/artist","cn":"嘉宾明星／艺术家"}},{"en":"a person who is invited to a particular place or organization, or to speak at a meeting","cn":"特邀嘉宾","ex":{"en":"a guest speaker","cn":"特邀演讲人"}},{"en":"to take part in a television or radio show, a concert, a game, etc. as a visiting or temporary performer or player","cn":"做特邀嘉宾；做客串；做特约演员","ex":{"en":"She guested on several chat shows while visiting Britain.","cn":"她访问英国时做过几个访谈节目的特邀嘉宾。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"客人；宾客","en":"A guest is someone who is visiting you or is at an event because you have invited them.","ex":{"en":"She was a guest at the wedding","cn":"她是参加婚礼的客人。"}},{"pos":"N-COUNT 可数名词","cn":"特邀嘉宾；客串演员","en":"A guest is someone who visits a place or organization or appears on a radio or television show because they have been invited to do so.","ex":{"en":"...a frequent chat show guest","cn":"经常出现在访谈节目中的特邀嘉宾"}},{"pos":"N-COUNT 可数名词","cn":"（旅馆的）客人，房客","en":"A guest is someone who is staying in a hotel. →see usage note at:","ex":{"en":"I was the only hotel guest","cn":"我是宾馆里唯一的住客。"}},{"pos":"VERB 动词","cn":"做特邀嘉宾；做特邀演员；客串","en":"To guest means to take part in a performance or a match as a guest, rather than as a regular member.","ex":{"en":"He guested for one or two League sides","cn":"他在一两支联赛队伍中做过外援。"}},{"pos":"CONVENTION 惯用语","cn":"请便；随便","en":"If you say be my guest to someone, you are giving them permission to do something.","ex":{"en":"If anybody wants to work on this, be my guest.","cn":"如果哪位想干这个，请便。"}}]},"examples":[{"en":"Guests should vacate their rooms by 10.30 a.m.","cn":"旅客应在上午 10:30 以前腾出房间。"},{"en":"She guested on several chat shows while visiting Britain.","cn":"她访问英国时做过几个访谈节目的特邀嘉宾。"}]},"guided":{"media":{"uk":"media/uk/guided__gb_1.mp3","us":"media/us/guided__us_1.mp3"},"oxford":{"phon":"ˈɡaɪdɪd","pos":"adjective","senses":[{"en":"that is led by somebody who works as a guide","cn":"有指导的；有向导的；有导游的","ex":{"en":"a guided tour/walk","cn":"有导游的观光／步行观光"}}]},"examples":[{"en":"a guided tour/walk","cn":"有导游的观光/步行观光"}],"base":"guide"},"greet":{"media":{"uk":"media/uk/greet__gb_1.mp3","us":"media/us/greet__us_1.mp3"},"oxford":{"phon":"ɡriːt","pos":"verb","senses":[{"en":"to say hello to somebody or to welcome them","cn":"和（某人）打招呼（或问好）；欢迎；迎接","ex":{"en":"He greeted all the guests warmly as they arrived.","cn":"客人到达时他都热情接待。"}},{"en":"to react to somebody/something in a particular way","cn":"（以某种方式）对…作出反应","g":"[often passive]","ex":{"en":"Loud cheers greeted the news.","cn":"这消息受到热烈欢呼。"}},{"en":"to be the first thing that you see, hear or smell at a particular time","cn":"映入…的眼帘；传入…的耳中（或鼻中）","g":"[usually passive]","ex":{"en":"When she opened the door she was greeted by a scene of utter confusion.","cn":"她打开门，一片混乱不堪的景象呈现在她的眼前。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"同…打招呼;向…问好；欢迎；迎接","en":"When you greet someone, you say 'Hello' or shake hands with them.","ex":{"en":"She liked to be home to greet Steve when he came in from school.","cn":"她喜欢呆在家里迎接放学回家的史蒂夫。"}},{"pos":"VERB 动词","cn":"对…作出反应；回应","en":"If something is greeted in a particular way, people react to it in that way.","ex":{"en":"The European Court's decision has been greeted with dismay by fishermen","cn":"渔民对欧洲法庭的裁决感到失望。"}},{"pos":"VERB 动词","cn":"呈现在…面前；映入…眼帘；最先被…感觉到","en":"If you are greeted by something, it is the first thing you notice in a particular place.","ex":{"en":"I was greeted by a shocking sight","cn":"一幅令人震惊的画面映入我的眼帘。"}}]},"examples":[{"en":"When she opened the door she was greeted by a scene of utter confusion.","cn":"她打开门，一片混乱不堪的景象呈现在她的眼前。"},{"en":"The team's win was greeted as a major triumph.","cn":"这个队获胜被看成是一个重大的胜利。"}]},"glad":{"media":{"uk":"media/uk/glad__gb_1.mp3","us":"media/us/glad__us_1.mp3"},"oxford":{"phon":"ɡlæd","pos":"adjective","senses":[{"en":"pleased; happy","cn":"高兴；愉快","g":"[not before noun]","ex":{"en":"‘I passed the test!’ ‘I’m so glad.’","cn":"“我考试通过了！”“我太高兴了。”"}},{"en":"grateful for something","cn":"感激；感谢","ex":{"en":"She was very glad of her warm coat in the biting wind.","cn":"在刺骨的寒风中她有温暖的大衣真是谢天谢地。"}},{"en":"very willing to do something","cn":"乐意；情愿；愿意","ex":{"en":"I'd be glad to lend you the money.","cn":"我很乐意借给你钱。"}},{"en":"bringing joy; full of joy","cn":"令人愉快的；使人高兴的；充满欢乐的","g":"[only before noun]","lab":"old-fashioned","ex":{"en":"glad tidings","cn":"喜讯"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"高兴的；愉快的","en":"If you are glad about something, you are happy and pleased about it.","ex":{"en":"I'm glad I relented in the end","cn":"我很高兴自己的态度最终缓和了下来。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"乐意的；非常愿意的","en":"If you say that you will be glad to do something, usually for someone else, you mean that you are willing and eager to do it.","ex":{"en":"I'll be glad to show you everything","cn":"我将很乐意向你们展示一切。"}},{"pos":"PHRASE 短语","cn":"好消息","en":"Glad tidings means good news.","ex":{"en":"...the bringer of glad tidings.","cn":"报喜讯的人"}}]},"examples":[{"en":"‘He doesn't need the pills any more.’ ‘I'm glad about that.’ “","cn":"他不再需要服那些药片了。” “这真让我高兴。”"},{"en":"She was very glad of her warm coat in the biting wind.","cn":"在刺骨的寒风中她有暖融融的大衣真是谢天谢地。"}]},"grey-haired":{"oxford":{"phon":"ˌɡreɪ ˈheəd","pos":"adjective","senses":[{"en":"with grey hair","cn":"头发灰白的；头发花白的"}]},"media":{"uk":"media/uk/grey_haired_1_gb_1.mp3","us":"media/us/grey_haired_1_us_1.mp3"}},"globally":{"oxford":{"phon":"ˈɡləʊbəli","pos":"adverb","senses":[{"en":"in a way that covers or affects the whole world","cn":"全球的；全世界的","ex":{"en":"We need to start thinking globally.","cn":"我们需要开始从全球视角考虑问题。"}},{"en":"in a way that considers or includes all parts of something","cn":"整体的；全面的；总括的","ex":{"en":"It is important to approach the problem globally.","cn":"从全球范围内解决这个问题非常重要。"}},{"en":"in a way that operates or applies through the whole of a file, program, etc.","cn":"全局的：以在整个文件，程序等中运行或应用的方式","lab":"computing","ex":{"en":"The processing can be applied globally to all digital output signals.","cn":"该处理可以全局应用于所有数字输出信号。"}}]},"media":{"uk":"media/uk/globally__gb_1.mp3","us":"media/us/globally__us_1.mp3"},"examples":[{"en":"We need to start thinking globally.","cn":"我们需着手全面考虑。"},{"en":"We are taking a global view of our business.","cn":""}]},"give":{"media":{"uk":"media/uk/give__gb_1.mp3","us":"media/us/give__us_1.mp3"},"oxford":{"phon":"ɡɪv","pos":"verb","senses":[{"en":"to hand something to somebody so that they can look at it, use it or keep it for a time","cn":"给；交给","g":"[transitive]","sc":"hand/provide","ex":{"en":"Give the letter to your mother when you've read it.","cn":"信看完后交给你母亲。"}},{"en":"to hand something to somebody as a present; to allow somebody to have something as a present","cn":"赠送；赠予；送给","g":"[transitive, intransitive]","sc":"hand/provide","ex":{"en":"What are you giving your father for his birthday?","cn":"你打算送给你父亲什么生日礼物？"}},{"en":"to provide somebody with something","cn":"（为某人）提供，供给，供应","g":"[transitive]","sc":"hand/provide","ex":{"en":"They were all thirsty so I gave them a drink.","cn":"他们都口渴了，所以我给了他们一杯饮料。"}},{"en":"to pay money to a charity, etc., to help people","cn":"捐助；捐赠；捐款","g":"[intransitive, transitive]","sc":"money","ex":{"en":"We need your help—please give generously.","cn":"我们需要您的帮助，请慷慨解囊吧。"}},{"en":"to pay in order to have or do something","cn":"（为获得某物或做某事而）支付，付款","g":"[transitive]","sc":"money","ex":{"en":"I'll give you £100 and not a penny more!","cn":"我会给你 100 英镑，一分钱也不多给！"}},{"en":"used with a noun to describe a particular action, giving the same meaning as the related verb","cn":"（与名词连用描述某一动作，意义与该名词相应的动词相同）","g":"[transitive]","sc":"do/produce something","ex":{"en":"She gave a shrug of her shoulders (= shrugged).","cn":"她耸了耸肩。"}},{"en":"to produce a particular feeling in somebody","cn":"使产生（某种感觉）","g":"[transitive]","sc":"do/produce something","ex":{"en":"All that driving has given me a headache.","cn":"这一路开车让我头都痛了。"}},{"en":"to make a phone call to somebody","cn":"给（某人）打（电话）","g":"[transitive]","lab":"British English","sc":"telephone call","ex":{"en":"Give me a call tomorrow.","cn":"明天给我打个电话。"}},{"en":"to judge somebody/something to be of a particular standard","cn":"给…评定（等级）","g":"[transitive]","sc":"mark/grade","ex":{"en":"She had given the assignment an A.","cn":"她给这份作业打了个优。"}},{"en":"to pass an illness onto somebody and make them ill","cn":"传染（疾病）给某人","g":"[transitive]","sc":"illness","ex":{"en":"You've given me your cold.","cn":"你把感冒传染给我了。"}},{"en":"to make somebody suffer a particular punishment","cn":"使受…惩罚","g":"[transitive]","sc":"punishment","ex":{"en":"The judge gave him a nine-month suspended sentence.","cn":"法官判处他有期徒刑九个月，缓期执行。"}},{"en":"if you give a party, you organize it and invite people","cn":"举办；举行","g":"[transitive]","sc":"party/event","ex":{"en":"We're giving a party to celebrate our silver wedding.","cn":"我们要举办一个聚会来庆祝我们的银婚。"}},{"en":"to perform something in public","cn":"表演；公开进行","g":"[transitive]","sc":"party/event","ex":{"en":"He gave a rousing performance of the Bob Marley song.","cn":"他表演了鲍勃·马利的一首歌，非常振奋人心。"}},{"en":"to use time, energy, etc. for somebody/something","cn":"将（时间、精力等）用于","g":"[transitive]","sc":"treat as important","ex":{"en":"I gave the matter a lot of thought.","cn":"我反复思考过这个问题。"}},{"en":"to predict that something will last a particular length of time","cn":"预计将持续（…时间）","g":"[transitive]","sc":"predict how long","ex":{"en":"That marriage won't last. I'll give them two years at the outside.","cn":"那桩婚姻不会持久，我看最多两年。"}},{"en":"to say that a player or the ball is in a particular position or that a goal has been scored","cn":"裁定（球员或球的位置）；判定（得分）","g":"[transitive]","sc":"in sport","ex":{"en":"The umpire gave the ball out.","cn":"裁判员判球出界。"}},{"en":"to bend or stretch under pressure","cn":"（在压力下）弯曲，伸长","g":"[intransitive]","lab":"figurative","sc":"bend","ex":{"en":"The branch began to give under his weight.","cn":"他身体的重量把树枝都压弯了。"}},{"en":"to agree to change your mind or give up some of your demands","cn":"让步；妥协","g":"[intransitive]","sc":"bend","ex":{"en":"You're going to have to give a little.","cn":"你可能非得稍做让步不可。"}},{"en":"the ability of something to bend or stretch under pressure","cn":"伸展性；弹性","ex":{"en":"The shoes may seem tight at first, but the leather has plenty of give in it.","cn":"这鞋刚开始穿时可能显得紧，但皮子的伸展性很好。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（与表示身体动作的名词连用，表示该动作）","en":"You can use give with nouns that refer to physical actions. The whole expression refers to the performing of the action. For example, She gave a smile means almost the same as 'She smiled'.","ex":{"en":"She stretched her arms out and gave a great yawn","cn":"她伸了个懒腰，打了个大哈欠。"}},{"pos":"VERB 动词","cn":"为…做；提供","en":"You use give to say that a person does something for another person. For example, if you give someone a lift, you take them somewhere in your car.","ex":{"en":"I gave her a lift back out to her house","cn":"我让她搭我的便车回家。"}},{"pos":"VERB 动词","cn":"（与表示信息、意见、问候等的名词连用）提供，给出，传递，告诉","en":"You use give with nouns that refer to information, opinions, or greetings to indicate that something is communicated. For example, if you give someone some news, you tell it to them.","ex":{"en":"He gave no details","cn":"他未透露细节。"}},{"pos":"VERB 动词","cn":"预计将（持续或达到…）","en":"You use give to say how long you think something will last or how much you think something will be.","ex":{"en":"A BBC poll gave the Labour Party a 12 per cent lead","cn":"英国广播公司的一项民意调查预计工党将领先12个百分点。"}},{"pos":"VERB 动词","cn":"毫不在乎","en":"People use give in expressions such as I don't give a damn to show that they do not care about something.","ex":{"en":"They don't give a damn about the country.","cn":"他们对这个国家毫不关心。"}},{"pos":"VERB 动词","cn":"使产生（某种想法或印象）","en":"If someone or something gives you a particular idea or impression, it causes you to have that idea or impression.","ex":{"en":"They gave me the impression that they were doing exactly what they wanted in life","cn":"他们给我的印象是，他们正在做自己人生中想做的事情。"}},{"pos":"VERB 动词","cn":"使身体感到…；使产生（某种情绪）","en":"If someone or something gives you a particular physical or emotional feeling, it makes you experience it.","ex":{"en":"He gave me a shock","cn":"他使我大吃一惊。"}},{"pos":"VERB 动词","cn":"作（表演或演说）","en":"If you give a performance or speech, you perform or speak in public.","ex":{"en":"Kotto gives a stupendous performance","cn":"科托的表演令人惊叹。"}},{"pos":"VERB 动词","cn":"给予，予以（考虑或关注）","en":"If you give something thought or attention, you think about it, concentrate on it, or deal with it.","ex":{"en":"I've been giving it some thought","cn":"这件事我已经考虑了一阵子。"}},{"pos":"VERB 动词","cn":"举办（聚会等）","en":"If you give a party or other social event, you organize it.","ex":{"en":"That evening, I gave a dinner party for a few close friends.","cn":"那天晚上，我设宴招待几位好朋友。"}},{"pos":"VERB 动词","cn":"提供；给予","en":"If you give someone something that you own or have bought, you provide them with it, so that they have it or can use it.","ex":{"en":"They gave us T-shirts and stickers","cn":"他们为我们提供了T恤衫和贴纸。"}},{"pos":"VERB 动词","cn":"递给；传给","en":"If you give someone something that you are holding or that is near you, you pass it to them, so that they are then holding it.","ex":{"en":"Give me that pencil","cn":"把那支铅笔递给我。"}},{"pos":"VERB 动词","cn":"赋予（权力或权利）","en":"To give someone or something a particular power or right means to allow them to have it.","ex":{"en":"...a citizen's charter giving rights to gays","cn":"赋予同性恋者权利的公民宪章"}},{"pos":"VERB 动词","cn":"坍塌；断裂；支撑不住","en":"If something gives, it collapses or breaks under pressure.","ex":{"en":"My knees gave under me.","cn":"我两腿发软。"}},{"pos":"V-PASSIVE 被动动词","cn":"使（理解）；使（知道）；使（相信）","en":"You say that you are given to understand or believe that something is the case when you do not want to say how you found out about it, or who told you.","ex":{"en":"We were given to understand that he was ill","cn":"我们得知他病了。"}},{"pos":"PHRASE 短语","cn":"毫不示弱地反击（或反驳）；回敬；以牙还牙","en":"If someone gives as good as they get, they fight or argue as well as the person they are fighting or arguing with.","ex":{"en":"For the first time in 12 years, the Democrats are giving as good as they get.","cn":"民主党人12年来首次予以反击。"}},{"pos":"PHRASE 短语","cn":"愿意付出一切（强调十分渴望做某事或拥有某物）","en":"You use give in phrases such as I'd give anything ,I'd give my right arm, and what wouldn't I give to emphasize that you are very eager to do or have something.","ex":{"en":"I'd give anything to be like you.","cn":"我真希望能像你一样。"}},{"pos":"PHRASE 短语","cn":"我宁可要；我宁可选择；我更喜欢","en":"You use give me to say that you would rather have one thing than another, especially when you have just mentioned the thing that you do not want.","ex":{"en":"I've never had anything barbecued and I don't want it. Give me a good roast dinner any day.","cn":"我还从未吃过烧烤，也不想吃，我宁愿哪一天美美地吃一顿烘烤大餐。"}},{"pos":"PHRASE 短语","cn":"互谅互让；相互迁就","en":"If you say that something requires give and take, you mean that people must compromise or co-operate for it to be successful.","ex":{"en":"...a happy relationship where there's a lot of give and take.","cn":"经常互相体谅的美满爱情"}},{"pos":"PHRASE 短语","cn":"相差不到…；出入至多…","en":"Give or take is used to indicate that an amount is approximate. For example, if you say that something is fifty years old, give or take a few years, you mean that it is approximately fifty years old.","ex":{"en":"They grow to a height of 12 ins — give or take a couple of inches.","cn":"它们会长到12英寸高——出入至多几英寸。"}},{"pos":"PHRASE 短语","cn":"我承认","en":"You say I'll give you that to indicate that you admit that someone has a particular characteristic or ability.","ex":{"en":"You're a bright enough kid, I'll give you that.","cn":"我得承认，你是个挺聪明的孩子。"}},{"pos":"PHRASE 短语","cn":"为…鼓掌","en":"If an audience is asked to give it up for a performer, they are being asked to applaud.","ex":{"en":"Ladies and Gentlemen, give it up for Fred Durst.","cn":"女士们，先生们，请为弗雷德·德斯特来点掌声。"}},{"pos":"","cn":"","en":"to give the game away→see: ; to give up the ghost→see: ; to give someone hell→see: ; to give notice→see: ; to give rise to→see: ; to give way→see: ;"},{"pos":"","cn":"","en":"相关词组：give away give back give in give off give out give over give over to give up give up on give up to"}]},"examples":[{"en":"‘I didn't have time to do it.’ ‘Oh, don't give me that!’ “","cn":"我没有时间做这事。” “哦，别以为我会相信你的鬼话！”"},{"en":"We don't go out much. Give me a quiet night in front of the TV any day!","cn":"我们不常出去。我宁愿坐在电视机前安安静静地过一夜！"}]},"gravitate":{"media":{"uk":"media/uk/gravitate__gb_1.mp3","us":"media/us/gravitate__us_1.mp3"},"oxford":{"phon":"ˈɡrævɪteɪt","pos":"verb","senses":[{"en":"to move towards sb/sth that you are attracted to","cn":"被吸引到；受吸引而转向"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"被吸引到；受吸引而参加","en":"If you gravitate towards a particular place, thing, or activity, you are attracted by it and go to it or get involved in it.","ex":{"en":"Traditionally young Asians in Britain have gravitated towards medicine, law and engineering.","cn":"英国的亚裔年轻人通常被吸引到医学、法律及工程专业。"}}]},"examples":[{"en":"Many young people gravitate to the cities in search of work.","cn":"许多年轻人被吸引到城里找工作。"},{"en":"Most visitors to London gravitate to Piccadilly Circus and Leicester Square.","cn":"多数到了伦敦的游客会被吸引前往皮卡迪利广场和莱斯特广场。"}]},"golden":{"media":{"uk":"media/uk/golden__gb_1.mp3","us":"media/us/golden__us_1.mp3"},"oxford":{"phon":"ˈɡəʊldən","pos":"adjective","senses":[{"en":"made of gold","cn":"金质的；金的","lab":"especially literary","ex":{"en":"a golden crown","cn":"金冕"}},{"en":"bright yellow in colour like gold","cn":"金色的；金黄色的","ex":{"en":"golden hair","cn":"金发"}},{"en":"special; wonderful","cn":"特别的；美好的","ex":{"en":"golden memories","cn":"美好的记忆"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"金色的；金黄色的","en":"Something that is golden is bright yellow in colour.","ex":{"en":"She combed and arranged her golden hair.","cn":"她梳理好自己的金发。"}},{"pos":"ADJ 形容词","cn":"金的；金制的","en":"Golden things are made of gold.","ex":{"en":"...a golden chain with a golden locket.","cn":"带有金制盒式链坠的金项链"}},{"pos":"ADJ 形容词","cn":"极好的；有发展前途的；有益的","en":"If you describe something as golden, you mean it is wonderful because it is likely to be successful and rewarding, or because it is the best of its kind.","ex":{"en":"He says there's a golden opportunity for peace which must be seized.","cn":"他说务必抓住这个谋求和平的绝佳机会。"}},{"pos":"PHRASE 短语","cn":"大受欢迎（或十分成功）的人","en":"If you refer to a man as a golden boy or a woman as a golden girl, you mean that they are especially popular and successful.","ex":{"en":"When the movie came out the critics went wild, hailing Tarantino as the golden boy of the 1990s.","cn":"这部影片上映后，批评家们反响十分热烈，他们将塔拉蒂诺誉为20世纪90年代的金牌男星。"}}]},"examples":[{"en":"He thinks once he gets the money he'll be golden.","cn":"他认为只要拿到钱就万事大吉了。"},{"en":"Businesses have a golden opportunity to expand into new markets.","cn":"商界有开拓新市场的良机。"}]},"great":{"media":{"uk":"media/uk/great__gb_1.mp3","us":"media/us/great__us_1.mp3"},"oxford":{"phon":"ɡreɪt","pos":"adjective","senses":[{"en":"very good or pleasant","cn":"美妙的；好极的；使人快乐的","lab":"informal","sc":"good","ex":{"en":"He's a great bloke.","cn":"他是个大好人。"}},{"en":"much more than average in degree or quantity","cn":"非常的；很多的；极大的","lab":"ironic","sc":"large","ex":{"en":"This is a matter of great importance.","cn":"这是个极其重要的问题。"}},{"en":"very large; much bigger than average in size or quantity","cn":"大的；巨大的；数量大的；众多的","g":"[usually before noun]","sc":"large","ex":{"en":"A great crowd had gathered.","cn":"一大群人聚集在一起。"}},{"en":"used to emphasize an adjective of size or quality","cn":"（强调尺寸、体积或质量）很","g":"[only before noun]","lab":"informal","sc":"large","ex":{"en":"There was a great big pile of books on the table.","cn":"桌上有很大一摞书。"}},{"en":"extremely good in ability or quality and therefore admired by many people","cn":"伟大的；优秀的；杰出的；卓越的","sc":"admired","ex":{"en":"Gary Kasparov, undoubtedly the greatest chess player of all time","cn":"加里·卡斯帕罗夫，无疑是有史以来最伟大的国际象棋棋手"}},{"en":"important and impressive","cn":"重要的；重大的；给人深刻印象的","g":"[only before noun]","sc":"important/impressive","ex":{"en":"The wedding was a great occasion.","cn":"这场婚礼可是一大盛典。"}},{"en":"having high status or a lot of influence","cn":"地位高的；位高权重的；影响大的","sc":"with influence","ex":{"en":"the great powers (= important and powerful countries)","cn":"大国"}},{"en":"in a very good state of physical or mental health","cn":"身心健康的；心情愉快的","sc":"in good health","ex":{"en":"She seemed in great spirits (= very cheerful).","cn":"她好像心情很不错。"}},{"en":"able to do something well","cn":"擅长；精通","g":"[not usually before noun]","lab":"informal","sc":"skilled","ex":{"en":"She's great at chess.","cn":"她国际象棋下得很好。"}},{"en":"very suitable or useful for something","cn":"适合；（对…）有用","lab":"informal","sc":"useful","ex":{"en":"This gadget's great for opening jars.","cn":"这小玩意儿开广口瓶挺好。"}},{"en":"used when you are emphasizing a particular description of somebody/something","cn":"（强调某种情况）","g":"[only before noun]","sc":"for emphasis","ex":{"en":"We are great friends.","cn":"我们是最要好的朋友。"}},{"en":"added to words for family members to show a further stage in relationship","cn":"（冠于家庭成员的称呼前，表示更高或更低一辈的亲属关系）","sc":"family","ex":{"en":"my great-aunt (= my father’s or mother’s aunt)","cn":"我的姑婆／姨婆"}},{"en":"used in the names of animals or plants that are larger than similar kinds","cn":"（用于相似动植物中较大者的名称前）大","g":"[only before noun]","sc":"larger animals/plants","ex":{"en":"the great tit","cn":"大山雀"}},{"en":"used with the name of a city to describe an area that includes the centre of the city and a large area all round it","cn":"（与城市名连用，指包括市区和周围广大地区在内的区域）大","sc":"city name","ex":{"en":"Greater London","cn":"大伦敦"}},{"en":"a very well-known and successful person","cn":"名人；伟人","ex":{"en":"He was one of boxing's all-time greats.","cn":"他是一位空前的拳击好手。"},"pos":"noun"},{"en":"very well","cn":"极佳地；非常好地","ex":{"en":"Well done. You did great.","cn":"干得好。你干得真棒。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"很大的；巨大的","en":"You use great to describe something that is very large. Great is more formal than big .","ex":{"en":"The room had a great bay window.","cn":"这间房有一扇巨大的凸窗。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（数量或程度）大的，巨大的，超乎寻常的","en":"Great means large in amount or degree.","ex":{"en":"I'll take great care of it","cn":"我会加倍爱惜它的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"重大的；闻名的；令人激动的","en":"You use great to describe something that is important, famous, or exciting.","ex":{"en":"...the great cultural achievements of the past","cn":"昔日辉煌的文化成就"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"伟大的；著名的； 卓越的；优秀的","en":"You can describe someone who is successful and famous for their actions, knowledge, or skill as great .","ex":{"en":"Wes Hall was once one of the West Indies' great cricketers.","cn":"韦斯·霍尔曾经是西印度群岛伟大的板球运动员之一。"}},{"pos":"N-PLURAL 复数名词","cn":"伟人；名人；大人物","en":"The greats in a particular subject or field of activity are the people who have been most successful or famous in it.","ex":{"en":"...all the greats of Hollywood.","cn":"所有的好莱坞名流"}},{"pos":"N-PLURAL 复数名词","cn":"金曲","en":"The greats of popular modern music are records that have been successful and that continue to be popular.","ex":{"en":"...a medley of rock'n'roll greats.","cn":"摇滚金曲大联唱"}},{"pos":"ADJ 形容词","cn":"美妙的；好极了的；了不起的","en":"If you describe someone or something as great, you approve of them or admire them.","ex":{"en":"Arturo has this great place in Cazadero","cn":"阿图罗在卡扎德罗威望极高。"}},{"pos":"ADJ 形容词","cn":"十分健康的；精力旺盛的；充满热情的","en":"If you feel great, you feel very healthy, energetic, and enthusiastic.","ex":{"en":"I feel just great.","cn":"我感觉好极了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"十足的；非常的","en":"You use great in order to emphasize the size or degree of a characteristic or quality.","ex":{"en":"...a great big Italian wedding.","cn":"场面盛大的意大利式婚礼"}},{"pos":"EXCLAM 感叹语","cn":"妙极了；太好了","en":"You say great in order to emphasize that you are pleased or enthusiastic about something.","ex":{"en":"Oh great! That'll be good for Fergus.","cn":"哦，太棒了！那将对弗格斯很有利。"}},{"pos":"EXCLAM 感叹语","cn":"哼，这倒好（表示气愤、恼火等）","en":"You say great in order to emphasize that you are angry or annoyed about something.","ex":{"en":"'Oh great,' I thought. 'Just what I need.'","cn":"“哼，”我想，“正合我心。”"}},{"pos":"N-IN-NAMES 名称名词","cn":"（用于同类动植物中较大者的名称前）大","en":"Great is used as part of the name of a species of plant or animal when there is another species of the same plant or animal which is smaller and has different characteristics.","ex":{"en":"...the great white shark.","cn":"大白鲨"}}]},"examples":[{"en":"You've been a great help, I must say (= no help at all).","cn":"依我看，你真是帮了个大忙啊（指帮倒忙）。"},{"en":"‘I'll pick you up at seven.’ ‘That'll be great, thanks.’ “","cn":"我七点钟来接你。” “太好了，谢谢。”"}]},"garage":{"media":{"uk":"media/uk/garage__gb_1.mp3","us":"media/us/garage__us_1.mp3","img":["media/ldoce/img/garage.jpg"]},"oxford":{"phon":"ˈɡærɑːʒ","pos":"noun","senses":[{"en":"a building for keeping one or more cars or other vehicles in","cn":"停车房；车库","g":"[countable]","ex":{"en":"a double garage (= one for two cars)","cn":"双车位车库"}},{"en":"a place where vehicles are repaired and/or where you can buy a car or buy petrol and oil","cn":"（兼营汽车销售、修理及加油的）汽车修理厂","g":"[countable]","ex":{"en":"I had to take the car to the garage.","cn":"我不得不把车开到维修站去。"}},{"en":"a style of rock music played with great energy but not necessarily great technique, popular in the 1960s","cn":"车库摇滚乐（流行于 20 世纪 60 年代）","g":"[uncountable]"},{"en":"a type of electronic dance music with elements of drum and bass, house music and soul","cn":"英式车库（一种电子舞曲，融合鼓打贝司、浩室音乐和灵乐元素）","g":"[uncountable]"},{"en":"to put or keep a vehicle in a garage","cn":"把…送入车库（或修车厂）","ex":{"en":"They have space to garage two cars.","cn":"他们有空间停放两辆车。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"车库；停车房","en":"A garage is a building in which you keep a car. A garage is often built next to or as part of a house."},{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"汽车修理厂（在英国兼营加油或汽车销售）","en":"A garage is a place where you can get your car repaired. In Britain, you can also buy fuel for your car, or buy cars.","ex":{"en":"Nancy took her car to a local garage for a check-up","cn":"南希把车开到当地的汽车修理厂检修。"}}]},"examples":[{"en":"a double garage (= one for two cars)","cn":"停放两辆车的车房"},{"en":"( BrE ) a house with a built-in garage","cn":"内设车库的房子"}]},"getting":{"lemma":"get","media":{"uk":"media/uk/getting__gb_1.mp3","us":"media/us/getting__us_1.mp3"}},"geographical":{"media":{"uk":"media/uk/geographical__gb_1.mp3","us":"media/us/geographical__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"地理（学）的","en":"Geographical or geographic means concerned with or relating to geography.","ex":{"en":"Its geographical location stimulated overseas mercantile enterprise.","cn":"它的地理位置引起了海外商家的兴趣。"}}]},"examples":[{"en":"The importance of the town is due to its geographical location.","cn":"这座城镇的重要性在于它的地理位置。"},{"en":"The survey covers a wide geographical area.","cn":"此项调查覆盖的地理区域非常广阔。"}],"oxford":{"phon":"ˌdʒiːəˈɡræfɪkl","pos":"adjective","senses":[{"en":"connected with the way in which the physical features of a place are arranged","cn":"与一个地方的物理特征的排列方式有关的","ex":{"en":"The importance of the town is due to its geographical location.","cn":"这个镇的重要性在于其地理位置。"}},{"en":"connected with the scientific study of the earth's surface, physical features, divisions, products, population, etc.","cn":"与地球表面、物理特征、分区、产品、人口等的科学研究有关。","ex":{"en":"Researchers and surveyors exchanged geographical knowledge.","cn":"研究人员和测量员交流地理知识。"}},{"en":"connected with the way in which a particular aspect of life or society is influenced by geography or varies according to geography","cn":"与生活或社会的某一特定方面受地理影响或随地理变化的方式有关的","ex":{"en":"the geographical distribution of wealth","cn":"财富的地理分布"}}]}},"generate":{"media":{"uk":"media/uk/generate__gb_1.mp3","us":"media/us/generate__us_1.mp3"},"oxford":{"phon":"ˈdʒenəreɪt","pos":"verb","senses":[{"en":"to produce energy, especially electricity","cn":"产生（能量）；发（电）","ex":{"en":"The wind turbines are used to generate electricity.","cn":"风力涡轮机被用来发电。"}},{"en":"to produce or create something","cn":"产生；引起","ex":{"en":"to generate revenue/income/profit","cn":"产生收益／收入／利润"}},{"en":"to produce a set or sequence of data by taking an initial set of data and applying a mathematical or logical process to it","cn":"生成：通过对初始数据集进行数学或逻辑处理，生成一组数据或一系列数据。","lab":"computing","ex":{"en":"We generated 10 data sets, which we used to run each of the models.","cn":"我们生成了 10 个数据集，用于运行每个模型。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"造成；引起；导致","en":"To generate something means to cause it to begin and develop.","ex":{"en":"The Employment Minister said the reforms would generate new jobs.","cn":"劳工大臣表示，改革将带来新的就业机会。"}},{"pos":"VERB 动词","cn":"产生（能量）；发（电）","en":"To generate a form of energy or power means to produce it.","ex":{"en":"The company, New England Electric, burns coal to generate power.","cn":"新英格兰电力公司用煤发电。"}}]},"examples":[{"en":"The proposal has generated a lot of interest.","cn":"这项建议引起众多的关注。"},{"en":"We need someone to generate new ideas.","cn":"我们需要有人出新主意。"}]},"gills":{"lemma":"gill","media":{"uk":"media/uk/gill__gb_1.mp3","us":"media/us/gill__us_1.mp3"}},"geometry":{"oxford":{"phon":"dʒiˈɒmətri","pos":"noun","senses":[{"en":"the branch of mathematics that deals with the measurements and relationships of lines, angles, surfaces and solids","cn":"几何（学）","g":"[uncountable]","ex":{"en":"Pre-Christian sacred geometry was incorporated into church architecture.","cn":"西历纪元开始以前的神圣几何被运用于教堂建筑中。"}},{"en":"the measurements and relationships of lines, angles, etc. in a particular object or shape","cn":"几何形状；几何图形；几何结构","g":"[singular]","ex":{"en":"the geometry of a spider’s web","cn":"蜘蛛网的几何形状"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"几何（学）","en":"Geometry is the branch of mathematics concerned with the properties and relationships of lines, angles, curves, and shapes.","ex":{"en":"...the very ordered way in which mathematics and geometry describe nature.","cn":"数学和几何学极有条理的描述自然的方式"}},{"pos":"N-UNCOUNT 不可数名词","cn":"形状；外形；几何图形；几何结构","en":"The geometry of an object is its shape or the relationship of its parts to each other.","ex":{"en":"They have tinkered with the geometry of the car's nose.","cn":"他们对车头的外观进行了改进。"}}]},"media":{"uk":"media/uk/geometry__gb_1.mp3","us":"media/us/geometry__us_1.mp3"},"examples":[{"en":"the geometry of a spider's web","cn":"蜘蛛网的几何形状"}]},"grass":{"media":{"img":["media/pic/blade_comp.jpg","media/thumb/grass.jpg"],"uk":"media/uk/grass__gb_1.mp3","us":"media/us/grass__us_1.mp3"},"oxford":{"phon":"ɡrɑːs","pos":"noun","senses":[{"en":"a common wild plant with narrow green leaves and stems that are eaten by cows, horses, sheep, etc.","cn":"草；青草；牧草","g":"[uncountable]","ex":{"en":"a blade of grass","cn":"一片草叶"}},{"en":"any type of grass","cn":"禾本科植物","g":"[countable]","ex":{"en":"ornamental grasses","cn":"观赏性草"}},{"en":"an area of ground covered with grass","cn":"草地；草坪；草场；牧场","g":"[singular, uncountable]","ex":{"en":"to cut/mow the grass","cn":"割草"}},{"en":"marijuana","cn":"大麻","g":"[uncountable]","lab":"informal"},{"en":"a person, usually a criminal, who tells the police about somebody’s criminal activities and plans","cn":"向警方告密的人（通常指罪犯）","g":"[countable]","lab":"British English, informal, usually disapproving，，，，"},{"en":"to tell the police about somebody’s criminal activities","cn":"（向警方）告密，告发","ex":{"en":"Who grassed on us?","cn":"谁向警方告发了我们？"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"草；青草","en":"Grass is a very common plant consisting of large numbers of thin, spiky, green leaves that cover the surface of the ground.","ex":{"en":"Small things stirred in the grass around the tent","cn":"一些小东西在帐篷四周的草丛里窸窸窣窣地动着。"}},{"pos":"N-SING 单数名词","cn":"草地；草坪；草场","en":"If you talk about the grass, you are referring to an area of ground that is covered with grass, for example in your garden.","ex":{"en":"In the old days, there were strict fines for walking on the grass or missing a study period","cn":"过去，踩踏草坪或旷课都会被重金处罚。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"同marijuana","en":"Grass is the same as marijuana .","ex":{"en":"I started smoking grass when I was about sixteen.","cn":"我大约16岁的时候开始吸大麻。"}},{"pos":"VERB 动词","cn":"（向警方等）揭发，告发","en":"If you say that one person grasses on another, the first person tells the police or other authorities about something criminal or wrong which the second person has done.","ex":{"en":"His wife wants him to grass on the members of his own gang","cn":"妻子要他向警方告发他所在团伙的成员。"}},{"pos":"N-COUNT 可数名词","cn":"告密者；揭发者","en":"A grass is someone who tells the police or other authorities about criminal activities that they know about."},{"pos":"PHRASE 短语","cn":"草是那边绿；这山望着那山高","en":"If you say the grass is greener somewhere else, you mean that other people's situations always seem better or more attractive than your own, but may not really be so.","ex":{"en":"He was very happy with us but wanted to see if the grass was greener elsewhere.","cn":"他对我们感到十分满意，但还想看看是否有更合适的人选。"}},{"pos":"PHRASE 短语","cn":"（因年老等）被辞退，遭解雇","en":"If you say that someone is being put out to grass, you mean they are no longer being employed because they are considered to be too old or no longer useful.","ex":{"en":"The Prime Minister refused to be put out to grass. Asked if he would quit, he replied: 'The answer is No'.","cn":"首相拒绝被解除职务，当问到他是否会辞职时，他说，“我的回答是不。”"}},{"pos":"","cn":"","en":"相关词组：grass over grass up"}]},"examples":[{"en":"Keep off the grass. (= on a sign)","cn":"请勿践踏草地。"},{"en":"The dry grass caught fire.","cn":"干草着火了。"}]},"gleaming":{"media":{"uk":"media/uk/gleaming__gb_1.mp3","us":"media/us/gleaming__us_1.mp3"},"oxford":{"phon":"ˈɡliːmɪŋ","pos":"adjective","senses":[{"en":"shining brightly because of being very clean","cn":"闪光的；明亮的","ex":{"en":"gleaming white teeth","cn":"皓齿"}}]},"examples":[{"en":"gleaming white teeth","cn":"皓齿"},{"en":"His teeth gleamed under his moustache.","cn":""}],"base":"gleam"},"generally":{"media":{"uk":"media/uk/generally__gb_1.mp3","us":"media/us/generally__us_1.mp3"},"oxford":{"phon":"ˈdʒenrəli","pos":"adverb","senses":[{"en":"by or to most people","cn":"普遍地；广泛地","ex":{"en":"The initiative was generally considered a success.","cn":"这项倡议被普遍认为是成功的。"}},{"en":"in most cases","cn":"一般地；通常；大体上","ex":{"en":"I generally get up at six.","cn":"我一般六点钟起床。"}},{"en":"without discussing the details of something","cn":"笼统地；概括地；大概","ex":{"en":"Let's talk just about investment generally.","cn":"咱们只大概谈谈投资吧。"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"笼统地；概括地","en":"You use generally to give a summary of a situation, activity, or idea without referring to the particular details of it.","ex":{"en":"University teachers generally have admitted a lack of enthusiasm about their subjects","cn":"高校教师大体上承认对其所教专业缺乏热情。"}},{"pos":"ADV 副词","cn":"通常地；一般地；普遍地","en":"You use generally to say that something happens or is used on most occasions but not on every occasion.","ex":{"en":"As women we generally say and feel too much about these things","cn":"作为女性，我们通常在这些事情上谈得过多，过于敏锐。"}}]},"examples":[{"en":"The new drug will be generally available from January.","cn":"这种新药从一月份开始将可广泛使用。"},{"en":"He was a generally unpopular choice for captain.","cn":"人们普遍不欢迎他成为队长的人选。"}]},"goose":{"media":{"uk":"media/uk/goose__gb_1.mp3","us":"media/us/goose__us_1.mp3","img":["media/ldoce/img/goose.jpg"]},"oxford":{"phon":"ɡuːs","pos":"noun","senses":[{"en":"a bird like a large duck with a long neck. Geese either live wild or are kept on farms.","cn":"鹅","g":"[countable]"},{"en":"meat from a goose","cn":"鹅肉","g":"[uncountable]","ex":{"en":"roast goose","cn":"烤鹅"}},{"en":"a female goose","cn":"雌鹅","g":"[countable]"},{"en":"a silly person","cn":"傻瓜；笨蛋","g":"[countable]","lab":"old-fashioned, informal，，"},{"en":"to touch or press somebody’s bottom quickly","cn":"戳（或捏）（某人）臀部","ex":{"en":"Jack goosed her as she reached for a file.","cn":"当她伸手去拿文件夹时，杰克刺激了她。"},"pos":"verb"},{"en":"to make something move or work faster","cn":"推动；促进；激励","lab":"North American English","ex":{"en":"The government has done everything possible to goose the economy along.","cn":"政府已尽一切可能推动经济发展。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鹅","en":"A goose is a large bird that has a long neck and webbed feet. Geese are often farmed for their meat."},{"pos":"N-UNCOUNT 不可数名词","cn":"鹅肉","en":"Goose is the meat from a goose that has been cooked.","ex":{"en":"...roast goose.","cn":"烤鹅"}},{"pos":"PHRASE 短语","cn":"阻挠；破坏…的计划","en":"If you cook someone's goose, you prevent their plans from succeeding.","ex":{"en":"He said that what they were up to would cook Krasky's goose.","cn":"他说他们暗中进行的阴谋可能会使克拉斯基的计划流产。"}},{"pos":"PHRASE 短语","cn":"杀鸡取卵；自绝财源","en":"If someone kills the goose that lays the golden egg, they harm or destroy the person or thing that gives them their money, power, or advantage.","ex":{"en":"Unregulated tourism can kill the goose that laid their golden egg.","cn":"旅游业的无序发展无异于杀鸡取卵。"}},{"pos":"PHRASE 短语","cn":"适于此者适于彼；应该一视同仁","en":"If you say what's sauce for the goose is sauce for the gander, you mean what is acceptable for one person in a particular situation should be acceptable for another person in a similar situation."}]},"examples":[{"en":"roast goose","cn":"烤鹅"}]},"gold":{"media":{"uk":"media/uk/gold__gb_1.mp3","us":"media/us/gold__us_1.mp3"},"oxford":{"phon":"ɡəʊld","pos":"noun","senses":[{"en":"a chemical element. Gold is a yellow precious metal used for making coins, jewellery, beautiful objects, etc.","cn":"金","g":"[uncountable]","ex":{"en":"gold coins/jewellery","cn":"金币；金首饰"}},{"en":"money, jewellery, etc. that is made of gold","cn":"金币；金饰品；黄金制品","g":"[uncountable]","ex":{"en":"The hotel was dripping with (= decorated with a lot of) gold.","cn":"这家酒店到处都是黄金饰品。"}},{"en":"a medal made of gold that is given to the winner of a race or competition","cn":"金牌；金质奖章","g":"[uncountable, countable]","ex":{"en":"The team look set to win Olympic gold.","cn":"这个队看来可能会拿奥运会金牌。"}},{"en":"the colour of gold","cn":"金色；金黄色","g":"[uncountable, countable]","ex":{"en":"a sunset of burnished gold","cn":"金色的夕阳"}},{"en":"bright yellow in colour, like gold","cn":"金色的","ex":{"en":"The company name was spelled out in gold letters.","cn":"该公司的名称用烫金字母拼成。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"黄金","en":"Gold is a valuable, yellow-coloured metal that is used for making jewellery and ornaments, and as an international currency.","ex":{"en":"...a sapphire set in gold","cn":"镶嵌在黄金上的蓝宝石"}},{"pos":"N-UNCOUNT 不可数名词","cn":"金饰物；黄金制品","en":"Gold is jewellery and other things that are made of gold.","ex":{"en":"We handed over all our gold and money.","cn":"我们将所有的金首饰和钱都交了出来。"}},{"pos":"COLOUR 颜色词","cn":"金色；金黄色","en":"Something that is gold is a bright yellow colour, and is often shiny.","ex":{"en":"I'd been wearing Michel's black and gold shirt.","cn":"我一直都穿着米歇尔那件黑色和金色相间的衬衫。"}},{"pos":"N-VAR 可变名词","cn":"同gold medal","en":"A gold is the same as a gold medal .","ex":{"en":"His ambition was to win gold at the Atlanta Games in 1996","cn":"他的志向是在1996年亚特兰大奥运会上夺取金牌。"}},{"pos":"PHRASE 短语","cn":"（小孩）规规矩矩的,乖巧的","en":"If you say that a child is being as good as gold, you are emphasizing that they are behaving very well and are not causing you any problems.","ex":{"en":"The boys were as good as gold on our walk.","cn":"我们散步的时候，这帮小男孩表现得很乖。"}},{"pos":"PHRASE 短语","cn":"一颗金子般的心；赤子之心","en":"If you say that someone has a heart of gold, you are emphasizing that they are very good and kind to other people.","ex":{"en":"They are all good boys with hearts of gold. They would never steal.","cn":"他们都是有着金子般心灵的好孩子，绝不会干偷摸扒窃之事。"}},{"pos":"PHRASE 短语","cn":"期望得到的一大笔钱，未来的一桶金（英国英语中亦作a crock of gold）","en":"Money that someone hopes they will get in the future is sometimes referred to as a pot of gold. Also a crock of gold, mainly in British English.","ex":{"en":"I would rather be honest with people than tell them that there is going to be some pot of gold at the end of the rainbow.","cn":"我宁肯实话实说也不愿意给予他们不切实际的期望。"}},{"pos":"See also:","cn":"","en":"to strike gold→see: ; worth one's weight in gold→see: ;"}]},"examples":[{"en":"The team look set to win Olympic gold.","cn":"这个队看来可能会拿奥运会金牌。"},{"en":"I love the reds and golds of autumn.","cn":"我喜欢秋天的火红色和金黄色。"}]},"glyph":{"oxford":{"phon":"ɡlɪf","pos":"noun","senses":[{"en":"a symbol or picture that represents a word, especially one from an ancient writing system","cn":"石雕符号；象形文字","ex":{"en":"how to write the Mayan glyph for cacao","cn":"如何书写可可的玛雅字形"}},{"en":"a small symbol","cn":"图元；字形","lab":"computing","ex":{"en":"This command will call up a table with all available glyphs in that font.","cn":"此命令将调用一个表格，其中包含该字体的所有可用字形。"}}]},"media":{"uk":"media/uk/glyph__gb_1.mp3","us":"media/us/glyph__us_1.mp3"}},"gear":{"media":{"uk":"media/uk/gear__gb_1.mp3","us":"media/us/gear__us_1.mp3"},"oxford":{"phon":"ɡɪə(r)","pos":"noun","senses":[{"en":"equipment in a vehicle that changes the relation between engine speed (or pedal speed on a bicycle) and the speed of the wheels moving forwards or backwards","cn":"排挡；齿轮；传动装置","g":"[countable, usually plural]","sc":"in vehicle","ex":{"en":"Careless use of the clutch may damage the gears.","cn":"离合器使用不慎可能会损坏传动装置。"}},{"en":"a particular position of the gears in a vehicle that gives a particular range of speed and power","cn":"挡","g":"[uncountable, countable]","lab":"British English","sc":"in vehicle","ex":{"en":"first/second, etc. gear","cn":"一挡、二挡等"}},{"en":"the equipment or clothing needed for a particular activity","cn":"（某种活动的）设备，用具，衣服","g":"[uncountable]","sc":"equipment/clothes","ex":{"en":"climbing/fishing/sports gear","cn":"登山／钓鱼／运动装备"}},{"en":"clothes","cn":"衣服","g":"[uncountable]","lab":"informal","sc":"equipment/clothes","ex":{"en":"Her friends were all wearing the latest gear.","cn":"她的朋友都穿着最新款的衣服。"}},{"en":"the things that a person owns","cn":"所有物；财物","g":"[uncountable]","lab":"informal","sc":"possessions","ex":{"en":"I've left all my gear at Dave's house.","cn":"我把我所有的东西都留在戴夫家了。"}},{"en":"a machine used for a particular purpose","cn":"（特定用途的）器械，装置","g":"[uncountable]","sc":"machinery","ex":{"en":"lifting/towing/winding gear","cn":"起重／牵引／卷扬装置"}},{"en":"used to talk about the speed or effort involved in doing something","cn":"（做事的）速度，努力","g":"[uncountable, countable]","lab":"British English","sc":"speed/effort","ex":{"en":"The party organization is moving into top gear as the election approaches.","cn":"随着选举的临近，这个政党的组织工作正在紧锣密鼓地进行。"}},{"en":"illegal drugs","cn":"毒品","g":"[uncountable]","lab":"slang","sc":"drugs"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"齿轮；传动装置；变速器","en":"The gears on a machine or vehicle are a device for changing the rate at which energy is changed into motion.","ex":{"en":"On hills, he must use low gears","cn":"在山上,他必须挂低速挡。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（某一特定活动的）设备，服装","en":"The gear involved in a particular activity is the equipment or special clothing that you use.","ex":{"en":"About 100 officers in riot gear were needed to break up the fight.","cn":"大约需要100名穿防暴服的警察前来制止这场斗殴。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"服装","en":"Gear means clothing.","ex":{"en":"I used to wear trendy gear but it just looked ridiculous.","cn":"我以前常穿新潮的衣服，但看上去却滑稽可笑。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"毒品；（尤指）海洛因","en":"Some people refer to illegal drugs, especially heroin, as gear .","ex":{"en":"Are these people using gear and amphetamines at the same time?","cn":"这些人同时服用海洛因和安非他明吗？"}},{"pos":"V-PASSIVE 被动动词","cn":"使为…而准备；使为了达到…而作好准备","en":"If someone or something is geared to or towards a particular purpose, they are organized or designed in order to achieve that purpose.","ex":{"en":"Colleges are not always geared to the needs of mature students","cn":"大学有时满足不了成人学生的需求。"}},{"pos":"","cn":"","en":"相关词组：gear up"}]},"examples":[{"en":"Coming out of the final bend, the runner stepped up a gear to overtake the rest of the pack.","cn":"那名赛跑选手绕过最后一个弯道后开始加速，以图超越同组的其他选手。"},{"en":"( BrE ) The party organization is moving into top gear as the election approaches.","cn":"随着选举的临近，这个政党的组织工作正在紧锣密鼓地进行。"}]},"generously":{"oxford":{"phon":"ˈdʒenərəsli","pos":"adverb","senses":[{"en":"in a way that shows that somebody is willing to give freely","cn":"慷慨地：以某种方式表明有人愿意自由地给予","ex":{"en":"Please give generously.","cn":"请慷慨解囊。"}},{"en":"using or providing more of something than is necessary","cn":"慷慨地：过度使用或提供不必要的","ex":{"en":"a dress that is generously cut (= uses plenty of material)","cn":"用料多的连衣裙"}},{"en":"kindly; in a way that shows that somebody is willing to see what is good about somebody/something","cn":"宽厚的；宽宏大量的；仁慈的","ex":{"en":"She speaks generously about everyone.","cn":"她对每个人都慷慨地谈论。"}}]},"media":{"uk":"media/uk/generously__gb_1.mp3","us":"media/us/generously__us_1.mp3"},"examples":[{"en":"a dress that is generously cut (= uses plenty of material)","cn":"用料多的连衣裙"},{"en":"Please give generously.","cn":"请慷慨施与。"}]},"grants":{"lemma":"grant"},"gap":{"media":{"uk":"media/uk/gap__gb_1.mp3","us":"media/us/gap__us_1.mp3"},"oxford":{"phon":"ɡæp","pos":"noun","senses":[{"en":"a space where something is missing","cn":"缺口；空白；漏洞","ex":{"en":"Extra funding is needed to plug the gap.","cn":"需要额外资金来填补这一缺口。"}},{"en":"a space between two things or in the middle of something, especially because there is a part missing","cn":"开口；豁口；缺口；裂口","ex":{"en":"There should be a six-inch gap at the bottom.","cn":"底部应该有六英寸的间隙。"}},{"en":"a period of time when something stops, or between two events","cn":"间断；间隔；间隙","ex":{"en":"a gap in the conversation","cn":"谈话的间隙"}},{"en":"a difference that separates people, or their opinions, situation, etc.","cn":"分歧；隔阂；差距","ex":{"en":"A huge gap has opened up between expectations and what is deliverable.","cn":"期望与现实所得之间出现了巨大的反差。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"缝隙；缺口；豁口；裂口","en":"A gap is a space between two things or a hole in the middle of something solid.","ex":{"en":"He pulled the thick curtains together, leaving just a narrow gap.","cn":"他拉上厚厚的窗帘，仅留下一条狭窄的缝隙。"}},{"pos":"N-COUNT 可数名词","cn":"（时间上的）间断，间隔，间隙","en":"A gap is a period of time when you are not busy or when you stop doing something that you normally do.","ex":{"en":"There followed a gap of four years, during which William joined the Army.","cn":"随后的4年时间，威廉在陆军服役。"}},{"pos":"N-COUNT 可数名词","cn":"漏洞；空白；缺口","en":"If there is something missing from a situation that prevents it being complete or satisfactory, you can say that there is a gap .","ex":{"en":"We need more young scientists to fill the gap left by a wave of retirements expected over the next decade","cn":"我们需要更多年轻的科学家来填补预计未来10年退休高峰带来的人才缺口。"}},{"pos":"N-COUNT 可数名词","cn":"分歧；差距；隔阂","en":"A gap between two groups of people, things, or sets of ideas is a big difference between them.","ex":{"en":"...the gap between rich and poor","cn":"贫富差距"}}]},"examples":[{"en":"We think we've identified a gap in the market (= a business opportunity to make or sell sth that is not yet available).","cn":"我们认为已经发现了市场上一个尚待填补的空白。"},{"en":"His death left an enormous gap in my life.","cn":"他去世给我的生活留下巨大的空白。"}]},"ground":{"media":{"uk":"media/uk/ground__gb_2.mp3","us":"media/us/ground__us_2.mp3"},"oxford":{"phon":"ɡraʊnd","pos":"noun","senses":[{"en":"the solid surface of the earth","cn":"地；地面","g":"[uncountable]","sc":"surface of earth","ex":{"en":"I found her lying on the ground.","cn":"我发现她躺在地上。"}},{"en":"used to describe activities that take place on the ground, not in the air or at sea","cn":"地面上的；陆地上的","g":"[uncountable]","sc":"surface of earth","ex":{"en":"Ground forces were deployed in the area.","cn":"该地区部署了地面部队。"}},{"en":"an area of open land","cn":"开阔地；空旷地","g":"[uncountable]","sc":"area of land","ex":{"en":"The kids were playing on waste ground behind the school.","cn":"孩子们在学校后面的荒地上玩耍。"}},{"en":"an area of land that is used for a particular purpose, activity or sport","cn":"（特定用途的）场地","g":"[countable]","lab":"North American English","sc":"area of land","ex":{"en":"a football/cricket ground","cn":"足球场；板球场"}},{"en":"a large area of land or sea that is used for a particular purpose","cn":"（某种用途的）地域，水域","g":"[plural]","sc":"area of land","ex":{"en":"fishing grounds","cn":"渔场"}},{"en":"soil on the surface of the earth","cn":"土；土地；土壤","g":"[uncountable]","lab":"especially North American English","sc":"soil","ex":{"en":"fertile ground for planting crops","cn":"种植农作物的肥沃土壤"}},{"en":"the land or gardens around a large building","cn":"（大建筑物周围的）场地，庭院，花园","g":"[plural]","sc":"gardens","ex":{"en":"the hospital grounds","cn":"医院的院子"}},{"en":"an area of interest, knowledge or ideas","cn":"（兴趣、知识或思想的）范围，领域","g":"[uncountable]","sc":"area of knowledge/ideas","ex":{"en":"He managed to cover a lot of ground in a short talk.","cn":"他在简短的谈话中涵盖了许多领域。"}},{"en":"a good or true reason for saying, doing or believing something","cn":"充分的理由；根据","g":"[countable, usually plural]","lab":"law","sc":"good reason","ex":{"en":"You have no grounds for complaint.","cn":"你没有理由抱怨。"}},{"en":"the small pieces of solid matter in a liquid that have fallen to the bottom","cn":"渣滓；沉淀物","g":"[plural]","sc":"in liquid","ex":{"en":"coffee grounds","cn":"咖啡渣"}},{"en":"a wire that connects an electric circuit with the ground and makes it safe","cn":"（接）地线","g":"[countable, usually singular]","lab":"North American English","sc":"electrical wire","ex":{"en":"Don't forget to connect the ground wire.","cn":"别忘了接地线。"}},{"en":"a background that a design is painted or printed on","cn":"（绘画或印刷的）背景，底子","g":"[countable]","sc":"background","ex":{"en":"pink roses on a white ground","cn":"白底粉红玫瑰"}},{"en":"when a boat grounds or something grounds it, it touches the ground in shallow water and is unable to move","cn":"（使）搁浅，触底","g":"[transitive, intransitive]","sc":"boat","ex":{"en":"The fishing boat had been grounded on rocks off the coast of Cornwall.","cn":"渔船在康沃尔海岸外礁石上搁浅了。"},"pos":"verb"},{"en":"to prevent an aircraft from taking off","cn":"使停飞；阻止…起飞","g":"[transitive, often passive]","sc":"aircraft","ex":{"en":"The balloon was grounded by strong winds.","cn":"热气球因强风停飞。"},"pos":"verb"},{"en":"to punish a child or young person by not allowing them to go out with their friends for a period of time","cn":"罚（儿童）不准出去玩","g":"[transitive, usually passive]","sc":"child","ex":{"en":"You're grounded for a week!","cn":"罚你一周不准出门！"},"pos":"verb"},{"en":"to make electrical equipment safe by connecting it to the ground with a wire","cn":"把（电线）接地","g":"[transitive, usually passive]","lab":"North American English","sc":"electricity","ex":{"en":"The spark plugs must be grounded to complete the electrical circuit.","cn":"火花塞必须接地才能完成电路。"},"pos":"verb"},{"en":"cut or crushed into very small pieces or powder","cn":"磨细的；剁碎的","lab":"US English","ex":{"en":"ground coffee","cn":"咖啡粉"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"地；地面","en":"The ground is the surface of the earth.","ex":{"en":"Forty or fifty women were sitting cross-legged on the ground","cn":"四五十个女人盘腿坐在地上。"}},{"pos":"N-SING 单数名词","cn":"（相对于空中的）地面","en":"If you say that something takes place on the ground, you mean it takes place on the surface of the earth and not in the air.","ex":{"en":"Coordinating airline traffic on the ground is as complicated as managing the traffic in the air.","cn":"协调地面的航空交通与管理空中交通一样复杂。"}},{"pos":"N-SING 单数名词","cn":"土；土地；土壤","en":"The ground is the soil and rock on the earth's surface.","ex":{"en":"The ground had eroded.","cn":"这片土壤遭到侵蚀。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（尤指建筑物极少或具有某种特性的）土地","en":"You can refer to land as ground, especially when it has very few buildings or when it is considered to be special in some way.","ex":{"en":"...a stretch of waste ground","cn":"一块荒地"}},{"pos":"N-COUNT 可数名词","cn":"（有特定用途的）场地","en":"You can use ground to refer to an area of land, sea, or air which is used for a particular activity.","ex":{"en":"...Indian hunting grounds","cn":"印第安人的狩猎场"}},{"pos":"N-COUNT 可数名词","cn":"运动场，…场（美国英语中亦作grounds）","en":"A ground is an area of land which is specially designed and made for playing sport or for some other activity. In American English grounds is also used.","ex":{"en":"...the city's football ground.","cn":"该市的足球场"}},{"pos":"N-PLURAL 复数名词","cn":"（大型或重要建筑周围的）场地，庭院，花园","en":"The grounds of a large or important building are the garden or area of land which surrounds it.","ex":{"en":"...the palace grounds.","cn":"皇家花园"}},{"pos":"N-VAR 可变名词","cn":"（适于方法、思想等发展的）地方","en":"You can use ground to refer to a place or situation in which particular methods or ideas can develop and be successful.","ex":{"en":"The company has maintained its reputation as the developing ground for new techniques","cn":"该公司一直享有新技术研发基地的美誉。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"范围；领域；基础","en":"You can use ground in expressions such as on shaky ground and the same ground to refer to a particular subject, area of experience, or basis for an argument.","ex":{"en":"Sensing she was on shaky ground, Marie changed the subject","cn":"感到自己的观点站不住脚，玛丽于是换了个话题。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"优势；有利条件","en":"Ground is used in expressions such as gain ground ,lose ground, and give ground in order to indicate that someone gets or loses an advantage.","ex":{"en":"There are signs that the party is gaining ground in the latest polls","cn":"有迹象表明该党在最新一轮投票中正逐渐领先。"}},{"pos":"N-VAR 可变名词","cn":"理由；根据","en":"If something is grounds for a feeling or action, it is a reason for it. If you do something on the grounds of a particular thing, that thing is the reason for your action.","ex":{"en":"In the interview he gave some grounds for optimism","cn":"他接受采访时阐述了持乐观态度的理由。"}},{"pos":"VERB 动词","cn":"以…为根据；建立在…基础上","en":"If an argument, belief, or opinion is grounded in something, that thing is used to justify it.","ex":{"en":"Her argument was grounded in fact","cn":"她的观点有事实根据。"}},{"pos":"VERB 动词","cn":"使不能起飞；使停飞","en":"If an aircraft or its passengers are grounded, they are made to stay on the ground and are not allowed to take off.","ex":{"en":"The civil aviation minister ordered all the planes to be grounded","cn":"民航部长下令所有飞机不得起飞。"}},{"pos":"VERB 动词","cn":"罚（儿童）不能出门；禁足","en":"When parents ground a child, they forbid them to go out and enjoy themselves for a period of time, as a punishment.","ex":{"en":"Thompson grounded him for a month, and banned television.","cn":"汤普森罚他一个月不能出门，并禁止看电视。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）搁浅","en":"If a ship or boat is grounded or if it grounds, it touches the bottom of the sea, lake, or river it is on, and is unable to move off.","ex":{"en":"Residents have been told to stay away from the region where the ship was grounded","cn":"居民们被告知不要靠近船只搁浅的区域。"}},{"pos":"N-COUNT 可数名词","cn":"接地装置；地线","en":"The ground in an electric plug or piece of electrical equipment is the wire through which electricity passes into the ground and which makes the equipment safe."},{"pos":"ADJ 形容词","cn":"（肉等）切碎的，磨碎的","en":"Ground meat has been cut into very small pieces in a machine.","ex":{"en":"...ground beef.","cn":"绞碎的牛肉"}},{"pos":"","cn":"","en":"Ground is the past tense and past participle of grind ."},{"pos":"PHRASE 短语","cn":"开辟新领域；开创新方法","en":"If you break new ground, you do something completely different or you do something in a completely different way.","ex":{"en":"Gellhorn may have broken new ground when she filed her first report on the Spanish Civil War.","cn":"当盖尔霍恩发出她第一篇关于西班牙内战的报道时，她也许已经开辟了一片新的天地。"}},{"pos":"PHRASE 短语","cn":"烧为灰烬；夷为平地","en":"If you say that a town or building is burnt to the ground or is razed to the ground, you are emphasizing that it has been completely destroyed by fire.","ex":{"en":"The town was razed to the ground after the French Revolution.","cn":"该镇在法国大革命后被夷为平地。"}},{"pos":"PHRASE 短语","cn":"共同看法；相同的立场","en":"If two people or groups find common ground, they agree about something, especially when they do not agree about other things."},{"pos":"PHRASE 短语","cn":"躲藏起来；潜伏起来","en":"If you go to ground, you hide somewhere where you cannot easily be found.","ex":{"en":"Citizens of East Beirut went to ground in basements and shelters.","cn":"东贝鲁特的市民们躲进了地下室和掩体中。"}},{"pos":"PHRASE 短语","cn":"中间立场；中间观点","en":"The middle ground between two groups, ideas, or plans involves things which do not belong to either of these groups, ideas, or plans but have elements of each, often in a less extreme form.","ex":{"en":"She seems to have found a middle ground in which mutual support, rather than complete dependency, is possible.","cn":"她似乎已经找到了实现相互支持而非完全依赖其中一方的中间立场。"}},{"pos":"PHRASE 短语","cn":"开始；起步","en":"If something such as a project gets off the ground, it begins or starts functioning.","ex":{"en":"We help small companies to get off the ground.","cn":"我们帮助一些小公司顺利起步。"}},{"pos":"PHRASE 短语","cn":"在自己熟悉的领域里；在自己的地盘","en":"If you are on your own ground, you are in a place or situation in which you feel confident because you are very familiar with it.","ex":{"en":"On her own ground she knows exactly what she's doing.","cn":"她在自己熟悉的领域里对自己的行为有十足的把握。"}},{"pos":"PHRASE 短语","cn":"为…打下基础","en":"If you prepare the ground for a future event, course of action, or development, you make it easier for it to happen.","ex":{"en":"...a political initiative which would prepare the ground for war.","cn":"为战争埋下了伏笔的政治倡议"}},{"pos":"PHRASE 短语","cn":"改变立场；改变观点","en":"If you shift your ground or change your ground, you change the basis on which you are arguing."},{"pos":"PHRASE 短语","cn":"坚持主张；坚定立场","en":"If you stand your ground or hold your ground, you continue to support a particular argument or to have a particular opinion when other people are opposing you or trying to make you change your mind.","ex":{"en":"The spectacle of Sakharov standing his ground and speaking his mind gave me hope.","cn":"萨哈罗夫坚持立场、坦率直言的样子让我看到了希望。"}},{"pos":"PHRASE 短语","cn":"坚守阵地；不退却","en":"If you stand your ground or hold your ground, you do not run away from a situation, but face it bravely.","ex":{"en":"She had to force herself to stand her ground when she heard someone approaching.","cn":"听到有人走近，她只好强迫自己鼓起勇气，绝不退缩。"}},{"pos":"PHRASE 短语","cn":"（工作、衣服等）完全适合","en":"If you say that something such as a job or piece of clothing suits someone down to the ground, you mean that it is completely suitable or right for them."},{"pos":"PHRASE 短语","cn":"为数不多；数目少","en":"If people or things of a particular kind are thin on the ground, there are very few of them.","ex":{"en":"Good managers are often thin on the ground.","cn":"优秀的经理人常常寥寥无几。"}},{"pos":"","cn":"","en":"to have one's ear to the ground→see: ;"}]},"examples":[{"en":"All planes out of Heathrow have been grounded by the strikes.","cn":"所有由希思罗机场起飞的飞机均因罢工而停飞。"},{"en":"Houses and a luxury tourist hotel were burned to the ground (= completely destroyed, so that there is nothing left).","cn":"多间房屋和一家豪华旅馆被大火焚烧殆尽。"}]},"guilt":{"oxford":{"phon":"ɡɪlt","pos":"noun","senses":[{"en":"the unhappy feelings caused by knowing or thinking that you have done something wrong","cn":"内疚；悔恨","ex":{"en":"She had feelings of guilt about leaving her children and going to work.","cn":"她因离开自己的孩子去工作而感到内疚。"}},{"en":"the fact that somebody has done something illegal","cn":"犯罪；罪行；有罪","ex":{"en":"His guilt was proved beyond all doubt by the prosecution.","cn":"他的罪行已被控方证实确凿无疑。"}},{"en":"blame or responsibility for doing something wrong or for something bad that has happened","cn":"罪责；责任；罪过","ex":{"en":"The investigation will try to find out where the guilt for the disaster really lies.","cn":"此调查将尽力查出灾难的真正责任所在。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"内疚；悔恨；负罪感","en":"Guilt is an unhappy feeling that you have because you have done something wrong or think that you have done something wrong.","ex":{"en":"Her emotions had ranged from anger to guilt in the space of a few seconds","cn":"几秒钟的时间里，她经历了从愤怒到内疚的情感变化。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"犯罪；罪行；有罪","en":"Guilt is the fact that you have done something wrong or illegal.","ex":{"en":"The trial is concerned only with the determination of guilt according to criminal law","cn":"依照刑法规定，审判仅涉及定罪。"}}]},"media":{"uk":"media/uk/guilt__gb_1.mp3","us":"media/us/guilt__us_1.mp3"},"examples":[{"en":"She had feelings of guilt about leaving her children and going to work.","cn":"她因离开自己的孩子去工作而感到内疚。"},{"en":"The investigation will try to find out where the guilt for the disaster really lies.","cn":"此调查将尽力查出灾难的真正责任所在。"}]},"greenhouse":{"media":{"uk":"media/uk/greenhouse__gb_1.mp3","us":"media/us/greenhouse__us_1.mp3","img":["media/ldoce/img/greenhouse.jpg"]},"oxford":{"phon":"ˈɡriːnhaʊs","pos":"noun","senses":[{"en":"a building with glass sides and a glass roof for growing plants in","cn":"温室；暖房"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"温室；暖房","en":"A greenhouse is a glass building in which you grow plants that need to be protected from bad weather."},{"pos":"ADJ 形容词","cn":"温室效应的；引起温室效应的","en":"Greenhouse means relating to or causing the greenhouse effect."}]}},"grant":{"oxford":{"phon":"ɡrɑːnt","pos":"verb","senses":[{"en":"to agree to give somebody what they ask for, especially formal or legal permission to do something","cn":"（尤指正式地或法律上）同意，准予，允许","g":"[often passive]","ex":{"en":"My request was granted.","cn":"我的要求得到了满足。"}},{"en":"to admit to somebody that something is true, although you may not like or agree with it","cn":"（勉强）承认，同意","ex":{"en":"She's a smart woman, I grant you, but she's no genius.","cn":"我同意你的观点，她是一个很聪明的女人，但绝不是天才。"}},{"en":"a sum of money that is given by the government or by another organization to be used for a particular purpose","cn":"（政府、机构的）拨款","ex":{"en":"government/federal grants","cn":"政府／联邦拨款"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"拨款;补助金","en":"A grant is an amount of money that a government or other institution gives to an individual or to an organization for a particular purpose such as education or home improvements.","ex":{"en":"They'd got a special grant to encourage research","cn":"他们得到一笔用以鼓励科研的特别经费。"}},{"pos":"VERB 动词","cn":"授予；给予","en":"If someone in authority grants you something, or if something is granted to you, you are allowed to have it.","ex":{"en":"France has agreed to grant him political asylum","cn":"法国已经同意给予他政治避难。"}},{"pos":"VERB 动词","cn":"承认","en":"If you grant that something is true, you accept that it is true, even though your opinion about it does not change.","ex":{"en":"The magistrates granted that the charity was justified in bringing the action.","cn":"地方法官承认该慈善机构有理由提起诉讼。"}},{"pos":"PHRASE 短语","cn":"（因视作理所当然而）不把…当回事，对…不予重视（或不知感激）","en":"If you say that someone takes you for granted, you are complaining that they benefit from your help, efforts, or presence without showing that they are grateful.","ex":{"en":"What right has the family to take me for granted, Martin?","cn":"这家人有什么资格瞧不起我，马丁？"}},{"pos":"PHRASE 短语","cn":"认为…是理所当然的","en":"If you take something for granted, you believe that it is true or accept it as normal without thinking about it.","ex":{"en":"I was amazed that virtually all the things I took for granted up north just didn't happen in London.","cn":"几乎所有我认为在北方是理所当然的事情在伦敦都没有发生，这让我惊诧不已。"}},{"pos":"PHRASE 短语","cn":"理所当然地认为","en":"If you take it for granted that something is the case, you believe that it is true or you accept it as normal without thinking about it.","ex":{"en":"He seemed to take it for granted that he should speak as a representative.","cn":"他似乎想当然地认为他应该以代表的身份发言。"}}]},"media":{"uk":"media/uk/grant__gb_1.mp3","us":"media/us/grant__us_1.mp3"},"examples":[{"en":"She's a smart woman, I grant you, but she's no genius.","cn":"我同意你的观点，她是一个很聪明的女人，但绝不是天才。"},{"en":"We take having an endless supply of clean water for granted.","cn":"我们想当然地认为洁净水的供应无穷无尽而不予以珍惜。"}]},"governed":{"lemma":"govern"},"gate":{"oxford":{"phon":"ɡeɪt","pos":"noun","senses":[{"en":"a barrier like a door that is used to close an opening in a fence or a wall outside a building","cn":"大门；栅栏门；围墙门","g":"[countable]","ex":{"en":"the front/main gate","cn":"前门；大门"}},{"en":"an opening that can be closed by a gate or gates","cn":"大门口","g":"[countable]","ex":{"en":"I was slightly nervous as I entered the gates.","cn":"当我进入大门时，我有点紧张。"}},{"en":"a way out of an airport through which passengers go to get on their plane","cn":"登机门；登机口","g":"[countable]","ex":{"en":"Passengers for Paris should proceed to gate 8.","cn":"前往巴黎的乘客应前往 8 号登机口。"}},{"en":"a barrier that is used to control the flow of water on a river or canal","cn":"闸门；阀门","g":"[countable]","ex":{"en":"a lock/sluice gate","cn":"船闸闸门；水闸"}},{"en":"the number of people who attend a sports event","cn":"（体育比赛的）观众人数","g":"[countable]","ex":{"en":"Tonight's game has attracted the largest gate of the season.","cn":"今晚比赛吸引的观众人数创本赛季之最。"}},{"en":"the amount of money made by selling tickets for a sports event","cn":"（体育比赛的）门票收入","g":"[uncountable]","ex":{"en":"Today's gate will be given to charity.","cn":"今天的门票收入将捐献给慈善事业。"}},{"en":"a political scandal connected with the person, place or event mentioned, usually involving a cover-up (= an attempt to hide an illegal activity)","cn":"（尤指有人试图掩盖的）丑闻","ex":{"en":"The newspapers have been running stories on the Partygate scandal for months.","cn":"几个月来，报纸一直在报道派对门丑闻。"}},{"en":"an electronic switch that reacts in one of two ways to data that is put into it. A computer performs operations by passing data through a very large number of gates.","cn":"门（电路）","lab":"computing"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"大门；门","en":"A gate is a structure like a door which is used at the entrance to a field, a garden, or the grounds of a building.","ex":{"en":"He opened the gate and started walking up to the house.","cn":"他打开大门，迈步朝房子走去。"}},{"pos":"N-COUNT 可数名词","cn":"登机门；登机口","en":"In an airport, a gate is a place where passengers leave the airport and get on their aeroplane.","ex":{"en":"Passengers with hand luggage can go straight to the departure gate to check in there.","cn":"携带手提行李的乘客可直接到登机口办理登机手续。"}},{"pos":"N-IN-NAMES 名称名词","cn":"…门（在英国用于街道名）","en":"Gate is used in the names of streets in Britain that are in a place where there once was a gate into a city.","ex":{"en":"...9 Palace Gate.","cn":"王宫门9号"}},{"pos":"N-COUNT 可数名词","cn":"（体育比赛的）观众总人数","en":"The gate at a sporting event such as a football match or baseball game is the total number of people who attend it.","ex":{"en":"Their average gate is less than 23,000.","cn":"他们的平均上座率不到23,000人。"}}]},"media":{"uk":"media/uk/gate__gb_1.mp3","us":"media/us/gate__us_1.mp3"},"examples":[{"en":"BA flight 726 to Paris is now boarding at gate 16.","cn":"飞往巴黎的英航 726 号班机在 16 号门登机。"},{"en":"Tonight's game has attracted the largest gate of the season.","cn":"今晚比赛吸引的观众人数创本赛季之最。"}]},"grown":{"media":{"uk":"media/uk/grown__gb_2.mp3","us":"media/us/grown__us_2.mp3"},"oxford":{"phon":"ɡrəʊn","pos":"adjective","senses":[{"en":"mentally and physically an adult","cn":"成熟的；成年的；长大成人的","ex":{"en":"It's pathetic that grown men have to resort to violence like this.","cn":"成年人还得这样诉诸暴力，真可悲。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"成年的；成熟的；长大的","en":"A grown man or woman is one who is fully developed and mature, both physically and mentally.","ex":{"en":"Few women can understand a grown man's love of sport","cn":"很少有女人能理解一个成年男人对体育的那份热爱。"}}]},"examples":[{"en":"It's pathetic that grown men have to resort to violence like this.","cn":"成年人还得这样诉诸暴力，真可悲。"},{"en":"Who ever heard of a grown man being scared of the dark?","cn":"有谁听说过一个大男人还怕黑？"}],"base":"grow"},"gone":{"media":{"uk":"media/uk/gone__gb_2.mp3","us":"media/us/gone__us_3.mp3"},"oxford":{"phon":"ɡɒn","pos":"adjective","senses":[{"en":"used up","cn":"用完了；用光了","ex":{"en":"‘Where's the coffee?’ ‘It's all gone.’","cn":"“咖啡在哪儿？”“喝光了。”"}},{"en":"having left a place; away from a place","cn":"走了；离开了；不在","ex":{"en":"‘Is Tom here?’ ‘No, he was gone before I arrived.’","cn":"“汤姆在这儿吗？”“不在，我来之前他就走了。”"}},{"en":"used to say that a particular situation no longer exists","cn":"不复存在；一去不复返","lab":"formal","ex":{"en":"The days are gone when you could leave your door unlocked at night.","cn":"夜不闭户的时代已经一去不复返了。"}},{"en":"having been pregnant for the length of time mentioned","cn":"怀孕…时间了","lab":"British English, informal，，","ex":{"en":"She's seven months gone.","cn":"她怀孕七个月了。"}},{"en":"later than the time mentioned","cn":"晚于；已过","ex":{"en":"It's gone six already.","cn":"已经过六点了。"},"pos":"preposition"}]},"collins":{"senses":[{"pos":"","cn":"","en":"Gone is the past participle of go ."},{"pos":"ADJ 形容词","cn":"离开的；过去的；不复存在的","en":"When someone is gone, they have left the place where you are and are no longer there. When something is gone, it is no longer present or no longer exists.","ex":{"en":"While he was gone she had tea with the Colonel","cn":"他不在时她跟上校一起喝了茶。"}},{"pos":"PREP 介词","cn":"晚于，超过（某一时间）","en":"If you say it is gone a particular time, you mean it is later than that time.","ex":{"en":"It was just gone 7 o'clock this evening when I finished.","cn":"今晚我做完的时候刚过7点。"}}]},"examples":[{"en":"‘Is Tom here?’ ‘No, he was gone before I arrived.’ “","cn":"汤姆在这儿吗？” “不在，我来之前他就走了。”"},{"en":"The days are gone when you could leave your door unlocked at night.","cn":"夜不闭户的时代已经一去不复返了。"}]},"guarded":{"media":{"uk":"media/uk/guarded__gb_1.mp3","us":"media/us/guarded__us_1.mp3"},"oxford":{"phon":"ˈɡɑːdɪd","pos":"adjective","senses":[{"en":"careful; not showing feelings or giving much information","cn":"谨慎的；有保留的；不明确表态的","ex":{"en":"a guarded reply","cn":"谨慎的回答"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"谨慎的；小心在意的；警惕的","en":"If you describe someone as guarded, you mean that they are careful not to show their feelings or give away information.","ex":{"en":"The boy gave him a guarded look","cn":"那个男孩充满戒心地瞧了他一眼。"}}]},"examples":[{"en":"They gave the news a guarded welcome (= did not show great enthusiasm about it).","cn":"他们对这消息表示谨慎的欢迎。"},{"en":"You should be more guarded in what you say to reporters.","cn":"你对记者说话应更谨慎些。"}],"base":"guard"},"gathering":{"oxford":{"phon":"ˈɡæðərɪŋ","pos":"noun","senses":[{"en":"a meeting of people for a particular purpose","cn":"聚集；聚会；集会","g":"[countable]","ex":{"en":"a social/family gathering","cn":"社交／家庭聚会"}},{"en":"the process of collecting something","cn":"收集；采集；搜集","g":"[uncountable]","ex":{"en":"methods of information gathering","cn":"信息采集的各种方法"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"集会；聚会","en":"A gathering is a group of people meeting together for a particular purpose.","ex":{"en":"...the twenty-second annual gathering of the South Pacific Forum.","cn":"第22届南太平洋论坛年会"}},{"pos":"ADJ 形容词","cn":"（夜色）渐浓的，逐渐变黑的","en":"If there is gathering darkness, the light is gradually decreasing, usually because it is nearly night.","ex":{"en":"The lighthouse beam was quite distinct in the gathering dusk.","cn":"灯塔的光束在渐浓的暮色中清晰可见。"}}]},"media":{"uk":"media/uk/gathering__gb_1.mp3","us":"media/us/gathering__us_1.mp3"},"examples":[{"en":"methods of information gathering","cn":"信息采集的各种方法"},{"en":"a social/family gathering","cn":"社交/家庭聚会"}],"base":"gather"},"gene":{"oxford":{"phon":"dʒiːn","pos":"noun","senses":[{"en":"a unit inside a cell that controls a particular quality in a living thing that has been passed on from its parents","cn":"基因","ex":{"en":"a dominant/recessive gene","cn":"显性／隐性基因"}},{"en":"a first name for boys, short for Eugene","cn":"吉恩（男子名，Eugene缩写）","pos":""}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"基因","en":"A gene is the part of a cell in a living thing which controls its physical characteristics, growth, and development."}]},"media":{"uk":"media/uk/gene__gb_1.mp3","us":"media/us/gene__us_1.mp3"},"examples":[{"en":"I've always enjoyed music — it's in the genes.","cn":"我向来喜欢音乐，这是拜父母所赐。"},{"en":"genes that code for the colour of the eyes","cn":"为眼睛的颜色编码的基因"}]},"gatekeeper":{"media":{"uk":"media/uk/gatekeeper__gb_1.mp3","us":"media/us/gatekeeper__us_1.mp3"},"oxford":{"phon":"ˈɡeɪtkiːpə(r)","pos":"noun","senses":[{"en":"a person whose job is to check and control who is allowed to go through a gate","cn":"看门人；守门人；门卫"},{"en":"a person, system, etc. that decides whether somebody/something will be allowed, or allowed to reach a particular place or person","cn":"看门人；把关系统","ex":{"en":"His secretary acts as a gatekeeper, reading all mail before it reaches her boss.","cn":"老板的秘书负责把关，所有邮件都由她先过目再呈送给老板。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"看门人；守门人","en":"A gatekeeper is a person who is in charge of a gate and who allows people through it."}]},"examples":[{"en":"His secretary acts as a gatekeeper, reading all mail before it reaches her boss.","cn":"老板的秘书负责把关，所有邮件都由她先过目再呈送给老板。"}]},"glassy":{"media":{"uk":"media/uk/glassy__gb_1.mp3","us":"media/us/glassy__us_1.mp3"},"oxford":{"phon":"ˈɡlɑːsi","pos":"adjective","senses":[{"en":"like glass; smooth and shiny","cn":"像玻璃一样的；光滑透亮的","ex":{"en":"a glassy lake","cn":"平静清澈的湖水"}},{"en":"showing no feeling or emotion","cn":"无表情的；木然的；呆滞的","ex":{"en":"glassy eyes","cn":"目光呆滞的眼睛"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"像玻璃一样的；光滑的；光亮透明的","en":"If you describe something as glassy, you mean that it is very smooth and shiny, like glass.","ex":{"en":"The water was glassy.","cn":"水面清澈明亮。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（眼神或表情）呆滞的，无表情的","en":"If you describe someone's eyes or expression as glassy, you mean that they are showing no feeling, emotion, or awareness.","ex":{"en":"He was very still, his eyes glassy","cn":"他纹丝不动，目光呆滞。"}}]},"examples":[{"en":"He looked flushed and glassy-eyed.","cn":"他显得满脸通红，目光呆滞。"},{"en":"a glassy look/stare","cn":"呆滞的神色/盯视"}]},"gin":{"oxford":{"phon":"dʒɪn","pos":"noun","senses":[{"en":"an alcoholic drink made from grain and with juniper berries added. Gin is usually drunk mixed with tonic or fruit juice.","cn":"杜松子酒","g":"[uncountable, countable]"},{"en":"a glass of gin","cn":"一杯杜松子酒","g":"[countable]","ex":{"en":"I'll have a gin and tonic, please.","cn":"请来一杯加奎宁水的杜松子酒。"}},{"en":"a machine for separating the seeds of a cotton plant from the cotton","cn":"轧棉机；轧花机"},{"en":"a device for catching small wild animals or birds","cn":"杜松子酒：一种捕获小型野生动物或鸟类的设备"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"杜松子酒","en":"Gin is a strong colourless alcoholic drink made from grain and juniper berries.","ex":{"en":"...another gin and tonic.","cn":"又一杯加奎宁水的杜松子酒"}}]},"media":{"uk":"media/uk/gin__gb_1.mp3","us":"media/us/gin__us_1.mp3"},"examples":[{"en":"I'll have a gin and tonic, please.","cn":"请来一杯加奎宁水的杜松子酒。"}]},"grasped":{"lemma":"grasp"},"group":{"media":{"uk":"media/uk/group__gb_1.mp3","us":"media/us/group__us_1.mp3"},"oxford":{"phon":"ɡruːp","pos":"noun","senses":[{"en":"a number of people or things that are together in the same place or that are connected in some way","cn":"组；群；批；类；簇","ex":{"en":"a group of people/students/friends","cn":"一伙人；一群学生；一帮朋友"}},{"en":"a number of people who work or do something together or share particular beliefs","cn":"伙；帮；组","ex":{"en":"The residents formed a community action group.","cn":"居民组成了社区行动组。"}},{"en":"a number of companies that are owned by the same person or organization","cn":"集团","lab":"business","ex":{"en":"This acquisition will make them the largest newspaper group in the world.","cn":"这次收购将使他们成为世界上最大的报业集团。"}},{"en":"a number of musicians who perform together, especially to play pop music","cn":"（尤指流行音乐的）演奏组，乐团，乐队","lab":"rather old-fashioned","ex":{"en":"She sings in a rock group.","cn":"她是摇滚乐队的歌手。"}},{"en":"to gather into a group; to make somebody/something form a group","cn":"（使）成群，成组，聚集","g":"[transitive, intransitive]","ex":{"en":"The children grouped themselves around their teacher.","cn":"孩子们聚集在老师周围。"},"pos":"verb"},{"en":"to divide people or things into groups of people or things that are similar in some way","cn":"将…分类；把…分组","g":"[transitive]","ex":{"en":"The books are grouped together by subject.","cn":"这些书按科目分类。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"（一）组；（一）群；（一）批","en":"A group of people or things is a number of people or things which are together in one place at one time.","ex":{"en":"The trouble involved a small group of football supporters","cn":"这次骚乱涉及一小撮足球迷。"}},{"pos":"N-COUNT 可数名词","cn":"集体；群体；团体","en":"A group is a set of people who have the same interests or aims, and who organize themselves to work or act together.","ex":{"en":"...the Minority Rights Group","cn":"少数民族权益团体"}},{"pos":"N-COUNT 可数名词","cn":"（具有共同点而被放在一起考虑的）组，群，类","en":"A group is a set of people, organizations, or things which are considered together because they have something in common.","ex":{"en":"She is among the most promising players in her age group","cn":"她是所在年龄组中最有前途的选手之一。"}},{"pos":"N-COUNT 可数名词","cn":"（企业）集团","en":"A group is a number of separate commercial or industrial firms which all have the same owner.","ex":{"en":"The group made a pre-tax profit of £11.05 million.","cn":"该集团的税前利润为1,105万英镑。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指流行乐的）乐队,乐团,组合","en":"A group is a number of musicians who perform together, especially ones who play popular music.","ex":{"en":"At school he played bass in a pop group called The Urge.","cn":"他上学的时候在一个叫“冲动”的流行乐队中担任贝司手。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）形成组；（把…）归在一起","en":"If a number of things or people are grouped together or group together, they are together in one place or within one organization or system.","ex":{"en":"The fact sheets are grouped into seven sections","cn":"这些资料被分成了7部分。"}}]},"examples":[{"en":"The colleges grouped together to offer a wider range of courses.","cn":"这些学院联合在一起，以开设范围更广的课程。"},{"en":"The proportion of single parent families varies between different income groups.","cn":"单亲家庭比例在不同收入群中各不相同。"}]},"granddaughter":{"oxford":{"phon":"ˈɡrændɔːtə(r)","pos":"noun","senses":[{"en":"a daughter of your son or daughter","cn":"（外）孙女"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"孙女；外孙女","en":"Someone's granddaughter is the daughter of their son or daughter.","ex":{"en":"...a drawing of my granddaughter Amelia.","cn":"我孙女阿梅莉亚的一张素描"}}]},"media":{"uk":"media/uk/granddaughter__gb_1.mp3","us":"media/us/granddaughter__us_1.mp3"}},"graphite":{"oxford":{"phon":"ˈɡræfaɪt","pos":"noun","senses":[{"en":"a soft black mineral that is a form of carbon. Graphite is used to make pencils, to lubricate machines and in nuclear reactors.","cn":"石墨"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"石墨","en":"Graphite is a soft black substance that is a form of carbon. It is used in pencils and electrical equipment."}]},"media":{"uk":"media/uk/graphite__gb_1.mp3","us":"media/us/graphite__us_1.mp3"}},"grave":{"media":{"uk":"media/uk/grave__gb_1.mp3","us":"media/us/grave__us_1.mp3"},"oxford":{"phon":"ɡreɪv","pos":"noun","senses":[{"en":"a place in the ground where a dead person is buried","cn":"坟墓；墓穴；坟头","ex":{"en":"We visited Grandma's grave.","cn":"我们给祖母扫了墓。"}},{"en":"a way of referring to death or a person’s death","cn":"死亡","g":"[singular]","lab":"usually literary","ex":{"en":"Is there life beyond the grave (= life after death)?","cn":"人死后有来生吗？"}},{"en":"very serious and important; giving you a reason to feel worried","cn":"严重的；重大的；严峻的；深切的","ex":{"en":"The police have expressed grave concern about the missing child's safety.","cn":"警方对失踪孩子的安全深表关注。"},"pos":"adjective"},{"en":"serious in manner, as if something sad or important has just happened","cn":"严肃的；庄严的；表情沉重的","ex":{"en":"He looked very grave as he entered the room.","cn":"他进入房间时表情非常严肃。"},"pos":"adjective"},{"en":"a mark placed over a vowel in some languages to show how it should be pronounced, as over the e in the French word père","cn":"钝重音符，沉音符，抑音符（标在元音上面表发音）"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"墓穴；坟墓；埋葬处","en":"A grave is a place where a dead person is buried.","ex":{"en":"They used to visit her grave twice a year.","cn":"他们以前每年去她的墓前凭吊两次。"}},{"pos":"N-COUNT 可数名词","cn":"死亡;终结","en":"You can refer to some-one's death as their grave or to death as the grave .","ex":{"en":"...drinking yourself to an early grave","cn":"纵酒而自折其寿"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"严重的；重大的；严峻的","en":"A grave event or situation is very serious, important, and worrying.","ex":{"en":"He said that the situation in his country is very grave","cn":"他说他的国家情况十分危急。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"严肃的；表情沉重的","en":"A grave person is quiet and serious in their appearance or behaviour.","ex":{"en":"William was up on the roof for some time and when he came down he looked grave","cn":"威廉在屋顶上呆了一段时间，他下来的时候面色凝重。"}},{"pos":"ADJ 形容词","cn":". 重音符;抑音符;沉音符","en":"In some languages such as French, a grave accent is a symbol that is placed over a vowel in a word to show how the vowel is pronounced. For example, the word 'mère' has a grave accent over the first 'e'"},{"pos":"PHRASE 短语","cn":"自掘坟墓；自取灭亡","en":"If you say that someone is digging their own grave, you are warning them that they are doing something foolish or dangerous that will cause their own failure.","ex":{"en":"The magazine isn't trying to ruin his career, the man's digging his own grave by refusing an interview.","cn":"这份杂志并非想断送他的事业，而他拒绝接受采访就是在自毁前程。"}},{"pos":"PHRASE 短语","cn":"九泉之下不得安宁","en":"If you say that someone who is dead would turn in their grave at something that is happening now, you mean that they would be very shocked or upset by it, if they were alive.","ex":{"en":"Darwin must be turning in his grave at the thought of what is being perpetrated in his name.","cn":"一想到冒他之名所做下的那些事，达尔文在九泉之下一定不得安宁。"}},{"pos":"","cn":"","en":"from the cradle to the grave→see: ;"}]},"examples":[{"en":"My father would turn in his grave if he knew.","cn":"我父亲知道的话在九泉之下也会不得安宁的。"},{"en":"The consequences will be very grave if nothing is done.","cn":"如果不采取任何措施后果将会是非常严重的。"}]},"guidebook":{"media":{"uk":"media/uk/guidebook__gb_1.mp3","us":"media/us/guidebook__us_1.mp3"},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"旅行指南","en":"A guidebook is a book that gives tourists information about a town, area, or country."},{"pos":"N-COUNT 可数名词","cn":"指南；手册","en":"A guidebook is a book that gives you information or instructions to help you do or understand something.","ex":{"en":"In 1987 Congressional Quarterly published a series of guidebooks to American politics.","cn":"1987年《国会季刊》出版了一系列美国政治指南读物。"}}]},"examples":[{"en":"travel guidebooks","cn":"旅游手册"}],"oxford":{"phon":"ˈɡaɪdbʊk","pos":"noun","senses":[{"en":"a book that gives information about a place for travellers or tourists","cn":"旅游指南（或手册）","ex":{"en":"a guidebook to Switzerland","cn":"瑞士旅游指南"}}]}},"gradual":{"media":{"uk":"media/uk/gradual__gb_1.mp3","us":"media/us/gradual__us_1.mp3"},"oxford":{"phon":"ˈɡrædʒuəl","pos":"adjective","senses":[{"en":"happening slowly over a long period; not sudden","cn":"逐渐的；逐步的；渐进的","ex":{"en":"a gradual change in the climate","cn":"气候的逐渐变化"}},{"en":"not steep","cn":"平缓的；不陡的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"逐渐的；逐步的","en":"A gradual change or process occurs in small stages over a long period of time, rather than suddenly.","ex":{"en":"Losing weight is a slow, gradual process","cn":"减肥是一个缓慢而渐进的过程。"}}]},"examples":[{"en":"Recovery from the disease is very gradual.","cn":"这种疾病的康复过程缓慢。"},{"en":"a gradual change in the climate","cn":"气候的逐渐变化"}]},"glove":{"oxford":{"phon":"ɡlʌv","pos":"noun","senses":[{"en":"a piece of clothing for the hand, made of wool, leather, etc. with separate parts for each finger and the thumb","cn":"（分手指的）手套","ex":{"en":"a pair of gloves","cn":"一副手套"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（分手指的）手套","en":"Gloves are pieces of clothing which cover your hands and wrists and have individual sections for each finger. You wear gloves to keep your hands warm or dry or to protect them.","ex":{"en":"He stuck his gloves in his pocket.","cn":"他把手套塞进口袋里。"}},{"pos":"PHRASE 短语","cn":"正合适；完全相配","en":"If you say that something fits like a glove, you are emphasizing that it fits exactly."},{"pos":"See also:","cn":"","en":"hand in glove→see: ;"}]},"media":{"img":["media/pic/gloves_accessories_comp.jpg","media/thumb/glove.jpg"],"uk":"media/uk/glove__gb_1.mp3","us":"media/us/glove__us_1.mp3"},"examples":[{"en":"gardening gloves","cn":"园艺用手套"},{"en":"a pair of gloves","cn":"一副手套"}]},"gloves":{"lemma":"glove"},"green":{"media":{"img":["media/pic/hobbies_comp.jpg","media/thumb/golf.jpg"],"uk":"media/uk/green__gb_1.mp3","us":"media/us/green__us_1.mp3"},"oxford":{"phon":"ɡriːn","pos":"adjective","senses":[{"en":"having the colour of grass or the leaves of most plants and trees","cn":"绿色的；草绿色的","sc":"colour","ex":{"en":"green grass/leaves/vegetables","cn":"绿草；绿叶；绿叶蔬菜"}},{"en":"covered with grass or other plants","cn":"长满青草的；布满植被的；绿油油的；青葱的","sc":"covered with grass","ex":{"en":"green fields/pastures/hills","cn":"绿油油的农田；绿色的草地；葱绿的山丘"}},{"en":"not yet ready to eat","cn":"未成熟的","sc":"fruit","ex":{"en":"green tomatoes","cn":"青西红柿"}},{"en":"connected with the protection of the environment; supporting the protection of the environment as a political principle","cn":"环境保护的；主张环保的","sc":"politics","ex":{"en":"green energy","cn":"绿色能源"}},{"en":"young and without experience","cn":"幼稚无经验的；不成熟的","lab":"informal","sc":"person","ex":{"en":"The new trainees are still very green.","cn":"这些受培训的新学员还很不成熟。"}},{"en":"being a pale colour, as if the person is going to vomit","cn":"苍白的；发青的；无血色的","sc":"person","ex":{"en":"It was a rough crossing and most of the passengers looked distinctly green.","cn":"渡海时风浪很大，多数乘客看上去脸色发青。"}},{"en":"the colour of grass and the leaves of most plants and trees","cn":"绿色；草绿色","g":"[uncountable, countable]","sc":"colour","ex":{"en":"light/pale green","cn":"浅绿色"},"pos":"noun"},{"en":"vegetables with dark green leaves, for example cabbage or spinach","cn":"青菜，绿叶菜（如卷心菜、菠菜）","g":"[plural]","sc":"vegetables","ex":{"en":"Eat up your greens.","cn":"把你那份青菜都吃了吧。"},"pos":"noun"},{"en":"an area of grass, especially in the middle of a town or village","cn":"（尤指城镇或村庄中心的）草地，草坪，公共绿地","g":"[countable]","lab":"British English","sc":"area of grass","ex":{"en":"Children were playing on the village green.","cn":"孩子们在村子里的公共草坪上玩耍。"},"pos":"noun"},{"en":"an area of grass cut short around a hole on a golf course","cn":"球穴区，果岭（高尔夫球洞口附近草修得很平整的地区）","g":"[countable]","sc":"area of grass","ex":{"en":"the 18th green","cn":"第 18 洞果岭"},"pos":"noun"},{"en":"the Green Party (= the party whose main aim is the protection of the environment)","cn":"绿党（以保护环境为主要目标）","g":"[plural]","sc":"politics","pos":"noun"},{"en":"to create parks and other areas with trees and plants in a city","cn":"绿化","sc":"create parks","ex":{"en":"projects for greening the cities","cn":"绿化城市的方案"},"pos":"verb"},{"en":"to make somebody more aware of issues connected with the environment; to make something appear friendly towards the environment","cn":"使增强环境保护意识；使善待环境","sc":"politics","ex":{"en":"an attempt to green industry bosses","cn":"使企业老板重视环境保护的努力"},"pos":"verb"}]},"collins":{"senses":[{"pos":"COLOUR 颜色词","cn":"绿；绿色","en":"Green is the colour of grass or leaves.","ex":{"en":"...shiny red and green apples","cn":"红红绿绿、富有光泽的苹果"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"长满青草的；绿油油的；碧绿的","en":"A place that is green is covered with grass, plants, and trees and not with houses or factories.","ex":{"en":"Cairo has only thirteen square centimetres of green space for each inhabitant.","cn":"开罗居民的人均绿地面积仅13平方厘米。"}},{"pos":"ADJ 形容词","cn":"环境保护的；主张环境保护的","en":"Green issues and political movements relate to or are concerned with the protection of the environment.","ex":{"en":"The power of the Green movement in Germany has made that country a leader in the drive to recycle more waste materials.","cn":"德国环保运动的影响力使得该国率先发起了回收利用更多废品的运动。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有利于环境的；环保的；绿色的","en":"If you say that someone or something is green, you mean they harm the environment as little as possible.","ex":{"en":"...trying to persuade governments to adopt greener policies","cn":"试图说服政府采取更为环保的政策"}},{"pos":"N-COUNT 可数名词","cn":"绿党成员（主张环境保护）","en":"Greens are members of green political movements.","ex":{"en":"The Greens see themselves as a radical alternative to the two major British political parties.","cn":"绿党人士认为他们与英国的两个主要政党截然不同。"}},{"pos":"N-COUNT 可数名词","cn":"（高尔夫球场的）球穴区，果岭","en":"A green is a smooth, flat area of grass around a hole on a golf course.","ex":{"en":"...the 18th green.","cn":"第18洞轻击区"}},{"pos":"N-COUNT 可数名词","cn":"（尤指城市或村庄中心的）草坪，绿地","en":"A green is an area of land covered with grass, especially in a town or in the middle of a village.","ex":{"en":"...the village green.","cn":"村子里的草坪"}},{"pos":"N-IN-NAMES 名称名词","cn":"（用于有绿地或过去有绿地的地方中）","en":"Green is used in the names of places that contain or used to contain an area of grass.","ex":{"en":"...Bethnal Green.","cn":"贝斯纳尔格林区"}},{"pos":"N-PLURAL 复数名词","cn":"绿叶菜；青菜","en":"You can refer to the cooked leaves of vegetables such as spinach or cabbage as greens .","ex":{"en":"Eat your greens.","cn":"把青菜吃掉。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"未熟的；青的；生的","en":"You can describe fruit and vegetables as green when they are unripe and not ready to be eaten.","ex":{"en":"Pick and ripen any green fruits in a warm dark place.","cn":"摘些还没有熟的水果然后在温暖阴暗的地方放熟。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"缺乏经验的；不成熟的；幼稚的","en":"If you say that someone is green, you mean that they have had very little experience of life or a particular job.","ex":{"en":"He was a young lad, very green, very immature.","cn":"他还是个毛头小子，幼稚得很，一点都不成熟。"}},{"pos":"PHRASE 短语","cn":"非常嫉妒的；眼红的","en":"If you say that someone is green with envy, you mean that they are very envious indeed."},{"pos":"PHRASE 短语","cn":"高超的园艺技能","en":"If someone has green fingers, they are very good at gardening and their plants grow well.","ex":{"en":"You don't need green fingers to fill your home with lush leaves.","cn":"不是园艺大师也可以把自己的家里装点得绿意盎然。"}},{"pos":"","cn":"","en":"to give someone the green light→see: ;"}]},"examples":[{"en":"The room was decorated in a combination of greens and blues.","cn":"这房间是把不同的绿色和蓝色搭配起来装饰的。"},{"en":"It was a rough crossing and most of the passengers looked distinctly green.","cn":"渡海时风浪很大，多数乘客看上去脸色发青。"}]},"governor":{"media":{"uk":"media/uk/governor__gb_1.mp3","us":"media/us/governor__us_1.mp3"},"oxford":{"phon":"ˈɡʌvənə(r)","pos":"noun","senses":[{"en":"a person who is the official head of a country or region that is governed by another country","cn":"统治者；管辖者；总督","ex":{"en":"the former governor of the colony","cn":"该殖民地的前总督"}},{"en":"a person who is chosen to be in charge of the government of a state in the US","cn":"（美国的）州长","ex":{"en":"the governor of Arizona","cn":"亚利桑那州州长"}},{"en":"a member of a group of people who are responsible for controlling an institution such as a school, a college or a hospital","cn":"（学校、学院、医院等机构的）董事，理事","lab":"especially British English","ex":{"en":"One way of getting things changed is to become a school governor.","cn":"要使情况发生改变，一个办法是成为学校的董事。"}},{"en":"a person who is in charge of an institution","cn":"主管；机构负责人；总裁","lab":"British English","ex":{"en":"A copy of the report was sent to the prison governor.","cn":"报告的一份复印件送交给了监狱长。"}}]},"collins":{"senses":[{"pos":"N-COUNT; N-TITLE 可数名词；头衔名词","cn":"州长；省长；总督","en":"In some systems of government, a governor is a person who is in charge of the political administration of a region or state.","ex":{"en":"He was governor of the province in the late 1970s","cn":"他在20世纪70年代末担任该省的省长。"}},{"pos":"N-COUNT 可数名词","cn":"（学校、医院等的)董事,理事","en":"A governor is a member of a committee which controls an organization such as a school or a hospital.","ex":{"en":"Governors are using the increased powers given to them to act against incompetent headteachers.","cn":"董事们运用赋予他们的更大权力罢免不称职的校长。"}},{"pos":"N-COUNT 可数名词","cn":"（英国一些机构的）主管,总裁","en":"In some British institutions, the governor is the most senior official, who is in charge of the institution.","ex":{"en":"The incident was reported to the prison governor.","cn":"这一事件已汇报给监狱长。"}}]},"examples":[{"en":"( informal ) I can't decide. I'll have to ask the governor (= the man in charge, who employs sb).","cn":"我做不了主，我得问问老板。"},{"en":"the former governor of the colony","cn":"该殖民地的前总督"}]},"guide":{"media":{"uk":"media/uk/guide__gb_1.mp3","us":"media/us/guide__us_1.mp3"},"oxford":{"phon":"ɡaɪd","pos":"noun","senses":[{"en":"a person who shows other people the way to a place, especially somebody employed to show tourists around interesting places","cn":"导游；向导","sc":"person","ex":{"en":"Our tour guide showed us around the old town.","cn":"导游领着我们转遍了整个古镇。"}},{"en":"a person who advises you on how to live and behave","cn":"指导者；指引者","sc":"person","ex":{"en":"A guru is the spiritual guide of his students.","cn":"导师是学生的精神导师。"}},{"en":"a book, magazine, app, etc. that gives you information, help or instructions about something","cn":"指南；手册","sc":"book/magazine","ex":{"en":"Let's have a look at the TV guide and see what's on.","cn":"咱们看一下节目表，好知道电视上在放些什么。"}},{"en":"a book that gives information about a place for travellers or tourists","cn":"旅游指南（或手册）","sc":"book/magazine","ex":{"en":"He has written a number of travel guides.","cn":"他写了几本旅游指南。"}},{"en":"something that gives you enough information to be able to make a decision about something or form an opinion","cn":"有指导意义的事物；指导的事物","sc":"something that helps you decide","ex":{"en":"As a rough guide, allow half a cup of rice per person.","cn":"大致定个标准，就是每人半杯米。"}},{"en":"a member of an organization (called the Guides or the Girl Scouts) that is similar to the Scouts and that trains girls in practical skills and does a lot of activities with them, for example camping","cn":"女童子军","lab":"old-fashioned","sc":"girl"},{"en":"to show somebody the way to a place, often by going with them; to show somebody a place that you know well","cn":"给某人领路（或导游）；指引","sc":"show the way","ex":{"en":"It's a dangerous route—you'll need someone to guide you.","cn":"这是一条危险的路线——你需要有人来引导你。"},"pos":"verb"},{"en":"to direct or influence somebody’s behaviour or the development of something","cn":"指导，影响（某人的行为或某事物的发展）","sc":"influence behaviour/development","ex":{"en":"He was always guided by his religious beliefs.","cn":"他的言行总是以自己的宗教信仰为依归。"},"pos":"verb"},{"en":"to explain something to somebody, especially something complicated or difficult","cn":"（向某人）解释，阐明","sc":"explain","ex":{"en":"The health and safety officer will guide you through the safety procedures.","cn":"健康安全专员会向你们讲解安全程序。"},"pos":"verb"},{"en":"to help somebody/something to move in a particular direction; to move something in a particular direction","cn":"搀扶（某人朝…方向）走；（朝…方向）移动（某物）","lab":"figurative","sc":"help somebody/something move","ex":{"en":"She took her arm and guided her across the busy road.","cn":"她挽着她的手臂领她穿过繁忙的公路。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-PROPER-COLL 专有集合名词","cn":"（英国的）女童子军（美国为Girl Scout）","en":"In Britain, the Guides is an organization for girls which teaches them to become practical and independent. The Guides used to be called the Girl Guides. In the United States, there is a similar organization called the Girl Scouts."},{"pos":"N-COUNT 可数名词","cn":"（英国的）女童子军成员","en":"In Britain, a Guide is a girl who is a member of the Guides."}]},"examples":[{"en":"Let's have a look at the TV guide and see what's on.","cn":"咱们看一下节目表，好知道电视上在放些什么。"},{"en":"We hired a local guide to get us across the mountains.","cn":"我们雇了一名当地人做向导带领我们翻山越岭。"}]},"grocers":{"lemma":"grocer"},"given":{"media":{"uk":"media/uk/given__gb_2.mp3","us":"media/us/given__us_2.mp3"},"oxford":{"phon":"ˈɡɪvn","pos":"adjective","senses":[{"en":"already arranged","cn":"已经安排好的；规定的","ex":{"en":"They were to meet at a given time and place.","cn":"他们要在规定的时间和地点会晤。"}},{"en":"that you have stated and are discussing; particular","cn":"指定的；所述的；特定的","ex":{"en":"We can find out how much money is spent on food in any given period.","cn":"我们可以查明在特定时间内花在食物上的钱有多少。"}},{"en":"when you consider something","cn":"考虑到；鉴于","ex":{"en":"Given his age (= considering how old he is), he's remarkably active.","cn":"考虑到他的年龄，他已是相当活跃的了。"},"pos":"preposition"},{"en":"something that is accepted as true, for example when you are discussing something, or planning something","cn":"认定的事实","pos":"noun"}]},"collins":{"senses":[{"pos":"","cn":"","en":"Given is the past participle of give ."},{"pos":"ADJ 形容词","cn":"特定的；指定的","en":"If you talk about, for example, any given position or a given time, you mean the particular position or time that you are discussing.","ex":{"en":"In chess there are typically about 36 legal moves from any given board position","cn":"在国际象棋中，一般来说从棋盘任何位置都可以移动大约36步。"}},{"pos":"PREP 介词","cn":"如果有（机会等）","en":"Given is used when indicating a possible situation in which someone has the opportunity or ability to do something. For example, given the chance means 'if I had the chance'.","ex":{"en":"Write down the sort of thing you would like to do, given the opportunity","cn":"写下有机会的话你想做的事情。"}},{"pos":"PHR-CONJ-SUBORD","cn":"考虑到；鉴于","en":"If you say given that something is the case, you mean taking that fact into account.","ex":{"en":"Usually, I am sensible with money, as I have to be, given that I don't earn that much.","cn":"考虑到自己挣得不多，我用钱通常比较精打细算，这也是迫不得已。"}},{"pos":"PREP 介词","cn":"考虑到","en":"If you say given something, you mean taking that thing into account.","ex":{"en":"Given the uncertainty over Leigh's future I was left with little other choice.","cn":"考虑到利前途未卜，我没有什么选择余地。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"经常的；习惯的","en":"If you are given to doing something, you often do it.","ex":{"en":"I am not very given to emotional displays.","cn":"我不习惯表露自己的感情。"}}]},"examples":[{"en":"We can find out how much money is spent on food in any given period.","cn":"我们可以查明在特定时间内花在食物上的钱有多少。"},{"en":"It was surprising the government was re-elected, given that they had raised taxes so much.","cn":"令人惊奇的是政府把税收提高这么多仍再次当选了。"}]},"gossip":{"media":{"uk":"media/uk/gossip__gb_1.mp3","us":"media/us/gossip__us_1.mp3"},"oxford":{"phon":"ˈɡɒsɪp","pos":"noun","senses":[{"en":"informal talk or stories about other people’s private lives, which may be unkind or not true","cn":"流言蜚语；闲言碎语","g":"[uncountable]","lab":"usually disapproving","ex":{"en":"Don't believe all the gossip you hear.","cn":"别对那些道听途说都信以为真。"}},{"en":"a conversation about other people and their private lives","cn":"闲聊","g":"[countable, usually singular]","ex":{"en":"I love a good gossip.","cn":"我喜欢闲聊天。"}},{"en":"a person who enjoys talking about other people’s private lives","cn":"喜欢传播流言蜚语的人；爱说长道短（或说三道四）的人","g":"[countable]","lab":"disapproving","ex":{"en":"The people I work with are terrible gossips.","cn":"和我一起工作的人都是可怕的八卦者。"}},{"en":"to talk about other people’s private lives, often in an unkind way","cn":"传播流言蜚语；说三道四；说长道短","ex":{"en":"I can't stand here gossiping all day.","cn":"我不能整天站在这儿闲聊啊。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"流言蜚语；小道消息；闲话","en":"Gossip is informal conversation, often about other people's private affairs.","ex":{"en":"He spent the first hour talking gossip","cn":"他头一个小时都在闲聊。"}},{"pos":"V-RECIP 相互动词","cn":"闲聊；说长道短","en":"If you gossip with someone, you talk informally, especially about other people or local events. You can also say that two people gossip .","ex":{"en":"We spoke, debated, gossiped into the night","cn":"我们交谈着，争论着，闲聊着，一直持续到晚上。"}},{"pos":"N-COUNT 可数名词","cn":"爱说长道短的人","en":"If you describe someone as a gossip, you mean that they enjoy talking informally to people about the private affairs of others.","ex":{"en":"He was a vicious gossip.","cn":"他总是喜欢说别人的坏话。"}}]},"examples":[{"en":"The gossip was that he had lost a fortune on the stock exchange.","cn":"有小道消息说他在股票交易中赔了一大笔钱。"},{"en":"Tell me all the latest gossip!","cn":"把最新的小道消息都讲给我听听吧！"}]},"gdp":{"media":{"uk":"media/uk/gdp__gb_1.mp3","us":"media/us/gdp__us_1.mp3"},"oxford":{"phon":"ˌdʒiː diː ˈpiː","pos":"noun","senses":[{"en":"the total value of all the goods and services produced by a country in one year (the abbreviation for ‘gross domestic product’)","cn":"国内生产总值（全写为 gross domestic product）","ex":{"en":"GDP grew 5.8 percent in the first quarter.","cn":"一季度GDP增长5.8%。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"国内生产总值","en":"In economics, a country's GDP is the total value of goods and services produced within a country in a year, not including its income from investments in other countries. GDP is an abbreviation for (缩略=) 'gross domestic product'."}]}},"guardian":{"oxford":{"phon":"ˈɡɑːdiən","pos":"noun","senses":[{"en":"a person who protects something","cn":"保护者；守卫者；保卫者","ex":{"en":"Farmers should be guardians of the countryside.","cn":"农民应是农村的守卫者。"}},{"en":"a person who is legally responsible for the care of another person, especially a child whose parents have died","cn":"（尤指双亲已故孩子的）监护人","ex":{"en":"I was left alone to live with my aunt, who became my legal guardian.","cn":"我被孤零零地撇下跟姨妈生活，她成了我的法定监护人。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"监护人","en":"A guardian is someone who has been legally appointed to look after the affairs of another person, for example a child or someone who is mentally ill."},{"pos":"N-COUNT 可数名词","cn":"保护者；护卫者","en":"The guardian of something is someone who defends and protects it.","ex":{"en":"The National Party is lifting its profile as socially conservative guardian of traditional values.","cn":"国家党正在提升自己作为持社会保守立场的传统价值观捍卫者的形象。"}}]},"media":{"uk":"media/uk/guardian__gb_1.mp3","us":"media/us/guardian__us_1.mp3"},"examples":[{"en":"The police are guardians of law and order.","cn":"警察是法律和治安的护卫者。"},{"en":"Farmers should be guardians of the countryside.","cn":"农民应是农村的保卫者。"}]},"grammatically":{"oxford":{"phon":"ɡrəˈmætɪkli","pos":"adverb","senses":[{"en":"in a way that is connected with the rules of grammar","cn":"语法的；文法的","ex":{"en":"a grammatically correct sentence","cn":"语法正确的句子"}},{"en":"in a way that correctly follows the rules of grammar","cn":"符合语法规则的；合乎文法的","ex":{"en":"to speak grammatically","cn":"合乎语法地说话"}}]},"media":{"uk":"media/uk/grammatically__gb_1.mp3","us":"media/us/grammatically__us_1.mp3"},"examples":[{"en":"a grammatically correct sentence","cn":"语法上正确的句子"}]},"graphic":{"media":{"uk":"media/uk/graphic__gb_1.mp3","us":"media/us/graphic__us_1.mp3"},"oxford":{"phon":"ˈɡræfɪk","pos":"adjective","senses":[{"en":"connected with drawings and design, especially in the production of books, magazines, websites, etc.","cn":"绘画的；书画的；图样的；图案的","g":"[only before noun]","ex":{"en":"graphic design","cn":"平面设计"}},{"en":"very clear and full of details, especially about something unpleasant","cn":"（尤指令人不快的事物）形象的，生动的，逼真的","ex":{"en":"a graphic account/description of a battle","cn":"对战斗的生动叙述／描述"}},{"en":"a diagram or picture, especially one that appears on a computer screen or in a newspaper or book","cn":"（尤指电脑屏幕、报纸或书上的）图表，图形，图画","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（对令人不快之事的描述）形象的，具体的，活灵活现的","en":"If you say that a description or account of something unpleasant is graphic, you are emphasizing that it is clear and detailed.","ex":{"en":"The descriptions of sexual abuse are graphic.","cn":"这些性虐待的描写绘声绘色。"}},{"pos":"ADJ 形容词","cn":"绘画的；绘图的；图像的","en":"Graphic means concerned with drawing or pictures, especially in publishing, industry, or computing.","ex":{"en":"...fine and graphic arts.","cn":"美术与平面艺术"}},{"pos":"N-UNCOUNT 不可数名词","cn":"绘画；(尤指出版、工业或计算机领域的)制图,图形设计","en":"Graphics is the activity of drawing or making pictures, especially in publishing, industry, or computing.","ex":{"en":"...a computer manufacturer which specialises in graphics.","cn":"专注于图形设计的计算机制造商"}},{"pos":"N-COUNT 可数名词","cn":"绘画作品；图表；图样","en":"Graphics are drawings and pictures that are composed using simple lines and sometimes strong colours.","ex":{"en":"The articles are noticeably shorter with strong headlines and graphics","cn":"这些文章明显短了许多，并且配上了醒目的标题和图表。"}}]},"examples":[{"en":"He kept telling us about his operation, in the most graphic detail.","cn":"他不停地向我们绘声绘色地讲述他动手术的详细情况。"},{"en":"a graphic account/description of a battle","cn":"对战斗的生动叙述/描述"}]},"gleefully":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"feeling happy because something good has happened or is going to happen","cn":""},{"en":"happy and satisfied that something has happened, especially something that has happened to someone else or something good they have done","cn":""}]},"media":{"uk":"media/uk/gleefully__gb_1.mp3","us":"media/us/gleefully__us_1.mp3"},"oxford":{"phon":"ˈɡliːfəli","pos":"adverb","senses":[{"en":"in a happy way because of something good you have done or something bad that has happened to somebody else","cn":"欢喜的；高兴的；幸灾乐祸的","ex":{"en":"He gleefully told me about all the different diseases that I could catch.","cn":"他兴高采烈地告诉我我可能感染的所有不同疾病。"}}]}},"gratification":{"media":{"uk":"media/uk/gratification__gb_1.mp3","us":"media/us/gratification__us_1.mp3"},"oxford":{"phon":"ˌɡrætɪfɪˈkeɪʃn","pos":"noun","senses":[{"en":"the state of feeling pleasure when something goes well for you or when your desires are satisfied; something that gives you pleasure","cn":"满足；满意；快感；令人喜悦的事物","ex":{"en":"sexual gratification","cn":"性满足"}}]},"examples":[{"en":"A feed will usually provide instant gratification to a crying baby.","cn":"喂食通常可使正在哭闹的婴儿立即得到满足。"},{"en":"sexual gratification","cn":"性满足"}]},"grocery":{"media":{"uk":"media/uk/grocery__gb_1.mp3","us":"media/us/grocery__us_1.mp3","img":["media/ldoce/img/grocery_bag.jpg"]},"oxford":{"phon":"ˈɡrəʊsəri","pos":"noun","senses":[{"en":"a shop that sells food and other things used in the home. In American English ‘grocery store’ is often used to mean ‘supermarket’.","cn":"食品杂货店（在美式英语中 grocery store 常指 supermarket）","g":"[countable]","lab":"especially British English","ex":{"en":"the corner grocery store","cn":"街角处的杂货店"}},{"en":"food and other goods sold by a grocer or at a supermarket","cn":"食品杂货","g":"[plural]","lab":"especially British English","ex":{"en":"He walked in and set the bag of groceries down on the floor.","cn":"他走进来，把那袋食品杂货放在地板上。"}},{"en":"connected with food and other goods sold by a grocer or at a supermarket","cn":"食品杂货","ex":{"en":"the grocery bill","cn":"食品杂货账单"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"食品杂货店","en":"A grocery or a grocery store is a grocer's shop."},{"pos":"N-PLURAL 复数名词","cn":"食品杂货","en":"Groceries are foods you buy at a grocer's or at a supermarket such as flour, sugar, and tinned foods."}]},"examples":[{"en":"the grocery bill","cn":"食品杂货账单"}]},"gravy":{"oxford":{"phon":"ˈɡreɪvi","pos":"noun","senses":[{"en":"a brown sauce made by adding flour to the juices that come out of meat while it is cooking","cn":"（调味）肉汁","g":"[uncountable, countable]"},{"en":"something, especially money, that is obtained when you do not expect it","cn":"意外之财；飞来福","g":"[uncountable]","lab":"North American English, informal，，","ex":{"en":"Anything on top of eight percent profit is just gravy for the industry.","cn":"任何高于百分之八利润的东西都只是这个行业的肉汁。"}}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"肉汁；肉卤","en":"Gravy is a sauce made from the juices that come from meat when it cooks."}]},"media":{"uk":"media/uk/gravy__gb_1.mp3","us":"media/us/gravy__us_1.mp3"}},"gulp":{"media":{"uk":"media/uk/gulp__gb_1.mp3","us":"media/us/gulp__us_1.mp3"},"oxford":{"phon":"ɡʌlp","pos":"verb","senses":[{"en":"to swallow large amounts of food or drink quickly","cn":"狼吞虎咽；大口吞咽；匆匆吞下","g":"[transitive]","ex":{"en":"He gulped down the rest of his tea and went out.","cn":"他把剩下的茶一饮而尽便出去了。"}},{"en":"to swallow, but without eating or drinking something, especially because of a strong emotion such as fear or surprise","cn":"（尤指因害怕或惊讶而）倒吸气","g":"[intransitive]","ex":{"en":"She gulped nervously before trying to answer.","cn":"她紧张地倒吸了一口气才尽力回答。"}},{"en":"to breathe quickly and deeply, because you need more air","cn":"深呼吸；喘大气；大口大口地吸气","g":"[intransitive, transitive]","ex":{"en":"She came up gulping for air.","cn":"她气喘吁吁地走上前来。"}},{"en":"an amount of something that you swallow or drink quickly","cn":"吞饮的量；一大口","ex":{"en":"He took a gulp of coffee.","cn":"他喝了一大口咖啡。"},"pos":"noun"},{"en":"an act of breathing in or of swallowing something","cn":"吸入；吞咽","ex":{"en":"‘Can you start on Monday?’ Amy gave a gulp. ‘Of course,’ she said.","cn":"“你星期一开始可以吗？”埃米吸了一口气。“当然可以。”她说。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"吞食；大口吃；狼吞虎咽","en":"If you gulp something, you eat or drink it very quickly by swallowing large quantities of it at once.","ex":{"en":"She quickly gulped her tea.","cn":"她将茶一饮而尽。"}},{"pos":"VERB 动词","cn":"（因紧张或兴奋）倒吸气","en":"If you gulp, you swallow air, often making a noise in your throat as you do so, because you are nervous or excited.","ex":{"en":"I gulped, and then proceeded to tell her the whole story","cn":"我倒吸了一口气，接着把事情的原委都讲给她听。"}},{"pos":"VERB 动词","cn":"大口大口地吸（气）","en":"If you gulp air, you breathe in a large amount of air quickly through your mouth.","ex":{"en":"She gulped air into her lungs","cn":"她大口大口地吸着气。"}},{"pos":"N-COUNT 可数名词","cn":"吞咽的量；一大口","en":"A gulp of air, food, or drink, is a large amount of it that you swallow at once.","ex":{"en":"I took in a large gulp of air","cn":"我深吸了一大口气。"}},{"pos":"","cn":"","en":"相关词组：gulp down"}]},"examples":[{"en":"‘Can you start on Monday?’ Amy gave a gulp. ‘Of course,’ she said. “","cn":"你星期一开始可以吗？”埃米吸了一口气。“当然可以。”她说。"},{"en":"She gulped nervously before trying to answer.","cn":"她紧张地倒吸了一口气才设法回答。"}]},"gross":{"media":{"uk":"media/uk/gross__gb_1.mp3","us":"media/us/gross__us_1.mp3"},"oxford":{"phon":"ɡrəʊs","pos":"adjective","senses":[{"en":"being the total amount of something before anything is taken away","cn":"（未扣除税费）总的，毛的","g":"[only before noun]","ex":{"en":"gross weight (= including the container or wrapping)","cn":"毛重"}},{"en":"very obvious and unacceptable","cn":"严重的","g":"[only before noun]","lab":"formal or law","ex":{"en":"gross negligence/misconduct","cn":"严重过失／失职"}},{"en":"very unpleasant","cn":"令人不快的；令人恶心的；使人厌恶的","lab":"informal","ex":{"en":"‘He ate it with mustard.’ ‘Oh, gross!’","cn":"“他用芥末拌着吃。”“啊，真恶心！”"}},{"en":"very rude","cn":"粗鲁的；不雅的","ex":{"en":"gross behaviour","cn":"粗鲁的行为"}},{"en":"very fat and ugly","cn":"肥胖而丑陋的"},{"en":"in total, before anything is taken away","cn":"（未扣除税费）总共","ex":{"en":"She earns £25 000 a year gross.","cn":"她税前年收入 25 000 英镑。"},"pos":"adverb"},{"en":"to earn a particular amount of money before tax has been taken off it","cn":"（未扣除税费）总收入为，总共赚得","ex":{"en":"It is one of the biggest grossing movies of all time.","cn":"这是有史以来票房总收入最高的影片之一。"},"pos":"verb"},{"en":"a group of 144 things","cn":"一罗（144 个）","ex":{"en":"two gross of apples","cn":"两罗苹果"},"pos":"noun"},{"en":"a total amount of money earned by something, especially a film, before any costs are taken away","cn":"（尤指影片的）毛收入，总收入","lab":"especially US English","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"重大的；严重的；极端的","en":"You use gross to describe something unacceptable or unpleasant to a very great amount, degree, or intensity.","ex":{"en":"The company were guilty of gross negligence.","cn":"该公司犯有严重过失。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（言语、行为）极端粗俗的，下流的","en":"If you say that someone's speech or behaviour is gross, you think it is very rude or unacceptable.","ex":{"en":"He abused the Admiral in the grossest terms","cn":"他用不堪入耳的话辱骂那位海军上将。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人不快的；让人恶心的；令人厌恶的","en":"If you describe something as gross, you think it is very unpleasant.","ex":{"en":"They had a commercial on the other night for Drug Free America that was so gross I thought Daddy was going to faint","cn":"他们前几天晚上为“美国远离毒品”组织播的那则广告非常恶心，我觉得爸爸看了都快晕过去了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"肥胖难看的；臃肿的","en":"If you describe someone as gross, you mean that they are extremely fat and unattractive.","ex":{"en":"I only resist things like chocolate if I feel really gross.","cn":"我只有在觉得自己胖得很难看的时候才能拒绝巧克力这类东西的诱惑。"}},{"pos":"ADJ 形容词","cn":"（尤指金额）总的，毛的","en":"Gross means the total amount of something, especially money, before any has been taken away.","ex":{"en":"...a fixed rate account guaranteeing 10.4% gross interest or 7.8% net until October.","cn":"10月份之前保证10.4%的毛利或7.8%的纯利收益的固定利率账户"}},{"pos":"ADJ 形容词","cn":"全部的；总计的","en":"Gross means the total amount of something, after all the relevant amounts have been added together.","ex":{"en":"National Savings gross sales in June totalled £709 million.","cn":"6月份国民储蓄机构的总销售额为7.09亿英镑。"}},{"pos":"ADJ 形容词","cn":"总重量的；毛重的","en":"Gross means the total weight of something, including its container or wrapping."},{"pos":"VERB 动词","cn":"（扣除税金前）总共赚得，总收入为","en":"If a person or a business grosses a particular amount of money, they earn that amount of money before tax has been taken away.","ex":{"en":"I'm a factory worker who grossed £12,900 last year","cn":"我是个工厂工人，去年的总收入为12,900英镑。"}},{"pos":"NUM 数词","cn":"罗（一罗为144个）","en":"A gross is a group of 144 things.","ex":{"en":"He ordered twelve gross of the disks.","cn":"他订购了12罗磁盘。"}},{"pos":"","cn":"","en":"相关词组：gross out"}]},"examples":[{"en":"‘He ate it with mustard.’ ‘Oh, gross!’ “","cn":"他用芥末拌着吃。” “啊，真恶心！”"},{"en":"She earns £25 000 a year gross.","cn":"她一年总收入为 25 000 英镑。"}]},"gentle":{"media":{"uk":"media/uk/gentle__gb_1.mp3","us":"media/us/gentle__us_1.mp3"},"oxford":{"phon":"ˈdʒentl","pos":"adjective","senses":[{"en":"calm and kind; doing things in a quiet and careful way","cn":"文静的；慈祥的；温柔的；细心的","ex":{"en":"a kind and gentle man","cn":"和善文雅的男士"}},{"en":"not strong or extreme","cn":"温和的；徐缓的","ex":{"en":"a gentle breeze","cn":"和风"}},{"en":"having only a small effect; not strong or violent","cn":"平和的；柔和的","ex":{"en":"We went for a gentle stroll.","cn":"我们溜达去了。"}},{"en":"not steep or sharp","cn":"平缓的","ex":{"en":"a gentle slope/curve","cn":"平缓的斜坡／弯道"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"文静的；温和的；和蔼的","en":"Someone who is gentle is kind, mild, and calm.","ex":{"en":"My son was a quiet and gentle man who liked sports and enjoyed life","cn":"我儿子是个安静温和的人，喜欢运动和享受生活。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（动作）轻柔的，徐缓的","en":"Gentle actions or movements are performed in a calm and controlled manner, with little force.","ex":{"en":"...a gentle game of tennis","cn":"不激烈的网球比赛"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（天气）温和的； （尤指风）和煦的，微弱的","en":"If you describe the weather, especially the wind, as gentle, you mean it is pleasant and calm and not harsh or violent.","ex":{"en":"The blustery winds of spring had dropped to a gentle breeze.","cn":"呼啸的春风已经减弱，成了习习的微风。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（斜坡或弯道）平缓的，不陡的","en":"A gentle slope or curve is not steep or severe.","ex":{"en":"...gentle, rolling meadows","cn":"缓缓起伏的牧场"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"微热的","en":"A gentle heat is a fairly low heat.","ex":{"en":"Cook for 30 minutes over a gentle heat.","cn":"用文火煮30分钟。"}}]},"examples":[{"en":"He looks scary but he's really a gentle giant.","cn":"他看上去可怕，实际却是个性格温和的巨人。"},{"en":"He lived in a gentler age than ours.","cn":"他生活的时代比我们这个时代更平静祥和。"}]},"gravitational":{"media":{"uk":"media/uk/gravitational__gb_1.mp3","us":"media/us/gravitational__us_1.mp3"},"oxford":{"phon":"ˌɡrævɪˈteɪʃənl","pos":"adjective","senses":[{"en":"connected with or caused by the force of gravity","cn":"引力的；重力引起的","ex":{"en":"a gravitational field","cn":"引力场"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"与引力有关的；引力所致的","en":"Gravitational means relating to or resulting from the force of gravity.","ex":{"en":"If a spacecraft travels faster than 11 km a second, it escapes the earth's gravitational pull.","cn":"如果飞行速度超过每秒11公里，宇宙飞船将摆脱地球的引力。"}}]},"examples":[{"en":"the gravitational pull of the moon","cn":"月球的引力"},{"en":"a gravitational field","cn":"引力场"}]},"genius":{"media":{"uk":"media/uk/genius__gb_1.mp3","us":"media/us/genius__us_1.mp3"},"oxford":{"phon":"ˈdʒiːniəs","pos":"noun","senses":[{"en":"unusually great intelligence, skill or artistic ability","cn":"天才；天资；天赋","g":"[uncountable]","ex":{"en":"the genius of Shakespeare","cn":"莎士比亚的天才"}},{"en":"a person who is unusually intelligent or artistic, or who has a very high level of skill, especially in one area","cn":"天才人物；（某领域的）天才","g":"[countable]","ex":{"en":"a mathematical/comic, etc. genius","cn":"数学、喜剧等天才"}},{"en":"a special skill or ability","cn":"（特别的）才能，本领","g":"[singular]","ex":{"en":"He had a genius for making people feel at home.","cn":"他有一种能够使人感觉轻松自在的本领。"}},{"en":"showing unusually great intelligence, skill or artistic ability","cn":"天才；天资；天赋","ex":{"en":"a genius idea","cn":"天才的想法"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"天才；天赋；天资","en":"Genius is very great ability or skill in a particular subject or activity.","ex":{"en":"This is the mark of her real genius as a designer","cn":"这展现了她作为设计师的真正天赋。"}},{"pos":"N-COUNT 可数名词","cn":"天才人物","en":"A genius is a highly talented, creative, or intelligent person.","ex":{"en":"Chaplin was not just a genius, he was among the most influential figures in film history.","cn":"卓别林不仅仅是天才，也是电影史上最有影响力的人物之一。"}}]},"examples":[{"en":"He had a genius for making people feel at home.","cn":"他有一种能够使人感觉轻松自在的本领。"},{"en":"He's a genius at organizing people.","cn":"他是人员组织方面的天才。"}]},"grassland":{"media":{"uk":"media/uk/grassland__gb_1.mp3","us":"media/us/grassland__us_1.mp3"},"oxford":{"phon":"ˈɡrɑːslænd","pos":"noun","senses":[{"en":"a large area of open land covered with wild grass","cn":"草原；草地；草场","ex":{"en":"turning grassland into farm land","cn":"把草地变成农田"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"草原；草地；草场","en":"Grassland is land covered with wild grass.","ex":{"en":"...areas of open grassland.","cn":"一片片开阔的草地"}}]}},"glowing":{"media":{"uk":"media/uk/glowing__gb_1.mp3","us":"media/us/glowing__us_1.mp3"},"oxford":{"phon":"ˈɡləʊɪŋ","pos":"adjective","senses":[{"en":"giving enthusiastic praise","cn":"热烈赞扬的；热情洋溢的","ex":{"en":"a glowing account/report/review","cn":"热情洋溢的叙述／报道／评论"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"热烈赞扬的；热情洋溢的","en":"A glowing description or opinion about someone or something praises them highly or supports them strongly.","ex":{"en":"The media has been speaking in glowing terms of the relationship between the two countries","cn":"媒体一直盛赞两国关系。"}}]},"examples":[{"en":"He spoke of her performance in the film in glowing terms (= praising her highly).","cn":"他热烈赞扬了她在影片中的表演。"},{"en":"a glowing account/report/review","cn":"热情洋溢的叙述/报道/评论"}],"base":"glow"},"grin":{"media":{"uk":"media/uk/grin__gb_1.mp3","us":"media/us/grin__us_1.mp3","img":["media/ldoce/img/grin.jpg"]},"oxford":{"phon":"ɡrɪn","pos":"verb","senses":[{"en":"to smile widely","cn":"露齿而笑；咧着嘴笑；粲然而笑","ex":{"en":"They grinned with delight when they heard our news.","cn":"他们得知我们的消息时高兴得直咧着嘴笑。"}},{"en":"a wide smile","cn":"露齿的笑；咧着嘴笑","ex":{"en":"She gave a broad grin.","cn":"她露出大大的笑容。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"露齿而笑；咧嘴大笑","en":"When you grin, you smile broadly.","ex":{"en":"He grins, delighted at the memory","cn":"想到往事，他开心地咧嘴笑了起来。"}},{"pos":"N-COUNT 可数名词","cn":"露齿的笑；咧嘴的笑","en":"A grin is a broad smile.","ex":{"en":"She came out of his office with a big grin on her face","cn":"她笑容满面地走出他的办公室。"}},{"pos":"PHRASE 短语","cn":"苦笑着忍受；默默承受","en":"If you grin and bear it, you accept a difficult or unpleasant situation without complaining because you know there is nothing you can do to make things better.","ex":{"en":"They cannot stand the sight of each other, but they will just have to grin and bear it.","cn":"他们连看对方一眼都不愿意，但是也只得默默忍受。"}}]},"examples":[{"en":"They grinned with delight when they heard our news.","cn":"他们得知我们的消息时高兴得直咧着嘴笑。"},{"en":"There's nothing we can do about it. We'll just have to grin and bear it.","cn":"对此我们无能为力，只好默默地忍受。"}]},"god":{"media":{"uk":"media/uk/god__gb_1.mp3","us":"media/us/god__us_1.mp3"},"oxford":{"phon":"ɡɒd","pos":"noun","senses":[{"en":"the being or spirit that is worshipped and is believed to have created the universe","cn":"上帝；天主；真主","g":"[singular]","lab":"North American English","ex":{"en":"Do you believe in God?","cn":"你信仰上帝吗？"}},{"en":"(in some religions) a being or spirit who is believed to have power over a particular part of nature or who is believed to represent a particular quality","cn":"（某些宗教中主宰某个领域的）神","g":"[countable]","ex":{"en":"the Hindu god Vishnu","cn":"印度教神毗湿奴"}},{"en":"a person who is loved or admired very much by other people","cn":"极受崇拜的人；被崇拜的偶像","g":"[countable]","ex":{"en":"To her fans she's a god.","cn":"对她的狂热崇拜者来说，她就是偶像。"}},{"en":"something to which too much importance or attention is given","cn":"受到过分崇尚（或推崇）的事物","g":"[countable]","ex":{"en":"Money is his god.","cn":"钱就是他的命。"}},{"en":"the seats that are high up at the back of a theatre","cn":"（剧院中的）顶层楼座，最高楼座","g":"[plural]","lab":"British English, informal，，","ex":{"en":"We could only afford to sit in the gods.","cn":"我们只能坐在神位上。"}}]},"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"上帝；天主；真主","en":"The name God is given to the spirit or being who is worshipped as the creator and ruler of the world, especially by Jews, Christians, and Muslims.","ex":{"en":"He believes in God","cn":"他信奉上帝。"}},{"pos":"CONVENTION 惯用语","cn":"（表示强调所说的话，或表示惊讶、恐惧或激动）啊呀，天啊，天哪（可能具冒犯意味）","en":"People sometimes use God in exclamations to emphasize something that they are saying, or to express surprise, fear, or excitement. This use could cause offence.","ex":{"en":"God, how I hated him!","cn":"啊呀！我恨死他了！"}},{"pos":"N-COUNT 可数名词","cn":"神","en":"In many religions, a god is one of the spirits or beings that are believed to have power over a particular part of the world or nature.","ex":{"en":"...Pan, the God of nature.","cn":"自然之神，潘"}},{"pos":"N-COUNT 可数名词","cn":"极受尊崇的人；影响极大的人","en":"Someone who is admired very much by a person or group of people, and who influences them a lot, can be referred to as a god .","ex":{"en":"To his followers he was a god.","cn":"在追随者眼中，他就是神。"}},{"pos":"PHRASE 短语","cn":"愿上帝阻止这样的事情；但愿这样的事不会发生","en":"If you say God forbid, you are expressing your hope that something will not happen.","ex":{"en":"If, God forbid, something goes wrong, I don't know what I would do.","cn":"如果哪儿出点儿岔子，我会不知所措的，但愿这样的事情不会发生。"}},{"pos":"PHRASE 短语","cn":"上帝的恩赐；十全十美的人","en":"If a person thinks they are God's gift to someone or something, they think they are perfect or extremely good.","ex":{"en":"Are men god's gift to women? Some of them think they are.","cn":"男人是上帝赐予女人的礼物吗？有些男人就是这样认为的。"}},{"pos":"PHRASE 短语","cn":"（警告语）愿上帝保佑你","en":"You use God help you to warn someone that something unpleasant will happen to them if they do a particular thing.","ex":{"en":"God help him if he gets in my way","cn":"他要是跟我作对，那就让上帝保佑他吧。"}},{"pos":"PHRASE 短语","cn":"愿上帝保佑…","en":"If you feel sorry for someone because they are in a difficult or unpleasant situation, especially if you think that nobody can help them, you can say God help them.","ex":{"en":"'God help them,' he said. 'They're beyond help.'","cn":"“愿上帝保佑他们吧，”他说，“谁也帮不了他们了。”"}},{"pos":"PHRASE 短语","cn":"真讨厌；真烦人","en":"If you say God help us, you mean that you have negative feelings about the person or situation you are talking about.","ex":{"en":"The first song is 11 minutes long, the last nearly the same, and, God help us, there's a drum solo along the way.","cn":"第一首歌有11分钟长，最后一首也差不多长，唉，上帝啊，中间还有一个击鼓独奏。"}},{"pos":"PHRASE 短语","cn":"（表示强调）只有上帝知道，天晓得","en":"You can say God knows ,God only knows, or God alone knows to emphasize that you do not know something.","ex":{"en":"Gunga spoke God knows how many languages","cn":"天晓得贡嘎会讲多少门语言。"}},{"pos":"PHRASE 短语","cn":"（表示不知道答案）天晓得","en":"If someone says God knows in reply to a question, they mean that they do not know the answer.","ex":{"en":"'Where is he now?' 'God knows.'","cn":"“他现在在哪里？”“天晓得。”"}},{"pos":"PHRASE 短语","cn":"（基督教的）牧师，神父","en":"The term a man of God is sometimes used to refer to Christian priests or ministers.","ex":{"en":"I am a man of God.","cn":"我是个牧师。"}},{"pos":"PHRASE 短语","cn":"（用来强调生气、懊恼或吃惊）究竟什么/ 究竟为什么/究竟如何","en":"If someone uses such expressions as what in God's name ,why in God's name, or how in God's name, they are emphasizing how angry, annoyed, or surprised they are.","ex":{"en":"What in God's name do you expect me to do?","cn":"你究竟要我做什么？"}},{"pos":"PHRASE 短语","cn":"俨然一副上帝的样子；表现得无所不能","en":"If someone plays God, they act as if they have unlimited power and can do anything they want.","ex":{"en":"You have no right to play God in my life!","cn":"你无权对我的人生指手画脚！"}},{"pos":"PHRASE 短语","cn":"（强调愿望之强烈）老天保佑，求求上天帮忙","en":"You say please God to emphasize a strong hope, wish, or desire that you have.","ex":{"en":"Please God, let him telephone me now.","cn":"拜托老天了，让他现在就给我来个电话吧。"}},{"pos":"PHRASE 短语","cn":"（表示强调）我向上帝祈祷/我真诚地希望/我向上帝发誓","en":"You can use God in expressions such as I hope to God, or I wish to God, or I swear to God, in order to emphasize what you are saying.","ex":{"en":"I hope to God they are paying you well","cn":"我真希望他们给你一份好的酬劳。"}},{"pos":"PHRASE 短语","cn":"如系天意；如一切顺利","en":"If you say God willing, you are saying that something will happen if all goes well.","ex":{"en":"God willing, there will be a breakthrough.","cn":"如果一切顺利，将会取得突破性的进展。"}},{"pos":"","cn":"","en":"to put the fear of God into someone→see: ; honest to God→see: ; in the lap of the gods→see: ; for God's sake→see: ; thank God→see: ;"}]},"examples":[{"en":"It is unfair to ask doctors to play God and end someone's life.","cn":"让医生担当上帝的角色去结束一个人的生命并不公平。"},{"en":"He seems to think he's God's gift to women.","cn":"他似乎认为自己是上帝赐给女人的礼物。"}]},"grime":{"media":{"uk":"media/uk/grime__gb_1.mp3","us":"media/us/grime__us_1.mp3"},"oxford":{"phon":"ɡraɪm","pos":"noun","senses":[{"en":"dirt that forms a layer on the surface of something","cn":"一层污垢；尘垢；积垢","ex":{"en":"a face covered with grime and sweat","cn":"满是污垢和汗水的脸"}},{"en":"a type of electronic dance music that developed from drum and bass, UK garage and other styles","cn":"车库说唱（由鼓打贝司、英式车库等音乐风格发展而来的一种电子舞曲音乐）"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"污垢；尘垢","en":"Grime is dirt which has collected on the surface of something.","ex":{"en":"Kelly got the grime off his hands before rejoining her in the kitchen.","cn":"凯利洗去手上的污垢，又回到厨房来帮她的忙。"}}]},"examples":[{"en":"a face covered with grime and sweat","cn":"满是污垢和汗水的脸"},{"en":"The walls were black with grime.","cn":"墙上黑黑的﹐积满了污垢。"}]},"glancing":{"media":{"uk":"media/uk/glancing__gb_1.mp3","us":"media/us/glancing__us_1.mp3"},"oxford":{"phon":"ˈɡlɑːnsɪŋ","pos":"adjective","senses":[{"en":"hitting something/somebody at an angle, not with full force","cn":"斜擦而过的；击偏的","ex":{"en":"to strike somebody a glancing blow","cn":"以斜击拳击中某人"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"斜擦而过的；击偏的","en":"A glancing blow is one that hits something at an angle rather than from directly in front.","ex":{"en":"The car struck him a glancing blow on the forehead.","cn":"那辆汽车蹭伤了他的前额。"}}]},"examples":[{"en":"to strike somebody a glancing blow","cn":"从侧面给某人一击"}],"base":"glance"},"gambling":{"media":{"uk":"media/uk/gambling__gb_1.mp3","us":"media/us/gambling__us_1.mp3"},"oxford":{"phon":"ˈɡæmblɪŋ","pos":"noun","senses":[{"en":"the activity of playing games of chance for money and of betting on horses, etc.","cn":"赌博；打赌；赌钱","ex":{"en":"online/internet gambling","cn":"线上／网络赌博"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"赌博；赌钱","en":"Gambling is the act or activity of betting money, for example in card games or on horse racing.","ex":{"en":"Gambling is a form of entertainment.","cn":"赌博是一种娱乐。"}}]},"examples":[{"en":"heavy gambling debts","cn":"沉重的赌债"},{"en":"The lottery is probably the most popular form of gambling.","cn":"彩票可能是最普遍的一种赌博形式。"}],"base":"gamble"},"goddess":{"media":{"uk":"media/uk/goddess__gb_1.mp3","us":"media/us/goddess__us_1.mp3"},"oxford":{"phon":"ˈɡɒdes","pos":"noun","senses":[{"en":"a female god","cn":"女神","ex":{"en":"Diana, the goddess of hunting","cn":"狩猎女神狄安娜"}},{"en":"a woman who is loved or admired very much by other people","cn":"极受崇拜（或敬慕）的女人","ex":{"en":"a screen goddess (= a female film star)","cn":"银幕女神"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"女神","en":"In many religions, a goddess is a female spirit or being that is believed to have power over a particular part of the world or nature.","ex":{"en":"...Athena, the goddess of war.","cn":"战争女神雅典娜"}}]},"examples":[{"en":"a screen goddess (= a female film/movie star)","cn":"银幕女神"},{"en":"Diana, the goddess of hunting","cn":"狩猎女神狄安娜"}]},"gallon":{"media":{"uk":"media/uk/gallon__gb_1.mp3","us":"media/us/gallon__us_1.mp3"},"oxford":{"phon":"ˈɡælən","pos":"noun","senses":[{"en":"a unit for measuring liquid. In the UK, Canada and other countries it is equal to about 4.5 litres; in the US it is equal to about 3.8 litres. There are four quarts in a gallon.","cn":"加仑（液量单位，在英国、加拿大及其他一些国家约等于 4.5 升，在美国约等于 3.8 升，一加仑为四夸脱）","ex":{"en":"The tankers carried 130 000 gallons of fuel.","cn":"油轮装载了 130 000 加仑的燃料。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"加仑（液量单位，1加仑等于8品脱，英制等于4.564升，美制等于3.785升）","en":"A gallon is a unit of measurement for liquids that is equal to eight pints. In Britain, it is equal to 4.564 litres. In America, it is equal to 3.785 litres.","ex":{"en":"...80 million gallons of water a day.","cn":"每天8千万加仑水"}}]},"examples":[{"en":"The car does about 50 miles per gallon .","cn":"这辆车每加仑油能开50英里左右。"},{"en":"We drank gallons of coffee.","cn":"我们畅饮咖啡。"}]},"guarantee":{"media":{"uk":"media/uk/guarantee__gb_1.mp3","us":"media/us/guarantee__us_1.mp3"},"oxford":{"phon":"ˌɡærənˈtiː","pos":"verb","senses":[{"en":"to promise to do something; to promise something will happen","cn":"保证；担保；保障","ex":{"en":"Basic human rights, including freedom of speech, are now guaranteed.","cn":"现在，包括言论自由在内的基本人权已有了保障。"}},{"en":"to give a written promise to replace or repair a product free if it goes wrong","cn":"提供（产品）保修单（免费掉换或修理有问题的产品）","ex":{"en":"All our electrical goods are fully guaranteed.","cn":"我们所有的电器都有全面质保。"}},{"en":"to make something certain to happen","cn":"使必然发生；确保","ex":{"en":"Tonight's victory guarantees the team's place in the final.","cn":"今晚的胜利确保这个队能进入决赛。"}},{"en":"to be certain that something will happen","cn":"肯定…必然发生","ex":{"en":"You can guarantee (that) the children will start being naughty as soon as they have to go to bed.","cn":"可以肯定孩子一到上床睡觉时就不听话了。"}},{"en":"to agree to be legally responsible for something or for doing something, especially for paying back money that somebody else owes if they cannot pay it back themselves","cn":"承诺对…负法律责任；为…作担保","ex":{"en":"to guarantee a bank loan","cn":"为银行贷款作保"}},{"en":"a formal promise that you will do something or that something will happen","cn":"保证；担保","ex":{"en":"They are demanding certain guarantees before they sign the treaty.","cn":"他们要求得到某些保证后才签署条约。"},"pos":"noun"},{"en":"a written promise given by a company that something you buy will be replaced or repaired without payment if it goes wrong within a particular period","cn":"保修单；保用证书","ex":{"en":"The television comes with a year's guarantee.","cn":"这电视机有一年的保修期。"},"pos":"noun"},{"en":"something that makes something else certain to happen","cn":"起保证作用的事物","ex":{"en":"Career success is no guarantee of happiness.","cn":"事业成功并不是幸福的保证。"},"pos":"noun"},{"en":"money or something valuable that you give or promise to a bank, for example, to make sure that you will do what you have promised","cn":"保证金；抵押品","ex":{"en":"We had to offer our house as a guarantee when getting the loan.","cn":"我们在贷款时不得不拿房子作抵押。"},"pos":"noun"},{"en":"a written promise to pay back money that somebody else owes, or do something that somebody else promised to do, if they cannot do it themselves","cn":"担保书","ex":{"en":"A close relative, usually a parent, can provide a guarantee for the loan.","cn":"近亲属，通常为父母，可为贷款作担保。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"确保；使必然发生","en":"If one thing guarantees another, the first is certain to cause the second thing to happen.","ex":{"en":"Surplus resources alone do not guarantee growth.","cn":"仅有富余的资源并不能确保发展。"}},{"pos":"N-COUNT 可数名词","cn":"保证","en":"Something that is a guarantee of something else makes it certain that it will happen or that it is true.","ex":{"en":"A famous old name on a firm is not necessarily a guarantee of quality","cn":"公司悠久的品牌并不能确保商品的质量。"}},{"pos":"VERB 动词","cn":"保证…必定发生；承诺做；答应提供","en":"If you guarantee something, you promise that it will definitely happen, or that you will do or provide it for someone.","ex":{"en":"Most states guarantee the right to free and adequate education","cn":"大多数州都保障人们免费享受充分教育的权利。"}},{"pos":"N-COUNT 可数名词","cn":"保修单","en":"A guarantee is a written promise by a company to replace or repair a product free of charge if it has any faults within a particular time.","ex":{"en":"Whatever a guarantee says, when something goes wrong, you can still claim your rights from the shop","cn":"不论保修单如何规定，若商品出了问题，消费者仍然可以去商店维护自身权益。"}},{"pos":"VERB 动词","cn":"为…提供质量保证；担保","en":"If a company guarantees its product or work, they provide a guarantee for it.","ex":{"en":"Some builders guarantee their work","cn":"一些建筑公司对其承建工程提供质量保证。"}},{"pos":"N-COUNT 可数名词","cn":"担保金；担保物；抵押品","en":"A guarantee is money or something valuable which you give to someone to show that you will do what you have promised.","ex":{"en":"Males between 18 and 20 had to leave a deposit as a guarantee of returning to do their military service.","cn":"18至20岁的男性必须缴纳一笔保证金，作为回来服兵役的担保。"}}]},"examples":[{"en":"Basic human rights, including freedom of speech, are now guaranteed.","cn":"现在，包括言论自由在内的基本人权已有了保障。"},{"en":"You can guarantee (that) the children will start being naughty as soon as they have to go to bed.","cn":"可以肯定孩子一到上床睡觉时就不听话了。"}]},"gravelled":{"media":{"uk":"media/uk/gravelled__gb_1.mp3","us":"media/us/gravelled__us_1.mp3"},"oxford":{"phon":"ˈɡrævld","pos":"adjective","senses":[{"en":"covered with gravel","cn":"砾石铺的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（道路等）铺上碎石的","en":"A gravelled path, road, or area has a surface made of gravel."}]}},"gasoline":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"同petrol","en":"Gasoline is the same as petrol ."}]},"media":{"uk":"media/uk/gasoline__gb_1.mp3","us":"media/us/gasoline__us_1.mp3"},"examples":[{"en":"I fill up the tank with gasoline about once a week.","cn":"我大约一个星期加满一箱汽油。"},{"en":"leaded/unleaded gasoline","cn":"含铅/无铅汽油"}],"oxford":{"phon":"ˈɡæsəliːn","pos":"noun","senses":[{"en":"a liquid obtained from petroleum, used as fuel in car engines, etc.","cn":"汽油","ex":{"en":"I fill up the tank with gasoline about once a week.","cn":"我大约一个星期加满一箱汽油。"}}]}},"gi":{"oxford":{"phon":"ˌdʒiː ˈaɪ","pos":"noun","senses":[{"en":"a soldier in the US armed forces","cn":"美国士兵"},{"en":"Glycaemic Index (= a system for measuring the effect of foods containing carbohydrates on the level of sugar in the blood)","cn":"血糖（生成）指数","ex":{"en":"The diet is based mainly on low GI foods.","cn":"这种饮食方式主要是以血糖指数低的食物为主。"},"pos":"abbreviation"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"美国兵","en":"A GI is a soldier in the United States army."}]},"media":{"uk":"media/uk/gi__gb_1.mp3","us":"media/us/gi__us_1.mp3"},"examples":[{"en":"The diet is based mainly on low GI foods.","cn":"这种饮食方式主要是以升糖指数低的食物为主。"}]},"glide":{"media":{"uk":"media/uk/glide__gb_1.mp3","us":"media/us/glide__us_1.mp3"},"oxford":{"phon":"ɡlaɪd","pos":"verb","senses":[{"en":"to move smoothly and quietly, especially as though it takes no effort","cn":"滑行；滑动；掠过","g":"[intransitive]","ex":{"en":"Swans went gliding past.","cn":"天鹅滑行而过。"}},{"en":"to fly using air currents, without the birds moving their wings or the aircraft using the engine","cn":"滑翔","g":"[intransitive]","ex":{"en":"An eagle was gliding high overhead.","cn":"一只鹰在头顶上空翱翔。"}},{"en":"a continuous smooth movement","cn":"滑行；滑动；滑翔","g":"[singular]","ex":{"en":"the graceful glide of a skater","cn":"滑冰者优美的滑行动作"},"pos":"noun"},{"en":"a speech sound made while moving the tongue from one position to another","cn":"滑音","g":"[countable]","lab":"phonetics","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"滑动；滑行；悄悄地走","en":"If you glide somewhere, you move silently and in a smooth and effortless way.","ex":{"en":"Waiters glide between tightly packed tables bearing trays of pasta.","cn":"侍者们端着一盘盘意大利面在拥挤的餐桌之间自如穿行。"}},{"pos":"VERB 动词","cn":"滑翔","en":"When birds or aeroplanes glide, they float on air currents.","ex":{"en":"Our only companion is the wandering albatross, which glides effortlessly and gracefully behind the yacht.","cn":"陪伴我们的仅有那只盘旋的信天翁，它在游艇后面优雅轻盈地翱翔。"}}]},"examples":[{"en":"The plane managed to glide down to the runway.","cn":"飞机终于成功地滑翔降落在跑道上。"},{"en":"An eagle was gliding high overhead.","cn":"一只鹰在头顶上空翱翔。"}]},"gunnel":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a gunwale","cn":"舷缘﹐船舷上缘"}]},"media":{"uk":"media/uk/gunnel__gb_1.mp3","us":"media/us/gunnel__us_1.mp3"},"oxford":{"phon":"ˈɡʌnl","pos":"noun","senses":[{"en":"the upper edge of the side of a boat or small ship","cn":"舷缘（船舷的上缘）"}]}},"go":{"media":{"uk":"media/uk/go__gb_1.mp3","us":"media/us/go__us_1.mp3"},"oxford":{"phon":"ɡəʊ","pos":"verb","senses":[{"en":"to move or travel from one place to another","cn":"去；走","g":"[intransitive]","lab":"North American English","sc":"move/travel","ex":{"en":"She went into her room and shut the door behind her.","cn":"她走进自己的房间，把门关上。"}},{"en":"to move or travel, especially with somebody else, to a particular place or in order to be present at an event","cn":"（尤指与某人）去（某处或出席某项活动）","g":"[intransitive]","sc":"move/travel","ex":{"en":"Are you going to Dave's party?","cn":"你要去参加戴夫的聚会吗？"}},{"en":"to move or travel in a particular way or over a particular distance","cn":"移动，旅行，行走（指方式或距离）","g":"[intransitive]","sc":"move/travel","ex":{"en":"He's going too fast.","cn":"他走得太快。"}},{"en":"to move in a particular way or while doing something else","cn":"（以某种方式）移动；在移动中做","g":"[intransitive]","sc":"move/travel","ex":{"en":"She crashed into a waiter and his tray of drinks went flying.","cn":"她一下子撞到侍者身上，弄得他托盘里的饮料四处飞溅。"}},{"en":"to leave one place in order to reach another","cn":"离开；离去；出发","g":"[intransitive]","sc":"leave","ex":{"en":"I must be going now.","cn":"我现在得走了。"}},{"en":"to leave a place and do something different","cn":"去做（某事）","g":"[intransitive]","lab":"British English","sc":"leave","ex":{"en":"to go on a journey/tour/trip/cruise","cn":"去旅行／观光游览／短途旅行／乘船旅游"}},{"en":"to visit or attend a place for a particular purpose","cn":"（为某目的）去（某处）","g":"[intransitive]","lab":"British English","sc":"visit/attend","ex":{"en":"to go to school/college/university","cn":"上学；上大学"}},{"en":"to look at a particular page or website","cn":"查看（页面或网站）","sc":"visit/attend","ex":{"en":"She went on Facebook and changed her relationship status.","cn":"她上脸书更新了她的感情状态。"}},{"en":"to leave a place or travel to a place in order to take part in an activity or a sport","cn":"去参加，去从事（某项活动或运动）","g":"[intransitive]","sc":"swimming/fishing/jogging, etc.","ex":{"en":"to go for a walk","cn":"去散步"}},{"en":"to be sent or passed somewhere","cn":"被发送；被传递","g":"[intransitive]","sc":"be sent","ex":{"en":"I want this memo to go to all managers.","cn":"我想让这份备忘录送交到所有经理手中。"}},{"en":"used to talk about how quickly or slowly time seems to pass","cn":"流逝；消逝；过去","g":"[intransitive]","sc":"time","ex":{"en":"Hasn't the time gone quickly?","cn":"时光过得真快，是不是？"}},{"en":"to stop existing; to be lost or stolen","cn":"不复存在；不见了；丢失；失窃","g":"[intransitive]","sc":"disappear","ex":{"en":"Has your headache gone yet?","cn":"你还头痛吗？"}},{"en":"to lead or extend in a particular direction","cn":"通往；延伸到","g":"[intransitive]","sc":"lead","ex":{"en":"Where does this road go?","cn":"这条路通到哪里？"}},{"en":"to have as a usual or correct position; to be placed","cn":"被放置，被置于，被安放（在通常或合适的位置）","g":"[intransitive]","sc":"place/space","ex":{"en":"This dictionary goes on the top shelf.","cn":"这部词典放在书架最上层。"}},{"en":"used to say that something does/did not fit into a particular place or space","cn":"（不）适合；放（不）进","g":"[intransitive]","sc":"place/space","ex":{"en":"My clothes won't all go in that one suitcase.","cn":"一个手提箱装不下我所有的衣服。"}},{"en":"used to talk about how well or badly something makes progress or succeeds","cn":"（事情）进展，进行","g":"[intransitive]","sc":"progress","ex":{"en":"‘How did the interview go?’ ‘It went well, thank you.’","cn":"“面试情况如何？”“非常顺利，谢谢。”"}},{"en":"used in many expressions to show that somebody/something has reached a particular state/is no longer in a particular state","cn":"进入…状态；处于…状况；脱离…状态","g":"[intransitive]","sc":"state/condition","ex":{"en":"She went to sleep.","cn":"她睡着了。"}},{"en":"to become different in a particular way, especially a bad way","cn":"（尤指朝坏的方面）变成，变为，变得","sc":"state/condition","ex":{"en":"to go crazy/mad/nuts/insane","cn":"发狂；发疯；失去理智"}},{"en":"to live or move around in a particular state","cn":"（在某种状态下）生活，过活，移动","g":"[intransitive]","sc":"state/condition","ex":{"en":"to go naked/barefoot","cn":"光着身子；赤着脚"}},{"en":"to spend a period of time in a particular way","cn":"以特定方式度过一段时间","g":"[intransitive]","sc":"state/condition","ex":{"en":"They went for two weeks without receiving any news.","cn":"他们两个星期没有收到任何消息。"}},{"en":"to not be noticed, reported, etc.","cn":"未被注意到（或报告等）","g":"[intransitive]","sc":"state/condition","ex":{"en":"Pippa's absence went unnoticed.","cn":"皮帕的缺席没有引起人们的注意。"}},{"en":"to make a particular sound or movement","cn":"发出（某种声音）；做（某种动作）","g":"[intransitive]","sc":"sound/movement","ex":{"en":"The gun went ‘bang’.","cn":"枪“砰”的一声响了。"}},{"en":"to be sounded as a signal or warning","cn":"发出信号（或警告）","g":"[intransitive]","sc":"sound/movement","ex":{"en":"The whistle went for the end of the game.","cn":"比赛结束的哨声响了。"}},{"en":"if a number will go into another number, it is contained in that number an exact number of times","cn":"除尽；除","g":"[intransitive]","lab":"North American English","sc":"numbers","ex":{"en":"3 into 12 goes 4 times.","cn":"3 除 12 得 4。"}},{"en":"to combine well with something","cn":"与某物相配（或协调、和谐）","sc":"combine well","ex":{"en":"Does this jacket go with this skirt?","cn":"这件上衣与这条裙子相配吗？"}},{"en":"used to talk about what tune or words a song or poem has or what happens in a story","cn":"（歌曲）唱道；（诗歌）写道；（歌词或故事）内容是","g":"[intransitive, transitive]","sc":"song/story","ex":{"en":"How does that song go?","cn":"那首歌怎么唱？"}},{"en":"to say","cn":"说","g":"[transitive]","lab":"informal","sc":"say","ex":{"en":"I asked ‘How much?’ and he goes, ‘Fifty’ and I go, ‘Fifty? You must be joking!’","cn":"我问：“多少钱？”他回答说：“五十。”我又说：“五十？你是在开玩笑吧！”"}},{"en":"to start an activity","cn":"开始（活动）","g":"[intransitive]","sc":"start","ex":{"en":"I'll say ‘One, two, three, go!’ as a signal for you to start.","cn":"我喊“一、二、三，开始！”作为你开始的信号。"}},{"en":"if a machine goes, it works","cn":"运行；运转；工作","g":"[intransitive]","sc":"machine","ex":{"en":"This clock doesn't go.","cn":"这钟不走了。"}},{"en":"used to talk about wanting to get rid of somebody/something","cn":"（必须或可以）辞掉（或扔掉、废弃）","g":"[intransitive]","sc":"be thrown out","ex":{"en":"The old sofa will have to go.","cn":"那旧沙发该扔掉了。"}},{"en":"to get worse; to become damaged or stop working correctly","cn":"变坏；损坏；不起作用","g":"[intransitive]","sc":"not work","ex":{"en":"Her sight is beginning to go.","cn":"她的视力开始下降。"}},{"en":"to die. People say ‘go’ to avoid saying ‘die’.","cn":"走（委婉说法，与 die 同义）","g":"[intransitive]","sc":"die","ex":{"en":"You can't take your money with you when you go.","cn":"你不可能把钱带进棺材。"}},{"en":"when money goes, it is spent or used for something","cn":"用于；花掉","g":"[intransitive]","sc":"money","ex":{"en":"I don't know where the money goes!","cn":"我不知道钱都花到什么地方去了！"}},{"en":"to be sold","cn":"被卖掉；被出售","g":"[intransitive]","sc":"money","ex":{"en":"We won't let the house go for less than $200 000.","cn":"这房子低于 20 万美元我们是不会卖的。"}},{"en":"to be willing to pay a particular amount of money for something","cn":"愿出价购买","g":"[intransitive]","sc":"money","ex":{"en":"He's offered £3 000 for the car and I don't think he'll go any higher.","cn":"他出价 3 000 英镑买这辆汽车，我看他不会愿意再多付了。"}},{"en":"to help; to play a part in doing something","cn":"有助于；促成；起作用","g":"[intransitive]","sc":"help","ex":{"en":"This all goes to prove my theory.","cn":"这一切都有助于证明我的说法是对的。"}},{"en":"to be available","cn":"可得到；可买到；现成可用","g":"[intransitive]","lab":"informal","sc":"be available","ex":{"en":"There just aren't any jobs going in this area.","cn":"此地几乎没有工作可找。"}},{"en":"to use a toilet","cn":"用厕所；上厕所","g":"[intransitive]","lab":"informal","sc":"use toilet","ex":{"en":"Do you need to go, Billy?","cn":"你要上厕所吗，比利？"}},{"en":"a person’s turn to move or play in a game or an activity","cn":"（游戏或活动中）轮到的机会","g":"[countable]","lab":"British English","ex":{"en":"Whose go is it?","cn":"轮到谁了？"},"pos":"noun"},{"en":"an attempt at doing something","cn":"（做某事的）尝试，一番努力","g":"[countable]","ex":{"en":"It took three goes to get it right.","cn":"试了三次才把它弄好。"},"pos":"noun"},{"en":"energy and enthusiasm","cn":"精力；活力；热情；干劲","g":"[uncountable]","lab":"British English","ex":{"en":"Mary's always got plenty of go.","cn":"玛丽总是精力充沛。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"去；行进","en":"When you go somewhere, you move or travel there.","ex":{"en":"We went to Rome","cn":"我们去了罗马。"}},{"pos":"VERB 动词","cn":"离开；走","en":"When you go, you leave the place where you are.","ex":{"en":"Let's go","cn":"我们走吧。"}},{"pos":"VERB 动词","cn":"去参加，去从事（某活动）","en":"You use go to say that someone leaves the place where they are and does an activity, often a leisure activity.","ex":{"en":"We went swimming very early","cn":"我们很早就去游泳了。"}},{"pos":"VERB 动词","cn":"去做…（可用go to do, 也可用go and do，美国英语中还可用go do，然而一般说 went and did）","en":"When you go to do something, you move to a place in order to do it and you do it. You can also go and do something, and in American English, you can go do something. However, you always say that someone went and did something.","ex":{"en":"His second son, Paddy, had gone to live in Canada","cn":"他的二儿子帕迪去加拿大生活了。"}},{"pos":"VERB 动词","cn":"去（上学、上班或教堂）","en":"If you go to school, work, or church, you attend it regularly as part of your normal life.","ex":{"en":"She will have to go to school","cn":"她将不得不去上学。"}},{"pos":"VERB 动词","cn":"（路）通向，延伸到，位于","en":"When you say where a road or path goes, you are saying where it begins or ends, or what places it is in.","ex":{"en":"There's a mountain road that goes from Blairstown to Millbrook Village.","cn":"有一条山路从布莱尔斯敦通向米尔布鲁克村。"}},{"pos":"VERB 动词","cn":"（用于否定表达中，表示对所提到行为不赞成或不允许某人有这种行为）","en":"You can use go in expressions such as 'don't go telling everybody', in order to express disapproval of the kind of behaviour you mention, or to tell someone not to behave in that way.","ex":{"en":"You don't have to go running upstairs every time she rings","cn":"用不着她一来电话你就往楼上跑。"}},{"pos":"VERB 动词","cn":"（与further,beyond等词连用，表示某事的进展或程度）","en":"You can use go with words like 'further' and 'beyond' to show the degree or extent of something.","ex":{"en":"He went even further in his speech to the conference","cn":"他在大会发言中作了更进一步的阐述。"}},{"pos":"VERB 动词","cn":"（时间）过去，流逝","en":"If you say that a period of time goes quickly or slowly, you mean that it seems to pass quickly or slowly.","ex":{"en":"The weeks go so quickly!","cn":"这几周过得真快！"}},{"pos":"VERB 动词","cn":"（钱）用于，花掉","en":"If you say where money goes, you are saying what it is spent on.","ex":{"en":"Most of my money goes on bills","cn":"我的钱大部分用来支付各种账单。"}},{"pos":"VERB 动词","cn":"由…得到；授予；归于","en":"If you say that something goes to someone, you mean that it is given to them.","ex":{"en":"A lot of credit must go to the chairman and his father","cn":"很大一部分功劳应归于主席和他的父亲。"}},{"pos":"VERB 动词","cn":"上，参加（电视或电台节目）","en":"If someone goes on television or radio, they take part in a television or radio programme.","ex":{"en":"The Turkish president has gone on television to defend stringent new security measures","cn":"土耳其总统上电视为严格的新安全措施进行辩护。"}},{"pos":"VERB 动词","cn":"被除掉；被去掉","en":"If something goes, someone gets rid of it.","ex":{"en":"The Institute of Export now fears that 100,000 jobs will go","cn":"现在出口协会担心将失去10万个工作机会。"}},{"pos":"VERB 动词","cn":"（常指被迫）辞职","en":"If someone goes, they leave their job, usually because they are forced to.","ex":{"en":"He had made a humiliating tactical error and he had to go.","cn":"他犯了一个让他颜面尽失的战术错误，只得引咎辞职。"}},{"pos":"VERB 动词","cn":"被放入；包含于","en":"If something goes into something else, it is put in it as one of the parts or elements that form it.","ex":{"en":"...the really interesting ingredients that go into the dishes that we all love to eat.","cn":"我们都爱吃的菜肴里所放入的十分有趣的原料"}},{"pos":"VERB 动词","cn":"装得进；塞得进","en":"If something goes in a particular place, it fits in that place or should be put there because it is the right size or shape.","ex":{"en":"He was trying to push it through the hole and it wouldn't go.","cn":"他想将它从这个洞里推过去，但却怎么也过不去。"}},{"pos":"VERB 动词","cn":"（按惯例应）置于","en":"If something goes in a particular place, it belongs there or should be put there, because that is where you normally keep it.","ex":{"en":"The shoes go on the shoe shelf","cn":"鞋子放在鞋架上。"}},{"pos":"VERB 动词","cn":"除尽；除","en":"If you say that one number goes into another number a particular number of times, you are dividing the second number by the first.","ex":{"en":"Six goes into thirty five times.","cn":"6除30得5。"}},{"pos":"VERB 动词","cn":"（官能）衰退，下降","en":"If one of a person's senses, such as their sight or hearing, is going, it is getting weak and they may soon lose it completely.","ex":{"en":"His eyes are going; he says he has glaucoma","cn":"他的视力在下降，他说自己得了青光眼。"}},{"pos":"VERB 动词","cn":"（灯泡、引擎等)损坏，报废，无法正常运转","en":"If something such as a light bulb or a part of an engine is going, it is no longer working properly and will soon need to be replaced.","ex":{"en":"I thought it looked as though the battery was going.","cn":"我看电池好像该换了。"}},{"pos":"VERB 动词","cn":"奄奄一息；去世","en":"If you say that someone is going or has gone, you are saying in an indirect way that they are dying or are dead.","ex":{"en":"'Any hope?' — 'No, he's gone.'","cn":"“还有希望吗？”——“没有，他已经死了。”"}},{"pos":"V-LINK 连系动词","cn":"变得；成为","en":"You can use go to say that a person or thing changes to another state or condition. For example, if someone goes crazy, they become crazy, and if something goes green, it changes colour and becomes green.","ex":{"en":"I'm going bald","cn":"我开始秃头了。"}},{"pos":"V-LINK 连系动词","cn":"（表示是否穿戴或拥有某物）","en":"You can use go when indicating whether or not someone wears or has something. For example, if someone goes barefoot, they do not wear any shoes.","ex":{"en":"The baby went naked on the beach","cn":"这个小宝贝光着身子在沙滩上。"}},{"pos":"V-LINK 连系动词","cn":"（用在以un开头的形容词之前表示某事没有发生）","en":"You can use go before adjectives beginning with 'un-' to say that something does not happen. For example, if something goes unheard, nobody hears it.","ex":{"en":"As President, he affirmed that no tyranny went unnoticed.","cn":"他以总统的名义宣称没有对任何暴行置若罔闻。"}},{"pos":"VERB 动词","cn":"进展；进行","en":"You use go to talk about the way something happens. For example, if an event or situation goes well, it is successful.","ex":{"en":"She says everything is going smoothly","cn":"她说一切进展顺利。"}},{"pos":"VERB 动词","cn":"（机器或装置）运转，运行，工作","en":"If a machine or device is going, it is working.","ex":{"en":"What about my copier? Can you get it going again?","cn":"我的复印机怎么样了？你能把它修好吗？"}},{"pos":"VERB 动词","cn":"（铃等）鸣响","en":"If a bell goes, it makes a noise, usually as a signal for you to do something.","ex":{"en":"The bell went for the break.","cn":"课间休息铃响了。"}},{"pos":"V-RECIP 相互动词","cn":"（与…）相配；（与…）相称","en":"If something goes with something else, or if two things go together, they look or taste nice together.","ex":{"en":"I was searching for a pair of grey gloves to go with my new gown","cn":"我在找一副跟我的新礼服相配的灰色手套。"}},{"pos":"VERB 动词","cn":"（用于引出要引用的话）","en":"You use go to introduce something you are quoting. For example, you say the story goes or the argument goes just before you quote all or part of it.","ex":{"en":"The story goes that she went home with him that night","cn":"据说她那天晚上跟他一起回了家。"}},{"pos":"VERB 动词","cn":"发出…声响","en":"You use go when indicating that something makes or produces a sound. For example, if you say that something goes 'bang', you mean it produces the sound 'bang'.","ex":{"en":"She stopped in front of a painting of a dog and she started going 'woof woof'","cn":"她在一幅狗的画像前停下来，开始“汪汪”地学起狗叫来。"}},{"pos":"VERB 动词","cn":"说（代替say，表示引述他人的话或认为他们要说的话）","en":"You can use go instead of 'say' when you are quoting what someone has said or what you think they will say.","ex":{"en":"They say 'Tom, shut up' and I go 'No, you shut up'","cn":"他们说：“汤姆，你闭嘴！”我说：“才不呢，你们闭嘴！”"}},{"pos":"N-COUNT 可数名词","cn":"尝试；努力","en":"A go is an attempt at doing something.","ex":{"en":"I always wanted to have a go at football","cn":"我一直都想试试踢足球。"}},{"pos":"N-COUNT 可数名词","cn":"（牌戏、下棋等中）轮到的顺序","en":"If it is your go in a game, it is your turn to do something, for example to play a card or move a piece.","ex":{"en":"I'm two behind you but it's your go","cn":"我落后你两步，但现在轮到你走了。"}},{"pos":"PHRASE 短语","cn":"全力以赴；不遗余力地做","en":"If you go all out to do something or go all out for something, you make the greatest possible effort to do it or get it.","ex":{"en":"They will go all out to get exactly what they want","cn":"他们将尽最大努力实现自己的愿望。"}},{"pos":"PHRASE 短语","cn":"干（或说）什么都行；什么事都不新鲜","en":"If people say 'anything goes', they mean that anything people say or do is considered acceptable, and usually they mean that they do not approve of this.","ex":{"en":"In the 90s, almost anything goes.","cn":"在90年代几乎无奇不有。"}},{"pos":"PHRASE 短语","cn":"与同类的事物相比/跟其他小孩相比","en":"You use expressions like as things go or as children go when you are describing one person or thing and comparing them with others of the same kind.","ex":{"en":"This is a straightforward case, as these things go","cn":"同其他同类情况相比，这件事还算简单。"}},{"pos":"PHRASE 短语","cn":"未事先准备；无意之中","en":"If you do something as you go along, you do it while you are doing another thing, without preparing it beforehand.","ex":{"en":"Learning how to become a parent takes time. It's a skill you learn as you go along.","cn":"学会如何为人父母需要时间，这种技能只能边经历边学习。"}},{"pos":"PHRASE 短语","cn":"干蠢事；犯傻","en":"If you say that someone has gone and done something, you are expressing your annoyance at the foolish thing they have done.","ex":{"en":"Well, he's gone and done it again, hasn't he?","cn":"噢，他又干傻事了，是吧？"}},{"pos":"CONVENTION 惯用语","cn":"大胆尝试吧","en":"You say 'Go for it' to encourage someone to increase their efforts to achieve or win something."},{"pos":"PHRASE 短语","cn":"攻击；批评；非难","en":"If someone has a go at you, they criticize you, often in a way that you feel is unfair.","ex":{"en":"Some people had a go at us for it, which made us more angry.","cn":"一些人因为此事攻击我们，这使我们更加气愤。"}},{"pos":"CONVENTION 惯用语","cn":"我们下一步该怎么办","en":"If someone says 'Where do we go from here?' they are asking what should be done next, usually because a problem has not been solved in a satisfactory way."},{"pos":"PHRASE 短语","cn":"在…方面取得一定成功","en":"If you say that someone is making a go of something such as a business or relationship, you mean that they are having some success with it.","ex":{"en":"I knew we could make a go of it and be happy.","cn":"我知道我们能做成这件事并且会很开心。"}},{"pos":"PHRASE 短语","cn":"忙个没完；十分活跃","en":"If you say that someone is always on the go, you mean that they are always busy and active.","ex":{"en":"I got a new job this year where I am on the go all the time.","cn":"我今年找了份新工作，一直忙得不可开交。"}},{"pos":"PHRASE 短语","cn":"忙于做…","en":"If you have something on the go, you have started it and are busy doing it.","ex":{"en":"Do you like to have many projects on the go at any one time?","cn":"你喜欢一次忙多个项目吗？"}},{"pos":"PHRASE 短语","cn":"待做；有待完成","en":"If you say that there are a particular number of things to go, you mean that they still remain to be dealt with.","ex":{"en":"I still had another five operations to go.","cn":"我还有5例手术要做。"}},{"pos":"PHRASE 短语","cn":"（时间）剩下","en":"If you say that there is a certain amount of time to go, you mean that there is that amount of time left before something happens or ends.","ex":{"en":"There is a week to go until the elections.","cn":"离选举还有一周的时间。"}},{"pos":"PHRASE 短语","cn":"（食物）带出餐馆吃的，外卖的","en":"If you are in a café or restaurant and ask for an item of food to go, you mean that you want to take it away with you and not eat it there.","ex":{"en":"Large fries to go.","cn":"大份炸薯条带走。"}},{"pos":"","cn":"","en":"相关词组：go about go after go against go ahead go along go along with go around go around with go at go away go back go back on go back to go before go by go down go down as go down on go down with go for go in go in for go into go off go off with go on go out go out for go out of go over go over to go round go through go through with go towards go under go up go with go without"}]},"examples":[{"en":"I asked ‘How much?’ and he goes, ‘Fifty’ and I go, ‘Fifty? You must be joking!’","cn":"我问：“多少钱？”他回答说：“五十。”我又说：“五十？你是在开玩笑吧！”"},{"en":"He's offered £3 000 for the car and I don't think he'll go any higher.","cn":"他出价 3 000 英镑买这辆汽车，我看他不会愿意再多付了。"}]},"genus":{"oxford":{"phon":"ˈdʒiːnəs","pos":"noun","senses":[{"en":"a group into which animals, plants, etc. that have similar characteristics are divided, smaller than a family and larger than a species","cn":"（动植物等分类的）属"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指动植物的）属","en":"A genus is a class of similar things, especially a group of animals or plants that includes several closely related species."}]},"media":{"uk":"media/uk/genus__gb_1.mp3","us":"media/us/genus__us_1.mp3"}},"goal":{"media":{"img":["media/pic/sports_comp.jpg","media/thumb/soccer.jpg"],"uk":"media/uk/goal__gb_1.mp3","us":"media/us/goal__us_1.mp3"},"oxford":{"phon":"ɡəʊl","pos":"noun","senses":[{"en":"a frame with a net into which players must kick or hit the ball in order to score a point","cn":"球门","ex":{"en":"He headed the ball into an open goal (= one that had nobody defending it).","cn":"他把球顶进了空门。"}},{"en":"the act of kicking or hitting the ball into the goal; a point that is scored for this","cn":"射门；进球得分","ex":{"en":"She scored twenty goals in her first season.","cn":"她在第一个赛季进了二十个球。"}},{"en":"something that you hope to achieve","cn":"目标；目的","ex":{"en":"to achieve/accomplish/reach a goal","cn":"达到目标"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（足球、无板篮球或曲棍球等的）球门","en":"In games such as football, netball or hockey, the goal is the space into which the players try to get the ball in order to score a point for their team.","ex":{"en":"David Seaman was back in the Arsenal goal after breaking a knuckle.","cn":"戴维·西曼在一个指关节骨折后又回到阿森纳队的球门前。"}},{"pos":"N-COUNT 可数名词","cn":"（足球或曲棍球赛等的）进球，进球得分","en":"In games such as football or hockey, a goal is when a player gets the ball into the goal, or the point that is scored by doing this.","ex":{"en":"They scored five goals in the first half of the match","cn":"他们在上半场比赛中攻入了5球。"}},{"pos":"N-COUNT 可数名词","cn":"目标；目的","en":"Something that is your goal is something that you hope to achieve, especially when much time and effort will be needed.","ex":{"en":"It's a matter of setting your own goals and following them.","cn":"这就需要设立自己的目标并为之努力。"}}]},"examples":[{"en":"Our ultimate goal must be the preservation of the environment.","cn":"我们的最终目的必须是环境保护。"},{"en":"United conceded two goals in the first half.","cn":"联队在上半场被攻入了两球。"}]},"greatness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"extremely big","cn":""},{"en":"very big – used especially to describe the level or number of something","cn":""}]},"examples":[{"en":"The movie was a great success.","cn":"","src":"ld"},{"en":"The news came as possibly the greatest shock of my life.","cn":"","src":"ld"}],"media":{"uk":"media/uk/greatness__gb_1.mp3","us":"media/us/greatness__us_1.mp3"},"oxford":{"phon":"ˈɡreɪtnəs","pos":"noun","senses":[{"en":"the fact of having high status or a lot of influence","cn":"地位高的；位高权重的；影响大的","ex":{"en":"He was made into a symbol of national greatness.","cn":"他被塑造成国家强大的象征。"}},{"en":"the quality of being extremely good in ability or quality and therefore admired by many people","cn":"伟大的；优秀的；杰出的；卓越的","ex":{"en":"The novel's greatness lies in its simplicity.","cn":"这部小说的伟大之处在于它的简洁。"}}]}},"geographically":{"media":{"uk":"media/uk/geographically__gb_1.mp3","us":"media/us/geographically__us_1.mp3"},"examples":[{"en":"geographically remote areas","cn":"地理上的边远地区"},{"en":"their geographical proximity to Japan (= nearness to Japan )","cn":""}],"oxford":{"phon":"ˌdʒiːəˈɡræfɪkli","pos":"adverb","senses":[{"en":"in a way that is connected with how the physical features of a place are arranged","cn":"地形；地貌；地势","ex":{"en":"geographically remote areas","cn":"偏远地区"}},{"en":"in a way that is connected with how a particular aspect of life or society is influenced by geography or varies according to geography","cn":"地理环境","ex":{"en":"There is currently much interest in the ways in which public money is distributed geographically.","cn":"目前人们对公共资金的地理分配方式很感兴趣。"}}]}},"global":{"media":{"uk":"media/uk/global__gb_1.mp3","us":"media/us/global__us_1.mp3"},"oxford":{"phon":"ˈɡləʊbl","pos":"adjective","senses":[{"en":"covering or affecting the whole world","cn":"全球的；全世界的","lab":"US English","ex":{"en":"This year the global economy will grow by about 4 per cent.","cn":"今年全球经济将增长 4% 左右。"}},{"en":"considering or including all parts of something","cn":"整体的；全面的；总括的","ex":{"en":"We need to take a more global approach to the problem.","cn":"我们需要更全面地看这个问题。"}},{"en":"operating or applying through the whole of a file, program, etc.","cn":"全局的；全文的","lab":"computing","ex":{"en":"We ran a global search on the database.","cn":"我们在数据库中进行了全程检索。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"全球的；全世界的","en":"You can use global to describe something that happens in all parts of the world or affects all parts of the world.","ex":{"en":"...a global ban on nuclear testing","cn":"全球核试验禁令"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"全面的；整体的；总括的","en":"A global view or vision of a situation is one in which all the different aspects of it are considered.","ex":{"en":"...the global view, the ability to make wider decisions based on a knowledge of all the facts, not just some of them.","cn":"大局观——基于全部而非部分事实作出更加宏观的决定的能力"}}]},"examples":[{"en":"They sent a global email to all staff.","cn":"他们向全体职员发了一封统一的电邮。"},{"en":"We need to take a more global approach to the problem.","cn":"我们需要更全面地看这个问题。"}]},"gregarious":{"media":{"uk":"media/uk/gregarious__gb_1.mp3","us":"media/us/gregarious__us_1.mp3"},"oxford":{"phon":"ɡrɪˈɡeəriəs","pos":"adjective","senses":[{"en":"liking to be with other people","cn":"爱交际的；合群的","ex":{"en":"She’s very outgoing and gregarious.","cn":"她非常外向且合群。"}},{"en":"living in groups","cn":"群居的","lab":"biology"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"爱交际的；合群的","en":"Someone who is gregarious enjoys being with other people.","ex":{"en":"She is such a gregarious and outgoing person.","cn":"她很外向，喜欢交朋结友。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（动物、鸟等）群居的","en":"Gregarious animals or birds normally live in large groups.","ex":{"en":"Snow geese are very gregarious birds.","cn":"雪雁是群居性鸟类。"}}]}},"guesses":{"lemma":"guess"},"groundbreaking":{"media":{"uk":"media/uk/groundbreaking__gb_1.mp3","us":"media/us/groundbreaking__us_1.mp3"},"oxford":{"phon":"ˈɡraʊndbreɪkɪŋ","pos":"adjective","senses":[{"en":"making new discoveries; using new methods","cn":"开创性的；创新的；革新的","ex":{"en":"a groundbreaking piece of research","cn":"富有开拓性的一项研究"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"开创性的；创新的；革新的","en":"You use groundbreaking to describe things which you think are significant because they provide new and positive ideas, and influence the way people think about things.","ex":{"en":"...his groundbreaking novel on homosexuality.","cn":"他关于同性恋题材的开创性小说"}}]},"examples":[{"en":"a groundbreaking piece of research","cn":"富有开拓性的一项研究"},{"en":"groundbreaking research","cn":"具开拓性的研究"}]},"gravel":{"media":{"uk":"media/uk/gravel__gb_1.mp3","us":"media/us/gravel__us_1.mp3"},"oxford":{"phon":"ˈɡrævl","pos":"noun","senses":[{"en":"small stones, often used to make the surface of paths and roads","cn":"沙砾；砾石；石子","ex":{"en":"a gravel path","cn":"石子路"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"砂砾；砾石","en":"Gravel consists of very small stones. It is often used to make paths.","ex":{"en":"...a gravel path leading to the front door.","cn":"通向前门的石子路"}}]},"examples":[{"en":"a gravel pit (= a place where gravel is taken from the ground)","cn":"砾石采掘场"},{"en":"a gravel path","cn":"石子路"}]},"gulf":{"media":{"uk":"media/uk/gulf__gb_1.mp3","us":"media/us/gulf__us_1.mp3"},"oxford":{"phon":"ɡʌlf","pos":"noun","senses":[{"en":"a large area of sea that is partly surrounded by land","cn":"海湾","g":"[countable]","ex":{"en":"the Gulf of Mexico","cn":"墨西哥湾"}},{"en":"the Persian Gulf, the area of sea between the Arabian peninsula and Iran","cn":"波斯湾","g":"[singular]"},{"en":"a large difference between two people or groups in the way that they think, live or feel","cn":"分歧；鸿沟；隔阂","g":"[countable, usually singular]","ex":{"en":"The gulf between rich and poor is enormous.","cn":"贫富悬殊。"}},{"en":"a wide deep opening in the ground","cn":"（地面的）裂口，深坑，沟壑","g":"[countable]"}]},"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"波斯湾；阿拉伯海湾；海湾地区","en":"The Gulf is used to refer to the Arabian Gulf, the Persian Gulf and the surrounding countries.","ex":{"en":"...the Gulf crisis.","cn":"海湾危机"}}]},"examples":[{"en":"The gulf between rich and poor is enormous.","cn":"贫富悬殊。"},{"en":"the Gulf States (= the countries with coasts on the Gulf)","cn":"海湾国家"}]},"generation":{"media":{"uk":"media/uk/generation__gb_1.mp3","us":"media/us/generation__us_1.mp3"},"oxford":{"phon":"ˌdʒenəˈreɪʃn","pos":"noun","senses":[{"en":"all the people who were born at about the same time","cn":"（统称）一代人，同代人，同辈人","g":"[countable + singular or plural verb]","ex":{"en":"the younger/older generation","cn":"年轻的一代；老一辈"}},{"en":"the average time in which children grow up, become adults and have children of their own, (usually considered to be about 30 years)","cn":"代，一代，一辈（通常认为大约 30 年）","g":"[countable]","ex":{"en":"Many more people go to university now than a generation ago.","cn":"现在上大学的人比上一代人多得多。"}},{"en":"a single stage in the history of a family","cn":"（家史中的）一代，一辈","g":"[countable, uncountable]","ex":{"en":"stories passed down from generation to generation","cn":"世代相传的故事"}},{"en":"a group of people of similar age involved in a particular activity","cn":"一批，一届（从事特定活动的同龄人）","g":"[countable, usually singular]","ex":{"en":"He influenced my generation more than any other actor.","cn":"他对我们这一代的影响比其他任何演员都大。"}},{"en":"a stage in the development of a product, usually a technical one","cn":"（产品发展，尤指技术方面的）代","g":"[countable, usually singular]","ex":{"en":"fifth-generation computing","cn":"第五代计算机技术"}},{"en":"the production of something, especially electricity, heat, etc.","cn":"（尤指电、热等的）产生","g":"[uncountable]","ex":{"en":"the generation of electricity","cn":"发电"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指经历或观点相同的）一代人，同代人，同辈人","en":"A generation is all the people in a group or country who are of a similar age, especially when they are considered as having the same experiences or attitudes.","ex":{"en":"...the younger generation of Party members","cn":"年轻一代的党员"}},{"pos":"N-COUNT 可数名词","cn":"代，一代，一辈（通常认为大约是30年）","en":"A generation is the period of time, usually considered to be about thirty years, that it takes for children to grow up and become adults and have children of their own.","ex":{"en":"Within a generation flight has become the method used by many travellers.","cn":"就在不到一代人的时间里，坐飞机已经成了很多旅行者的出行方式。"}},{"pos":"N-COUNT 可数名词","cn":"（机械设备的设计和制造的）代","en":"You can use generation to refer to a stage of development in the design and manufacture of machines or equipment.","ex":{"en":"...a new generation of IBM/Apple computers.","cn":"新一代的IBM/苹果电脑"}},{"pos":"ADJ 形容词","cn":"（表示家庭成员拥有某国国籍的时间长短情况）第…代的","en":"Generation is used to indicate how long members of your family have had a particular nationality. For example, second generation means that you were born in the country you live in, but your parents were not.","ex":{"en":"...second generation Asians in Britain","cn":"英国的第二代亚洲移民"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（能源的）产生","en":"Generation is also the production of a form of energy or power from fuel or another source of power such as water.","ex":{"en":"Japan has announced plans for a sharp rise in its nuclear power generation.","cn":"日本宣布了大幅增加核能发电的计划。"}}]},"examples":[{"en":"a first-/second-generation American (= a person whose family has lived in America for one/two generations)","cn":"第一/第二代美国人（家人在美国居住了一、二代者）"},{"en":"My generation have grown up without the experience of a world war.","cn":"我这一代人在成长过程中没有经历过世界大战。"}]},"gallantry":{"media":{"uk":"media/uk/gallantry__gb_1.mp3","us":"media/us/gallantry__us_1.mp3"},"oxford":{"phon":"ˈɡæləntri","pos":"noun","senses":[{"en":"courage, especially in a battle","cn":"（尤指在战场上）勇敢，英勇顽强","ex":{"en":"a medal for gallantry","cn":"英勇勋章"}},{"en":"polite attention given by men to women","cn":"（男子对女子的）殷勤","ex":{"en":"‘I like to think that gallantry isn’t dead,’ he said, kissing her hand.","cn":"“我认为，英勇还没有消亡，”他一边说，一边亲吻她的手。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"英勇；勇敢","en":"Gallantry is bravery shown by someone who is in danger, for example when they are fighting in a war.","ex":{"en":"For his gallantry he was awarded a Victoria Cross.","cn":"他因为表现英勇而荣获维多利亚十字勋章。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（尤指对女子的）殷勤，彬彬有礼","en":"Gallantry is kind, polite, and considerate behaviour towards other people, especially women.","ex":{"en":"It's that time of year again, when thoughts turn to romance and gallantry.","cn":"又到了每年的那个时候，人们又想到了风花雪月和献殷勤的男人。"}}]},"examples":[{"en":"a medal for gallantry","cn":"英勇勋章"}]},"glittering":{"media":{"uk":"media/uk/glittering__gb_1.mp3","us":"media/us/glittering__us_1.mp3"},"oxford":{"phon":"ˈɡlɪtərɪŋ","pos":"adjective","senses":[{"en":"very impressive and successful","cn":"辉煌的；成功的","ex":{"en":"He has a glittering career ahead of him.","cn":"他前程似锦。"}},{"en":"very impressive and involving rich and successful people","cn":"盛大的；华丽的；众星云集的","ex":{"en":"a glittering occasion/ceremony","cn":"盛会；盛典"}},{"en":"shining brightly with many small flashes of light","cn":"灿烂夺目的；闪闪发光的","ex":{"en":"glittering jewels","cn":"璀璨的宝石"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"辉煌的；成功的","en":"You use glittering to indicate that something is very impressive or successful.","ex":{"en":"...a brilliant school pupil destined for a glittering academic career.","cn":"必将在学术上取得辉煌成就的杰出学生"}}]},"examples":[{"en":"He has a glittering career ahead of him.","cn":"他前程似锦。"},{"en":"a glittering array of stars","cn":"众星云集的盛大场面"}],"base":"glitter"},"goods":{"media":{"uk":"media/uk/goods__gb_1.mp3","us":"media/us/goods__us_1.mp3"},"oxford":{"phon":"ɡʊdz","pos":"noun","senses":[{"en":"things that are produced to be sold","cn":"商品；货品","ex":{"en":"to produce/buy/sell goods","cn":"生产／购买／销售商品"}},{"en":"possessions that can be moved","cn":"动产；私人财产","ex":{"en":"He was accused of handling stolen goods.","cn":"他被指控买卖赃物。"}},{"en":"things (not people) that are transported by railway or road","cn":"（铁路或公路）运载的货物","lab":"British English","ex":{"en":"A goods train was derailed last night.","cn":"昨晚一列货车脱轨。"}}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"货物；商品","en":"Goods are things that are made to be sold.","ex":{"en":"Money can be exchanged for goods or services.","cn":"钱可以用来换取商品或服务。"}},{"pos":"N-PLURAL 复数名词","cn":"私人财产；动产","en":"Your goods are the things that you own and that can be moved.","ex":{"en":"All his worldly goods were packed into a neat checked carrier bag","cn":"他的所有家当都装在一个干净的方格图案手提袋里。"}},{"pos":"PHRASE 短语","cn":"不负众望；达到要求","en":"If you deliver the goods or come up with the goods, you do what is expected or required of you.","ex":{"en":"As long as I deliver the goods, my boss is very happy.","cn":"只要我做好本职工作，我的老板就很高兴。"}},{"pos":"PHRASE 短语","cn":"掌握了…的罪证（或把柄）","en":"If you get the goods or have the goods on someone, you have evidence that they have done something wrong or criminal.","ex":{"en":"He was the victim of those in his own party who had the goods on him.","cn":"党内一些人掌握了他的把柄，结果他成了牺牲品。"}}]},"examples":[{"en":"We expected great things of the England team, but on the day they simply failed to deliver the goods.","cn":"我们本指望英格兰队大获全胜，可那天他们真是有负众望。"},{"en":"The plastic bag contained all his worldly goods (= everything he owned).","cn":"这塑料袋里装着他的全部家当。"}],"base":"good"},"gis":{"oxford":{"phon":"ˌdʒiː ˈaɪ","pos":"noun","senses":[{"en":"a soldier in the US armed forces","cn":"美国兵"},{"en":"Glycaemic Index (= a system for measuring the effect of foods containing carbohydrates on the level of sugar in the blood)","cn":"升糖指数；血糖指数"}]},"media":{"uk":"media/uk/gi__gb_1.mp3","us":"media/us/gi__us_1.mp3"}},"gloomy":{"media":{"uk":"media/uk/gloomy__gb_1.mp3","us":"media/us/gloomy__us_1.mp3"},"oxford":{"phon":"ˈɡluːmi","pos":"adjective","senses":[{"en":"nearly dark, or badly lit in a way that makes you feel sad","cn":"黑暗的；阴暗的；幽暗的","ex":{"en":"a gloomy room/atmosphere","cn":"昏暗的房间；阴沉沉的气氛"}},{"en":"sad and without hope","cn":"忧郁的；沮丧的；无望的","ex":{"en":"a gloomy expression","cn":"沮丧的表情"}},{"en":"without much hope of success or happiness in the future","cn":"前景黯淡的；悲观的","ex":{"en":"a gloomy picture of the country’s economic future","cn":"该国经济前景的黯淡景象"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"昏暗的；幽暗的","en":"If a place is gloomy, it is almost dark so that you cannot see very well.","ex":{"en":"Inside it's gloomy after all that sunshine","cn":"尽管阳光明媚，里面依然暗淡无光。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"忧伤的；沮丧的；无望的","en":"If people are gloomy, they are unhappy and have no hope.","ex":{"en":"Miller is gloomy about the fate of the serious playwright in America.","cn":"米勒对这位严肃剧作家在美国的命运颇为忧虑。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"前景黯淡的；悲观的","en":"If a situation is gloomy, it does not give you much hope of success or happiness.","ex":{"en":"...a gloomy picture of an economy sliding into recession","cn":"经济陷入萧条的惨淡景象"}}]},"examples":[{"en":"Suddenly, the future didn't look so gloomy after all.","cn":"突然感到前途似乎并非如此黯淡。"},{"en":"It was a wet and gloomy day.","cn":"那一天下着雨，阴沉沉的。"}]},"guardians":{"lemma":"guardian"},"game":{"media":{"uk":"media/uk/game__gb_1.mp3","us":"media/us/game__us_1.mp3"},"oxford":{"phon":"ɡeɪm","pos":"noun","senses":[{"en":"an activity that you do to have fun, often one that has rules and that you can win or lose; the equipment for a game","cn":"游戏；游戏机；游戏用具","g":"[countable]","sc":"fun","ex":{"en":"The kids were playing a game with their balloons.","cn":"孩子们正在用气球玩游戏。"}},{"en":"a sport with rules in which people or teams compete against each other","cn":"运动项目","g":"[countable]","sc":"sport","ex":{"en":"ball games, such as football or tennis","cn":"诸如足球或网球等球类运动"}},{"en":"an occasion of playing a game","cn":"（一项）游戏，运动，比赛","g":"[countable]","lab":"especially North American English","sc":"sport","ex":{"en":"to win/lose a game","cn":"赢／输一场比赛"}},{"en":"the way in which somebody plays a game","cn":"比赛（或游戏）时用的手法；比赛（或游戏）技巧","g":"[singular]","sc":"sport","ex":{"en":"Maguire raised his game to collect the £40 000 first prize.","cn":"马圭尔的比赛技巧有所提升，摘得 4 万英镑的一等奖。"}},{"en":"a large organized sports event","cn":"运动会","g":"[plural]","sc":"sport","ex":{"en":"She's hoping to participate in the next Olympic Games.","cn":"她希望参加下一届奥运会。"}},{"en":"sport as a lesson or an activity at school","cn":"（学校的）体育课，体育活动","g":"[plural]","lab":"old-fashioned, British English，，","sc":"sport","ex":{"en":"I always hated games at school.","cn":"我念书的时候一直不喜欢体育活动。"}},{"en":"a section of some games, such as tennis, which forms a unit in scoring","cn":"（网球等比赛的）一局，一场","g":"[countable]","sc":"sport","ex":{"en":"two games all (= both players have won two games)","cn":"各赢两局"}},{"en":"a type of activity or business","cn":"行当；行业；职业","g":"[countable]","sc":"activity/business","ex":{"en":"How long have you been in this game?","cn":"你干这行当多长时间了？"}},{"en":"a secret and clever plan; a trick","cn":"诡计；策略；花招","g":"[singular]","lab":"informal","sc":"secret plan","ex":{"en":"So that's his game (= now I know what he has been planning).","cn":"原来这就是他的鬼把戏。"}},{"en":"wild animals or birds that people hunt for sport or food","cn":"猎物；野禽；野味","g":"[uncountable]","sc":"wild animals/birds"},{"en":"to risk money playing a game of chance","cn":"赌博","g":"[intransitive]","pos":"verb"},{"en":"to play video games","cn":"玩电子游戏","g":"[intransitive]","pos":"verb"},{"en":"to use something in a way that is unfair but legal, in order to get what you want","cn":"不公平地利用；钻法律空子图利","g":"[transitive]","ex":{"en":"Some companies only received a government grant because they gamed the system.","cn":"一些公司钻了这个制度的空子而得到了政府补助。"},"pos":"verb"},{"en":"to treat somebody who trusts you in an unfair way in order to get what you want","cn":"不公平地对待；利用","g":"[transitive]","ex":{"en":"He gamed his publishers, his family and his friends in order to make a success of his autobiography.","cn":"为了使自己的自传成功，他利用了他的出版商、家人和朋友。"},"pos":"verb"},{"en":"ready and willing to do something new, difficult or dangerous","cn":"甘愿尝试；有冒险精神","ex":{"en":"She's game for anything.","cn":"她什么事都敢试。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"游戏；运动；比赛（项目）","en":"A game is an activity or sport usually involving skill, knowledge, or chance, in which you follow fixed rules and try to win against an opponent or to solve a puzzle.","ex":{"en":"...the wonderful game of football.","cn":"精彩的足球比赛"}},{"pos":"N-COUNT 可数名词","cn":"（一场）游戏，比赛","en":"A game is one particular occasion on which a game is played.","ex":{"en":"It was the first game of the season","cn":"这是本赛季的首场比赛。"}},{"pos":"N-COUNT 可数名词","cn":"（网球、桥牌等比赛中的）一局，一盘，一场","en":"A game is a part of a match, for example in tennis or bridge, consisting of a fixed number of points.","ex":{"en":"She won six games to love in the second set.","cn":"第二盘她以6比0获胜。"}},{"pos":"N-PLURAL 复数名词","cn":"运动会","en":"Games are an organized event in which competitions in several sports take place.","ex":{"en":"...the 2000 Olympic Games at Sydney.","cn":"2000年悉尼奥运会"}},{"pos":"N-PLURAL 复数名词","cn":"（学校的）体育课，体育活动","en":"Games are organized sports activities that children do at school.","ex":{"en":"At his grammar school he is remembered for being bad at games but good in debates.","cn":"在文法学校里，他因拙于体育但擅长辩论而让人印象深刻。"}},{"pos":"N-SING 单数名词","cn":"（某人比赛或游戏时的）手法，技巧，风格","en":"Someone's game is the degree of skill or the style that they use when playing a particular game.","ex":{"en":"Once I was through the first set my game picked up.","cn":"我打完第一局之后就进入了状态。"}},{"pos":"N-COUNT 可数名词","cn":"玩笑；儿戏；不认真对待的事情","en":"You can describe a situation that you do not treat seriously as a game .","ex":{"en":"Many people regard life as a game: you win some, you lose some","cn":"许多人视人生如同一场游戏：有输也有赢。"}},{"pos":"N-COUNT 可数名词","cn":"策略；计谋；诡计","en":"You can use game to describe a way of behaving in which a person uses a particular plan, usually in order to gain an advantage for himself or herself.","ex":{"en":"When the uncertainties become greater than the certainties, we end up in a game of bluff","cn":"情况愈发难以确定，我们最终陷入一个唬人的把戏中。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"猎物；野味","en":"Wild animals or birds that are hunted for sport and sometimes cooked and eaten are referred to as game .","ex":{"en":"...men who shot game for food.","cn":"靠捕猎获取食物的人"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"甘愿尝试（新鲜或不平常事物）的；有冒险精神的","en":"If you are game for something, you are willing to do something new, unusual, or risky.","ex":{"en":"After all this time he still had new ideas and was game to try them","cn":"过了这么久，他依然不乏新点子并敢于去尝试。"}},{"pos":"PHRASE 短语","cn":"泄露秘密；露马脚；露馅","en":"If someone or something gives the game away, they reveal a secret or reveal their feelings, and this puts them at a disadvantage.","ex":{"en":"The faces of the two conspirators gave the game away.","cn":"这两个共谋者的表情泄漏了秘密。"}},{"pos":"PHRASE 短语","cn":"对…不了解；缺乏经验","en":"If you are new to a particular game, you have not done a particular activity or been in a particular situation before.","ex":{"en":"Don't forget that she's new to this game and will take a while to complete the task.","cn":"别忘了她缺乏这方面的经验，完成任务还需要一些时间。"}},{"pos":"PHRASE 短语","cn":"卖淫；当妓女（或“鸭子”）","en":"If a man or woman is on the game, he or she is working as a prostitute."},{"pos":"PHRASE 短语","cn":"将计就计；以其人之道还治其人之身","en":"If you beat someone at their own game, you use the same methods that they have used, but more successfully, so that you gain an advantage over them.","ex":{"en":"He must anticipate the maneuvers of the other lawyers and beat them at their own game","cn":"他必须预见到其他律师的策略，并以其人之道还治其人之身，从而打败他们。"}},{"pos":"PHRASE 短语","cn":"（某种情况下）常有的事，司空见惯的事","en":"If you say that something is all part of the game, you are telling someone not to be surprised or upset by something, because it is a normal part of the situation that they are in.","ex":{"en":"For investors, risks are part of the game.","cn":"对投资者而言,风险不足为奇。"}},{"pos":"PHRASE 短语","cn":"不认真对待；耍花招；玩把戏","en":"If you say that someone is playing games or playing silly games, you mean that they are not treating a situation seriously and you are annoyed with them.","ex":{"en":"'Don't play games with me!' he thundered","cn":"“别跟我耍把戏!”他怒吼道。"}},{"pos":"PHRASE 短语","cn":"（通常在压力下）开始更好表现，干得更出色","en":"If you say that someone has raised their game, you mean that they have begun to perform better, usually because they were under pressure to do so.","ex":{"en":"The world No. 9 had to raise his game to see off a strong challenge from Dale","cn":"这位世界排名第九的选手必须有更出色的表现才能击退戴尔强有力的挑战。"}},{"pos":"PHRASE 短语","cn":"戏该收场了，别再演戏了（指所从事的秘密计划或活动被揭穿）","en":"If you say the game is up, you mean that someone's secret plans or activities have been revealed and therefore must stop because they cannot succeed.","ex":{"en":"Some thought they would hold out until Sunday. The realists knew that the game was already up.","cn":"有些人以为他们还能撑到星期天，务实的人却很清楚，这一切都已结束了。"}}]},"examples":[{"en":"We were losing 2–0 with ten minutes to go, and then we scored. It was game on!","cn":"离终场还有十分钟，我们以 0:2 落后，随后我们进球了。谁输谁赢还说不定呢！"},{"en":"Maguire raised his game to collect the £40 000 first prize.","cn":"马圭尔的比赛技巧有所提高，得到了 4 万英镑的头等奖。"}]},"gloved":{"media":{"uk":"media/uk/gloved__gb_1.mp3","us":"media/us/gloved__us_1.mp3"},"oxford":{"phon":"ɡlʌvd","pos":"adjective","senses":[{"en":"wearing a glove or gloves","cn":"戴着手套的","ex":{"en":"She laid her gloved hand on my arm.","cn":"她把戴着手套的手放在我的手臂上。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"戴手套的","en":"A gloved hand has a glove on it.","ex":{"en":"His gloved hand held up a computer disk.","cn":"他用那只戴着手套的手拿起一张光盘。"}}]}},"grocer":{"oxford":{"phon":"ˈɡrəʊsə(r)","pos":"noun","senses":[{"en":"a person who owns, manages or works in a shop selling food and other things used in the home","cn":"食品杂货商"},{"en":"a shop that sells these things","cn":"食品杂货店"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"食品杂货商","en":"A grocer is a shopkeeper who sells foods such as flour, sugar, and tinned foods."},{"pos":"N-COUNT 可数名词","cn":"食品杂货店","en":"A grocer or a grocer's is a shop where foods such as flour, sugar, and tinned foods are sold."}]},"media":{"uk":"media/uk/grocer__gb_1.mp3","us":"media/us/grocer__us_1.mp3"}},"guard":{"oxford":{"phon":"ɡɑːd","pos":"noun","senses":[{"en":"a person, such as a soldier, a police officer or a prison officer, who protects a place or people, or prevents prisoners from escaping","cn":"卫兵；警卫员；看守","g":"[countable]","sc":"people who protect","ex":{"en":"prison/border guards","cn":"监狱看守；边防卫士"}},{"en":"the act or duty of protecting property, places or people from attack or danger; the act or duty of preventing prisoners from escaping","cn":"警戒；保卫；保护；看守","g":"[uncountable]","sc":"people who protect","ex":{"en":"a sentry on guard (= at his or her post, on duty)","cn":"执勤哨兵"}},{"en":"a group of people, such as soldiers or police officers, who protect somebody/something","cn":"（统称）卫兵，警卫，看守","g":"[countable + singular or plural verb]","sc":"people who protect","ex":{"en":"the captain of the guard","cn":"卫队长"}},{"en":"(in the UK and some other countries) special regiments of soldiers whose original duty was to protect the king or queen","cn":"（英国和其他一些国家的）禁军，御林军，近卫军","g":"[plural]","sc":"people who protect","ex":{"en":"the Scots Guards","cn":"苏格兰卫队"}},{"en":"something that covers a part of a person’s body or a dangerous part of a machine to prevent injury","cn":"防护罩；防护装置；防护用品","g":"[countable]","sc":"against injury","ex":{"en":"All players wear helmets and face guards.","cn":"所有球员都戴头盔和面罩。"}},{"en":"conductor (= a person who is in charge of a train and travels with it, but does not drive it)","cn":"列车长","g":"[countable]","lab":"British English, becoming old-fashioned，，","sc":"on train"},{"en":"a position you take to defend yourself, especially in a sport such as boxing or fencing","cn":"防御姿势","g":"[uncountable]","lab":"figurative","sc":"in boxing/fencing","ex":{"en":"to drop/keep up your guard","cn":"放弃／保持防御姿势"}},{"en":"one of the two players on a basketball team who are mainly responsible for staying close to players of the other team to stop them from scoring","cn":"后卫","g":"[countable]","sc":"in basketball"},{"en":"one of the two players on an American football team who play either side of the centre forward","cn":"（中锋两侧的）哨锋","g":"[countable]","sc":"in American football"},{"en":"to protect property, places or people from attack or danger","cn":"警卫；守卫；保卫","lab":"figurative","ex":{"en":"Armed officers guarded the entrance.","cn":"武装人员把守着入口。"},"pos":"verb"},{"en":"to prevent prisoners from escaping","cn":"看守，监视（囚犯）","ex":{"en":"The prisoners were guarded by soldiers.","cn":"犯人由士兵看守。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"守卫；护卫；警卫","en":"If you guard a place, person, or object, you stand near them in order to watch and protect them.","ex":{"en":"Gunmen guarded homes near the cemetery with shotguns","cn":"持枪者手持猎枪守卫着墓地附近的房子。"}},{"pos":"VERB 动词","cn":"看守；监视","en":"If you guard someone, you watch them and keep them in a particular place to stop them from escaping.","ex":{"en":"Marines with rifles guarded them","cn":"手持步枪的海军陆战队士兵监视着他们。"}},{"pos":"N-COUNT 可数名词","cn":"卫兵；警卫员；看守","en":"A guard is someone such as a soldier, police officer, or prison officer who is guarding a particular place or person.","ex":{"en":"The prisoners overpowered their guards and locked them in a cell.","cn":"囚犯们制服了监狱看守，并将他们锁进了牢房。"}},{"pos":"N-SING-COLL 单数集合名词","cn":"（一队）卫兵；（一队）警卫","en":"A guard is a specially organized group of people, such as soldiers or policemen, who protect or watch someone or something.","ex":{"en":"We have a security guard around the whole area","cn":"我们在该地区各处部署了保安。"}},{"pos":"N-COUNT 可数名词","cn":"列车长","en":"On a train, a guard is a person whose job is to travel on the train in order to help passengers, check tickets, and make sure that the train travels safely and on time."},{"pos":"VERB 动词","cn":"保护；保守；遮掩","en":"If you guard some information or advantage that you have, you try to protect it or keep it for yourself.","ex":{"en":"He closely guarded her identity.","cn":"他对她的身份守口如瓶。"}},{"pos":"N-COUNT 可数名词","cn":"保护装置；保护罩；保护器","en":"A guard is a protective device which covers a part of someone's body or a dangerous part of a piece of equipment.","ex":{"en":"...the chin guard of my helmet","cn":"我头盔上的下巴保护罩"}},{"pos":"N-IN-NAMES 名称名词","cn":"（英国的）近卫军，禁军，近卫军士兵","en":"Some regiments in the British Army, or the soldiers in them, are referred to as Guards.","ex":{"en":"...the Grenadier Guards.","cn":"英国近卫步兵团"}},{"pos":"PHRASE 短语","cn":"乘（人）不备；使猝不及防","en":"If someone catches you off guard, they surprise you by doing something you do not expect. If something catches you off guard, it surprises you by happening when you are not expecting it.","ex":{"en":"Charm the audience and catch them off guard","cn":"吸引观众的注意力，然后给他们来个出其不意。"}},{"pos":"PHRASE 短语","cn":"丧失警惕；放松警惕；不提防","en":"If you lower your guard ,let your guard down or drop your guard, you relax when you should be careful and alert, often with unpleasant consequences.","ex":{"en":"The ANC could not afford to lower its guard until everything had been carried out","cn":"非洲人国民大会在所有事项皆已完成前不敢有丝毫松懈。"}},{"pos":"PHRASE 短语","cn":"派人守卫；安排看守","en":"If you mount guard or if you mount a guard, you organize people to watch or protect a person or place.","ex":{"en":"They've even mounted guard outside the main hotel in the capital","cn":"他们甚至派人在首都的大饭店外面站岗。"}},{"pos":"PHRASE 短语","cn":"警惕；提防","en":"If you are on your guard or on guard, you are being very careful because you think a situation might become difficult or dangerous.","ex":{"en":"The police have questioned him thoroughly, and he'll be on his guard","cn":"警方已经对他进行了详细的盘问，因此他会保持戒备心理。"}},{"pos":"PHRASE 短语","cn":"站岗；值班","en":"If someone is on guard, they are on duty and responsible for guarding a particular place or person.","ex":{"en":"Police were on guard at Barnet town hall.","cn":"警察在巴尼特市政厅值守。"}},{"pos":"PHRASE 短语","cn":"站岗；放哨","en":"If you stand guard, you stand near a particular person or place because you are responsible for watching or protecting them.","ex":{"en":"One young policeman stood guard outside the locked embassy gates.","cn":"一位年轻的警察在大门紧闭的使馆外站岗。"}},{"pos":"PHRASE 短语","cn":"在…看守之下","en":"If someone is under guard, they are being guarded.","ex":{"en":"Three men were arrested and one was under guard in hospital.","cn":"有3人被逮捕，1人在警方监护下送医院治疗。"}},{"pos":"","cn":"","en":"相关词组：guard against"}]},"media":{"uk":"media/uk/guard__gb_1.mp3","us":"media/us/guard__us_1.mp3"},"examples":[{"en":"( figurative ) In spite of the awkward questions the minister never let his guard fall for a moment.","cn":"尽管遇到些令人尴尬的问题，部长从没有丝毫退缩。"},{"en":"The lawyer's apparently innocent question was designed to catch the witness off (his) guard.","cn":"律师看似不经意的问题是为了使证人措手不及。"}]},"gimme":{"media":{"uk":"media/uk/gimme__gb_1.mp3","us":"media/us/gimme__us_1.mp3"},"oxford":{"phon":"ˈɡɪmi","pos":"short form","senses":[{"en":"a way of writing the way that the words ‘give me’ are sometimes spoken","cn":"（give me 的一种书写形式，表示此短语某些时候的读法）给我","ex":{"en":"Gimme back my bike!","cn":"把自行车还给我！"}},{"en":"something that is very easy to do or achieve","cn":"轻而易举的事；容易获得的事物","ex":{"en":"The two-foot putt was hardly a gimme.","cn":"两英尺推杆可不是一件容易的事情。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"","cn":"（用于书面英语中，表示give me的非正式发音形式）","en":"Gimme is sometimes used in written English to represent the words 'give me' when they are pronounced informally.","ex":{"en":"'Gimme a break, kid! You know how much those things cost?'","cn":"“饶了我吧，小祖宗！你知道这些东西有多贵吗？”"}}]},"examples":[{"en":"Gimme back my bike!","cn":"把自行车还给我！"},{"en":"Gimme the ball!","cn":"把球给我！"}]},"growing":{"media":{"uk":"media/uk/growing__gb_1.mp3","us":"media/us/growing__us_1.mp3"},"oxford":{"phon":"ˈɡrəʊɪŋ","pos":"adjective","senses":[{"en":"increasing in size, amount or degree","cn":"增加的；增长的；增强的","ex":{"en":"A growing number of people are returning to full-time education.","cn":"越来越多的人重返学校接受全日制教育。"}},{"en":"becoming bigger and taller and developing into an adult","cn":"成长的；发育的；生长的","ex":{"en":"A growing child needs plenty of sleep.","cn":"成长中的孩子需要充足的睡眠。"}}]},"examples":[{"en":"A growing number of people are returning to full-time education.","cn":"越来越多的人重返学校接受全日制教育。"},{"en":"There is growing concern over the safety of the missing teenager.","cn":"人们对这个失踪少年的安全越来越担心。"}],"base":"grow"},"granted":{"oxford":{"phon":"ˈɡrɑːntɪd","pos":"adverb","senses":[{"en":"used to show that you accept that something is true, often before you make another statement about it","cn":"（表示肯定属实，然后再作另一番表述）不错，的确","ex":{"en":"‘You could have done more to help.’ ‘Granted.’","cn":"“你本可以多给点帮助的。”“我承认。”"}},{"en":"because of the fact that","cn":"因为","ex":{"en":"Granted that it is a simple test to perform, it should be easy to get results quickly.","cn":"因为这化验做起来简单，所以应该不难很快得出结果。"},"pos":"conjunction"}]},"collins":{"senses":[{"pos":"CONJ-SUBORD 连词","cn":"（表示某事属实，然后再对其作出评论）不错，的确","en":"You use granted or granted that at the beginning of a clause to say that something is true, before you make a comment on it.","ex":{"en":"Granted that the firm has not broken the law, is the law what it should be?","cn":"的确，这家公司没有违法，但这样的法律是否合理呢？"}}]},"media":{"uk":"media/uk/granted__gb_1.mp3","us":"media/us/granted__us_1.mp3"},"examples":[{"en":"Granted that it is a simple test to perform, it should be easy to get results quickly.","cn":"因为这化验做起来简单，所以应该不难很快得出结果。"},{"en":"Granted, it's not the most pleasant of jobs but it has to be done.","cn":"的确，这不是最令人愉快的工作，但也得做呀。"}],"base":"grant"},"globe":{"media":{"uk":"media/uk/globe__gb_1.mp3","us":"media/us/globe__us_1.mp3","img":["media/ldoce/img/globe.jpg"]},"oxford":{"phon":"ɡləʊb","pos":"noun","senses":[{"en":"the world (used especially to emphasize its size)","cn":"地球，世界（尤用以强调其大）","g":"[singular]","ex":{"en":"tourists from every corner of the globe","cn":"来自世界各地的游客"}},{"en":"an object like a ball in shape with a map of the world on its surface, usually on a stand so that it can be turned","cn":"地球仪","g":"[countable]","ex":{"en":"A dusty old globe stood in the corner of the schoolroom.","cn":"教室的角落里放着一个积满灰尘的旧地球仪。"}},{"en":"a thing that is like a ball in shape","cn":"球体；球状物","g":"[countable]"},{"en":"a light bulb (= the glass part that fits into an electric lamp, etc. to give light when it is switched on)","cn":"灯泡","lab":"Australian English, New Zealand English，，","ex":{"en":"Halogen globes are being replaced with LEDs, which use 80 per cent less energy.","cn":"卤素灯正在被 LED 灯取代，LED 灯的能耗可减少 80%。"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"地球，世界（用于强调其广大或某事在许多地区发生）","en":"You can refer to the world as the globe when you are emphasizing how big it is or that something happens in many different parts of it.","ex":{"en":"...bottles of beer from every corner of the globe","cn":"来自世界各个角落的一瓶瓶啤酒"}},{"pos":"N-COUNT 可数名词","cn":"地球仪","en":"A globe is a ball-shaped object with a map of the world on it. It is usually fixed on a stand.","ex":{"en":"...a globe of the world","cn":"世界地球仪"}},{"pos":"N-COUNT 可数名词","cn":"球状物；球体","en":"Any ball-shaped object can be referred to as a globe .","ex":{"en":"The overhead light was covered now with a white globe.","cn":"现在，顶灯已装上了一个白色球状罩子。"}}]},"examples":[{"en":"tourists from every corner of the globe","cn":"来自世界各地的游客"},{"en":"We export our goods all over the globe.","cn":"我们的商品出口到世界各地。"}]},"golf":{"oxford":{"phon":"ɡɒlf","pos":"noun","senses":[{"en":"a game played over a large area of ground using sticks with a special shape to hit a small hard ball (a golf ball) into a series of 9 or 18 holes, using as few shots as possible","cn":"高尔夫球运动","ex":{"en":"I play golf every weekend.","cn":"我每个周末都打高尔夫球。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"高尔夫球运动","en":"Golf is a game in which you use long sticks called clubs to hit a small, hard ball into holes that are spread out over a large area of grassy land."}]},"media":{"img":["media/pic/hobbies_comp.jpg","media/thumb/golf.jpg"],"uk":"media/uk/golf__gb_1.mp3","us":"media/us/golf__us_1.mp3"},"examples":[{"en":"He enjoyed a round of golf on a Sunday morning.","cn":"他喜欢星期天的上午打一场高尔夫球。"},{"en":"He plays golf on Sundays.","cn":"他星期天都去打高尔夫球。"}]},"gray":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"media":{"uk":"media/uk/gray__gb_1.mp3","us":"media/us/gray__us_1.mp3"},"oxford":{"phon":"ɡreɪ","pos":"adjective","senses":[{"en":"having the colour of smoke or ashes","cn":"灰色的；烟灰色的；灰白色的","ex":{"en":"gray eyes/hair","cn":"灰色的眼睛/头发"}},{"en":"not bright; full of clouds","cn":"昏暗的；阴沉的","ex":{"en":"gray skies","cn":"灰蒙蒙的天空"}},{"en":"having grey hair","cn":"头发花白；头发灰白","g":"[not usually before noun]","ex":{"en":"He's gone very gray.","cn":"他的脸色已经非常灰白了。"}},{"en":"pale, because they are ill, tired or sad","cn":"苍白的","ex":{"en":"The next morning she looked very gray and hollow-eyed.","cn":"第二天早上，她看上去脸色灰白，眼睛凹陷。"}},{"en":"without interest or variety; making you feel sad","cn":"单调乏味的；忧郁的；沉闷的","ex":{"en":"Life seems gray and pointless without him.","cn":"没有他，生活显得灰暗而毫无意义。"}},{"en":"not interesting or attractive","cn":"没趣味的；毫无吸引力的","lab":"disapproving","ex":{"en":"The company was full of faceless gray men who all looked the same.","cn":"公司里挤满了没有面孔的灰色男人，他们看起来都一样。"}},{"en":"connected with old people","cn":"老年人的","g":"[only before noun]","ex":{"en":"the gray vote","cn":"老年选民的投票"}},{"en":"the colour of smoke or ashes","cn":"灰色；烟灰色；灰白色","g":"[uncountable, countable]","ex":{"en":"the dull gray of the sky","cn":"天空的暗灰色"},"pos":"noun"},{"en":"a gray or white horse","cn":"褐马","g":"[countable]","ex":{"en":"She's riding the gray.","cn":"她骑着那匹灰马。"},"pos":"noun"},{"en":"to become grey","cn":"变灰白；变花白","ex":{"en":"His hair was greying at the sides.","cn":"他的两鬓已渐渐斑白。"},"pos":"verb"}]}},"geography":{"media":{"uk":"media/uk/geography__gb_1.mp3","us":"media/us/geography__us_1.mp3"},"oxford":{"phon":"dʒiˈɒɡrəfi","pos":"noun","senses":[{"en":"the scientific study of the earth’s surface, physical features, divisions, products, population, etc.","cn":"地理（学）","g":"[uncountable]","ex":{"en":"recent work in economic geography","cn":"经济地理学近期作品"}},{"en":"the way in which the physical features of a place are arranged","cn":"地形；地貌；地势","g":"[singular]","ex":{"en":"These streets had a very particular geography.","cn":"这些街道的地理位置非常特殊。"}},{"en":"the way in which a particular aspect of life or society is influenced by geography or varies according to geography","cn":"地理环境","g":"[singular]","ex":{"en":"The geography of poverty and the geography of voting are connected.","cn":"贫穷人口的地理分布与选票的地理分布是相联系的。"}},{"en":"a country, area or region","cn":"国家；地区","g":"[countable]","lab":"business","ex":{"en":"We are now operational across multiple geographies.","cn":"我们现在在多个地区开展业务。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"地理学","en":"Geography is the study of the countries of the world and of such things as the land, seas, climate, towns, and population."},{"pos":"N-UNCOUNT 不可数名词","cn":"地形；地貌","en":"The geography of a place is the way that features such as rivers, mountains, towns, or streets are arranged within it.","ex":{"en":"...policemen who knew the local geography.","cn":"熟悉当地地形的警察"}}]},"examples":[{"en":"Kim knew the geography of the building and strode along the corridor.","cn":"金熟悉这栋建筑物的布局，大步流星地走在走廊上。"},{"en":"The geography of poverty and the geography of voting are connected.","cn":"贫穷人口的地理分布与选票的地理分布是相联系的。"}]},"gps":{"media":{"uk":"media/uk/gps__gb_1.mp3","us":"media/us/gps__us_1.mp3"},"oxford":{"phon":"ˌdʒiː piː ˈes","pos":"noun","senses":[{"en":"a system by which signals are sent from satellites to a special device, used to show the position of a person or thing on the surface of the earth very accurately (the abbreviation for ‘global positioning system’)","cn":"全球定位系统（全写为 global positioning system）","ex":{"en":"The drivers all have GPS in the van.","cn":"这些司机的厢式货车里都装有全球定位系统。"}}]},"examples":[{"en":"The drivers all have GPS in the van.","cn":"这些司机的厢式货车里都装有全球定位系统。"}],"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"","en":"GPS is an abbreviation for (缩略=) global positioning system .","ex":{"en":"GPS operates best near the equator.","cn":"全球定位系统在赤道附近性能最好。"}}]},"base":"gp"},"gauze":{"media":{"uk":"media/uk/gauze__gb_1.mp3","us":"media/us/gauze__us_1.mp3"},"oxford":{"phon":"ɡɔːz","pos":"noun","senses":[{"en":"a type of light cloth that you can see through, usually made of cotton or silk","cn":"薄纱，纱罗（通常由棉或丝织成）","g":"[uncountable]"},{"en":"a type of thin cotton cloth used for covering and protecting wounds","cn":"纱布（包扎伤口用）","g":"[uncountable]","ex":{"en":"a gauze dressing","cn":"纱布敷料"}},{"en":"material made of a network of wire; a piece of this","cn":"（金属丝制的）网纱，网","g":"[uncountable, countable]","ex":{"en":"wire gauze","cn":"金属网纱"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"薄纱；纱布","en":"Gauze is a type of light, soft cloth with tiny holes in it.","ex":{"en":"Strain the juice through a piece of gauze or a sieve.","cn":"用一块纱布或过滤网将果汁过滤一下。"}}]},"examples":[{"en":"a gauze dressing","cn":"纱布敷料"},{"en":"wire gauze","cn":"金属网纱"}]},"guarding":{"lemma":"guard"},"grand":{"media":{"uk":"media/uk/grand__gb_1.mp3","us":"media/us/grand__us_1.mp3"},"oxford":{"phon":"ɡrænd","pos":"adjective","senses":[{"en":"impressive and large or important","cn":"壮丽的；堂皇的；重大的","ex":{"en":"It's not a very grand house.","cn":"这房子并不是十分富丽堂皇。"}},{"en":"used in the names of impressive or very large buildings, etc.","cn":"（用于大建筑物等的名称）大","g":"[only before noun]","ex":{"en":"the Grand Canyon","cn":"大峡谷"}},{"en":"needing a lot of effort, money or time to succeed but intended to achieve impressive results","cn":"宏大的；宏伟的；有气派的","ex":{"en":"a grand plan/strategy/scheme","cn":"宏大计划；重大战略；重要方案"}},{"en":"used to describe the largest or most important item of its kind","cn":"最大的；最重要的","ex":{"en":"The film won the grand prize at the Berlin Film Festival.","cn":"这部电影在柏林电影节上获大奖。"}},{"en":"behaving in a proud way because they are rich or from a high social class","cn":"傲慢的；高高在上的","ex":{"en":"They're all Lord or Lady somebody or other, but they're not at all grand.","cn":"他们都是勋爵或夫人，但他们一点也不伟大。"}},{"en":"very good or great fun; excellent","cn":"极好的；快乐的；美妙的；出色的","lab":"dialect or informal","ex":{"en":"I had a grand day out at the seaside.","cn":"我在海边痛痛快快玩了一天。"}},{"en":"used in the titles of people of very high social rank","cn":"（对上层社会的人的称呼）大","ex":{"en":"the Grand Duchess Elena","cn":"大公夫人埃琳娜"}},{"en":"$1 000; £1 000","cn":"1 000 美元；1 000 英镑","lab":"informal","ex":{"en":"It'll cost you five grand!","cn":"这要花去你五千块钱！"},"pos":"noun"},{"en":"a large piano in which the strings are horizontal","cn":"大钢琴；三角钢琴","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"宏伟的；壮丽的；富丽堂皇的","en":"If you describe a building or a piece of scenery as grand, you mean that its size or appearance is very impressive.","ex":{"en":"...this grand building in the center of town","cn":"这幢位于市中心的宏伟建筑"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（计划等）宏伟的，宏大的","en":"Grand plans or actions are intended to achieve important results.","ex":{"en":"Critics will point to other grand schemes that have gone less well, such as Sheffield's World Student Games disaster","cn":"批评家将会指出其他一些并不成功的大项目，比如谢菲尔德世界大学生运动会这一败笔。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"牛气的；不可一世的","en":"People who are grand think they are important or socially superior.","ex":{"en":"He is grander and even richer than the Prince of Wales","cn":"他比威尔士亲王还牛气，甚至更有钱。"}},{"pos":"ADJ 形容词","cn":"快乐的；令人非常愉快的","en":"If you describe an activity or experience as grand, you mean that it is very pleasant and enjoyable.","ex":{"en":"Few museums could rival the Old Royal Observatory at Greenwich for a grand day out","cn":"若想找个地儿开心地逛一天，没有哪家博物馆能比得上格林尼治皇家天文台。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"了不起的；出色的；极好的","en":"You can describe someone or something as grand when you admire or approve of them very much.","ex":{"en":"He was a grand bloke.","cn":"他非常了不起。"}},{"pos":"ADJ 形容词","cn":"总括的","en":"A grand total is one that is the final amount or the final result of a calculation.","ex":{"en":"It came to a grand total of £20,329.","cn":"总计20,329英镑。"}},{"pos":"ADJ 形容词","cn":"（常用于大型建筑物的名称前）大的","en":"Grand is often used in the names of buildings such as hotels, especially when they are very large.","ex":{"en":"They stayed at The Grand Hotel, Budapest.","cn":"他们住在布达佩斯大饭店。"}},{"pos":"N-COUNT 可数名词","cn":"一千美元（或英镑）","en":"A grand is a thousand dollars or a thousand pounds.","ex":{"en":"They're paying you ten grand now for those adaptations of old plays.","cn":"他们打算付你一万美元作为改编老剧本的报酬。"}},{"pos":"N-COUNT 可数名词","cn":"同grand piano","en":"A grand is the same as a grand piano ."}]},"examples":[{"en":"James Lovelock, the grand old man of environmental science","cn":"詹姆斯 · 洛夫洛克，环境科学的元老"},{"en":"She finally learned to drive at the grand old age of 70.","cn":"她终于在 70 岁高龄学会了开车。"}]},"gins":{"lemma":"gin"},"grasp":{"oxford":{"phon":"ɡrɑːsp","pos":"verb","senses":[{"en":"to take a strong hold of somebody/something","cn":"抓紧；抓牢","ex":{"en":"He grasped my hand and shook it warmly.","cn":"他热情地抓住我的手握了起来。"}},{"en":"to understand something completely","cn":"理解；领会；领悟；明白","ex":{"en":"They failed to grasp the importance of his words.","cn":"他们没有理解他的话的重要性。"}},{"en":"to take an opportunity without hesitating and use it","cn":"急忙抓住，毫不犹豫地抓住（机会）","ex":{"en":"I grasped the opportunity to work abroad.","cn":"我毫不犹豫地抓住了去国外工作的机会。"}},{"en":"a strong hold of somebody/something or control over somebody/something","cn":"紧抓；紧握；控制","ex":{"en":"I grabbed him, but he slipped from my grasp.","cn":"我紧抓着他，可他还是从我手里溜掉了。"},"pos":"noun"},{"en":"a person’s understanding of a subject or of difficult facts","cn":"理解（力）；领会","ex":{"en":"He has a good grasp of German grammar.","cn":"他德语语法掌握得很好。"},"pos":"noun"},{"en":"the ability to get or achieve something","cn":"能力所及","ex":{"en":"Success was within her grasp.","cn":"她有把握获得成功。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"抓紧；握牢；握紧","en":"If you grasp something, you take it in your hand and hold it very firmly.","ex":{"en":"He grasped both my hands","cn":"他紧紧抓住我的双手。"}},{"pos":"N-SING 单数名词","cn":"紧抓；紧握","en":"A grasp is a very firm hold or grip.","ex":{"en":"His hand was taken in a warm, firm grasp.","cn":"他的手被热情地紧紧握住了。"}},{"pos":"N-SING 单数名词","cn":"掌握；控制","en":"If you say that something is in someone's grasp, you disapprove of the fact that they possess or control it. If something slips from your grasp, you lose it or lose control of it.","ex":{"en":"The people in your grasp are not guests, they are hostages","cn":"你所控制的这些人不是客人，而是人质。"}},{"pos":"VERB 动词","cn":"理解；领悟；明白","en":"If you grasp something that is complicated or difficult to understand, you understand it.","ex":{"en":"The Government has not yet grasped the seriousness of the crisis","cn":"政府当局还没有意识到这场危机的严重性。"}},{"pos":"N-SING 单数名词","cn":"理解；掌握","en":"A grasp of something is an understanding of it.","ex":{"en":"They have a good grasp of foreign languages.","cn":"他们外语掌握得很好。"}},{"pos":"PHRASE 短语","cn":"为…所能实现；为…所能及","en":"If you say that something is within someone's grasp, you mean that it is very likely that they will achieve it.","ex":{"en":"Peace is now within our grasp.","cn":"现在和平在望。"}}]},"media":{"uk":"media/uk/grasp__gb_1.mp3","us":"media/us/grasp__us_1.mp3"},"examples":[{"en":"She grasped at his coat as he rushed past her.","cn":"他从她身边冲过去时，她使劲地向他的外衣抓去。"},{"en":"It took him some time to grasp that he was now a public figure.","cn":"他过了些时候才意识到自己已是个公众人物了。"}]},"gods":{"lemma":"god","media":{"uk":"media/uk/god__gb_1.mp3","us":"media/us/god__us_1.mp3"}},"gloriously":{"oxford":{"phon":"ˈɡlɔːriəsli","pos":"adverb","senses":[{"en":"in a way that deserves or brings great success and makes somebody/something famous","cn":"光荣地：以值得或取得巨大成功并使某人/某事成名的方式","lab":"formal","ex":{"en":"Nelson died gloriously at Trafalgar.","cn":"纳尔逊在特拉法加光荣牺牲。"}},{"en":"in a very beautiful and impressive way","cn":"壮丽的；辉煌的；光辉灿烂的","lab":"formal","ex":{"en":"The show has been gloriously successful.","cn":"该剧取得了巨大成功。"}},{"en":"in a wonderful way","cn":"光荣地：美妙地","ex":{"en":"the gloriously named criminal mastermind, Goldthwait Higginson Dorr","cn":"光荣的犯罪主谋戈德斯韦特·希金森·多尔"}},{"en":"in a pleasantly hot way, with the sun shining","cn":"热的；阳光灿烂的；晴朗的","ex":{"en":"a gloriously sunny day","cn":"令人愉快的晴朗日子"}}]},"media":{"uk":"media/uk/gloriously__gb_1.mp3","us":"media/us/gloriously__us_1.mp3"},"examples":[{"en":"He’s got a great future ahead of him.","cn":""},{"en":"The house has great views.","cn":""}]},"grey":{"media":{"uk":"media/uk/grey__gb_1.mp3","us":"media/us/grey__us_1.mp3"},"oxford":{"phon":"ɡreɪ","pos":"adjective","senses":[{"en":"having the colour of smoke or ashes","cn":"灰色的；烟灰色的；灰白色的","ex":{"en":"grey eyes/hair","cn":"灰色的眼睛；花白的头发"}},{"en":"not bright; full of clouds","cn":"昏暗的；阴沉的","ex":{"en":"grey skies","cn":"昏暗的天空"}},{"en":"having grey hair","cn":"头发花白；头发灰白","g":"[not usually before noun]","ex":{"en":"He's gone very grey.","cn":"他已满头银丝。"}},{"en":"pale, because they are ill, tired or sad","cn":"苍白的","ex":{"en":"The next morning she looked very grey and hollow-eyed.","cn":"第二天早上她脸色苍白，眼窝深陷。"}},{"en":"without interest or variety; making you feel sad","cn":"单调乏味的；忧郁的；沉闷的","ex":{"en":"Life seems grey and pointless without him.","cn":"没有他，生活就显得沉闷而无意义。"}},{"en":"not interesting or attractive","cn":"没趣味的；毫无吸引力的","lab":"disapproving","ex":{"en":"The company was full of faceless grey men who all looked the same.","cn":"公司里全是些缺乏个性、毫无吸引力的男人。"}},{"en":"connected with old people","cn":"老年人的","g":"[only before noun]","ex":{"en":"the grey vote","cn":"老年人的投票总数"}},{"en":"the colour of smoke or ashes","cn":"灰色；烟灰色；灰白色","g":"[uncountable, countable]","ex":{"en":"the dull grey of the sky","cn":"暗灰色的天空"},"pos":"noun"},{"en":"a grey or white horse","cn":"灰马；白马","g":"[countable]","ex":{"en":"She's riding the grey.","cn":"她骑着一匹灰马。"},"pos":"noun"},{"en":"to become grey","cn":"变灰白；变花白","ex":{"en":"His hair was greying at the sides.","cn":"他的两鬓已渐渐斑白。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"COLOUR 颜色词","cn":"灰色","en":"Grey is the colour of ashes or of clouds on a rainy day.","ex":{"en":"...a grey suit.","cn":"灰色套装"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（头发）灰白的","en":"You use grey to describe the colour of people's hair when it changes from its original colour, usually as they get old.","ex":{"en":"...my grey hair","cn":"我灰白的头发"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（天气）昏暗的，阴沉的","en":"If the weather is grey, there are many clouds in the sky and the light is dull.","ex":{"en":"It was a grey, wet April Sunday.","cn":"这是4月一个阴雨绵绵的星期天。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"沉闷的；阴郁的；暗淡的","en":"If you describe a situation as grey, you mean that it is dull, unpleasant, or difficult.","ex":{"en":"Brazilians look gloomily forward to a New Year that even the president admits will be grey and cheerless.","cn":"展望新年，巴西人心情沮丧，甚至连总统都承认明年困难重重，不容乐观。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"单调乏味的；无特色的；不吸引人的","en":"If you describe someone or something as grey, you think that they are boring and unattractive, and very similar to other things or other people.","ex":{"en":"...little grey men in suits.","cn":"身着西服、缺乏个性的小个子男人们"}},{"pos":"ADJ 形容词","cn":"老年人的（新闻用语）","en":"Journalists sometimes use grey to describe things concerning old people.","ex":{"en":"There was further evidence of grey consumer power last week, when Ford revealed a car designed with elderly people in mind.","cn":"福特汽车公司为老年人设计的一款汽车于上周亮相，这进一步体现了老年消费者的购买力。"}}]},"examples":[{"en":"The company was full of faceless grey men who all looked the same.","cn":"公司里全是些缺乏个性、毫无吸引力的男人。"},{"en":"Life seems grey and pointless without him.","cn":"没有他，生活就显得沉闷而无意义。"}]},"globalization":{"oxford":{"phon":"ˌɡləʊbəlaɪˈzeɪʃn","pos":"noun","senses":[{"en":"the fact that different cultures and economic systems around the world are becoming connected and similar to each other because of the influence of large multinational companies and of improved communication","cn":"全球化，全世界化（世界各地的文化和经济体系日益关联）","lab":"US English"}]},"media":{"uk":"media/uk/globalization__gb_1.mp3","us":"media/us/globalization__us_1.mp3"},"examples":[{"en":"the increasing globalization of world trade","cn":"世界贸易的日益全球化"}]},"grimy":{"media":{"uk":"media/uk/grimy__gb_1.mp3","us":"media/us/grimy__us_1.mp3"},"oxford":{"phon":"ˈɡraɪmi","pos":"adjective","senses":[{"en":"covered with dirt","cn":"沾满污垢的；满是灰尘的","ex":{"en":"grimy hands/windows","cn":"沾满污垢的手；满是灰尘的窗户"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"满是污垢的；肮脏的","en":"Something that is grimy is very dirty.","ex":{"en":"...a grimy industrial city.","cn":"肮脏的工业城市"}}]},"examples":[{"en":"grimy hands/windows","cn":"沾满污垢的手；满是灰尘的窗户"},{"en":"grimy windows","cn":"落满灰尘的窗子"}]},"giant":{"media":{"uk":"media/uk/giant__gb_1.mp3","us":"media/us/giant__us_1.mp3"},"oxford":{"phon":"ˈdʒaɪənt","pos":"adjective","senses":[{"en":"very large; much larger or more important than similar things usually are","cn":"巨大的；特大的；伟大的","ex":{"en":"The match was shown on a giant screen outside the town hall.","cn":"比赛在市政厅外的一面大屏幕上播放。"}},{"en":"(in stories) a very large strong person who is often cruel and stupid","cn":"（故事中常为残酷而愚蠢的）巨人","ex":{"en":"tales of giants and ogres","cn":"巨人和食人魔的故事"},"pos":"noun"},{"en":"a person or thing that is unusually large","cn":"巨人；庞然大物","ex":{"en":"He's a giant of a man.","cn":"他是个巨人。"},"pos":"noun"},{"en":"a very large and powerful organization","cn":"大公司；强大的组织","ex":{"en":"These are boom times for the software giant.","cn":"现在是这个软件巨头的繁荣时期。"},"pos":"noun"},{"en":"a person who is very good at something","cn":"伟人；卓越人物","ex":{"en":"Toni Morrison is one of the twentieth century's literary giants.","cn":"托妮·莫里森是二十世纪的文学巨匠之一。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"巨大的；特大的；极其重要的","en":"Something that is described as giant is much larger or more important than most others of its kind.","ex":{"en":"...Italy's giant car maker, Fiat.","cn":"意大利汽车生产巨头菲亚特公司"}},{"pos":"N-COUNT 可数名词","cn":"大公司；大企业；大国","en":"Giant is often used to refer to any large, successful business organization or country.","ex":{"en":"...Japanese electronics giant Sony.","cn":"日本电子业巨头索尼公司"}},{"pos":"N-COUNT 可数名词","cn":"（尤指古代传说中虚构的）巨人","en":"A giant is an imaginary person who is very big and strong, especially one mentioned in old stories.","ex":{"en":"...a Nordic saga of giants.","cn":"北欧的巨人传奇"}},{"pos":"N-COUNT 可数名词","cn":"伟人；巨子；高大健壮的人","en":"You can refer to someone, especially a man, as a giant, if they seem important or powerful or if they are big and strong.","ex":{"en":"He has enormous charisma. He is a giant of a man","cn":"他有超凡的个人魅力，是个伟人。"}},{"pos":"N-COUNT 可数名词","cn":"卓越人物；大师；才华超群的人","en":"You can refer to someone such as a famous musician or writer as a giant, if they are regarded as one of the most important or successful people in their field.","ex":{"en":"...the giant of opera, Luciano Pavarotti","cn":"歌剧界巨擘卢恰诺·帕瓦罗蒂"}}]},"examples":[{"en":"a giant step towards achieving independence","cn":"朝着独立迈出的巨大的一步"},{"en":"He's a giant of a man.","cn":"他是个巨人。"}]},"gorilla":{"media":{"uk":"media/uk/gorilla__gb_1.mp3","us":"media/us/gorilla__us_1.mp3"},"oxford":{"phon":"ɡəˈrɪlə","pos":"noun","senses":[{"en":"a very large powerful African ape (= an animal like a large monkey without a tail) covered with black or brown hair","cn":"大猩猩（产于非洲）"},{"en":"a large aggressive man","cn":"高大凶恶的人","lab":"informal"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"大猩猩","en":"A gorilla is a very large ape. It has long arms, black fur, and a black face."}]}},"gave":{"lemma":"give","media":{"uk":"media/uk/gave__gb_1.mp3","us":"media/us/gave__us_1.mp3"}},"gratitude":{"media":{"uk":"media/uk/gratitude__gb_1.mp3","us":"media/us/gratitude__us_1.mp3"},"oxford":{"phon":"ˈɡrætɪtjuːd","pos":"noun","senses":[{"en":"the feeling of being grateful and wanting to express your thanks","cn":"感激之情；感谢","ex":{"en":"He smiled at them with gratitude.","cn":"他向他们微笑表示谢意。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"感恩之情；感谢","en":"Gratitude is the state of feeling grateful.","ex":{"en":"...a sense of gratitude","cn":"感恩图报之意"}}]},"examples":[{"en":"She was presented with the gift in gratitude for her long service.","cn":"这礼物赠送给她以表达对她长期服务的感激之情。"},{"en":"I would like to express my gratitude to everyone for their hard work.","cn":"我要对所有辛勤劳动的人表示感谢。"}]},"grew":{"lemma":"grow","media":{"uk":"media/uk/grew__gb_1.mp3","us":"media/us/grew__us_1.mp3"}},"goodwill":{"media":{"uk":"media/uk/goodwill__gb_1.mp3","us":"media/us/goodwill__us_1.mp3"},"oxford":{"phon":"ˌɡʊdˈwɪl","pos":"noun","senses":[{"en":"friendly or helpful feelings towards other people or countries","cn":"友善；友好；善意；亲善","ex":{"en":"a spirit of goodwill in international relations","cn":"国际关系中的亲善精神"}},{"en":"the good relationship between a business and its customers that is calculated as part of its value when it is sold","cn":"信誉；商誉"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"友善；善意；亲善","en":"Goodwill is a friendly or helpful attitude towards other people, countries, or organizations.","ex":{"en":"I invited them to dinner, a gesture of goodwill","cn":"我请他们吃饭以示友善。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"信誉；商誉","en":"The goodwill of a business is something such as its good reputation, which increases the value of the business.","ex":{"en":"We do not want to lose the goodwill built up over 175 years.","cn":"我们不想让历经175年树立起来的良好信誉毁于一旦。"}}]},"examples":[{"en":"a spirit of goodwill in international relations","cn":"国际关系中的亲善精神"},{"en":"a goodwill gesture/a gesture of goodwill","cn":"友好的表示"}]},"growth":{"media":{"uk":"media/uk/growth__gb_1.mp3","us":"media/us/growth__us_1.mp3"},"oxford":{"phon":"ɡrəʊθ","pos":"noun","senses":[{"en":"the process in people, animals or plants of growing physically, mentally or emotionally","cn":"发育；成长；生长","g":"[uncountable]","ex":{"en":"Lack of water will stunt the plant's growth.","cn":"缺水会阻碍植物生长。"}},{"en":"an increase in the size, amount or degree of something","cn":"增加；增长；增强","g":"[uncountable]","ex":{"en":"The report links population growth with rural poverty.","cn":"该报告把人口增长与农村的贫困联系起来。"}},{"en":"an increase in economic activity","cn":"经济增长；经济发展","g":"[uncountable]","ex":{"en":"policies aimed at sustaining economic growth","cn":"旨在保持经济增长的政策"}},{"en":"a mass of cells caused by a disease that forms on or inside a person, an animal or a plant","cn":"肿瘤；赘生物","g":"[countable]","ex":{"en":"a malignant growth","cn":"恶性肿瘤"}},{"en":"something that has grown","cn":"生长物；长成物；产物","g":"[uncountable, countable]","ex":{"en":"The forest's dense growth provides nesting places for a wide variety of birds.","cn":"森林里茂密的植物为各种各样的鸟儿提供了筑巢的地方。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"发展；增长；兴起","en":"The growth of something such as an industry, organization, or idea is its development in size, wealth, or importance.","ex":{"en":"...the growth of nationalism.","cn":"民族主义的高涨"}},{"pos":"N-UNCOUNT 不可数名词","cn":"增加；增多；增长","en":"The growth in something is the increase in it.","ex":{"en":"A steady growth in the popularity of two smaller parties may upset the polls","cn":"两个较小政党的支持率稳步上升，可能会打乱投票结果。"}},{"pos":"ADJ 形容词","cn":"发展的；增长的","en":"A growth industry, area, or market is one which is increasing in size or activity.","ex":{"en":"Computers and electronics are growth industries and need skilled technicians","cn":"计算机与电子行业属于蓬勃发展的产业，需要娴熟的技术人员。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（性格的）成长，发展","en":"Someone's growth is the development and progress of their character.","ex":{"en":"...the child's emotional and intellectual growth","cn":"孩子的情感与智力发展"}},{"pos":"N-UNCOUNT 不可数名词","cn":"发育；生长；成长","en":"Growth in a person, animal, or plant is the process of increasing in physical size and development.","ex":{"en":"...hormones which control fertility and body growth","cn":"控制生殖和身体发育的荷尔蒙"}},{"pos":"N-VAR 可变名词","cn":"新生发的植株；一茬植株","en":"You can use growth to refer to plants which have recently developed or which developed at the same time.","ex":{"en":"This helps to ripen new growth and makes it flower profusely","cn":"这有助于新生发植株的成熟，令其开出繁茂的花朵。"}},{"pos":"N-COUNT 可数名词","cn":"肿块；肿瘤；赘生物","en":"A growth is a lump that grows inside or on a person, animal, or plant, and that is caused by a disease.","ex":{"en":"This type of surgery could even be used to extract cancerous growths.","cn":"这种外科手术甚至可以用来切除癌性肿瘤。"}}]},"examples":[{"en":"The forest's dense growth provides nesting places for a wide variety of birds.","cn":"森林里茂密的植物为各种各样的鸟儿提供了筑巢的地方。"},{"en":"a disappointing year of little growth in Britain and America","cn":"英美经济增长无几令人沮丧的一年"}]},"guiding":{"media":{"uk":"media/uk/guiding__gb_1.mp3","us":"media/us/guiding__us_1.mp3"},"oxford":{"phon":"ˈɡaɪdɪŋ","pos":"adjective","senses":[{"en":"giving advice and help; having a strong influence on people","cn":"给予指导的；有影响的","ex":{"en":"She was inexperienced and needed a guiding hand.","cn":"她缺乏经验，需要有人指导。"}}]},"examples":[{"en":"She was inexperienced and needed a guiding hand.","cn":"她缺乏经验，需要有人指导。"},{"en":"a guiding force","cn":"有影响的力量"}],"base":"guide"},"gill":{"media":{"uk":"media/uk/gill__gb_1.mp3","us":"media/us/gill__us_1.mp3","img":["media/ldoce/img/trout.jpg"]},"oxford":{"phon":"dʒɪl","pos":"","senses":[{"en":"a first name for girls, short for Gillian","cn":"吉尔（女子名，Gillian 缩写）"},{"en":"one of the openings on the side of a fish’s head that it breathes through","cn":"鳃","pos":"noun"},{"en":"a unit for measuring liquids, equal to 0.142 of a litre in the UK and some other countries, and 0.118 of a litre in the US. There are four gills in a pint.","cn":"及耳（液量单位，在英国等国家等于 0.142 升，在美国等于 0.118 升；等于四分之一品脱）","pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（鱼等的）鳃","en":"Gills are the organs on the sides of fish and other water creatures through which they breathe."}]},"examples":[{"en":"I was stuffed to the gills with chocolate cake.","cn":"我吃巧克力蛋糕都撑到嗓子眼儿了。"},{"en":"The bar was packed to the gills on Monday.","cn":"星期一﹐酒吧里人满为患。"}]},"geeky":{"media":{"uk":"media/uk/geeky__gb_1.mp3","us":"media/us/geeky__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"愚蠢的；无能的；痴迷于电脑的","en":"If you describe someone as geeky, you think they look or behave like a geek.","ex":{"en":"...that geeky guy from the video-store counter.","cn":"在音像店上班的电脑迷"}}]},"oxford":{"phon":"ˈɡiːki","pos":"adjective","senses":[{"en":"typical of a person who is boring, wears clothes that are not fashionable, does not know how to behave in social situations, etc.","cn":"闷蛋；土包子","ex":{"en":"a geeky guy/toy","cn":"一个极客/玩具"}},{"en":"very interested in a particular thing, especially computers or technology; showing this","cn":"怪癖","ex":{"en":"a bunch of geeky techies","cn":"一群极客技术人员"}}]}},"gym":{"media":{"uk":"media/uk/gym__gb_1.mp3","us":"media/us/gym__us_1.mp3"},"oxford":{"phon":"dʒɪm","pos":"noun","senses":[{"en":"a room or hall with equipment for doing physical exercise, for example in a school","cn":"健身房；体育馆","g":"[countable]","lab":"formal","ex":{"en":"The school has recently built a new gym.","cn":"学校最近新建了一个体育馆。"}},{"en":"a private club where people go to do physical exercise in order to stay or become healthy and fit","cn":"健身俱乐部","g":"[countable]","lab":"British English","ex":{"en":"I just joined a gym.","cn":"我刚加入了健身俱乐部。"}},{"en":"physical exercises done in a gym, especially at school","cn":"（尤指学校的）体育活动，健身","g":"[uncountable]","ex":{"en":"I don't enjoy gym.","cn":"我不喜欢做健身锻炼。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"健身所；健身房；体育馆","en":"A gym is a club, building, or large room, usually containing special equipment, where people go to do physical exercise and get fit.","ex":{"en":"While the lads are golfing, I work out in the gym.","cn":"小伙子们打高尔夫球的时候，我在健身房锻炼。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"健身；（尤指学校的）体育活动","en":"Gym is the activity of doing physical exercises in a gym, especially at school.","ex":{"en":"...gym classes.","cn":"体育课"}}]},"examples":[{"en":"I work out at the gym most days.","cn":"我多数日子都在健身俱乐部锻炼身体。"},{"en":"The school has recently built a new gym.","cn":"学校最近新建了一个体育馆。"}]},"glare":{"media":{"uk":"media/uk/glare__gb_1.mp3","us":"media/us/glare__us_1.mp3"},"oxford":{"phon":"ɡleə(r)","pos":"verb","senses":[{"en":"to look at somebody/something in an angry way","cn":"怒目而视","g":"[intransitive]","ex":{"en":"He didn't shout, he just glared at me silently.","cn":"他没有喊叫，只是默默地怒视着我。"}},{"en":"to shine with a very bright, unpleasant light","cn":"发出刺眼的光","g":"[intransitive]"},{"en":"a very bright, unpleasant light","cn":"刺眼的光","g":"[uncountable, singular]","lab":"figurative","ex":{"en":"For a moment she was blinded by the harsh glare of the sun.","cn":"她一时被刺眼的阳光照得眼睛昏花。"},"pos":"noun"},{"en":"a long, angry look","cn":"（长久的）怒视，瞪眼","g":"[countable]","ex":{"en":"to give somebody a hostile glare","cn":"含敌意地瞪着某人"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"怒目而视；瞪眼","en":"If you glare at someone, you look at them with an angry expression on your face.","ex":{"en":"The old woman glared at him","cn":"那个老妇人狠狠地瞪着他。"}},{"pos":"N-COUNT 可数名词","cn":"怒视；瞪眼","en":"A glare is an angry, hard, and unfriendly look.","ex":{"en":"His glasses magnified his irritable glare.","cn":"他那怒不可遏的眼神在眼镜片下显得愈发逼人。"}},{"pos":"VERB 动词","cn":"发出强光；发出刺眼的光芒","en":"If the sun or a light glares, it shines with a very bright light which is difficult to look at.","ex":{"en":"The sunlight glared.","cn":"阳光耀眼。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"强光；刺眼的光","en":"Glare is very bright light that is difficult to look at.","ex":{"en":"...the glare of a car's headlights","cn":"汽车头灯的强光"}},{"pos":"N-SING 单数名词","cn":"密切关注","en":"If someone is in the glare of publicity or public attention, they are constantly being watched and talked about by a lot of people.","ex":{"en":"Norma is said to dislike the glare of publicity","cn":"据说诺尔玛不喜欢被人过多关注。"}}]},"examples":[{"en":"These sunglasses are designed to reduce glare.","cn":"这些太阳镜是为减少刺眼的强光而设计的。"},{"en":"( figurative ) The divorce was conducted in the full glare of publicity (= with continuous attention from newspapers and television).","cn":"这桩离婚案是在媒体的密切关注下进行的。"}]},"grape":{"media":{"img":["media/pic/fruit_comp.jpg","media/thumb/grape.jpg"],"uk":"media/uk/grape__gb_1.mp3","us":"media/us/grape__us_1.mp3"},"oxford":{"phon":"ɡreɪp","pos":"noun","senses":[{"en":"a small green or purple fruit that grows in bunches on a climbing plant (called a vine). Wine is made from grapes.","cn":"葡萄","ex":{"en":"a bunch of grapes","cn":"一串葡萄"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"葡萄","en":"Grapes are small green or dark purple fruit which grow in bunches. Grapes can be eaten raw, used for making wine, or dried."},{"pos":"PHRASE 短语","cn":"酸葡萄心理（指因得不到想要的东西便说它一文不值）","en":"If you describe some-one's attitude as sour grapes, you mean that they say something is worthless or undesirable because they want it themselves but cannot have it.","ex":{"en":"These accusations have been going on for some time now, but it is just sour grapes.","cn":"这些指责到现在已经持续了一段时间，但这不过是吃不到葡萄说葡萄酸罢了。"}}]},"examples":[{"en":"black/white grapes (= grapes that are actually purple/green in colour)","cn":"紫/绿葡萄"},{"en":"a bunch of grapes","cn":"一串葡萄"}]},"gesticulate":{"oxford":{"phon":"dʒeˈstɪkjuleɪt","pos":"verb","senses":[{"en":"to move your hands and arms about in order to attract attention or make somebody understand what you are saying","cn":"做手势；用手势表达；用动作示意","ex":{"en":"He gesticulated wildly at the clock.","cn":"他使劲指着钟打手势。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"做手势；用手势表达；用动作示意","en":"If you gesticulate, you make movements with your arms or hands, often while you are describing something that is difficult to express in words.","ex":{"en":"A man with a paper hat upon his head was gesticulating wildly","cn":"一个戴纸帽的男子在拼命地打手势。"}}]},"media":{"uk":"media/uk/gesticulate__gb_1.mp3","us":"media/us/gesticulate__us_1.mp3"},"examples":[{"en":"He gesticulated wildly at the clock.","cn":"他使劲指着钟打手势。"},{"en":"wild/frantic gesticulations","cn":"发狂似的手势"}]},"grip":{"media":{"uk":"media/uk/grip__gb_1.mp3","us":"media/us/grip__us_1.mp3"},"oxford":{"phon":"ɡrɪp","pos":"noun","senses":[{"en":"an act of holding somebody/something tightly; a particular way of doing this","cn":"紧握；紧抓","g":"[countable, usually singular]","lab":"figurative","sc":"holding tightly","ex":{"en":"Keep a tight grip on the rope.","cn":"紧紧抓住绳索不放。"}},{"en":"control or power over somebody/something","cn":"（对…的）控制，影响力","g":"[singular]","sc":"control/power","ex":{"en":"The home team took a firm grip on the game.","cn":"主队牢牢控制着比赛的局面。"}},{"en":"an understanding of something","cn":"理解；了解","g":"[singular]","sc":"understanding","ex":{"en":"I couldn't get a grip on what was going on.","cn":"我无法理解正在发生的事情。"}},{"en":"the ability of something to move over a surface without slipping","cn":"不打滑；走得稳","g":"[uncountable, singular]","sc":"moving without slipping","ex":{"en":"These tyres give the bus better grip in slippery conditions.","cn":"这些轮胎可使公共汽车在路滑时行驶得平稳一些。"}},{"en":"a part of something that has a special surface so that it can be held without the hands slipping","cn":"把手；手柄；握杆","g":"[countable]","sc":"part of object","ex":{"en":"the grip on a golf club","cn":"高尔夫球杆的握柄"}},{"en":"a small thin piece of metal or plastic folded in the middle, used by women for holding their hair in place","cn":"发夹","g":"[countable]","lab":"both British English","sc":"for hair"},{"en":"a person who prepares and moves the cameras, and sometimes the lighting equipment, when a film is being made","cn":"（拍摄电影时）摄影机和灯光设备管理人员","g":"[countable]","sc":"job in the movies"},{"en":"a large soft bag, used when travelling","cn":"旅行袋；手提包","g":"[countable]","lab":"old-fashioned","sc":"bag"},{"en":"to hold something tightly","cn":"抓紧某物","g":"[transitive, intransitive]","sc":"hold tightly","ex":{"en":"‘Please don't go,’ he said, gripping her arm.","cn":"“请别走。”他紧紧抓住她的手臂说。"},"pos":"verb"},{"en":"to interest or have a strong effect on somebody; to hold somebody’s attention","cn":"使感兴趣；使受强有力的影响；吸引住（某人的）注意","g":"[transitive]","sc":"interest/excite","ex":{"en":"The book grips you from start to finish.","cn":"这本书从头至尾扣人心弦。"},"pos":"verb"},{"en":"to have a powerful effect on somebody/something","cn":"对…产生强有力的影响","g":"[transitive]","sc":"have powerful effect","ex":{"en":"I was gripped by a feeling of panic.","cn":"我惊恐万状。"},"pos":"verb"},{"en":"to hold onto or to move over a surface without slipping","cn":"抓牢","g":"[transitive, intransitive]","sc":"move/hold without slipping","ex":{"en":"tyres that grip the road","cn":"抓地力好的车胎"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"紧握；抓牢","en":"If you grip something, you take hold of it with your hand and continue to hold it firmly.","ex":{"en":"She gripped the rope.","cn":"她紧紧抓住绳索。"}},{"pos":"N-COUNT 可数名词","cn":"紧握；抓牢","en":"A grip is a firm, strong hold on something.","ex":{"en":"His strong hand eased the bag from her grip.","cn":"他强有力的手迫使她松开了握紧袋子的双手。"}},{"pos":"N-SING 单数名词","cn":"掌握；支配；控制","en":"Someone's grip on something is the power and control they have over it.","ex":{"en":"The president maintains an iron grip on his country","cn":"总统牢牢地控制着他的国家。"}},{"pos":"VERB 动词","cn":"强烈地影响","en":"If something grips you, it affects you very strongly.","ex":{"en":"Pain gripped him","cn":"他感到一阵剧痛。"}},{"pos":"VERB 动词","cn":"吸引;迷住","en":"If you are gripped by something such as a story or a series of events, your attention is concentrated on it and held by it.","ex":{"en":"The nation is gripped by the dramatic story.","cn":"举国上下都为那个戏剧性的故事牵动着。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"防滑；抓地力","en":"If things such as shoes or car tyres have grip, they do not slip.","ex":{"en":"...a new way of reinforcing rubber which gives car tyres better grip.","cn":"加固橡胶以增强车胎抓地力的新方法"}},{"pos":"N-COUNT 可数名词","cn":"手提包；旅行袋","en":"A grip is a bag that is smaller than a suitcase, and that you use when you are travelling."},{"pos":"PHRASE 短语","cn":"认真考虑并着手处理","en":"If you get to grips with a problem or if you come to grips with it, you consider it seriously, and start taking action to deal with it.","ex":{"en":"The government's first task is to get to grips with the economy.","cn":"政府的首要任务是处理好经济问题。"}},{"pos":"PHRASE 短语","cn":"（使自己）镇定下来；控制住（自己）","en":"If you get a grip on yourself, you make an effort to control or improve your behaviour or work."},{"pos":"PHRASE 短语","cn":"受制于；受…的深刻影响","en":"If a person, group, or place is in the grip of something, they are being severely affected by it.","ex":{"en":"Britain is still in the grip of recession.","cn":"英国依然没有摆脱经济衰退。"}},{"pos":"PHRASE 短语","cn":"效率降低；失去信心；驾驭不住","en":"If you lose your grip, you become less efficient and less confident, and less able to deal with things."},{"pos":"PHRASE 短语","cn":"了解形势；理解现状","en":"If you say that someone has a grip on reality, you mean they recognize the true situation and do not have mistaken ideas about it.","ex":{"en":"Shakur loses his fragile grip on reality and starts blasting away at friends and foe alike.","cn":"沙库尔丧失了对形势仅存的一点判断，无论对敌对友都开始大加挞伐。"}}]},"examples":[{"en":"These tyres give the bus better grip in slippery conditions.","cn":"这些轮胎可使公共汽车在路滑时行驶得平稳一些。"},{"en":"I have to take a grip on myself, he told himself firmly.","cn":"我一定要控制住自己的情绪，他坚定地对自己说。"}]},"girl":{"oxford":{"phon":"ɡɜːl","pos":"noun","senses":[{"en":"a female child","cn":"女孩","g":"[countable]","ex":{"en":"a little girl of six","cn":"六岁的小女孩"}},{"en":"a daughter","cn":"女儿","g":"[countable]","ex":{"en":"They have two girls and a boy.","cn":"他们有两个女孩和一个男孩。"}},{"en":"a young woman","cn":"年轻女子；女郎","g":"[countable]","lab":"sometimes offensive","ex":{"en":"He married the girl next door.","cn":"他与隔壁的女孩结婚了。"}},{"en":"the women in a group","cn":"姑娘们；姐妹们","g":"[plural]","ex":{"en":"I'm having a night out with the girls.","cn":"我今晚要和姐妹们外出。"}},{"en":"a girlfriend","cn":"女朋友","g":"[countable]","lab":"old-fashioned","ex":{"en":"He’s taking his girl home to meet his parents.","cn":"他要带他的女儿回家见他的父母。"}},{"en":"a female worker","cn":"女工；女职员","g":"[countable]","lab":"old-fashioned, offensive，，","ex":{"en":"an office girl","cn":"女办事员"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"女孩；姑娘","en":"A girl is a female child.","ex":{"en":"...an eleven year old girl","cn":"11岁的女孩"}},{"pos":"N-COUNT 可数名词","cn":"女儿","en":"You can refer to someone's daughter as a girl .","ex":{"en":"We had a little girl.","cn":"我们有一个小女儿。"}},{"pos":"N-COUNT 可数名词","cn":"年轻女子，小妞儿（可能具冒犯意味）","en":"Young women are often referred to as girls. This use could cause offence.","ex":{"en":"...a pretty twenty-year-old girl.","cn":"20岁的漂亮姑娘"}},{"pos":"N-COUNT 可数名词","cn":"（男人的）女朋友","en":"Some people refer to a man's girlfriend as his girl.","ex":{"en":"I've been with my girl for nine years.","cn":"我同我女朋友交往9年了。"}}]},"media":{"uk":"media/uk/girl__gb_1.mp3","us":"media/us/girl__us_1.mp3"},"examples":[{"en":"Alex is not interested in girls yet.","cn":"亚历克斯对女孩子还不感兴趣。"},{"en":"Our youngest girl is at college.","cn":"我们的小女儿在大学读书。"}]},"goat":{"media":{"uk":"media/uk/goat__gb_1.mp3","us":"media/us/goat__us_1.mp3","img":["media/ldoce/img/goat.jpg"]},"oxford":{"phon":"ɡəʊt","pos":"noun","senses":[{"en":"an animal with horns and a coat of hair, that lives wild in mountain areas or is kept on farms for its milk or meat","cn":"山羊","ex":{"en":"a mountain goat","cn":"山羊"}},{"en":"an old man who you think is unpleasant and annoying in a sexual way","cn":"老色鬼；色狼；好色之徒","lab":"informal"},{"en":"the best person ever in a particular field, especially a sport (the abbreviation for greatest of all time)","cn":"史上最佳，史上最伟大（Greatest Of All Time 的缩写）","ex":{"en":"There's no doubt he's the GOAT, but someone's going to beat him one day.","cn":"毫无疑问，他是山羊，但总有一天有人会打败他。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"山羊","en":"A goat is a farm animal or a wild animal that is about the size of a sheep. Goats have horns, and hairs on their chin which resemble a beard."}]},"examples":[{"en":"goat's milk/cheese","cn":"羊奶；羊奶酪"},{"en":"a mountain goat","cn":"山羊"}]},"gases":{"lemma":"gas","media":{"uk":"media/uk/gas__gb_1.mp3","us":"media/us/gas__us_1.mp3"}},"geese":{"lemma":"goose","media":{"uk":"media/uk/geese__gb_1.mp3","us":"media/us/geese__us_1.mp3"}},"grandmother":{"oxford":{"phon":"ˈɡrænmʌðə(r)","pos":"noun","senses":[{"en":"the mother of your father or mother","cn":"（外）祖母；奶奶；姥姥；外婆","ex":{"en":"I always loved going to visit my grandmother.","cn":"我总是喜欢去看望我的祖母。"}}]},"collins":{"senses":[{"pos":"N-FAMILY 家庭成员名词","cn":"（外）祖母；奶奶；外婆","en":"Your grandmother is the mother of your father or mother.","ex":{"en":"My grandmothers are both widows.","cn":"我奶奶和外婆都是孤寡一人。"}}]},"media":{"uk":"media/uk/grandmother__gb_1.mp3","us":"media/us/grandmother__us_1.mp3"},"examples":[{"en":"My grandma used to make lovely cakes.","cn":"我祖母以前常做很好吃的蛋糕。"}]},"grateful":{"oxford":{"phon":"ˈɡreɪtfl","pos":"adjective","senses":[{"en":"feeling or showing thanks because somebody has done something kind for you or has done as you asked","cn":"感激的；表示感谢的","ex":{"en":"Thank you for doing this. I really am so grateful.","cn":"谢谢你这样做。我实在是太感激了。"}},{"en":"used to make a request, especially in a letter or in a formal situation","cn":"（尤用于书信或正式场合提出请求）感激不尽，请","ex":{"en":"I would be grateful if you could send the completed form back as soon as possible.","cn":"如能尽快把表格填好寄回，将不胜感激。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"感激的；表示感谢的","en":"If you are grateful for something that someone has given you or done for you, you have warm, friendly feelings towards them and wish to thank them.","ex":{"en":"She was grateful to him for being so good to her","cn":"他对她这么好，令她很感激。"}}]},"media":{"uk":"media/uk/grateful__gb_1.mp3","us":"media/us/grateful__us_1.mp3"},"examples":[{"en":"Grateful thanks are due to the following people for their help …","cn":"向下列给予过帮助的人表示衷心的感谢 …"},{"en":"She seems to think I should be grateful to have a job at all.","cn":"她似乎认为我有份工作就该谢天谢地了。"}]},"government":{"media":{"uk":"media/uk/government__gb_1.mp3","us":"media/us/government__us_1.mp3"},"oxford":{"phon":"ˈɡʌvənmənt","pos":"noun","senses":[{"en":"the group of people who are responsible for controlling a country or a state","cn":"政府；内阁","g":"[countable + singular or plural verb]","lab":"especially North American English","ex":{"en":"to lead/form a government","cn":"领导政府；组成内阁"}},{"en":"a particular system or method of controlling a country","cn":"政体；国家体制","g":"[uncountable]","ex":{"en":"Democratic government has now replaced military rule.","cn":"民主政体现已取代军事统治。"}},{"en":"the activity or the manner of controlling a country","cn":"（一国的）统治，治理，统治方式，管理方式","g":"[uncountable]","ex":{"en":"We need strong government to take the country through this crisis.","cn":"我们需要靠强有力的政府管理使国家渡过这次危机。"}}]},"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"政府;内阁","en":"The government of a country is the group of people who are responsible for governing it.","ex":{"en":"The Government has insisted that confidence is needed before the economy can improve.","cn":"政府坚持认为只有坚定信心经济才会有起色。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(国家等的)治理，管理，执政","en":"Government consists of the activities, methods, and principles involved in governing a country or other political unit.","ex":{"en":"The first four years of government were completely disastrous.","cn":"政府前4年的执政彻底失败。"}}]},"examples":[{"en":"Foreign governments have been consulted about this decision.","cn":"这一决定曾征求过他国政府的意见。"},{"en":"The Government has/have been considering further tax cuts.","cn":"政府一直在考虑进一步减税的问题。"}]},"glass":{"media":{"img":["media/pic/cupsandglasses_diningroom_comp.jpg","media/thumb/tumbler.jpg"],"uk":"media/uk/glass__gb_1.mp3","us":"media/us/glass__us_1.mp3"},"oxford":{"phon":"ɡlɑːs","pos":"noun","senses":[{"en":"a hard, usually clear, substance used, for example, for making windows and bottles","cn":"玻璃","g":"[uncountable]","sc":"clear substance","ex":{"en":"a sheet/pane of glass","cn":"一片玻璃；一块窗玻璃"}},{"en":"a container made of glass, used for drinking out of","cn":"玻璃杯；酒杯","g":"[countable]","sc":"for drinking","ex":{"en":"He poured orange juice into a glass.","cn":"他把橙汁倒进玻璃杯里。"}},{"en":"the contents of a glass","cn":"一杯（的量）","g":"[countable]","sc":"for drinking","ex":{"en":"He drank three whole glasses.","cn":"他喝了满满三杯。"}},{"en":"two lenses in a frame that rests on the nose and ears. People wear glasses in order to be able to see better or to protect their eyes from bright light.","cn":"眼镜","g":"[plural]","lab":"North American English also","sc":"for eyes","ex":{"en":"a pair of glasses","cn":"一副眼镜"}},{"en":"objects made of glass","cn":"玻璃器皿；玻璃制品","g":"[uncountable]","sc":"glass objects","ex":{"en":"We keep all our glass and china in this cupboard.","cn":"我们把所有玻璃器皿和瓷器都放在这个橱里。"}},{"en":"a protecting cover made of glass on a watch, picture or photograph frame, fire alarm, etc.","cn":"玻璃保护面；玻璃（镜）框；（火灾警报器的）玻璃罩","g":"[singular]","sc":"glass objects","ex":{"en":"In case of emergency, break the glass and press the button.","cn":"如遇紧急情况，击碎玻璃罩按下按钮。"}},{"en":"a mirror","cn":"镜子","g":"[countable, usually singular]","lab":"old-fashioned","sc":"mirror"},{"en":"a barometer","cn":"气压表；晴雨表","g":"[singular]","sc":"barometer"},{"en":"to hit somebody in the face with a glass","cn":"用玻璃杯击（某人）的脸部","pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"玻璃","en":"Glass is a hard transparent substance that is used to make things such as windows and bottles.","ex":{"en":"...a pane of glass.","cn":"一块玻璃"}},{"pos":"N-COUNT 可数名词","cn":"玻璃杯","en":"A glass is a container made from glass, which you can drink from and which does not have a handle.","ex":{"en":"Grossman raised the glass to his lips.","cn":"格罗斯曼把杯子举到唇边。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"玻璃制品","en":"Glass is used to mean objects made of glass, for example drinking containers and bowls.","ex":{"en":"There's a glittering array of glass to choose from at markets.","cn":"市场上有很多晶莹闪亮的玻璃制品可供挑选。"}},{"pos":"N-PLURAL 复数名词","cn":"眼镜","en":"Glasses are two lenses in a frame that some people wear in front of their eyes in order to help them see better.","ex":{"en":"He took off his glasses.","cn":"他摘掉眼镜。"}}]},"examples":[{"en":"We keep all our glass and china in this cupboard.","cn":"我们把所有玻璃器皿和瓷器都放在这个橱里。"},{"en":"She has a fine collection of Bohemian glass.","cn":"她收藏了一批做工精细的波希米亚玻璃制品。"}]},"grapple":{"media":{"uk":"media/uk/grapple__gb_1.mp3","us":"media/us/grapple__us_1.mp3"},"oxford":{"phon":"ˈɡræpl","pos":"verb","senses":[{"en":"to take a strong hold of somebody/something and struggle with them","cn":"扭打；搏斗","g":"[intransitive, transitive]","ex":{"en":"Passers-by grappled with the man after the attack.","cn":"袭击之后过路人便与这男人扭打起来。"}},{"en":"to try hard to find a solution to a problem","cn":"努力设法解决","g":"[intransitive]","ex":{"en":"The new government has yet to grapple with the problem of air pollution.","cn":"新政府还需尽力解决空气污染问题。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"努力解决（问题）；设法克服（困难）","en":"If you grapple with a problem or difficulty, you try hard to solve it.","ex":{"en":"The economy is just one of several critical problems the country is grappling with.","cn":"经济问题只是该国正竭力解决的几个关键问题之一。"}},{"pos":"V-RECIP 相互动词","cn":"扭打;搏斗","en":"If you grapple with someone, you take hold of them and struggle with them, as part of a fight. You can also say that two people grapple .","ex":{"en":"He was grappling with an alligator in a lagoon","cn":"他正在环礁湖里与一只短吻鳄搏斗。"}}]},"examples":[{"en":"Passers-by grappled with the man after the attack.","cn":"袭击之后过路人便与这男人扭打起来。"},{"en":"The new government has yet to grapple with the problem of air pollution.","cn":"新政府还需尽力解决空气污染问题。"}]},"groom":{"media":{"uk":"media/uk/groom__gb_1.mp3","us":"media/us/groom__us_1.mp3"},"oxford":{"phon":"ɡruːm","pos":"verb","senses":[{"en":"to clean or brush an animal","cn":"（给动物）擦洗，刷洗","ex":{"en":"to groom a horse/dog/cat","cn":"刷洗马／狗／猫"}},{"en":"to clean the fur or skin of another animal or itself","cn":"（给自己或其他动物）理毛，梳毛","ex":{"en":"a female ape grooming her mate","cn":"为同伴梳毛的母猿"}},{"en":"to prepare or train somebody for an important job or position","cn":"使做好准备；培养；训练","ex":{"en":"Our junior employees are being groomed for more senior roles.","cn":"我们的初级雇员正在接受培训以承担更重要的职责。"}},{"en":"to prepare a child for a meeting, especially using social media, with the intention of performing an illegal sexual act","cn":"（尤指利用网络社交媒体）勾引（儿童）"},{"en":"a person whose job is to feed and take care of horses, especially by brushing and cleaning them","cn":"马夫；马倌；马匹饲养员","pos":"noun"},{"en":"a man on his wedding day, or just before or just after it","cn":"新郎；即将（或刚刚）结婚的男子","pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同bridegroom","en":"A groom is the same as a bridegroom .","ex":{"en":"...the bride and groom.","cn":"新娘与新郎"}},{"pos":"N-COUNT 可数名词","cn":"马夫；马倌","en":"A groom is someone whose job is to look after the horses in a stable and to keep them clean."},{"pos":"VERB 动词","cn":"洗刷（动物）；给（动物）梳毛","en":"If you groom an animal, you clean its fur, usually by brushing it.","ex":{"en":"The horses were exercised and groomed with special care.","cn":"这些马接受专门训练，鬃毛也得到精心梳理。"}},{"pos":"VERB 动词","cn":"训练；培养","en":"If you are groomed for a special job, someone prepares you for it by teaching you the skills you will need.","ex":{"en":"George was already being groomed for the top job","cn":"为承担这份高级工作，乔治已在接受专门的培训。"}}]},"examples":[{"en":"Our junior employees are being groomed for more senior roles.","cn":"我们的初级雇员正在接受培训以承担更重要的职责。"},{"en":"The eldest son is being groomed to take over when his father dies.","cn":"长子正在接受培养，以在父亲过世后接手父业。"}]},"gather":{"media":{"uk":"media/uk/gather__gb_1.mp3","us":"media/us/gather__us_1.mp3"},"oxford":{"phon":"ˈɡæðə(r)","pos":"verb","senses":[{"en":"to come together, or bring people together, in one place to form a group","cn":"聚集；集合；召集","g":"[intransitive, transitive]","sc":"come/bring together","ex":{"en":"A crowd soon gathered.","cn":"很快就聚集起了一群人。"}},{"en":"to bring things together that have been spread around","cn":"收拢，归拢（分散的东西）","g":"[transitive]","sc":"come/bring together","ex":{"en":"People slowly gathered their belongings and left the hall.","cn":"人们慢慢地收起他们的随身物品离开了大厅。"}},{"en":"to collect information from different sources","cn":"搜集，收集（情报）","g":"[transitive]","sc":"collect","ex":{"en":"to gather information/data/intelligence","cn":"收集信息／数据／情报"}},{"en":"to collect plants, fruit, etc. from a wide area","cn":"采集（植物、水果等）","g":"[transitive]","sc":"collect","ex":{"en":"to gather wild flowers","cn":"采集野花"}},{"en":"to pick or cut and collect crops to be stored","cn":"收割；收获","g":"[transitive]","lab":"formal or literary","sc":"crops/harvest","ex":{"en":"It was late August and the harvest had been safely gathered in.","cn":"已是八月下旬，庄稼都妥善收割完毕。"}},{"en":"to believe or understand that something is true because of information or evidence you have","cn":"认为；猜想；推断；理解","g":"[transitive]","sc":"believe/understand","ex":{"en":"I gather (that) you wanted to see me.","cn":"我猜想你想要见我。"}},{"en":"to increase in speed, force, etc.","cn":"增加（速度、力量等）","g":"[transitive]","sc":"increase","ex":{"en":"The truck gathered speed.","cn":"卡车加快了速度。"}},{"en":"to gradually increase in number or amount","cn":"逐渐增加；积聚","g":"[intransitive]","sc":"of clouds/darkness","ex":{"en":"The storm clouds were gathering.","cn":"暴风雨乌云正在聚集。"}},{"en":"to pull a piece of clothing tighter to your body","cn":"收紧，拢起（衣服）","g":"[transitive]","sc":"clothing","ex":{"en":"He gathered his cloak around him.","cn":"他用披风把身子裹紧。"}},{"en":"to pull parts of a piece of clothing together in folds and sew them in place","cn":"给…打褶子","g":"[transitive]","sc":"clothing","ex":{"en":"She wore a skirt gathered (in) at the waist.","cn":"她穿了一条腰部打褶的裙子。"}},{"en":"to pull somebody towards you and put your arms around them","cn":"拢；拢住","g":"[transitive]","sc":"hold somebody","ex":{"en":"She gathered the child in her arms and held him close.","cn":"她把那男孩拢过来紧紧抱在怀里。"}},{"en":"to prepare yourself to do something that requires effort","cn":"攒（动）；使做好准备","g":"[transitive]","sc":"prepare yourself","ex":{"en":"I sat down for a moment to gather my strength.","cn":"我坐下片刻积蓄力量。"}},{"en":"to get your breath back after an effort","cn":"攒（动）；使做好准备","sc":"breath","ex":{"en":"He paused to gather his breath.","cn":"他停下来平复呼吸。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）聚集；（使）集合","en":"If people gather somewhere or if someone gathers people somewhere, they come together in a group.","ex":{"en":"In the evenings, we gathered around the fireplace and talked","cn":"晚上，我们聚在火炉边聊天。"}},{"pos":"VERB 动词","cn":"收集；收拢；归拢","en":"If you gather things, you collect them together so that you can use them.","ex":{"en":"I suggest we gather enough firewood to last the night","cn":"我建议大家捡足够多的木柴来撑过这一晚。"}},{"pos":"VERB 动词","cn":"（尤指经过一段时间的辛苦工作）收集，搜集（情报、证据等）","en":"If you gather information or evidence, you collect it, especially over a period of time and after a lot of hard work.","ex":{"en":"...a private detective using a hidden tape recorder to gather information","cn":"用暗藏的录音机搜集证据的私家侦探"}},{"pos":"VERB 动词","cn":"逐渐增加（速度、动力、力量等）","en":"If something gathers speed, momentum, or force, it gradually becomes faster or more powerful.","ex":{"en":"Demands for his dismissal have gathered momentum in recent weeks","cn":"最近几周，要求将他解职的呼声越来越高。"}},{"pos":"VERB 动词","cn":"集中（精力、思想等）；鼓起（勇气）；振作（精神）","en":"When you gather something such as your strength, courage, or thoughts, you make an effort to prepare yourself to do something.","ex":{"en":"You must gather your strength for the journey.","cn":"你必须为这次行程打起精神来。"}},{"pos":"VERB 动词","cn":"（用于引出已发现的信息，尤其是间接获得的信息）据我所知，据我了解","en":"You use gather in expressions such as 'I gather' and 'as far as I can gather' to introduce information that you have found out, especially when you have found it out in an indirect way.","ex":{"en":"I gather his report is highly critical of the trial judge","cn":"据我所知，他在报道中毫不留情地批评了初审法官。"}},{"pos":"VERB 动词","cn":"给…打褶","en":"If you gather fabric or cloth, you make a row of very small folds in it by sewing a thread through it and then pulling the thread tight.","ex":{"en":"Gather the skirt at the waist.","cn":"在裙子的腰部打褶。"}},{"pos":"","cn":"","en":"to gather dust→see: ;"},{"pos":"","cn":"","en":"相关词组：gather up"}]},"examples":[{"en":"During the 1980s the green movement gathered momentum. * 20","cn":"世纪 80 年代期间绿色运动的势头开始增强。"},{"en":"People slowly gathered their belongings and left the hall.","cn":"人们慢慢地收起他们的随身物离开了大厅。"}]},"glossary":{"oxford":{"phon":"ˈɡlɒsəri","pos":"noun","senses":[{"en":"a list of technical or special words, especially those in a particular text, explaining their meanings","cn":"术语汇编；词汇表","ex":{"en":"a glossary of financial terms","cn":"金融术语词汇表"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"术语汇编；词汇表","en":"A glossary of special, unusual, or technical words or expressions is an alphabetical list of them giving their meanings, for example at the end of a book on a particular subject."}]},"media":{"uk":"media/uk/glossary__gb_1.mp3","us":"media/us/glossary__us_2.mp3"}},"graduated":{"media":{"img":["media/pic/laboratory_equipment_comp.jpg","media/thumb/graduatedcylinder.jpg"],"uk":"media/uk/graduated__gb_1.mp3","us":"media/us/graduated__us_1.mp3"},"oxford":{"phon":"ˈɡrædʒueɪtɪd","pos":"adjective","senses":[{"en":"divided into groups or levels on a scale","cn":"分等级的；分层次的","ex":{"en":"graduated lessons/tests","cn":"分级课程／测验"}},{"en":"marked with lines to show measurements","cn":"标有刻度的","ex":{"en":"a graduated jar","cn":"标有刻度的广口瓶"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"递增的；递进的","en":"Graduated means increasing by regular amounts or grades.","ex":{"en":"The US military wants to avoid the graduated escalation that marked the Vietnam War.","cn":"美国军方希望避免出现类似于越南战争那样逐步升级的态势。"}},{"pos":"ADJ 形容词","cn":"（广口瓶等）标有刻度的","en":"Graduated jars are marked with lines and numbers which show particular measurements.","ex":{"en":"...a graduated tube marked in millimetres.","cn":"以毫米标注刻度的试管"}}]},"examples":[{"en":"a graduated jar","cn":"标有刻度的广口瓶"},{"en":"graduated lessons/tests","cn":"分级教程/测验"}],"base":"graduate"},"guilty":{"oxford":{"phon":"ˈɡɪlti","pos":"adjective","senses":[{"en":"feeling ashamed because you have done something that you know is wrong or have not done something that you should have done","cn":"感到内疚的；感到惭愧的","ex":{"en":"Matt and Chrissy both looked equally guilty.","cn":"马特和克丽茜看上去同样内疚。"}},{"en":"having done something illegal; being responsible for something bad that has happened","cn":"犯有罪的；有过失的；有罪责的","lab":"especially North American English","ex":{"en":"He pleaded guilty to murder.","cn":"他承认犯有谋杀罪。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"内疚的；感到愧疚的","en":"If you feel guilty, you feel unhappy because you think that you have done something wrong or have failed to do something which you should have done.","ex":{"en":"I feel so guilty, leaving all this to you","cn":"把这些事都留给你去做，我真感到过意不去。"}},{"pos":"ADJ 形容词","cn":"罪恶的","en":"Guilty is used of an action or fact that you feel guilty about. guilty conscience→see: ;","ex":{"en":"Many may be keeping it a guilty secret","cn":"许多人或许保守着这个罪恶的秘密。"}},{"pos":"ADJ 形容词","cn":"犯罪的；有罪的","en":"If someone is guilty of a crime or offence, they have committed that crime or offence.","ex":{"en":"They were found guilty of murder","cn":"他们被判谋杀罪成立。"}},{"pos":"ADJ 形容词","cn":"有过失的","en":"If someone is guilty of doing something wrong, they have done that thing.","ex":{"en":"He claimed Mr Brooke had been guilty of a 'gross error of judgment'","cn":"他宣称布鲁克先生犯有“判断失误的重大过错”。"}}]},"media":{"uk":"media/uk/guilty__gb_1.mp3","us":"media/us/guilty__us_1.mp3"},"examples":[{"en":"We've all been guilty of selfishness at some time in our lives.","cn":"我们每个人一生中都有过自私自利的过失。"},{"en":"I felt guilty about not visiting my parents more often.","cn":"我因没有常去看望父母而感到内疚。"}]},"gram":{"oxford":{"phon":"ɡræm","pos":"noun","senses":[{"en":"a unit for measuring weight. There are 1 000 grams in one kilogram.","cn":"克（重量单位，等于 0.001 千克）","lab":"also British English, less frequent，，"},{"en":"a thing that is written or drawn","cn":"写（或画）的东西","ex":{"en":"telegram","cn":"电报"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"克（重量单位）","en":"A gram is a unit of weight. One thousand grams are equal to one kilogram.","ex":{"en":"A football weighs about 400 grams.","cn":"足球重约400克。"}}]},"media":{"uk":"media/uk/gram__gb_1.mp3","us":"media/us/gram__us_1.mp3"},"examples":[{"en":"hologram","cn":"全息图"},{"en":"telegram","cn":"电报"}]},"guns":{"lemma":"gun"},"greeting":{"media":{"uk":"media/uk/greeting__gb_1.mp3","us":"media/us/greeting__us_1.mp3"},"oxford":{"phon":"ˈɡriːtɪŋ","pos":"noun","senses":[{"en":"something that you say or do to greet somebody","cn":"问候；招呼；迎接；致意","g":"[countable, uncountable]","ex":{"en":"She waved a friendly greeting.","cn":"她友好地挥手致意。"}},{"en":"a message of good wishes for somebody’s health, happiness, etc.","cn":"问候的话；祝词；贺词","g":"[plural]","ex":{"en":"Christmas/birthday, etc. greetings","cn":"圣诞、生日等祝词"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"问候；招呼；致意","en":"A greeting is something friendly that you say or do when you meet someone.","ex":{"en":"His greeting was familiar and friendly","cn":"他的问候让人觉得随意又亲切。"}},{"pos":"CONVENTION 惯用语","cn":"（旧时的）祝词，贺词，问候语","en":"'Greetings' is an old-fashioned greeting."}]},"examples":[{"en":"They exchanged greetings and sat down to lunch.","cn":"他们相互致意后便坐下吃午饭。"},{"en":"My mother sends her greetings to you all.","cn":"我母亲向你们各位问好。"}],"base":"greet"},"german":{"media":{"uk":"media/uk/german_1_gb_1.mp3","us":"media/us/german_1_us_1.mp3"},"oxford":{"phon":"ˈdʒɜːmən","pos":"adjective","senses":[{"en":"from or connected with Germany","cn":"德国的"},{"en":"a person from Germany","cn":"德国人","g":"[countable]","pos":"noun"},{"en":"the language of Germany, Austria and parts of Switzerland","cn":"德语（德国、奥地利和瑞士部分地区的语言）","g":"[uncountable]","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"德国的；德国人的；德语的","en":"German means belonging or relating to Germany.","ex":{"en":"...a cut in German interest rates.","cn":"德国利率的下调"}},{"pos":"N-UNCOUNT 不可数名词","cn":"德语","en":"German is the language used in Germany, Austria, and parts of Switzerland.","ex":{"en":"I heard a very angry man talking in German.","cn":"我听到一个怒不可遏的人说着德语。"}}]},"examples":[{"en":"German history","cn":"德国历史"}]},"geared":{"media":{"uk":"media/uk/geared__gb_1.mp3","us":"media/us/geared__us_1.mp3"},"oxford":{"phon":"ɡɪəd","pos":"adjective","senses":[{"en":"designed or organized to achieve a particular purpose, or to be suitable for a particular group of people","cn":"旨在；适合于","ex":{"en":"The programme is geared to preparing students for the world of work.","cn":"本计划旨在为学生进入职场做准备。"}},{"en":"prepared and ready for something","cn":"（为…）做好准备，准备好","ex":{"en":"We have people on board geared up to help with any problems.","cn":"我们已得到人员支持，准备帮助解决任何问题。"}}]},"examples":[{"en":"We have people on board geared up to help with any problems.","cn":"我们已让船上的人做好准备帮助解决任何问题。"},{"en":"The programme is geared to preparing students for the world of work.","cn":"本计划旨在为学生开始就业做准备。"}]},"ghost":{"oxford":{"phon":"ɡəʊst","pos":"noun","senses":[{"en":"the spirit of a dead person that a living person believes they can see or hear","cn":"鬼；鬼魂；幽灵","g":"[countable]","ex":{"en":"Do you believe in ghosts (= believe that they exist)?","cn":"你相信有鬼吗？"}},{"en":"the memory of something, especially something bad","cn":"（尤指可怕事物的）记忆，回忆","g":"[countable]","ex":{"en":"The ghost of anti-Semitism still haunts Europe.","cn":"反犹主义在欧洲仍然阴魂不散。"}},{"en":"a very slight amount of something that is left behind or that you are not sure really exists","cn":"隐约的一点点；（某物残留的）一丝，一点","g":"[singular]","ex":{"en":"There was a ghost of a smile on his face.","cn":"他脸上露出隐隐的一丝微笑。"}},{"en":"a second image on a television screen that is not as clear as the first, caused by a fault","cn":"（电视屏幕上的）重影","g":"[singular]"},{"en":"to write a book, an article, etc. for another person who publishes it as their own work","cn":"代人写作；为人捉刀；代写","g":"[transitive, usually passive, intransitive]","pos":"verb"},{"en":"to move without making a sound","cn":"悄悄地行进","g":"[intransitive]","lab":"literary","ex":{"en":"They ghosted up the smooth waters of the river.","cn":"他们悄悄地航行在平静的河水上。"},"pos":"verb"},{"en":"to suddenly stop all communication with somebody, usually online, in order to end a relationship","cn":"与…断绝（线上）联系","g":"[transitive]","ex":{"en":"After three dates, she ghosted me.","cn":"约会了三次之后，她就对我产生了幻觉。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鬼；幽灵","en":"A ghost is the spirit of a dead person that someone believes they can see or feel.","ex":{"en":"...the ghost of Marie Antoinette","cn":"玛丽·安托瓦妮特的幽灵"}},{"pos":"N-COUNT 可数名词","cn":"（尤指对可怕事物的）记忆，回忆","en":"The ghost of something, especially of something bad that has happened, is the memory of it.","ex":{"en":"The President is using the two visits to lay the ghosts of the Munich Agreement.","cn":"总统正借这两次访问来消除《慕尼黑协定》的阴影。"}},{"pos":"N-SING 单数名词","cn":"一丝；一点","en":"If there is a ghost of something, that thing is so faint or weak that it hardly exists.","ex":{"en":"He gave the ghost of a smile","cn":"他露出一丝微笑。"}},{"pos":"VERB 动词","cn":"代人写作；为人代笔","en":"If a book or other piece of writing is ghosted, it is written by a writer for another person, for example a politician or sportsman, who then publishes it as his or her own work.","ex":{"en":"I published his autobiography, which was very competently ghosted by a woman journalist from the Daily Mail","cn":"我出版了《每日邮报》的女记者为他代笔的自传，写得颇具文采。"}},{"pos":"PHRASE 短语","cn":"没有一点（成功的）可能；机会渺茫","en":"If someone does not stand or does not have a ghost of a chance of doing something, they have very little chance of succeeding in it.","ex":{"en":"He doesn't stand a ghost of a chance of selling the house.","cn":"那房子他根本不可能卖得出去。"}},{"pos":"PHRASE 短语","cn":"（人）放弃，撂挑子；（机器）报废，不再运转","en":"If someone gives up the ghost, they stop trying to do something because they no longer believe they can do it successfully. If a machine gives up the ghost, it stops working.","ex":{"en":"Some firms give up the ghost before they find what they are looking for","cn":"一些公司没等找到目标便已放弃。"}}]},"media":{"uk":"media/uk/ghost__gb_1.mp3","us":"media/us/ghost__us_1.mp3"},"examples":[{"en":"They ghosted up the smooth waters of the river.","cn":"他们悄悄地航行在平静的河水上。"},{"en":"He looked as if he had seen a ghost (= looked very frightened).","cn":"他那副样子就像是见到鬼一样。"}]},"grow":{"media":{"uk":"media/uk/grow__gb_1.mp3","us":"media/us/grow__us_1.mp3"},"oxford":{"phon":"ɡrəʊ","pos":"verb","senses":[{"en":"to increase in size, number, strength or quality","cn":"扩大；增加；增强","g":"[intransitive]","sc":"increase","ex":{"en":"The sector is growing at a phenomenal rate.","cn":"该行业正在以惊人的速度增长。"}},{"en":"to become bigger or taller and develop into an adult","cn":"长大；长高；发育；成长","g":"[intransitive]","sc":"of person/animal","ex":{"en":"You've grown since the last time I saw you!","cn":"自从我上次见到你后，你又见长了！"}},{"en":"to exist and develop in a particular place; to make plants grow","cn":"（使）生长，发育","g":"[intransitive, transitive]","sc":"of plant","ex":{"en":"The region is too dry for plants to grow.","cn":"这地区干旱得草木不生。"}},{"en":"to become longer; to allow something to become longer by not cutting it","cn":"（使）留长，蓄长","g":"[intransitive, transitive]","sc":"of hair/nails","ex":{"en":"I've decided to let my hair grow.","cn":"我已决定留长发。"}},{"en":"to begin to have a particular quality or feeling over a period of time","cn":"逐渐变得；逐渐成为","sc":"become/begin","ex":{"en":"He had grown old and fat.","cn":"他年纪大了，也胖了。"}},{"en":"to gradually begin to do something","cn":"逐渐开始","g":"[intransitive]","sc":"become/begin","ex":{"en":"I'm sure you'll grow to like her in time.","cn":"我肯定你慢慢就会喜欢她了。"}},{"en":"to develop and improve particular qualities or skills","cn":"提升品质；培养技能","g":"[intransitive]","sc":"develop skills","ex":{"en":"She continues to grow as an artist.","cn":"她作为艺术家不断有所提高。"}},{"en":"to increase the size, quality or number of something","cn":"扩大；扩展；增加","g":"[transitive]","sc":"business","ex":{"en":"We are trying to grow the business.","cn":"我们正在努力扩展业务。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"生长；长大；发育","en":"When people, animals, and plants grow, they increase in size and change physically over a period of time.","ex":{"en":"We stop growing at maturity.","cn":"我们成年之后不再长个儿。"}},{"pos":"VERB 动词","cn":"成活；生长","en":"If a plant or tree grows in a particular place, it is alive there.","ex":{"en":"The station had roses growing at each end of the platform.","cn":"车站月台的两头种着玫瑰花。"}},{"pos":"VERB 动词","cn":"栽种；种植","en":"If you grow a particular type of plant, you put seeds or young plants in the ground and look after them as they develop.","ex":{"en":"I always grow a few red onions","cn":"我总是喜欢种一些红洋葱。"}},{"pos":"VERB 动词","cn":"（毛发、指甲等）变长","en":"When someone's hair grows, it gradually becomes longer. Your nails also grow.","ex":{"en":"Then the hair began to grow again and I felt terrific.","cn":"然后，头发又长起来了，我感觉棒极了。"}},{"pos":"VERB 动词","cn":"留长（头发或指甲）；蓄（胡须）","en":"If someone grows their hair, or grows a beard or moustache, they stop cutting their hair or shaving so that their hair becomes longer. You can also grow your nails.","ex":{"en":"I'd better start growing my hair.","cn":"我最好开始留头发。"}},{"pos":"VERB 动词","cn":"成长；长大；成熟","en":"If someone grows mentally, they change and develop in character or attitude.","ex":{"en":"They began to grow as persons.","cn":"他们开始长大成人了。"}},{"pos":"V-LINK 连系动词","cn":"变得；变成；长成","en":"You use grow to say that someone or something gradually changes until they have a new quality, feeling, or attitude.","ex":{"en":"I grew a little afraid of the guy next door","cn":"我开始有些害怕隔壁的那个家伙。"}},{"pos":"VERB 动词","cn":"增加；增强；增大","en":"If an amount, feeling, or problem grows, it becomes greater or more intense.","ex":{"en":"The number of unemployed people in Poland has grown by more than a quarter in the last month","cn":"上个月，波兰的失业人数增长超过了1/4。"}},{"pos":"VERB 动词","cn":"成长为；发展为","en":"If one thing grows into another, it develops or changes until it becomes that thing.","ex":{"en":"The boys grew into men","cn":"这些男孩子长成了男子汉。"}},{"pos":"VERB 动词","cn":"（观点、计划等）产生于，源于","en":"If something such as an idea or a plan grows out of something else, it develops from it.","ex":{"en":"The idea for this book grew out of conversations with Philippa Brewster.","cn":"创作这本书的想法来源于跟菲莉帕·布鲁斯特的谈话。"}},{"pos":"VERB 动词","cn":"（经济或公司）增长，扩大，发展","en":"If the economy or a business grows, it increases in wealth, size, or importance.","ex":{"en":"The economy continues to grow.","cn":"经济持续发展。"}},{"pos":"VERB 动词","cn":"扩大，壮大，发展（公司等）","en":"If someone grows a business, they take actions that will cause it to increase in wealth, size, or importance.","ex":{"en":"To grow the business, he needs to develop management expertise and innovation across his team.","cn":"为了拓展业务，他需要提高整个团队的管理技能和创新能力。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（晶体）产生；使（晶体）形成","en":"If a crystal grows, or if a scientist grows it, it forms from a solution.","ex":{"en":"...crystals that grow in cavities in the rock","cn":"岩石洞穴中形成的水晶"}},{"pos":"","cn":"","en":"相关词组：grow apart grow away from grow into grow on grow out grow out of grow up"}]},"examples":[{"en":"The dress is too long for her now but she'll grow into it.","cn":"这件连衣裙她现在穿太长，不过她长大了可以穿。"},{"en":"Fears are growing for the safety of a teenager who disappeared a week ago.","cn":"大家对那一周前失踪少年的安危越来越担忧。"}]},"going":{"media":{"uk":"media/uk/going__gb_1.mp3","us":"media/us/going__us_1.mp3"},"oxford":{"phon":"ˈɡəʊɪŋ","pos":"noun","senses":[{"en":"an act of leaving a place","cn":"离去；去；离开","g":"[singular]","lab":"formal","ex":{"en":"We were all sad at her going.","cn":"我们对她的离去都很难过。"}},{"en":"the speed with which somebody does something; how difficult it is to do something","cn":"进展速度；难度","g":"[uncountable]","ex":{"en":"Walking four miles in an hour is pretty good going for me.","cn":"一小时走四英里对我来说是相当不错了。"}},{"en":"the condition of the ground, especially in horse racing","cn":"（尤指赛马场的）地面状况","g":"[uncountable]","ex":{"en":"The going is good to firm.","cn":"赛马场的地面稍偏硬。"}},{"en":"going regularly to the place or event mentioned","cn":"常去…的","ex":{"en":"the theatre-going public","cn":"常去戏院的观众"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"PHR-MODAL 情态动词短语","cn":"将要，即将（发生）","en":"If you say that something is going to happen, you mean that it will happen in the future, usually quite soon.","ex":{"en":"I think it's going to be successful","cn":"我认为这事会成功。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"想要（做…）；决定（做…）","en":"You say that you are going to do something to express your intention or determination to do it.","ex":{"en":"I'm going to go to bed","cn":"我要睡觉了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"进展（或进行）情况","en":"You use the going to talk about how easy or difficult it is to do something. You can also say that something is, for example, hard going or tough going .","ex":{"en":"He has her support to fall back on when the going gets tough","cn":"他在进展困难的时候可以求助于她。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（赛马场等的）地面状况","en":"In horse racing and horse riding, when you talk about the going, you are talking about the condition of the surface the horses are running on.","ex":{"en":"The going was soft; some horses found it hard work.","cn":"这块场地偏软，有一些马跑得很费劲。"}},{"pos":"ADJ 形容词","cn":"（价格、工资等）通常的，现行的","en":"The going rate or the going salary is the usual amount of money that you expect to pay or receive for something.","ex":{"en":"She says that's the going rate for a house this big","cn":"她说这么大的房子现在就是这个价。"}},{"pos":"PHRASE 短语","cn":"占优势；占有利条件","en":"If someone or something has a lot going for them, they have a lot of advantages.","ex":{"en":"This area has a lot going for it","cn":"该地区占据很多优势。"}},{"pos":"PHRASE 短语","cn":"（尤指耽搁后）开始做，出发","en":"When you get going, you start doing something or start a journey, especially after a delay.","ex":{"en":"Now what about that shopping list? I've got to get going.","cn":"那张购物清单呢？我得出发了。"}},{"pos":"PHRASE 短语","cn":"趁情况还有利时","en":"If you say that someone should do something while the going is good, you are advising them to do it while things are going well and they still have the opportunity, because you think it will become much more difficult to do.","ex":{"en":"People are leaving in their thousands while the going is good.","cn":"成千上万的人趁着局势稳定赶紧撤离。"}},{"pos":"PHRASE 短语","cn":"继续做","en":"If you keep going, you continue doing things or doing a particular thing.","ex":{"en":"I like to keep going. I hate to sit still.","cn":"我喜欢一直有事情做，讨厌一动不动地坐着。"}},{"pos":"PHRASE 短语","cn":"维持下去","en":"If you can keep going with the money you have, you can manage to live on it.","ex":{"en":"Things were difficult, and we needed her wages to keep going.","cn":"日子很艰难，我们要靠她的工资来维持生活。"}},{"pos":"PHRASE 短语","cn":"进展顺利；进展不错","en":"If you say that something that has been achieved is good going or not bad going, you mean that it is better than usual or than expected.","ex":{"en":"4,000 copies of Wuthering Heights went in two days. That's not bad going for a book that has been on the market for 145 years.","cn":"4,000册《呼啸山庄》在两天内销售一空，对于一本已经面市145年的书而言，这是一个不错的成绩。"}},{"pos":"PHRASE 短语","cn":"眼下；暂时","en":"If you say that something is enough to be going on with, you mean that it is enough for your needs at the moment, although you will need something better at some time in the future.","ex":{"en":"It was a good enough description for Mattie to be going on with.","cn":"这个描述对玛蒂来说暂时还不错。"}},{"pos":"PHRASE 短语","cn":"接近；快；几乎","en":"You can use going on before a number to say that something has almost reached that number. For example, you can say that someone is going on 40 to indicate that they are nearly 40.","ex":{"en":"We've been married for going on two years","cn":"我们结婚快两年了。"}},{"pos":"See also:","cn":"","en":"going concern→see: ;"}]},"examples":[{"en":"She had her own company by 25 — not bad going!","cn":"她 25 岁时就有了自己的公司，真了不起！"},{"en":"Walking four miles in an hour is pretty good going for me.","cn":"一小时走四英里对我来说是相当不错了。"}],"base":"go"},"gallery":{"oxford":{"phon":"ˈɡæləri","pos":"noun","senses":[{"en":"a room or building for showing works of art, especially to the public","cn":"（艺术作品的）陈列室，展览馆","lab":"US English","ex":{"en":"a picture gallery","cn":"美术馆"}},{"en":"a collection of pictures","cn":"图片库","ex":{"en":"Visit the photo gallery on our website to see pictures from the event.","cn":"请访问我们网站的图片库，查看活动照片。"}},{"en":"a small private shop where you can see and buy works of art","cn":"（经营性）画廊"},{"en":"an upstairs area at the back or sides of a large hall where people can sit","cn":"（大厅的）楼座，楼上旁听席","ex":{"en":"Relatives of the victim watched from the public gallery as the murder charge was read out in court.","cn":"法庭宣读谋杀指控时受害者的亲属在公共旁听席观看。"}},{"en":"the highest level in a theatre where the cheapest seats are","cn":"（剧场中票价最低的）顶层楼座"},{"en":"a long narrow room, especially one used for a particular purpose","cn":"长廊；走廊；柱廊"},{"en":"a level passage under the ground in a mine or cave","cn":"（矿坑或洞穴中的）水平巷道"}]},"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"（艺术作品的）陈列室，展览馆；画廊","en":"A gallery is a place that has permanent exhibitions of works of art in it.","ex":{"en":"...an art gallery.","cn":"美术馆"}},{"pos":"N-COUNT 可数名词","cn":"私人画店；私人画廊（或画室）","en":"A gallery is a privately owned building or room where people can look at and buy works of art.","ex":{"en":"The painting is in the gallery upstairs.","cn":"那幅画在楼上的画廊里。"}},{"pos":"N-COUNT 可数名词","cn":"（大厅的）楼座，边座，楼上旁听席","en":"A gallery is an area high above the ground at the back or at the sides of a large room or hall.","ex":{"en":"A crowd already filled the gallery.","cn":"楼座已经挤满了人。"}},{"pos":"N-COUNT 可数名词","cn":"（剧场或音乐厅中通常票价最低的）顶层楼座","en":"The gallery in a theatre or concert hall is an area high above the ground that usually contains the cheapest seats.","ex":{"en":"They had been forced to find cheap tickets in the gallery.","cn":"他们不得已买了顶层楼座的廉价票。"}}]},"media":{"uk":"media/uk/gallery__gb_1.mp3","us":"media/us/gallery__us_1.mp3"},"examples":[{"en":"Relatives of the victim watched from the public gallery as the murder charge was read out in court.","cn":"法庭宣读谋杀指控时受害者的亲属在公共旁听席观看。"},{"en":"an art/a picture gallery","cn":"美术馆；绘画陈列室"}]},"gaze":{"media":{"uk":"media/uk/gaze__gb_1.mp3","us":"media/us/gaze__us_1.mp3"},"oxford":{"phon":"ɡeɪz","pos":"verb","senses":[{"en":"to look steadily at somebody/something for a long time, either because you are very interested or surprised, or because you are thinking of something else","cn":"凝视；注视；盯着","ex":{"en":"She gazed at him in amazement.","cn":"她惊异地注视着他。"}},{"en":"a long, steady look at somebody/something","cn":"凝视；注视","ex":{"en":"He met her gaze (= looked at her while she looked at him).","cn":"他与她凝视的目光相遇。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"凝视；注视；盯着看","en":"If you gaze at someone or something, you look steadily at them for a long time, for example because you find them attractive or interesting, or because you are thinking about something else.","ex":{"en":"She stood gazing at herself in the mirror","cn":"她站在那儿，凝视着镜中的自己。"}},{"pos":"N-COUNT 可数名词","cn":"凝视；注视","en":"You can talk about someone's gaze as a way of describing how they are looking at something, especially when they are looking steadily at it.","ex":{"en":"The Monsignor turned his gaze from the flames to meet the Colonel's","cn":"这位大人凝视的目光离开火苗，与上校的目光相遇。"}},{"pos":"PHRASE 短语","cn":"受公众关注；受人瞩目","en":"If someone or something is in the public gaze, they are receiving a lot of attention from the general public.","ex":{"en":"You won't find a couple more in the public gaze than Michael and Lizzie.","cn":"没有比迈克尔和莉齐更受人瞩目的夫妇了。"}}]},"examples":[{"en":"He sat for hours just gazing into space.","cn":"他一连几个小时坐在那里茫然地看着前面。"},{"en":"He met her gaze (= looked at her while she looked at him).","cn":"他与她凝视的目光相遇。"}]},"germanic":{"oxford":{"phon":"dʒɜːˈmænɪk","pos":"adjective","senses":[{"en":"connected with or considered typical of Germany or its people","cn":"德国的；德国人的；有德国（或德国人）特点的","ex":{"en":"She had an almost Germanic regard for order.","cn":"她简直像德国人一样讲究条理。"}},{"en":"connected with the language family that includes German, English, Dutch and Swedish among others","cn":"日耳曼语（族）的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"德国人的；德国式的","en":"If you describe someone or something as Germanic, you think that their appearance or behaviour is typical of German people or things.","ex":{"en":"He asked in his Germanic English if I was enjoying France.","cn":"他操着一口带有德国腔的英语问我在法国玩得是否愉快。"}},{"pos":"ADJ 形容词","cn":"日耳曼文化的；日耳曼语的","en":"Germanic is used to describe the ancient culture and language of the peoples of northern Europe.","ex":{"en":"...the Germanic tribes of pre-Christian Europe.","cn":"基督教创立之前定居在欧洲的日耳曼部落"}}]},"media":{"uk":"media/uk/germanic__gb_1.mp3","us":"media/us/germanic__us_1.mp3"},"examples":[{"en":"She had an almost Germanic regard for order.","cn":"她简直像德国人一样讲究条理。"}]},"gusto":{"media":{"uk":"media/uk/gusto__gb_1.mp3","us":"media/us/gusto__us_1.mp3"},"oxford":{"phon":"ˈɡʌstəʊ","pos":"noun","senses":[{"en":"enthusiasm and energy in doing something","cn":"热情高涨；兴致勃勃","ex":{"en":"They sang with gusto.","cn":"他们兴致勃勃地唱歌。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（做某事的）热情，兴致，精力","en":"If you do something with gusto, you do it with energetic and enthusiastic enjoyment.","ex":{"en":"Hers was a minor part, but she played it with gusto.","cn":"她演的是个小角色，但是演得很投入。"}}]},"examples":[{"en":"They sang with gusto.","cn":"他们兴致勃勃地唱歌。"},{"en":"They sang hymns with great gusto.","cn":"他们满怀热情地唱赞美诗。"}]},"gift":{"media":{"uk":"media/uk/gift__gb_1.mp3","us":"media/us/gift__us_1.mp3"},"oxford":{"phon":"ɡɪft","pos":"noun","senses":[{"en":"a thing that you give to somebody, especially on a special occasion or to say thank you","cn":"礼物；赠品","lab":"formal","ex":{"en":"to give/receive a gift","cn":"送礼；收礼"}},{"en":"a natural ability","cn":"天赋；天才；才能","ex":{"en":"She can pick up a tune instantly on the piano. It's a gift.","cn":"她听到曲子就能马上用钢琴弹出来，这是天分。"}},{"en":"a thing that is very easy to do or cheap to buy","cn":"轻而易举的事；极便宜的东西","g":"[usually singular]","lab":"informal","ex":{"en":"Their second goal was an absolute gift.","cn":"他们第二个进球简直不费吹灰之力。"}},{"en":"to give something to somebody without their having to make any effort to get it","cn":"白送；白给","ex":{"en":"They gifted their opponents a goal.","cn":"他们白送给对方一分。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"礼物；礼品","en":"A gift is something that you give someone as a present.","ex":{"en":"...a gift of $50.00","cn":"价值50美元的礼物"}},{"pos":"N-COUNT 可数名词","cn":"天赋；天才；才能","en":"If someone has a gift for doing something, they have a natural ability for doing it.","ex":{"en":"As a youth he discovered a gift for teaching","cn":"他年轻时就表现出教书的天赋。"}},{"pos":"","cn":"","en":"God's gift→see: ;"}]},"examples":[{"en":"She can pick up a tune instantly on the piano. It's a gift.","cn":"她听到曲子就能马上用钢琴弹出来，这是天分。"},{"en":"Their second goal was an absolute gift.","cn":"他们第二个进球简直不费吹灰之力。"}]},"gang":{"media":{"uk":"media/uk/gang__gb_1.mp3","us":"media/us/gang__us_1.mp3"},"oxford":{"phon":"ɡæŋ","pos":"noun","senses":[{"en":"an organized group of criminals","cn":"一帮，一伙（罪犯）","ex":{"en":"criminal gangs","cn":"犯罪团伙"}},{"en":"a group of young people who spend a lot of time together and often cause trouble or fight against other groups","cn":"一帮，一群，一伙（闹事、斗殴的年轻人）","ex":{"en":"to join a gang","cn":"加入团伙"}},{"en":"a group of friends who meet regularly","cn":"一伙（经常聚在一起的朋友）","lab":"informal","ex":{"en":"The whole gang will be there.","cn":"大伙儿都将在那儿。"}},{"en":"an organized group of workers or prisoners doing work together","cn":"一队，一组（一起干活的工人或囚犯）","ex":{"en":"a prison/work gang","cn":"狱内团伙；劳动队"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一帮，一伙（尤指滋事的年轻人）","en":"A gang is a group of people, especially young people, who go around together and often deliberately cause trouble.","ex":{"en":"During the fight with a rival gang he lashed out with his flick knife","cn":"在与敌对帮派的打斗中，他挥舞着弹簧折刀一通猛刺。"}},{"pos":"N-COUNT 可数名词","cn":"一帮，一伙（罪犯）","en":"A gang is a group of criminals who work together to commit crimes.","ex":{"en":"Police were hunting for a gang who had allegedly stolen fifty-five cars.","cn":"警方正在追捕一个被控盗窃了55辆汽车的犯罪团伙。"}},{"pos":"N-SING 单数名词","cn":"一伙（常聚会的朋友）","en":"The gang is a group of friends who frequently meet.","ex":{"en":"Come on over, we've got lots of the old gang here.","cn":"过来吧，好多老朋友都在这儿。"}},{"pos":"N-COUNT 可数名词","cn":"一群，一队，一组（一起干体力活的人）","en":"A gang is a group of workers who do physical work together.","ex":{"en":"...a gang of labourers.","cn":"一群工人"}},{"pos":"","cn":"","en":"相关词组：gang up"}]},"examples":[{"en":"At school the older boys ganged up on him and called him names.","cn":"在学校读书时那些大男孩联合起来欺负他，辱骂他。"},{"en":"A four-man gang carried out the robbery.","cn":"这起抢劫是一个四人团伙所为。"}]},"gloom":{"media":{"uk":"media/uk/gloom__gb_1.mp3","us":"media/us/gloom__us_1.mp3"},"oxford":{"phon":"ɡluːm","pos":"noun","senses":[{"en":"a feeling of being sad and without hope","cn":"忧郁；愁闷；无望","g":"[uncountable, singular]","ex":{"en":"The gloom deepened as the election results came in.","cn":"选举结果陆续传来，失落的情绪越来越重。"}},{"en":"almost total darkness","cn":"幽暗；黑暗；昏暗","g":"[uncountable]","lab":"literary","ex":{"en":"We watched the boats come back in the gathering gloom.","cn":"我们注视着船只在越来越浓的暮色中返航。"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"阴暗；昏暗","en":"The gloom is a state of near darkness.","ex":{"en":"...the gloom of a foggy November morning","cn":"11月份一个雾蒙蒙的早晨，天空昏暗阴沉"}},{"pos":"N-UNCOUNT 不可数名词","cn":"忧郁；愁闷；无望","en":"Gloom is a feeling of sadness and lack of hope.","ex":{"en":"...the deepening gloom over the economy.","cn":"对经济的忧虑日益加重"}}]},"examples":[{"en":"The gloom deepened as the election results came in.","cn":"选举结果陆续传来，失落的情绪越来越重。"},{"en":"We watched the boats come back in the gathering gloom.","cn":"我们注视着船只在朦胧暮色中返航。"}]},"grammatical":{"oxford":{"phon":"ɡrəˈmætɪkl","pos":"adjective","senses":[{"en":"connected with the rules of grammar","cn":"语法的；文法的","ex":{"en":"a grammatical error","cn":"语法错误"}},{"en":"correctly following the rules of grammar","cn":"符合语法规则的；合乎文法的","ex":{"en":"That sentence is not grammatical.","cn":"那个句子不合语法。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"语法的；文法的","en":"Grammatical is used to indicate that something relates to grammar.","ex":{"en":"Should the teacher present grammatical rules to students?","cn":"老师是否应该给学生讲授语法规则？"}},{"pos":"ADJ 形容词","cn":"符合语法规则的；符合文法的","en":"If someone's language is grammatical, it is considered correct because it obeys the rules of grammar.","ex":{"en":"...a new test to determine whether students can write grammatical English.","cn":"考查学生是否能用符合语法规则的英语进行写作的新型考试"}}]},"media":{"uk":"media/uk/grammatical__gb_1.mp3","us":"media/us/grammatical__us_1.mp3"},"examples":[{"en":"That sentence is not grammatical.","cn":"那个句子不合语法。"},{"en":"a grammatically correct sentence","cn":"语法上正确的句子"}]},"genetic":{"oxford":{"phon":"dʒəˈnetɪk","pos":"adjective","senses":[{"en":"connected with genes (= the units in the cells of a living thing that control its physical characteristics) or genetics (= the study of genes)","cn":"基因的；遗传学的","ex":{"en":"genetic and environmental factors","cn":"遗传和环境因素"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"遗传的；基因的","en":"You use genetic to describe something that is concerned with genetics or with genes.","ex":{"en":"Cystic fibrosis is the most common fatal genetic disease in the United States.","cn":"囊性纤维化是美国最常见的致命遗传疾病。"}}]},"media":{"uk":"media/uk/genetic__gb_1.mp3","us":"media/us/genetic__us_1.mp3"},"examples":[{"en":"genetically engineered/determined/transmitted","cn":"转基因的；由基因决定的；遗传的"},{"en":"genetic and environmental factors","cn":"遗传和环境因素"}]},"gently":{"media":{"uk":"media/uk/gently__gb_1.mp3","us":"media/us/gently__us_1.mp3"},"oxford":{"phon":"ˈdʒentli","pos":"adverb","senses":[{"en":"in a way that is soft and light, not strong, extreme or violent","cn":"温柔地；和缓地","ex":{"en":"She held the baby gently.","cn":"她轻轻地抱着婴儿。"}},{"en":"in a calm, kind and quiet way","cn":"温和地","ex":{"en":"‘You miss them, don't you?’ he asked gently.","cn":"“你想念他们，是吗？”他温和地问道。"}},{"en":"in a way that slopes very gradually","cn":"平缓地","ex":{"en":"The path ran gently down to the sea.","cn":"这条小路平缓地向大海延伸。"}},{"en":"used to tell somebody to be careful","cn":"（提醒对方小心）注意点，小心点，慢点","lab":"British English, informal，，","ex":{"en":"Gently! You'll hurt the poor thing!","cn":"小心点，你会弄痛这可怜的家伙！"}}]},"examples":[{"en":"‘You miss them, don't you?’ he asked gently. “","cn":"你想念他们，是吗？”他温和地问道。"},{"en":"Gently! You'll hurt the poor thing!","cn":"小心点，你会弄痛这可怜的家伙的！"}]},"grilling":{"oxford":{"phon":"ˈɡrɪlɪŋ","pos":"noun","senses":[{"en":"a period of being questioned closely about your ideas, actions, etc.","cn":"盘问，责问，审问（的一段时间）","ex":{"en":"The minister faced a tough grilling at today's press conference.","cn":"部长在今天的记者招待会上受到了严厉的盘问。"}}]},"media":{"uk":"media/uk/grilling__gb_1.mp3","us":"media/us/grilling__us_1.mp3"},"examples":[{"en":"The minister faced a tough grilling at today's press conference.","cn":"部长在今天的记者招待会上受到了严厉的盘问。"},{"en":"The three party leaders each endured a 20-minute television grilling from voters.","cn":"三名政党领导人各在电视上接受了选民二十分钟的提问。"}],"base":"grill"},"gothic":{"media":{"uk":"media/uk/gothic__gb_1.mp3","us":"media/us/gothic__us_1.mp3"},"oxford":{"phon":"ˈɡɒθɪk","pos":"adjective","senses":[{"en":"connected with the Goths (= a Germanic people who fought against the Roman Empire)","cn":"哥特人的，哥特族的，哥特语的"},{"en":"built in the style that was popular in western Europe from the 12th to the 16th centuries, and which has pointed arches and windows and tall thin pillars","cn":"哥特式的，哥特风格的（12 至 16 世纪流行于西欧的建筑风格，以尖拱、尖窗和细长柱为特色）","lab":"architecture","ex":{"en":"a Gothic church","cn":"哥特式教堂"}},{"en":"written in the style popular in the 18th and 19th centuries, which described romantic adventures in mysterious or frightening places or situations","cn":"哥特派的，哥特风格的（流行于 18 至 19 世纪，描述神秘或恐怖背景下的浪漫历险故事）"},{"en":"having pointed letters with thick lines and sharp angles. German books used to be printed in this style.","cn":"哥特体黑体字的（旧时德语书籍常用）"},{"en":"connected with goths","cn":"哥特派的"},{"en":"the Gothic style of architecture","cn":"哥特式建筑；尖拱式建筑","pos":"noun"},{"en":"Gothic printing type or printed letters","cn":"哥特体黑体字","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（建筑等）哥特式的，哥特风格的","en":"Gothic architecture and religious art was produced in the Middle Ages. Its features include tall pillars, high curved ceilings, and pointed arches.","ex":{"en":"...a vast, lofty Gothic cathedral.","cn":"宏伟高耸的哥特式教堂"}},{"pos":"ADJ 形容词","cn":"（小说）哥特派的（描写怪诞、神秘的恐怖故事）","en":"In Gothic stories, strange, mysterious adventures happen in dark and lonely places such as graveyards and old castles.","ex":{"en":"This novel is not science fiction, nor is it Gothic horror.","cn":"这本小说既非科幻小说亦非哥特派恐怖小说。"}},{"pos":"ADJ 形容词","cn":"（印刷或书写文字）哥特体的，花体的，德文老式字体的","en":"Gothic is used to describe a style of printing or writing in which the letters are very decorative. German books and signs were often written in Gothic script."}]},"examples":[{"en":"a Gothic church","cn":"哥特式教堂"}]},"gravity":{"media":{"uk":"media/uk/gravity__gb_1.mp3","us":"media/us/gravity__us_1.mp3"},"oxford":{"phon":"ˈɡrævəti","pos":"noun","senses":[{"en":"the force that attracts objects in space towards each other, and that on the earth pulls them towards the centre of the planet, so that things fall to the ground when they are dropped","cn":"重力；地球引力","ex":{"en":"Newton’s law of gravity","cn":"牛顿万有引力定律"}},{"en":"extreme importance and a cause for worry","cn":"严重性","lab":"formal","ex":{"en":"I don't think you realise the gravity of the situation.","cn":"我认为你没有意识到形势的严重性。"}},{"en":"serious behaviour, speech or appearance","cn":"严肃；庄严","lab":"formal","ex":{"en":"They were asked to behave with the gravity that was appropriate in a court of law.","cn":"他们被要求在法庭上表现出应有的严肃态度。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"重力；地球引力","en":"Gravity is the force which causes things to drop to the ground.","ex":{"en":"Arrows would continue to fly forward forever in a straight line were it not for gravity, which brings them down to earth.","cn":"要不是重力使箭落向地面，它们将永远以直线往前飞行。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（事态的）严重性，重大","en":"The gravity of a situation or event is its extreme importance or seriousness.","ex":{"en":"They deserve punishment which matches the gravity of their crime","cn":"应当根据罪行的严重性来惩治他们。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（言谈举止的）庄重，严肃","en":"The gravity of someone's behaviour or speech is the extremely serious way in which they behave or speak.","ex":{"en":"There was an appealing gravity to everything she said.","cn":"她说的每句话都带着一种庄严，很能吸引人。"}}]},"examples":[{"en":"They were asked to behave with the gravity that was appropriate in a court of law.","cn":"他们被要求在法庭上表现出应有的严肃态度。"},{"en":"Punishment varies according to the gravity of the offence.","cn":"处罚根据罪行的严重程度而有所不同。"}]},"gaining":{"lemma":"gain","media":{"uk":"media/uk/gain__gb_1.mp3","us":"media/us/gain__us_1.mp3"}},"grounded":{"media":{"uk":"media/uk/grounded__gb_1.mp3","us":"media/us/grounded__us_1.mp3"},"oxford":{"phon":"ˈɡraʊndɪd","pos":"adjective","senses":[{"en":"having a sensible and realistic attitude to life","cn":"（对生活）持有理智和现实态度的","ex":{"en":"Away from Hollywood, he relies on his family and friends to keep him grounded.","cn":"离开好莱坞之后，他靠家人和朋友使自己保持心态平衡。"}}]},"collins":{"senses":[{"pos":"","cn":"头脑清醒的；理智的；脚踏实地的","en":"If you say that someone is grounded, you mean that they are sensible and reasonable, and that they understand the importance of ordinary things in life.","ex":{"en":"Family and old friends help me stay grounded.","cn":"是家人和老友帮助我始终做到脚踏实地。"}}]},"examples":[{"en":"Away from Hollywood, he relies on his family and friends to keep him grounded.","cn":"离开好莱坞之后，他靠家人和朋友使自己保持心态平衡。"},{"en":"His views are grounded on the assumption that all people are equal.","cn":"他的观点建立在人人平等的假设之上。"}],"base":"ground"},"glacier":{"oxford":{"phon":"ˈɡlæsiə(r)","pos":"noun","senses":[{"en":"a slow-moving mass or river of ice, formed from snow on mountains or near the North Pole or South Pole","cn":"冰川"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"冰川；冰河","en":"A glacier is an extremely large mass of ice which moves very slowly, often down a mountain valley."}]},"media":{"uk":"media/uk/glacier__gb_1.mp3","us":"media/us/glacier__us_1.mp3"}},"gaps":{"lemma":"gap","media":{"uk":"media/uk/gap__gb_1.mp3","us":"media/us/gap__us_1.mp3"}},"guidance":{"media":{"uk":"media/uk/guidance__gb_1.mp3","us":"media/us/guidance__us_1.mp3"},"oxford":{"phon":"ˈɡaɪdns","pos":"noun","senses":[{"en":"help or advice that is given to somebody, especially by somebody older or with more experience","cn":"指导；引导；咨询","ex":{"en":"guidance for teachers on how to use video in the classroom","cn":"为教师提供的课堂录像教学指导"}},{"en":"the process of controlling the direction of a rocket, etc., using electronic equipment","cn":"（火箭等的）制导，导航","ex":{"en":"a missile guidance system","cn":"导弹制导系统"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"指导；引导；咨询","en":"Guidance is help and advice.","ex":{"en":"...an opportunity for young people to improve their performance under the guidance of professional coaches","cn":"年轻人在职业教练的指导下提高成绩的机会"}}]},"examples":[{"en":"Activities all take place under the guidance of an experienced tutor.","cn":"所有活动都在经验丰富的导师指导下进行。"},{"en":"guidance for teachers on how to use video in the classroom","cn":"对教师提供的课堂录像教学指导"}]},"gotten":{"lemma":"get","media":{"uk":"media/uk/gotten__gb_1.mp3","us":"media/us/gotten__us_1.mp3"}},"good-natured":{"oxford":{"phon":"ˌɡʊd ˈneɪtʃəd","pos":"adjective","senses":[{"en":"kind, friendly and patient when dealing with people","cn":"本性善良的；和蔼可亲的；友好的","ex":{"en":"a good-natured person/discussion","cn":"和蔼可亲的人；友好的讨论"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"性情温和的；友善的；温驯的","en":"A good-natured person or animal is naturally friendly and does not get angry easily.","ex":{"en":"Bates looks like a good-natured lad","cn":"贝茨看起来像个性情温和的小伙子。"}}]},"media":{"uk":"media/uk/good_natured_1_gb_1.mp3","us":"media/us/good_natured_1_us_1.mp3"},"examples":[{"en":"a good-natured person/discussion","cn":"和蔼可亲的人；友好的讨论"},{"en":"to smile good-naturedly","cn":"和善地微笑"}]},"gears":{"lemma":"gear","media":{"uk":"media/uk/gear__gb_1.mp3","us":"media/us/gear__us_1.mp3"}},"greenfield":{"oxford":{"phon":"ˈɡriːnfiːld","pos":"adjective","senses":[{"en":"used to describe an area of land that has not yet had buildings on it, but for which building development may be planned","cn":"未开发地区的；地产发展规划区的；绿色开发区的","ex":{"en":"a greenfield site","cn":"待开发区"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未开发地区的；待开发地区的","en":"Greenfield is used to refer to land that has not been built on before.","ex":{"en":"The Government has ruled out the building of a new airport on a greenfield site.","cn":"政府禁止在一块未开发地皮上建设新机场的。"}}]},"media":{"uk":"media/uk/greenfield__gb_1.mp3","us":"media/us/greenfield__us_1.mp3"},"examples":[{"en":"a greenfield site","cn":"绿色开发区"}]},"greek":{"media":{"uk":"media/uk/greek__gb_1.mp3","us":"media/us/greek__us_1.mp3"},"oxford":{"phon":"ɡriːk","pos":"noun","senses":[{"en":"a person from modern or ancient Greece","cn":"希腊人；古希腊人","g":"[countable]"},{"en":"the language of modern or ancient Greece","cn":"希腊语","g":"[uncountable]"},{"en":"a member of a fraternity or a sorority at a college or university","cn":"（大学的）学生联谊会会员，女生联谊会会员","g":"[countable]","lab":"North American English"},{"en":"of or connected with Greece, its people or their language","cn":"希腊的；希腊人的；希腊语的","pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"希腊的","en":"Greek means belonging or relating to Greece.","ex":{"en":"In the Greek general election, the New Democracy party has claimed victory.","cn":"新民主党在希腊大选中获胜。"}},{"pos":"N-COUNT 可数名词","cn":"希腊人","en":"A Greek is a person who comes from Greece.","ex":{"en":"He had looked through the house for the two Greeks.","cn":"他搜遍了整个房子想要找到那两个希腊人。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"希腊语","en":"Greek is the language used in Greece.","ex":{"en":"I had to learn Greek.","cn":"我不得不学习希腊语。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"古希腊语","en":"Greek or Ancient Greek was the language used in Greece in ancient times.","ex":{"en":"Teachers warn today that Latin, Greek and other classics will be squeezed out of school timetables.","cn":"老师们今天发出警告说，拉丁语、古希腊语和其他古典文学将被挤出学校的课程表。"}}]},"examples":[{"en":"She tried to explain how the system works, but it's all Greek to me.","cn":"她努力解释系统如何运作，可我就是怎么也弄不明白。"},{"en":"Greek yoghurt","cn":"希腊酸奶"}]},"galley":{"media":{"uk":"media/uk/galley__gb_1.mp3","us":"media/us/galley__us_1.mp3"},"oxford":{"phon":"ˈɡæli","pos":"noun","senses":[{"en":"a long flat ship with sails, especially one used by the ancient Greeks or Romans in war, usually rowed by slaves or prisoners","cn":"（常由奴隶或囚犯划桨的）桨帆船；（古希腊和古罗马的）战舰","ex":{"en":"a galley slave","cn":"划桨的奴隶"}},{"en":"the kitchen on a ship or plane","cn":"（船或飞机上的）厨房"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（轮船或飞机上的）厨房","en":"On a ship or aircraft, the galley is the kitchen."},{"pos":"N-COUNT 可数名词","cn":"（旧时常由奴隶或囚犯划桨的）桨帆船","en":"In former times, a galley was a ship with sails and a lot of oars, which was often rowed by slaves or prisoners."}]},"examples":[{"en":"The fire extinguishers are stored in the galley.","cn":"灭火器存放在船上的厨房里。"}]},"genial":{"media":{"uk":"media/uk/genial__gb_1.mp3","us":"media/us/genial__us_1.mp3"},"oxford":{"phon":"ˈdʒiːniəl","pos":"adjective","senses":[{"en":"friendly and cheerful","cn":"友好的；亲切的；欢快的","ex":{"en":"a genial person","cn":"和蔼可亲的人"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"友善的；真诚的；亲切的；和蔼可亲的","en":"Someone who is genial is kind and friendly.","ex":{"en":"Bob was always genial and welcoming","cn":"鲍勃总是那么友善热情。"}}]},"examples":[{"en":"an atmosphere of warmth and geniality","cn":"热情友好的气氛"},{"en":"a genial person","cn":"和蔼可亲的人"}]},"geopolitical":{"media":{"uk":"media/uk/geopolitical__gb_1.mp3","us":"media/us/geopolitical__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"地缘政治（学）的","en":"Geopolitical means relating to or concerned with geopolitics.","ex":{"en":"Hungary and Poland have suffered before because of their unfortunate geopolitical position on the European map.","cn":"匈牙利和波兰因其在欧洲地图上的极为不利的地缘政治位置而备受磨难。"}}]},"oxford":{"phon":"ˌdʒiːəʊpəˈlɪtɪkl","pos":"adjective","senses":[{"en":"connected with the political relations between countries and groups of countries in the world, as influenced by their geography","cn":"地缘政治的，地缘政治学的","ex":{"en":"an uncertain economic and geopolitical situation","cn":"不确定的经济和地缘政治形势"}}]}},"gentleman":{"media":{"uk":"media/uk/gentleman__gb_1.mp3","us":"media/us/gentleman__us_1.mp3"},"oxford":{"phon":"ˈdʒentlmən","pos":"noun","senses":[{"en":"a man who is polite and well educated, who has excellent manners and always behaves well","cn":"彬彬有礼的人；有教养的人；君子","g":"[countable]","ex":{"en":"You acted like a true gentleman.","cn":"你表现得像个真正的绅士。"}},{"en":"used to address or refer to a man, especially somebody you do not know","cn":"（称呼或指男子，尤其是不认识的）先生","g":"[countable, usually plural]","lab":"formal","ex":{"en":"Ladies and gentlemen! Can I have your attention, please?","cn":"女士们，先生们，请大家注意！"}},{"en":"used to address or refer to a male member of a legislature, for example the House of Representatives","cn":"（对立法机构男议员的称呼）先生，阁下","lab":"North American English"},{"en":"a man from a high social class, especially one who does not need to work","cn":"有身份的人；绅士；富绅","lab":"old-fashioned","ex":{"en":"He retired to his estate and lived the life of a country gentleman.","cn":"他退隐庄园，过着乡绅的生活。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"有身份的人；绅士","en":"A gentleman is a man who comes from a family of high social standing.","ex":{"en":"...this wonderful portrait of English gentleman Joseph Greenway.","cn":"英国绅士约瑟夫·格林韦的精美画像"}},{"pos":"N-COUNT 可数名词","cn":"有教养的人；彬彬有礼的人；君子","en":"If you say that a man is a gentleman, you mean he is polite and educated, and can be trusted.","ex":{"en":"He was always such a gentleman.","cn":"他总是那么彬彬有礼。"}},{"pos":"N-COUNT; N-VOC 可数名词；称呼名词","cn":"（对人礼貌的称呼）先生","en":"You can address men as gentlemen, or refer politely to them as gentlemen.","ex":{"en":"This way, please, ladies and gentlemen","cn":"女士们，先生们，这边请。"}},{"pos":"PHRASE 短语","cn":"（口头的）君子协定，绅士协定","en":"A gentleman's agreement or a gentlemen's agreement is an informal agreement in which people trust one another to do what they have promised. The agreement is not written down and does not have any legal force.","ex":{"en":"We had no contract; it was done by a gentleman's agreement","cn":"我们没有签合同，就订了个君子协定。"}}]},"examples":[{"en":"a gentleman farmer (= one who owns a farm for pleasure, not as his main job)","cn":"乡绅（以拥有农场为乐趣，而不作为主业）"},{"en":"Ladies and gentlemen! Can I have your attention, please?","cn":"女士们，先生们，请大家注意！"}]},"gorgeous":{"media":{"uk":"media/uk/gorgeous__gb_1.mp3","us":"media/us/gorgeous__us_1.mp3"},"oxford":{"phon":"ˈɡɔːdʒəs","pos":"adjective","senses":[{"en":"very beautiful and attractive; giving great pleasure","cn":"非常漂亮的；美丽动人的；令人愉快的","lab":"informal","ex":{"en":"a gorgeous girl/man","cn":"漂亮的女郎；美男子"}},{"en":"with very deep colours; impressive","cn":"绚丽的；灿烂的；华丽的","g":"[usually before noun]","ex":{"en":"exotic birds with feathers of gorgeous colours","cn":"长着绚丽羽毛的异国的鸟"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人愉快的；美丽动人的；引人入胜的","en":"If you say that something is gorgeous, you mean that it gives you a lot of pleasure or is very attractive.","ex":{"en":"...gorgeous mountain scenery","cn":"秀丽的山间景色"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"性感的；漂亮的","en":"If you describe someone as gorgeous, you mean that you find them very sexually attractive.","ex":{"en":"The cosmetics industry uses gorgeous women to sell its skincare products","cn":"化妆品行业常找一些性感美女来推销护肤产品。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"绚丽的；华丽的；灿烂的","en":"If you describe things such as clothes and colours as gorgeous, you mean they are bright, rich, and impressive.","ex":{"en":"...a red-haired man in the gorgeous uniform of a Marshal of the Empire.","cn":"身着华丽的帝国元帅服的红发男子"}}]},"examples":[{"en":"exotic birds with feathers of gorgeous colours","cn":"长着绚丽羽毛的异国的鸟"},{"en":"It was absolutely gorgeous.","cn":"那真是美丽绝伦。"}]},"ghosts":{"lemma":"ghost"},"guess":{"oxford":{"phon":"ɡes","pos":"verb","senses":[{"en":"to try and give an answer or make a judgement about something without being sure of all the facts","cn":"猜测；估计","g":"[intransitive, transitive]","lab":"British English or formal, North American English，，","ex":{"en":"I don't really know. I'm just guessing.","cn":"我并不知道，我只是猜测。"}},{"en":"to find the right answer to a question or the truth without knowing all the facts","cn":"猜对；猜中；猜到","g":"[transitive, intransitive]","ex":{"en":"She guessed the answer straight away.","cn":"她一下子就猜中了答案。"}},{"en":"used to show that you are going to say something surprising or exciting","cn":"（引出令人惊奇或激动的事）你猜","g":"[transitive]","ex":{"en":"Guess what! He's asked me out!","cn":"你猜怎么着！他约我出去了！"}},{"en":"to suppose that something is true or likely","cn":"我想；我以为","g":"[transitive, intransitive]","lab":"informal","ex":{"en":"I guess (that) you’ll be looking for a new job now.","cn":"我想你现在要找新工作了吧。"}},{"en":"an attempt to give an answer or an opinion when you cannot be certain if you are right","cn":"猜测；猜想","lab":"British English","ex":{"en":"to have/make a guess","cn":"（对某事）作猜测"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"猜；猜想；推测","en":"If you guess something, you give an answer or provide an opinion which may not be true because you do not have definite knowledge about the matter concerned.","ex":{"en":"The suit was faultless: Wood guessed that he was a very successful publisher or a banker","cn":"西装无可挑剔：伍德推测他可能是个相当成功的出版商或银行家。"}},{"pos":"VERB 动词","cn":"猜中；猜对","en":"If you guess that something is the case, you correctly form the opinion that it is the case, although you do not have definite knowledge about it.","ex":{"en":"By now you will have guessed that I'm back in Ireland","cn":"你现在应该已经猜出我回到了爱尔兰了。"}},{"pos":"N-COUNT 可数名词","cn":"猜测；猜想","en":"A guess is an attempt to give an answer or provide an opinion which may not be true because you do not have definite knowledge about the matter concerned.","ex":{"en":"My guess is that the chance that these vaccines will work is zero","cn":"我猜测这些疫苗根本不可能奏效。"}},{"pos":"PHRASE 短语","cn":"大家都拿不准的事","en":"If you say that something is anyone's guess or anybody's guess, you mean that no-one can be certain about what is really true.","ex":{"en":"Just when this will happen is anyone's guess","cn":"谁也说不准这事什么时候会发生。"}},{"pos":"PHRASE 短语","cn":"凭猜测","en":"You say at a guess to indicate that what you are saying is only an estimate or what you believe to be true, rather than being a definite fact.","ex":{"en":"At a guess he's been dead for two days.","cn":"据猜测，他已死了两天。"}},{"pos":"PHRASE 短语","cn":"我想；我认为","en":"You say I guess to show that you are slightly uncertain or reluctant about what you are saying.","ex":{"en":"I guess she thought that was pretty smart","cn":"我想她可能认为那个很漂亮。"}},{"pos":"PHRASE 短语","cn":"让（人）捉摸不定","en":"If someone keeps you guessing, they do not tell you what you want to know.","ex":{"en":"The author's intention is to keep everyone guessing until the bitter end","cn":"这位作家打算把悲惨结局的悬念一直保留到最后。"}},{"pos":"CONVENTION 惯用语","cn":"你猜怎么着；想不到吧","en":"You say guess what to draw attention to something exciting, surprising, or interesting that you are about to say.","ex":{"en":"Guess what, I just got my first part in a movie.","cn":"你猜怎么着，我刚刚得到了自己的第一个电影角色。"}}]},"media":{"uk":"media/uk/guess__gb_1.mp3","us":"media/us/guess__us_1.mp3"},"examples":[{"en":"You would never guess (that) she had problems. She's always so cheerful.","cn":"你怎么也猜不到她有难以解决的问题。她总是那么乐观。"},{"en":"They might be here by 3 — but that's just a rough guess (= not exact).","cn":"他们可能 3 点钟到，不过这只是一个大致的猜测。"}]},"gradually":{"media":{"uk":"media/uk/gradually__gb_1.mp3","us":"media/us/gradually__us_1.mp3"},"oxford":{"phon":"ˈɡrædʒuəli","pos":"adverb","senses":[{"en":"slowly, over a long period of time","cn":"逐渐地；逐步地；渐进地","ex":{"en":"to gradually increase/decrease","cn":"逐渐增加／减少"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"逐渐地；逐步地","en":"If something changes or is done gradually, it changes or is done in small stages over a long period of time, rather than suddenly.","ex":{"en":"Electricity lines to 30,000 homes were gradually being restored yesterday","cn":"昨天，3万户家庭逐渐恢复了供电。"}}]},"examples":[{"en":"Gradually, the children began to understand.","cn":"孩子们渐渐开始明白。"},{"en":"The weather gradually improved.","cn":"天气逐渐好转。"}]},"glorious":{"media":{"uk":"media/uk/glorious__gb_1.mp3","us":"media/us/glorious__us_1.mp3"},"oxford":{"phon":"ˈɡlɔːriəs","pos":"adjective","senses":[{"en":"deserving or bringing great success and making somebody/something famous","cn":"辉煌的；光荣的；荣耀的","lab":"formal","ex":{"en":"We congratulate you on this glorious victory.","cn":"我们祝贺你取得了这一辉煌的胜利。"}},{"en":"very beautiful and impressive","cn":"壮丽的；辉煌的；光辉灿烂的","ex":{"en":"We sat on the beach and gazed at the glorious sunset.","cn":"我们坐在海滩上，凝望着瑰丽的晚霞。"}},{"en":"hot, with the sun shining","cn":"热的；阳光灿烂的；晴朗的","ex":{"en":"They had three weeks of glorious sunshine.","cn":"他们度过了三周阳光灿烂的日子。"}},{"en":"extremely pleasant","cn":"极其令人愉快的；极为宜人的","ex":{"en":"a glorious trip to Rome","cn":"极为享受的罗马之行"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"宏伟的；壮丽的","en":"Something that is glorious is very beautiful and impressive.","ex":{"en":"...a glorious rainbow in the air","cn":"空中壮观的彩虹"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人愉快的；美好的","en":"If you describe something as glorious, you are emphasizing that it is wonderful and it makes you feel very happy.","ex":{"en":"The win revived glorious memories of his championship-winning days","cn":"这次胜利勾起了他对往昔那些夺冠岁月的美好回忆。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"辉煌的；光荣的；荣耀的","en":"A glorious career, victory, or occasion involves great fame or success.","ex":{"en":"Harrison had a glorious career spanning more than six decades","cn":"哈里森辉煌的职业生涯长达60多年。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（天气）晴好的，阳光灿烂的","en":"Glorious weather is hot and sunny.","ex":{"en":"I got dressed and emerged into glorious sunshine","cn":"我穿好衣服，走进灿烂的阳光中。"}}]},"examples":[{"en":"They had three weeks of glorious sunshine.","cn":"他们度过了三周阳光灿烂的日子。"},{"en":"a glorious chapter in our country's history","cn":"我国历史上光辉的一页"}]},"grinding":{"media":{"uk":"media/uk/grinding__gb_1.mp3","us":"media/us/grinding__us_1.mp3"},"oxford":{"phon":"ˈɡraɪndɪŋ","pos":"adjective","senses":[{"en":"that never ends or improves","cn":"没完没了的；无休止的；无改进的","ex":{"en":"grinding poverty","cn":"贫困不堪"}},{"en":"rough and unpleasant to listen to","cn":"刺耳的；难听的","ex":{"en":"I heard a loud grinding noise coming from the engine.","cn":"我听到发动机发出巨大的摩擦声。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"没完没了的；无休止的；毫无起色的","en":"If you describe a bad situation as grinding, you mean it never gets better, changes, or ends.","ex":{"en":"Their grandfather had left his village in order to escape the grinding poverty.","cn":"为了摆脱贫困的煎熬，他们的祖父离开了村子。"}},{"pos":"PHRASE 短语","cn":"突然停顿下来","en":"If you say that something comes to a grinding halt, you are emphasizing that it stops very suddenly, especially before it was meant to.","ex":{"en":"A car will come to a grinding halt if you put water in the petrol tank.","cn":"如果把水灌进油箱，汽车会猛然间停下来。"}}]},"examples":[{"en":"grinding poverty","cn":"贫困不堪"},{"en":"a country devastated by civil war and grinding poverty","cn":"一个被内战和极度贫困压垮的国家"}],"base":"grind"},"glance":{"media":{"uk":"media/uk/glance__gb_1.mp3","us":"media/us/glance__us_1.mp3"},"oxford":{"phon":"ɡlɑːns","pos":"verb","senses":[{"en":"to look quickly at something/somebody","cn":"瞥一眼；匆匆一看；扫视","g":"[intransitive]","ex":{"en":"She glanced at her watch.","cn":"她匆匆看了看表。"}},{"en":"to read something quickly and not carefully or completely","cn":"浏览；翻阅","g":"[intransitive]","ex":{"en":"I only had time to glance at my emails.","cn":"我只来得及粗略地看了一下电邮。"}},{"en":"a quick look","cn":"匆匆一看；一瞥；扫视","ex":{"en":"to take/have a glance at the newspaper headlines","cn":"匆匆看一眼报纸的大标题"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"瞥；迅速地看一眼","en":"If you glance at something or someone, you look at them very quickly and then look away again immediately.","ex":{"en":"He glanced at his watch","cn":"他匆匆看了一下手表。"}},{"pos":"VERB 动词","cn":"浏览","en":"If you glance through or at a newspaper, report, or book, you spend a short time looking at it without reading it very carefully.","ex":{"en":"I picked up the phone book and glanced through it","cn":"我拿起电话簿，匆匆扫了一遍。"}},{"pos":"N-COUNT 可数名词","cn":"一瞥；扫视","en":"A glance is a quick look at someone or something.","ex":{"en":"Trevor and I exchanged a glance.","cn":"特雷弗和我迅速交换了一下眼色。"}},{"pos":"PHRASE 短语","cn":"立刻；一眼就","en":"If you see something at a glance, you see or recognize it immediately, and without having to think or look carefully.","ex":{"en":"One could tell at a glance that she was a compassionate person.","cn":"一眼就能看出她很有同情心。"}},{"pos":"PHRASE 短语","cn":"乍一看；乍看上去","en":"If you say that something is true or seems to be true at first glance, you mean that it seems to be true when you first see it or think about it, but that your first impression may be wrong.","ex":{"en":"At first glance, organic farming looks much more expensive for the farmer.","cn":"乍一看，有机耕作对农民而言似乎花费大多了。"}},{"pos":"PHRASE 短语","cn":"偷偷地看一眼；偷瞥","en":"If you steal a glance at someone or something, you look at them quickly so that nobody sees you looking.","ex":{"en":"He stole a glance at the clock behind her.","cn":"他偷偷地看了一眼她背后的钟。"}},{"pos":"","cn":"","en":"相关词组：glance off"}]},"examples":[{"en":"I glanced up quickly to see who had come in.","cn":"我迅速抬头瞥了一眼看是谁进来了。"},{"en":"I only had time to glance at the newspapers.","cn":"我只来得及浏览了一下报纸。"}]},"get":{"media":{"uk":"media/uk/get__gb_1.mp3","us":"media/us/get__us_1.mp3"},"oxford":{"phon":"ɡet","pos":"verb","senses":[{"en":"to receive something","cn":"收到；接到","g":"[transitive, no passive]","sc":"receive/obtain","ex":{"en":"I got a call from Dave this morning.","cn":"今天早上我接到戴夫的电话。"}},{"en":"to obtain something","cn":"获得；得到","g":"[transitive, no passive]","sc":"receive/obtain","ex":{"en":"He has just got a new job.","cn":"他刚找到一份新工作。"}},{"en":"to buy something","cn":"买；购买；采购","g":"[transitive]","lab":"North American English","sc":"receive/obtain","ex":{"en":"Where did you get that skirt?","cn":"你在哪儿买的那条裙子？"}},{"en":"to obtain or receive an amount of money by selling something","cn":"（卖某物）挣得，获得","g":"[transitive, no passive]","sc":"receive/obtain","ex":{"en":"If you sell it at auction you can expect to get roughly £800.","cn":"如果你在拍卖会上出售它，预计可以得到大约 800 英镑。"}},{"en":"to go to a place and bring somebody/something back","cn":"去取；去带回","g":"[transitive]","sc":"bring","ex":{"en":"Quick—go and get a cloth!","cn":"快，去拿块布来！"}},{"en":"to achieve or be given a particular mark or grade in an exam","cn":"获得，得到（某考试成绩）","g":"[transitive, no passive]","sc":"mark/grade","ex":{"en":"He got a ‘C’ in Chemistry and a ‘B’ in English.","cn":"他化学得了 C，英语得了 B。"}},{"en":"to start to develop an illness; to suffer from a pain, etc.","cn":"感染上；患上；遭受…之苦","g":"[transitive, no passive]","sc":"illness","ex":{"en":"I got this cold off (= from) you!","cn":"我这感冒是被你传染的！"}},{"en":"to receive something as a punishment","cn":"受到；遭到；被判（刑）","g":"[transitive, no passive]","sc":"punishment","ex":{"en":"He got ten years (= was sent to prison for ten years) for armed robbery.","cn":"他因持枪抢劫被判刑十年。"}},{"en":"to connect to the internet or a phone network; to receive broadcasts from a particular television or radio station","cn":"接收到；收听到；收看到","g":"[transitive, no passive]","sc":"internet/phone/broadcasts","ex":{"en":"95 per cent of the UK can now get superfast broadband.","cn":"英国 95% 的地区现在可以接入超高速宽带。"}},{"en":"to be connected with somebody by phone","cn":"与（某人）电话联系；与（某人）通电话","g":"[transitive, no passive]","sc":"contact","ex":{"en":"I wanted to speak to the manager but I got his secretary instead.","cn":"我想与经理说话，可接电话的却是他的秘书。"}},{"en":"to arrive at or reach a place or point","cn":"抵达，到达（某地或某点）","g":"[intransitive]","sc":"arrive","ex":{"en":"We got to San Diego at 7 o'clock.","cn":"我们 7 点钟到达了圣迭戈。"}},{"en":"to move to or from a particular place or in a particular direction, sometimes with difficulty; to make somebody/something do this","cn":"（使）到达，离开，沿…移动，艰难地移动","g":"[intransitive, transitive]","sc":"move/travel","ex":{"en":"The bridge was destroyed so we couldn't get across the river.","cn":"大桥已经毁坏，我们无法过河了。"}},{"en":"to use a bus, taxi, plane, etc.","cn":"搭乘，乘坐（公共汽车、出租车、飞机等）","g":"[transitive, no passive]","sc":"move/travel","ex":{"en":"We're going to be late—let's get a taxi.","cn":"我们要迟到了，咱们坐出租车吧。"}},{"en":"to reach a particular state or condition; to make somebody/something/yourself reach a particular state or condition","cn":"（使）达到，处于","sc":"state/condition","ex":{"en":"to get angry/bored/hungry/fat","cn":"发怒；生厌；感到饿；发胖"}},{"en":"to reach the point at which you feel, know, are, etc. something","cn":"开始（感觉到、认识到、成为）；达到…地步（或程度）","g":"[intransitive]","sc":"state/condition","ex":{"en":"After a time you get to realize that these things don't matter.","cn":"过段时间你会明白这些事情并不要紧。"}},{"en":"to cause something to happen or be done","cn":"使（某事）发生；使完成（某事）","g":"[transitive]","sc":"get something done","ex":{"en":"I must get my hair cut.","cn":"我得理发了。"}},{"en":"to make, persuade, etc. somebody/something to do something","cn":"使，让（某人或物做某事）；说服（某人做某事）","g":"[transitive]","sc":"make/persuade","ex":{"en":"I couldn't get the car to start this morning.","cn":"我今天早上没法让这汽车发动起来。"}},{"en":"to start doing something","cn":"开始；开始做","g":"[transitive]","sc":"start","ex":{"en":"I got talking to her.","cn":"我开始与她谈起来。"}},{"en":"to have the opportunity to do something","cn":"有机会（做某事）；得到（做某事的）机会","g":"[intransitive]","lab":"informal","sc":"opportunity","ex":{"en":"He got to try out all the new software.","cn":"他得以试用了所有的新软件。"}},{"en":"to prepare a meal","cn":"准备，做（饭）","g":"[transitive]","lab":"especially British English","sc":"meal","ex":{"en":"Who's getting the lunch?","cn":"谁来做午饭？"}},{"en":"to answer the phone or a door when somebody calls, knocks, etc.","cn":"接（电话）；应（门）","g":"[transitive, no passive]","lab":"informal","sc":"telephone/door","ex":{"en":"Will you get the phone?","cn":"你去接一下电话好吗？"}},{"en":"to catch or take hold of somebody, especially in order to harm or punish them","cn":"（尤指为伤害或惩罚）抓住，捉住，逮住","g":"[transitive]","lab":"informal","sc":"catch/hit","ex":{"en":"He was on the run for a week before the police got him.","cn":"他逃跑一周后警方才将他逮住。"}},{"en":"to hit or wound somebody","cn":"击中；使受伤","g":"[transitive]","sc":"catch/hit","ex":{"en":"The bullet got him in the neck.","cn":"子弹击中了他的颈部。"}},{"en":"to understand somebody/something","cn":"理解；明白","g":"[transitive, no passive]","lab":"informal","sc":"understand","ex":{"en":"I don't get you.","cn":"我搞不懂你的意思。"}},{"en":"used to say that something happens or exists","cn":"（表示发生或存在）","g":"[transitive, no passive]","lab":"informal","sc":"happen/exist","ex":{"en":"You get (= There are) all these kids hanging around in the street.","cn":"所有这些孩子都在街上闲逛。"}},{"en":"to make somebody feel confused because they do not understand something","cn":"使困惑；使迷惑；把…难住","g":"[transitive, no passive]","lab":"informal","sc":"confuse/annoy","ex":{"en":"‘What's the capital of Bhutan?’ ‘You've got me there!’ (= I don't know)","cn":"“不丹的首都在什么地方？”“你可把我难倒了！”"}},{"en":"to annoy somebody","cn":"使烦恼；使恼火","g":"[transitive, no passive]","lab":"informal","sc":"confuse/annoy","ex":{"en":"What gets me is having to do the same thing all day long.","cn":"使我感到烦恼的是整天都得干同样的事。"}}]},"collins":{"senses":[{"pos":"V-LINK 连系动词","cn":"（与形容词连用）变得","en":"You use get with adjectives to mean 'become'. For example, if someone gets cold, they become cold, and if they get angry, they become angry.","ex":{"en":"The boys were getting bored","cn":"男孩子们开始感到厌烦。"}},{"pos":"V-LINK 连系动词","cn":"（用于表示状况或处境的表达中）陷入，处于","en":"Get is used with expressions referring to states or situations. For example, to get into trouble means to start being in trouble.","ex":{"en":"Half the pleasure of an evening out is getting ready","cn":"晚上外出时一半的乐趣在于出门前的准备。"}},{"pos":"VERB 动词","cn":"使陷入，使处于（某种状况或处境）","en":"To get someone or something into a particular state or situation means to cause them to be in it.","ex":{"en":"I don't know if I can get it clean","cn":"我不知道自己是否能把它清理干净。"}},{"pos":"VERB 动词","cn":"使…，让…（做）","en":"If you get someone to do something, you cause them to do it by asking, persuading, or telling them to do it.","ex":{"en":"...a long campaign to get US politicians to take the Aids epidemic more seriously","cn":"旨在使美国政界人士更加重视艾滋病流行的长期运动"}},{"pos":"VERB 动词","cn":"使做好；使完成","en":"If you get something done, you cause it to be done.","ex":{"en":"I might benefit from getting my teeth fixed","cn":"补牙可能对我有好处。"}},{"pos":"VERB 动词","cn":"来到，移动到（某处）","en":"To get somewhere means to move there.","ex":{"en":"I got off the bed and opened the door","cn":"我下床把门打开了。"}},{"pos":"VERB 动词","cn":"到达；抵达","en":"When you get to a place, you arrive there.","ex":{"en":"Generally I get to work at 9.30am","cn":"我通常上午9点半到单位。"}},{"pos":"VERB 动词","cn":"使移动到","en":"To get something or someone into a place or position means to cause them to move there.","ex":{"en":"Mack got his wallet out","cn":"麦克掏出钱包。"}},{"pos":"AUX 助动词","cn":"（常用作助动词，代替be构成被动语态）","en":"Get is often used in place of 'be' as an auxiliary verb to form passives.","ex":{"en":"Does she ever get asked for her autograph?","cn":"有人向她索要过签名吗？"}},{"pos":"VERB 动词","cn":"（最终或逐渐）到达（某阶段）","en":"If you get to do something, you eventually or gradually reach a stage at which you do it.","ex":{"en":"Miller and Ferlinghetti got to be friends","cn":"米勒和费林盖蒂渐渐成了朋友。"}},{"pos":"VERB 动词","cn":"得以做；有机会做","en":"If you get to do something, you manage to do it or have the opportunity to do it.","ex":{"en":"How do these people get to be the bosses of major companies?","cn":"这些人是怎样成为大公司的老总的？"}},{"pos":"VERB 动词","cn":"（让…）迅速行动起来/干起来/工作起来","en":"You can use get in expressions like get moving ,get going, and get working when you want to tell people to begin moving, going, or working quickly.","ex":{"en":"I aim to be off the lake before dawn, so let's get moving","cn":"我计划黎明前从湖畔出发，大家马上行动起来吧。"}},{"pos":"VERB 动词","cn":"到达（人生、事业的某一阶段）","en":"If you get to a particular stage in your life or in something you are doing, you reach that stage.","ex":{"en":"We haven't got to the stage of a full-scale military conflict","cn":"我们还未到全面军事冲突的地步。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（用于谈论进展情况）（使…）取得进展/不会有进展","en":"You can use get to talk about the progress that you are making. For example, if you say that you are getting somewhere, you mean that you are making progress, and if you say that something won't get you anywhere, you mean it will not help you to progress at all.","ex":{"en":"Radical factions say the talks are getting nowhere and they want to withdraw","cn":"激进派宣称谈判没有进展，他们打算退出。"}},{"pos":"V-LINK 连系动词","cn":"到，接近（…时间）","en":"When it gets to a particular time, it is that time. If it is getting towards a particular time, it is approaching that time.","ex":{"en":"It got to after 1am and I was exhausted","cn":"已是凌晨一点多了，我累得筋疲力尽。"}},{"pos":"VERB 动词","cn":"对…产生影响；使痛苦","en":"If something that has continued for some time gets to you, it starts causing you to suffer.","ex":{"en":"That's the first time I lost my cool in 20 years in this job. This whole thing's getting to me.","cn":"干这份工作20年来，我头一次失去了冷静，这一切让我大伤脑筋。"}},{"pos":"VERB 动词","cn":"使烦恼；使恼怒","en":"If something gets you, it annoys you.","ex":{"en":"What gets me is the attitude of so many of the people.","cn":"让我恼怒的是这么多人都是这样的态度。"}},{"pos":"VERB 动词","cn":"获得；得到","en":"If you get something that you want or need, you obtain it.","ex":{"en":"I got a job at the sawmill","cn":"我在锯木厂找了份工作。"}},{"pos":"VERB 动词","cn":"收到；得到","en":"If you get something, you receive it or are given it.","ex":{"en":"I'm getting a bike for my birthday","cn":"我过生日时会得到一辆自行车。"}},{"pos":"VERB 动词","cn":"去取；去带来","en":"If you get someone or something, you go and bring them to a particular place.","ex":{"en":"I came down this morning to get the newspaper","cn":"我今天上午过来取报纸。"}},{"pos":"VERB 动词","cn":"准备（饭菜）","en":"If you get a meal, you prepare it.","ex":{"en":"She was getting breakfast as usual.","cn":"她像往常一样在准备早餐。"}},{"pos":"VERB 动词","cn":"得出，计算出（结果）","en":"If you get a particular result, you obtain it from some action that you take, or from a calculation or experiment.","ex":{"en":"You could run that race again and get a different result each time","cn":"如果再参加一次那样的赛跑，每次的结果可能都不一样。"}},{"pos":"VERB 动词","cn":"卖得，售得（…钱）","en":"If you get a particular price for something that you sell, you obtain that amount of money by selling it.","ex":{"en":"He can't get a good price for his crops.","cn":"他的庄稼无法卖个好价钱。"}},{"pos":"VERB 动词","cn":"有（做…的时间或机会）","en":"If you get the time or opportunity to do something, you have the time or opportunity to do it.","ex":{"en":"You get time to think in prison","cn":"你在监狱里有时间反省。"}},{"pos":"VERB 动词","cn":"开始有（想法、印象或感受）","en":"If you get an idea, impression, or feeling, you begin to have that idea, impression, or feeling as you learn or understand more about something.","ex":{"en":"I get the feeling that you're an honest man","cn":"我开始觉得你是个诚实的人。"}},{"pos":"VERB 动词","cn":"得到，获得（感受或好处）","en":"If you get a feeling or benefit from an activity or experience, the activity or experience gives you that feeling or benefit.","ex":{"en":"Charles got a shock when he saw him","cn":"查尔斯见到他时大吃一惊。"}},{"pos":"VERB 动词","cn":"（设法）看到","en":"If you get a look, view, or glimpse of something, you manage to see it.","ex":{"en":"Young men climbed on buses and fences to get a better view","cn":"为了看得更清楚些，年轻人爬上了公共汽车和围墙。"}},{"pos":"VERB 动词","cn":"有（…的天气）","en":"If a place gets a particular type of weather, it has that type of weather.","ex":{"en":"Riyadh got 25 mm of rain in just 12 hours","cn":"利雅得在12小时内降水就达25毫米。"}},{"pos":"VERB 动词","cn":"理解，明白（笑话或所说的话）","en":"If you get a joke or get the point of something that is said, you understand it.","ex":{"en":"Did you get that joke, Ann? I'll explain later","cn":"安，听懂那个笑话了吗？我过会儿会解释。"}},{"pos":"VERB 动词","cn":"染（病）；患（病）","en":"If you get an illness or disease, you become ill with it.","ex":{"en":"When I was five I got measles.","cn":"我5岁时出过麻疹。"}},{"pos":"VERB 动词","cn":"搭乘，乘（火车、公共汽车、飞机或船）","en":"When you get a train, bus, plane, or boat, you leave a place on a particular train, bus, plane, or boat.","ex":{"en":"It'll be two pounds to get the bus","cn":"乘公共汽车要花两英镑。"}},{"pos":"VERB 动词","cn":"捕获；猎杀","en":"If you get a person or animal, you succeed in catching, killing, or hitting them.","ex":{"en":"Take it easy. We've got him. He's not going to kill anyone else.","cn":"别担心，我们已经抓住他了，他不会再杀人。"}},{"pos":"VERB 动词","cn":"定期买（报刊、杂志等）","en":"If you get a newspaper or magazine, you regularly buy it.","ex":{"en":"We don't get a paper","cn":"我们不买报纸。"}},{"pos":"VERB 动词","cn":"接收；收到；收看到","en":"If you can get a particular radio or television channel, you are able to receive broadcasts from it on your radio or television.","ex":{"en":"I only get Channel 7.","cn":"我只能收看到第7频道。"}},{"pos":"PHRASE 短语","cn":"最…；（好…) 极了","en":"You can say that something is, for example, as good as you can get to mean that it is as good as it is possible for that thing to be.","ex":{"en":"Consort has a population of 714 and is about as rural and isolated as you can get.","cn":"康索特有714名居民，是极其偏僻的乡村地区。"}},{"pos":"PHRASE 短语","cn":"不能否认；无法否认","en":"If you say you can't get away from something or there is no getting away from something, you are emphasizing that it is true, even though people might prefer it not to be true.","ex":{"en":"There is no getting away from the fact that he is on the left of the party.","cn":"他属于该党左派的事实无法否认。"}},{"pos":"PHRASE 短语","cn":"休假；度假","en":"If you get away from it all, you have a holiday in a place that is very different from where you normally live and work.","ex":{"en":"...the ravishing island of Ischia, where rich Italians get away from it all.","cn":"意大利富人消遣度假的美丽岛屿伊斯基亚"}},{"pos":"CONVENTION 惯用语","cn":"（表示蔑视、不同意或拒绝）滚开，去你的","en":"Get is used in rude expressions like get stuffed and get lost to express contempt, disagreement, or refusal to do something."},{"pos":"PHRASE 短语","cn":"你真是太走运了/你真是蠢得无可救药了","en":"You can say, for example, 'How lucky can you get?' or 'How stupid can you get? ' to show your surprise that anyone could be as lucky or stupid as the person that you are talking about.","ex":{"en":"I mean, how crazy can you get?","cn":"我是说，你真是太疯狂了。"}},{"pos":"PHRASE 短语","cn":"叫…不要指望；叫…别做梦","en":"If you tell someone where to get off, you tell them in a rather rude way that you are not going to do or agree to what they want.","ex":{"en":"If somebody tried to do that to you, you'd just go right up to them and tell them where to get off.","cn":"如果有人想那样对待你，你就直截了当地告诉他们别做梦了。"}},{"pos":"PHRASE 短语","cn":"有；存在","en":"You can use you get instead of 'there is' or 'there are' to say that something exists, happens, or can be experienced.","ex":{"en":"You get a lot of things like that now, don't you","cn":"你现在有很多那样的东西，是吧？"}},{"pos":"","cn":"","en":"相关词组：get about get across get ahead get along get around get around to get at get away get away with get back get back to get by get down get down to get in get in on get into get in with get off get off on get off with get on get on to get out get out of get over get over with get round get round to get through get together get up get up to"}]},"examples":[{"en":"You should get into the routine of saving the document you are working on every ten minutes.","cn":"你应该养成每十分钟将正在编辑的文件存盘一次的习惯。"},{"en":"Thousands of refugees will die if these supplies don't get through to them.","cn":"如果这些生活用品运不到，数以千计的难民就会死去。"}]},"governing":{"oxford":{"phon":"ˈɡʌvənɪŋ","pos":"adjective","senses":[{"en":"having the right and the authority to control something such as a country or an institution","cn":"统治的；控制的；管理的；治理的","ex":{"en":"The Conservatives were then the governing party.","cn":"那时是保守党当政。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"统治的；管理的；控制的","en":"A governing body or organization is one which controls a particular activity.","ex":{"en":"The league became the governing body for amateur fencing in the U.S.","cn":"该联合会成了美国业余击剑运动的管理机构。"}}]},"media":{"uk":"media/uk/governing__gb_1.mp3","us":"media/us/governing__us_1.mp3"},"examples":[{"en":"The school's governing body (= the group of people who control the organization of the school) took responsibility for the decision.","cn":"学校行政机构对这个决定负责。"},{"en":"The Conservatives were then the governing party.","cn":"那时是保守党当政。"}],"base":"govern"},"gt":{"oxford":{"phon":"","pos":"abbreviation","senses":[{"en":"(in names of places) Great","cn":"（用于地名）大","ex":{"en":"Gt Britain","cn":"大不列颠"}}]},"examples":[{"en":"Gt Britain","cn":"大不列颠"},{"en":"Gt Yarmouth","cn":"大雅茅斯"}]},"gullible":{"media":{"uk":"media/uk/gullible__gb_1.mp3","us":"media/us/gullible__us_1.mp3"},"oxford":{"phon":"ˈɡʌləbl","pos":"adjective","senses":[{"en":"too willing to believe or accept what other people tell you and therefore easily tricked","cn":"轻信的；易受骗的；易上当的","ex":{"en":"The advertisement is aimed at gullible young women worried about their weight.","cn":"这则广告针对的是担心发胖而易受骗的年轻女性。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"轻信的；易受骗的；易上当的","en":"If you describe someone as gullible, you mean they are easily tricked because they are too trusting.","ex":{"en":"What point is there in admitting that the stories fed to the gullible public were false?","cn":"承认向轻信媒体的公众提供了不实报道有何意义呢？"}}]},"examples":[{"en":"Plastic replicas of the Greek pottery are sold to gullible tourists.","cn":"仿古希腊陶器的塑料复制品被卖给易上当的游客。"}]},"gain":{"media":{"uk":"media/uk/gain__gb_1.mp3","us":"media/us/gain__us_1.mp3"},"oxford":{"phon":"ɡeɪn","pos":"verb","senses":[{"en":"to obtain or win something, especially something that you need or want","cn":"获得；赢得；博得；取得","g":"[transitive]","sc":"obtain/win","ex":{"en":"They managed to gain access to secret files.","cn":"他们设法访问秘密文件。"}},{"en":"to obtain an advantage or benefit from something or from doing something","cn":"（从…中）受益，获益；得到（好处）","g":"[transitive, intransitive]","sc":"obtain/win","ex":{"en":"The firm is hoping to gain an advantage over its competitors.","cn":"这家公司希望能够胜过竞争对手一筹。"}},{"en":"to gradually get more of something","cn":"增加；增添；增进；增长","g":"[transitive]","sc":"get more","ex":{"en":"As you gain experience, you will grow in confidence.","cn":"随着你逐渐积累经验，你将会变得更加自信。"}},{"en":"to go too fast (by a particular amount of time)","cn":"走得快（若干时间）","g":"[transitive, intransitive]","sc":"of watch/clock","ex":{"en":"My watch gains two minutes every 24 hours.","cn":"我的表每 24 小时快两分钟。"}},{"en":"to increase in value","cn":"增值；升值","g":"[transitive, intransitive]","sc":"of currencies/shares","ex":{"en":"The shares gained 14p to 262p.","cn":"股价上升了 14 便士，收报 262 便士。"}},{"en":"to reach a place, usually after a lot of effort","cn":"（经过努力）到达","g":"[transitive]","lab":"formal","sc":"reach place","ex":{"en":"At last she gained the shelter of the forest.","cn":"她终于到达了森林中的隐蔽处。"}},{"en":"an increase in the amount of something, especially in wealth or weight","cn":"（尤指财富、重量的）增值，增加","g":"[countable, uncountable]","sc":"increase","ex":{"en":"The opposition made unexpected gains in the last election.","cn":"反对党在最近的选举中取得了意外收获。"},"pos":"noun"},{"en":"an advantage or improvement","cn":"好处；利益；改进","g":"[countable]","sc":"advantage","ex":{"en":"Our loss is their gain.","cn":"我们之所失即他们之所得。"},"pos":"noun"},{"en":"financial profit","cn":"利润；经济收益","g":"[uncountable]","lab":"often disapproving","sc":"profit","ex":{"en":"He only seems to be interested in personal gain.","cn":"他似乎只在乎个人的收益。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"获得；博得；赢得","en":"If a person or place gains something such as an ability or quality, they gradually get more of it.","ex":{"en":"Students can gain valuable experience by working on the campus radio or magazine","cn":"学生们在校广播台或校刊工作能够获得宝贵的经验。"}},{"pos":"VERB 动词","cn":"（从…中）受益,获益,得到好处","en":"If you gain from something such as an event or situation, you get some advantage or benefit from it.","ex":{"en":"The company didn't disclose how much it expects to gain from the two deals","cn":"这家公司未透露这两笔交易的预期获利情况。"}},{"pos":"VERB 动词","cn":"增加（体重、速度等）","en":"To gain something such as weight or speed means to have an increase in that particular thing.","ex":{"en":"Some people do gain weight after they stop smoking","cn":"一些人戒烟后体重确实会增加。"}},{"pos":"VERB 动词","cn":"（尤指经努力）获得，取得","en":"If you gain something, you obtain it, especially after a lot of hard work or effort.","ex":{"en":"They realise that passing exams is no longer enough to gain a place at university","cn":"他们认识到现在仅仅是考试通过，并不能确保进入大学。"}},{"pos":"PHRASE 短语","cn":"为了获得利益；为了获得好处","en":"If you do something for gain, you do it in order to get some advantage or profit for yourself, and for no other reason.","ex":{"en":"...buying art solely for financial gain.","cn":"纯粹为了赚钱而购买艺术品"}},{"pos":"PHRASE 短语","cn":"（想法、理想等）越来越流行，逐渐为人接受","en":"If something such as an idea or an ideal gains ground, it gradually becomes more widely known or more popular.","ex":{"en":"There are strong signs that his views are gaining ground","cn":"各种明显的迹象显示他的观点越来越受欢迎。"}},{"pos":"PHRASE 短语","cn":"赢得时间；争取时间","en":"If you do something in order to gain time, you do it in order to give yourself enough time to think of an excuse or a way out of a difficult situation.","ex":{"en":"I hoped to gain time by keeping him talking.","cn":"我希望让他一直说下去以争取时间。"}},{"pos":"","cn":"","en":"相关词组：gain on"}]},"examples":[{"en":"The shares gained 14p to 262p.","cn":"股价上升了 14 便士，收报 262 便士。"},{"en":"a £3 000 gain from our investment","cn":"从我们的投资中获取的 3 000 英镑的收益"}]},"glue":{"oxford":{"phon":"ɡluː","pos":"noun","senses":[{"en":"a sticky substance that is used for joining things together","cn":"胶；胶水","lab":"figurative","ex":{"en":"All you will need is a sharp knife and a tube of glue.","cn":"你只需要一把锋利的刀和一管胶水。"}},{"en":"to join two things together using glue","cn":"（用胶水）黏合，粘牢，粘贴","ex":{"en":"She glued the label onto the box.","cn":"她把标签贴在箱子上。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"胶；胶水","en":"Glue is a sticky substance used for joining things together, often for repairing broken things.","ex":{"en":"...a tube of glue.","cn":"一管胶水"}},{"pos":"VERB 动词","cn":"用胶水粘","en":"If you glue one object to another, you stick them together using glue.","ex":{"en":"Glue the fabric around the window","cn":"用胶水把布料粘在窗户周围。"}},{"pos":"V-PASSIVE 被动动词","cn":"完全吸引；使专注于","en":"If you say that someone is glued to something, you mean that they are giving it all their attention.","ex":{"en":"They are all glued to the Olympic Games.","cn":"他们都被奥运会吸引住了。"}}]},"media":{"img":["media/pic/stationery_supplies_comp.jpg","media/thumb/gluestick.jpg"],"uk":"media/uk/glue__gb_1.mp3","us":"media/us/glue__us_1.mp3"},"examples":[{"en":"Glue the two pieces of cardboard together.","cn":"把这两张硬纸板粘在一起。"},{"en":"Her eyes were glued to the screen (= she did not stop watching it).","cn":"她目不转睛地盯着屏幕。"}]},"grid":{"oxford":{"phon":"ɡrɪd","pos":"noun","senses":[{"en":"a pattern of straight lines, usually crossing each other to form squares","cn":"网格；方格","ex":{"en":"New York’s grid of streets","cn":"纽约棋盘式的街道布局"}},{"en":"a frame of metal or wooden bars that are parallel or cross each other","cn":"（金属或木制的）格子，格栅，栅栏"},{"en":"a pattern of squares on a map that are marked with letters or numbers to help you find the exact position of a place","cn":"（地图上的）坐标方格","ex":{"en":"The grid reference is C8.","cn":"地图上的坐标方格数字为 C8。"}},{"en":"a system of electric wires or pipes carrying gas, for sending power over a large area","cn":"（输电线路、天然气管道的）系统网络；输电网；煤气输送网","lab":"especially British English","ex":{"en":"the national grid (= the electricity supply in a country)","cn":"国家输电网"}},{"en":"a pattern of lines marking the starting positions for the racing cars","cn":"赛车起跑线","ex":{"en":"The 20-year-old didn't get the best of starts off the grid.","cn":"这位20岁的选手在比赛中并没有取得最好的开局。"}},{"en":"a number of computers that are linked together using the internet so that they can share power, data, etc. in order to work on difficult problems","cn":"（利用互联网的）联网，联机","g":"[singular]","lab":"computing"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"网格；（地图上的）坐标方格","en":"A grid is something which is in a pattern of straight lines that cross over each other, forming squares. On maps the grid is used to help you find a particular thing or place.","ex":{"en":"...a grid of ironwork.","cn":"铁格栅"}},{"pos":"N-COUNT 可数名词","cn":"（输送电力等的）系统网络","en":"A grid is a network of wires and cables by which sources of power, such as electricity, are distributed throughout a country or area.","ex":{"en":"...breakdowns in communications and electric power grids.","cn":"通信系统与输电网的中断"}},{"pos":"N-COUNT 可数名词","cn":"赛车起跑线","en":"The grid or the starting grid is the starting line on a car-racing track.","ex":{"en":"The Ferrari of Alain Prost will be second on the grid.","cn":"阿兰·普罗斯特的法拉利赛车将排在起跑线的第二位。"}}]},"media":{"uk":"media/uk/grid__gb_1.mp3","us":"media/us/grid__us_1.mp3"},"examples":[{"en":"The mountain cabin is entirely off the grid.","cn":"这山中小屋完全不用水电等公共设施。"},{"en":"The grid reference is C8.","cn":"地图上的坐标方格数字为 C8。"}]},"g":{"media":{"uk":"media/uk/g__gb_1.mp3","us":"media/us/g__us_1.mp3"},"oxford":{"phon":"","pos":"abbreviation","senses":[{"en":"gram(s)","cn":"克","ex":{"en":"400g flour","cn":"400 克面粉"}},{"en":"gravity or a measurement of the force with which something moves faster through space because of gravity","cn":"重力；地球引力","ex":{"en":"Spacecraft which are re-entering the earth's atmosphere are affected by g forces.","cn":"重返大气层的航天器受到重力的作用。"},"pos":"symbol"},{"en":"the 7th letter of the English alphabet","cn":"英语字母表的第 7 个字母","ex":{"en":"‘Gold’ begins with (a) G/‘G’.","cn":"gold 一词以字母 g 开头。"},"pos":"noun"},{"en":"the fifth note in the scale of C major","cn":"G 音（C 大调的第 5 音或音符）","lab":"music","pos":"noun"},{"en":"general audiences (a label for a movie that is suitable for anyone, including children)","cn":"G 级，老少咸宜（影片分级用语，表示适合包括儿童在内的任何人观看）"},{"en":"giga-","cn":"吉（咖）；千兆","ex":{"en":"a download bandwidth of 1.5 Gbits per second","cn":"每秒 1.5 吉比特的下载带宽"}},{"en":"$1 000","cn":"1 000 美元","lab":"North American English, informal，，"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"英语字母表的第7个字母","en":"G is the seventh letter of the English alphabet."},{"pos":"N-VAR 可变名词","cn":"C大调音阶中的第五音；G音","en":"In music, G is the fifth note in the scale of C major."},{"pos":"N-COUNT 可数名词","cn":"重力；地球引力","en":"A G is a unit of measurement of the force resulting from acceleration. One G is equivalent to the force of the earth's gravitational pull."},{"pos":"N-COUNT 可数名词","cn":"一千英镑（或美元）","en":"A G is a thousand pounds or dollars."},{"pos":"","cn":"（用于首字母为 g 的一些单词的缩写，如gram，gallon 和German）","en":"G or g is used as an abbreviation for words beginning with g, such as 'gram', 'gallon', and 'German'.","ex":{"en":"Oranges contain only 35 calories per 100g.","cn":"每100克橙子仅含35卡的热量。"}}]},"examples":[{"en":"‘Gold’ begins with (a) G/‘G’. * gold","cn":"一词以字母 g 开头。"},{"en":"‘Gold’ begins with (a) G/‘G’.","cn":""}]},"grammar":{"media":{"uk":"media/uk/grammar__gb_1.mp3","us":"media/us/grammar__us_1.mp3"},"oxford":{"phon":"ˈɡræmə(r)","pos":"noun","senses":[{"en":"the rules in a language for changing the form of words and joining them into sentences","cn":"语法；文法","g":"[uncountable]","ex":{"en":"the basic rules of grammar","cn":"基本语法规则"}},{"en":"a person’s knowledge and use of a language","cn":"（人的）语言知识及运用能力","g":"[uncountable]","ex":{"en":"His grammar is appalling.","cn":"他运用语言的能力糟透了。"}},{"en":"a book containing a description of the rules of a language","cn":"语法书","g":"[countable]","ex":{"en":"a French grammar","cn":"法语语法书"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"语法;文法","en":"Grammar is the ways that words can be put together in order to make sentences.","ex":{"en":"He doesn't have mastery of the basic rules of grammar.","cn":"他还没有掌握基本的语法规则。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"文法；语言的运用","en":"Someone's grammar is the way in which they obey or do not obey the rules of grammar when they write or speak.","ex":{"en":"His vocabulary was sound and his grammar excellent.","cn":"他的词汇丰富，语法也很精通。"}},{"pos":"N-COUNT 可数名词","cn":"语法书","en":"A grammar is a book that describes the rules of a language.","ex":{"en":"...an advanced English grammar.","cn":"高阶英语语法书"}},{"pos":"N-VAR 可变名词","cn":"语法理论；语法学","en":"A particular grammar is a particular theory that is intended to explain the rules of a language.","ex":{"en":"Transformational grammars are more restrictive.","cn":"转换生成语法局限性更大。"}}]},"examples":[{"en":"His grammar is appalling.","cn":"他运用语言的能力糟透了。"},{"en":"bad grammar","cn":"极差的语言运用能力"}]},"galleries":{"lemma":"gallery"},"gesture":{"media":{"uk":"media/uk/gesture__gb_1.mp3","us":"media/us/gesture__us_1.mp3"},"oxford":{"phon":"ˈdʒestʃə(r)","pos":"noun","senses":[{"en":"a movement that you make with your hands, your head or your face to show a particular meaning","cn":"手势；姿势；示意动作","g":"[countable, uncountable]","ex":{"en":"He made a rude gesture at the driver of the other car.","cn":"他向另外那辆汽车的司机做了个粗野的手势。"}},{"en":"something that you do or say to show a particular feeling or intention","cn":"（表明感情或意图的）姿态，表示","g":"[countable]","ex":{"en":"They sent some flowers as a gesture of sympathy to the parents of the child.","cn":"他们送了一些花表示对孩子父母的同情。"}},{"en":"to move your hands, head, face, etc. as a way of expressing what you mean or want","cn":"做手势；用手势表示；用动作示意","ex":{"en":"‘I see you read a lot,’ he said, gesturing at the wall of books.","cn":"“看来你读的书很多。”他指着那一墙的书说道。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"手势；姿势；示意动作","en":"A gesture is a movement that you make with a part of your body, especially your hands, to express emotion or information.","ex":{"en":"Sarah made a menacing gesture with her fist","cn":"萨拉用拳头做了一个威胁性的动作。"}},{"pos":"N-COUNT 可数名词","cn":"（表明态度或意图的）姿态，表示","en":"A gesture is something that you say or do in order to express your attitude or intentions, often something that you know will not have much effect.","ex":{"en":"He questioned the government's commitment to peace and called on it to make a gesture of good will","cn":"他对政府致力和平的承诺提出质疑，并呼吁政府做出友好的表示。"}},{"pos":"VERB 动词","cn":"打手势；用手势表示；用动作示意","en":"If you gesture, you use movements of your hands or head in order to tell someone something or draw their attention to something.","ex":{"en":"I gestured towards the boathouse, and he looked inside","cn":"我朝船库方向示意，他便往里面瞧了瞧。"}}]},"examples":[{"en":"We do not accept responsibility but we will refund the money as a gesture of goodwill.","cn":"我们不承担责任，不过我们愿意退款以表示我们的善意。"},{"en":"He made a rude gesture at the driver of the other car.","cn":"他向另外那辆汽车的司机做了个粗野的手势。"}]},"gb":{"oxford":{"phon":"","pos":"abbreviation","senses":[{"en":"gigabit","cn":"吉比特，千兆比特（计算机内存或数据单位）"},{"en":"Great Britain","cn":"大不列颠"},{"en":"gigabyte","cn":"吉字节，千兆字节（计算机内存或数据单位）","ex":{"en":"a 750GB hard drive","cn":"750 千兆字节的硬盘"}}]},"media":{"uk":"media/uk/gb__gb_1.mp3","us":"media/us/gb__us_1.mp3"},"examples":[{"en":"a 750GB hard drive * 750","cn":"千兆字节的硬盘"},{"en":"a 750GB hard drive","cn":""}],"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"","en":"GB is an abbreviation for (缩略=) Great Britain."}]}},"generalization":{"media":{"uk":"media/uk/generalization__gb_1.mp3","us":"media/us/generalization__us_1.mp3"},"oxford":{"phon":"ˌdʒenrəlaɪˈzeɪʃn","pos":"noun","senses":[{"en":"a general statement that is based on only a few facts or examples; the act of making such statements","cn":"概括；归纳；泛论","ex":{"en":"a speech full of broad/sweeping generalizations","cn":"通篇大而无当的发言"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"概括；概论；归纳","en":"A generalization is a statement that seems to be true in most situations or for most people, but that may not be completely true in all cases.","ex":{"en":"He is making sweeping generalisations to get his point across","cn":"为了让大家领会他的观点，他正在作全面的概括。"}}]},"examples":[{"en":"a speech full of broad/sweeping generalizations","cn":"满是概而论之话语的发言"},{"en":"Try to avoid generalization.","cn":"尽量避免泛泛而论。"}]},"graded":{"oxford":{"phon":"ˈɡreɪdɪd","pos":"adjective","senses":[{"en":"arranged in order or in groups according to difficulty, size, etc.","cn":"（按难度、大小等）分级的","ex":{"en":"graded tests for language students","cn":"语言学习者的分级测验"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（动词或副词）有程度之分的，分级的","en":"In this dictionary, a graded adjective or adverb is one which is sometimes used with an adverb or phrase indicating degree. 'Clever' is an example of a graded adjective."}]},"media":{"uk":"media/uk/graded__gb_1.mp3","us":"media/us/graded__us_1.mp3"},"examples":[{"en":"graded tests for language students","cn":"语言学习者的分级测验"},{"en":"graded doses of a drug","cn":"药物的分级剂量"}],"base":"grade"},"garden":{"media":{"img":["media/pic/garden_labels_comp.jpg","media/thumb/garden.jpg"],"uk":"media/uk/garden__gb_1.mp3","us":"media/us/garden__us_1.mp3"},"oxford":{"phon":"ˈɡɑːdn","pos":"noun","senses":[{"en":"a piece of land next to or around your house where you can grow flowers, fruit, vegetables, etc., usually with a lawn (= an area of grass)","cn":"（住宅旁或周围的）园圃，花园，果园，菜园","g":"[countable]","lab":"British English","ex":{"en":"a front/back/rear garden","cn":"前／后花园"}},{"en":"an area in a yard where you grow flowers or plants","cn":"庭园；园子","g":"[countable]","lab":"North American English","ex":{"en":"These flowers brighten up backyard gardens all over the country.","cn":"这些花为全国各地的后花园增色不少。"}},{"en":"a public park","cn":"公园","g":"[countable]","ex":{"en":"Thousands of people now visit the gardens every year.","cn":"现在每年都有成千上万人来公园游览。"}},{"en":"used in the name of streets","cn":"（用于街名）园，街，广场","g":"[singular]","lab":"British English","ex":{"en":"39 Belvoir Gardens","cn":"贝尔沃街 39 号"}},{"en":"to work in a garden","cn":"做园艺工作；种植花木","ex":{"en":"More people are choosing to garden organically.","cn":"越来越多的人选择有机园艺。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（住宅旁的）花园，菜园，庭园，园子（美国英语中表示此义时常用yard，而garden仅用来指花园和菜园）","en":"In British English, a garden is a piece of land next to a house, with flowers, vegetables, other plants, and often grass. In American English, the usual word is yard, and a garden refers only to land which is used for growing flowers and vegetables.","ex":{"en":"...the most beautiful garden on Earth.","cn":"世界上最漂亮的花园"}},{"pos":"VERB 动词","cn":"干园艺活；种植花木","en":"If you garden, you do work in your garden such as weeding or planting.","ex":{"en":"Jim gardened at the homes of friends on weekends.","cn":"吉姆周末帮忙打理朋友家的花园。"}},{"pos":"N-PLURAL 复数名词","cn":"公园","en":"Gardens are places like a park that have areas of plants, trees, and grass, and that people can visit and walk around.","ex":{"en":"The Gardens are open from 10.30am until 5pm.","cn":"公园从上午10点半到下午5点之间开放。"}},{"pos":"N-IN-NAMES 名称名词","cn":"（用于街名）园，街，广场","en":"Gardens is sometimes used as part of the name of a street.","ex":{"en":"He lives at 9, Acacia Gardens.","cn":"他住在金合欢街9号。"}}]},"examples":[{"en":"We employ a gardener two days a week.","cn":"我们雇了个花匠，每周工作两天。"},{"en":"My wife's a keen gardener.","cn":"我的妻子是个热衷园艺的人。"}]},"glow":{"oxford":{"phon":"ɡləʊ","pos":"verb","senses":[{"en":"to produce a steady light that is not very bright","cn":"发微光；发出暗淡的光","g":"[intransitive]","ex":{"en":"The embers still glowed in the hearth.","cn":"余烬仍在炉膛里发出暗淡的光。"}},{"en":"to look or feel warm or pink, especially after exercise or because you are excited, embarrassed, etc.","cn":"（尤指运动后或因情绪激动、尴尬等而）发红，发热，显得红，感觉热","g":"[intransitive]","ex":{"en":"Her cheeks were glowing.","cn":"她双颊绯红。"}},{"en":"to look very pleased or satisfied","cn":"喜形于色；心满意足","g":"[intransitive]","ex":{"en":"She was positively glowing with pride.","cn":"她一副踌躇满志的样子。"}},{"en":"to appear a strong, warm colour","cn":"色彩鲜艳；绚丽夺目","g":"[intransitive]","ex":{"en":"The countryside glowed with autumn colours.","cn":"乡村里秋色绚烂。"}},{"en":"a steady light that is not too bright, like the light from a fire that has stopped producing flames","cn":"微弱稳定的光；暗淡的光","ex":{"en":"The city was just a red glow on the horizon.","cn":"城市看上去只是地平线上的一片红光。"},"pos":"noun"},{"en":"the pink colour in your face when you have been doing exercise or feel happy and excited","cn":"（运动、高兴或激动时）满面红光，容光焕发，满脸通红","ex":{"en":"The fresh air had brought a healthy glow to her cheeks.","cn":"新鲜空气使她两颊红润，精神焕发。"},"pos":"noun"},{"en":"a gold or red colour","cn":"金色；红色","ex":{"en":"the glow of autumn leaves","cn":"秋叶红似火"},"pos":"noun"},{"en":"a feeling of pleasure","cn":"喜悦；愉快","ex":{"en":"When she looked at her children, she felt a glow of pride.","cn":"看见自己的孩子，她就感到由衷的自豪。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"微弱稳定的光；暗淡的光","en":"A glow is a dull, steady light, for example the light produced by a fire when there are no flames.","ex":{"en":"...the cigarette's red glow","cn":"香烟发出的红光"}},{"pos":"N-SING 单数名词","cn":"（脸上的）红光，红晕，红润","en":"A glow is a pink colour on a person's face, usually because they are healthy or have been exercising.","ex":{"en":"The moisturiser gave my face a healthy glow that lasted all day.","cn":"涂了润肤霜，我的脸一整天都红润亮泽。"}},{"pos":"N-SING 单数名词","cn":"一股，满腔（满足感等）","en":"If you feel a glow of satisfaction or achievement, you have a strong feeling of pleasure because of something that you have done or that has happened.","ex":{"en":"Exercise will give you a glow of satisfaction at having achieved something","cn":"运动将让你体会到一种有所成就的无比喜悦感。"}},{"pos":"VERB 动词","cn":"发微弱而稳定的光；发暗淡的光","en":"If something glows, it produces a dull, steady light.","ex":{"en":"The night lantern glowed softly in the darkness","cn":"晚上点亮的灯笼在黑暗中发出柔和的光。"}},{"pos":"VERB 动词","cn":"色彩鲜艳；绚丽夺目；洋溢着（某种特征）","en":"If a place glows with a colour or a quality, it is bright, attractive, and colourful.","ex":{"en":"Used together these colours will make your interiors glow with warmth and vitality.","cn":"这些颜色搭配使用会使你屋子里暖意融融，充满生机。"}},{"pos":"VERB 动词","cn":"发光；泛光","en":"If something glows, it looks bright because it is reflecting light.","ex":{"en":"The instruments glowed in the bright orange light","cn":"明亮的橙色灯光下，这些乐器闪闪发光。"}},{"pos":"VERB 动词","cn":"（皮肤由于健康、激动或运动）发红，泛红晕，容光焕发","en":"If someone's skin glows, it looks pink because they are healthy or excited, or have been doing physical exercise.","ex":{"en":"Her freckled skin glowed with health again.","cn":"她长有雀斑的皮肤又泛出了健康的红光。"}},{"pos":"VERB 动词","cn":"洋溢着，散发出（某种情感）","en":"If someone glows with an emotion such as pride or pleasure, the expression on their face shows how they feel.","ex":{"en":"The expectant mothers that Amy had encountered positively glowed with pride.","cn":"埃米遇见的准妈妈们个个洋溢着自豪和喜悦。"}}]},"media":{"uk":"media/uk/glow__gb_1.mp3","us":"media/us/glow__us_1.mp3"},"examples":[{"en":"There was no light except for the occasional glow of a cigarette.","cn":"除偶尔有香烟的微弱红光外没有一点亮光。"},{"en":"The strap has a fluorescent coating that glows in the dark.","cn":"皮带面上有一层荧光在黑暗中微微发光。"}]},"gigantic":{"media":{"uk":"media/uk/gigantic__gb_1.mp3","us":"media/us/gigantic__us_1.mp3"},"oxford":{"phon":"dʒaɪˈɡæntɪk","pos":"adjective","senses":[{"en":"extremely large","cn":"极大的；庞大的","ex":{"en":"a gigantic house","cn":"一座巨大的房子"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"巨大的；庞大的","en":"If you describe something as gigantic, you are emphasizing that it is extremely large in size, amount, or degree.","ex":{"en":"...gigantic rocks","cn":"巨石"}}]},"examples":[{"en":"a gigantic skyscraper","cn":"摩天大楼"}]},"gauge":{"media":{"uk":"media/uk/gauge__gb_1.mp3","us":"media/us/gauge__us_1.mp3","img":["media/ldoce/img/gauge.jpg"]},"oxford":{"phon":"ɡeɪdʒ","pos":"noun","senses":[{"en":"an instrument for measuring the amount or level of something","cn":"测量仪器（或仪表）；计量器","ex":{"en":"a fuel/pressure/temperature gauge","cn":"燃油表；压力表；温度计"}},{"en":"a measurement of how wide or thick something is","cn":"宽度；厚度","ex":{"en":"What gauge of wire do we need?","cn":"我们需要多大直径的金属丝？"}},{"en":"a measurement of how wide the barrel of a gun is","cn":"（枪管的）口径","lab":"especially in British English","ex":{"en":"a 12-gauge shotgun","cn":"12 号猎枪"}},{"en":"the distance between the rails of a railway track or the wheels of a train","cn":"（铁道的）轨距；（火车的）轮距","ex":{"en":"standard gauge (= 56½ inches in Britain)","cn":"标准轨距（等于英制的 56.5 英寸）"}},{"en":"a fact or an event that can be used to estimate or judge something","cn":"（用于估计或判断的）事实，依据，尺度，标准","g":"[usually singular]","ex":{"en":"Tomorrow's game against Arsenal will be a good gauge of their promotion chances.","cn":"明天与阿森纳队的比赛是衡量他们能否晋级的很好依据。"}},{"en":"to make a judgement about something, especially people’s feelings or attitudes","cn":"判定，判断（尤指人的感情或态度）","ex":{"en":"They interviewed employees to gauge their reaction to the changes.","cn":"他们与雇员面谈以判定他们的应变能力。"},"pos":"verb"},{"en":"to measure something accurately using a special instrument","cn":"（用仪器）测量","ex":{"en":"precision instruments that can gauge the diameter to a fraction of a millimetre","cn":"可测出直径为若干分之一毫米的精密仪器"},"pos":"verb"},{"en":"to calculate something approximately","cn":"估计；估算","ex":{"en":"We were able to gauge the strength of the wind from the movement of the trees.","cn":"我们可根据树的摇动估算出风力。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（常指用某种仪器）测量，测定，算出","en":"If you gauge the speed or strength of something, or if you gauge an amount, you measure or calculate it, often by using a device of some kind.","ex":{"en":"He gauged the wind at over thirty knots","cn":"他测出风速在30节以上。"}},{"pos":"N-COUNT 可数名词","cn":"测量仪器；计量仪","en":"A gauge is a device that measures the amount or quantity of something and shows the amount measured.","ex":{"en":"...temperature gauges.","cn":"温度计"}},{"pos":"VERB 动词","cn":"判断，判定（人的行动、情感或意图）","en":"If you gauge people's actions, feelings, or intentions in a particular situation, you carefully consider and judge them.","ex":{"en":"...as he gauged possible enemy moves and his own responses","cn":"他在盘算着敌人可能的动向和自己的对策时"}},{"pos":"N-SING 单数名词","cn":"（评价或判断的）事实，依据，标准","en":"A gauge of someone's feelings or a situation is a fact or event that can be used to judge them.","ex":{"en":"The index is the government's chief gauge of future economic activity.","cn":"这一指数是政府判断未来经济活动的主要依据。"}},{"pos":"N-COUNT 可数名词","cn":"（铁道的）轨距","en":"A gauge is the distance between the two rails on a railway line.","ex":{"en":"...a narrow gauge railway.","cn":"窄轨铁路"}},{"pos":"N-COUNT 可数名词","cn":"（金属等的）厚度；（金属丝等的）直径","en":"A gauge is the thickness of something, especially metal or wire."}]},"examples":[{"en":"Tomorrow's game against Arsenal will be a good gauge of their promotion chances.","cn":"明天与阿森纳队的比赛是衡量他们能否升级的很好依据。"},{"en":"standard gauge (= 56½ inches in Britain)","cn":"标准轨距（在英国为 56.5 英寸）"}]},"geology":{"oxford":{"phon":"dʒiˈɒlədʒi","pos":"noun","senses":[{"en":"the scientific study of the physical structure of the earth, including the origin and history of the rocks and soil of which the earth is made","cn":"地质学","g":"[uncountable]"},{"en":"the origin and history of the rocks and soil of a particular area","cn":"（某地区的）地质","g":"[singular]","ex":{"en":"the geology of the British Isles","cn":"不列颠群岛的地质"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"地质学","en":"Geology is the study of the Earth's structure, surface, and origins.","ex":{"en":"He was visiting professor of geology at the University of Jordan.","cn":"他是约旦大学的地质学客座教授。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"地质状况","en":"The geology of an area is the structure of its land, together with the types of rocks and minerals that exist within it.","ex":{"en":"...an expert on the geology of southeast Asia.","cn":"研究东南亚地质状况的专家"}}]},"media":{"uk":"media/uk/geology__gb_1.mp3","us":"media/us/geology__us_1.mp3"},"examples":[{"en":"the geology of the British Isles","cn":"不列颠群岛的地质"},{"en":"a geological survey","cn":"地质勘察"}]},"gravely":{"oxford":{"phon":"ˈɡreɪvli","pos":"adverb","senses":[{"en":"in a very serious and important way; in a way that gives you a reason to feel worried","cn":"严重的；重大的；严峻的；深切的","ex":{"en":"She is gravely ill.","cn":"她病得很重。"}},{"en":"in a way that is serious in manner, as if something sad or important has just happened","cn":"严肃的；庄严的；表情沉重的","ex":{"en":"He nodded gravely as I poured out my troubles.","cn":"我倾诉烦恼时，他神情肃穆地不断点头。"}}]},"media":{"uk":"media/uk/gravely__gb_1.mp3","us":"media/us/gravely__us_1.mp3"},"examples":[{"en":"He nodded gravely as I poured out my troubles.","cn":"我倾诉我的苦恼时他心情沉重地点了点头。"},{"en":"Local people are gravely concerned.","cn":"当地人都深感不安。"}]},"glimpse":{"media":{"uk":"media/uk/glimpse__gb_1.mp3","us":"media/us/glimpse__us_1.mp3"},"oxford":{"phon":"ɡlɪmps","pos":"noun","senses":[{"en":"a sight of somebody/something for a very short time, when you do not see the person or thing completely","cn":"一瞥；一看","ex":{"en":"He caught a glimpse of her in the crowd.","cn":"他一眼瞥见她在人群里。"}},{"en":"a short experience of something that helps you to understand it","cn":"短暂的感受（或体验、领会）","ex":{"en":"The programme gives us a rare glimpse of a great artist at work.","cn":"这个节目使我们难得地认识到伟大艺术家工作时的情况。"}},{"en":"to see somebody/something for a moment, but not very clearly","cn":"瞥见；看一眼","ex":{"en":"He'd glimpsed her through the window as he passed.","cn":"他路过时透过窗户瞥见了她。"},"pos":"verb"},{"en":"to start to understand something","cn":"开始领悟；开始认识到","ex":{"en":"Suddenly she glimpsed the truth about her sister.","cn":"她突然开始了解到她姐姐的真实情况。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一瞥；扫视","en":"If you get a glimpse of someone or something, you see them very briefly and not very well.","ex":{"en":"Some of the fans had waited 24 hours outside the Hyde Park Hotel to catch a glimpse of their heroine.","cn":"为了一睹女主角的风采，一些追星族已经在海德公园饭店外守候了24个小时。"}},{"pos":"VERB 动词","cn":"瞥见","en":"If you glimpse someone or something, you see them very briefly and not very well.","ex":{"en":"She glimpsed a group of people standing on the bank of a river.","cn":"她瞥见一群人站在河岸边。"}},{"pos":"N-COUNT 可数名词","cn":"短暂的感受；初步的认识","en":"A glimpse of something is a brief experience of it or an idea about it that helps you understand or appreciate it better.","ex":{"en":"As university campuses become increasingly multi-ethnic, they offer a glimpse of the conflicts society will face tomorrow.","cn":"大学校园变得日益多种族化，通过校园可以对未来社会将要面对的诸多冲突有一个初步的认识。"}}]},"examples":[{"en":"The programme gives us a rare glimpse of a great artist at work.","cn":"这个节目使我们难得地认识到伟大艺术家工作时的情况。"},{"en":"a fascinating glimpse into life in the ocean","cn":"对海洋生物的一次短暂而动人心魄的感受"}]},"general":{"media":{"uk":"media/uk/general__gb_1.mp3","us":"media/us/general__us_1.mp3"},"oxford":{"phon":"ˈdʒenrəl","pos":"adjective","senses":[{"en":"affecting all or most people, places or things","cn":"全体的；普遍的；总的","sc":"affecting all","ex":{"en":"books of general interest (= of interest to most people)","cn":"普遍感兴趣的书籍"}},{"en":"normal; usual","cn":"正常的；一般的；常规的","g":"[usually before noun]","sc":"usual","ex":{"en":"There is one exception to this general principle.","cn":"这个一般性原则有一例外。"}},{"en":"including the most important aspects of something; not exact or detailed","cn":"概括性的；大体的；笼统的","sc":"not exact","ex":{"en":"I check the bookings to get a general idea of what activities to plan.","cn":"我核查预订情况以便对计划安排些什么活动有个大体的想法。"}},{"en":"approximately, but not exactly, the direction/area mentioned","cn":"大致的，大概的（方向或地区）","sc":"not exact","ex":{"en":"They fired in the general direction of the enemy.","cn":"他们向敌军大致的方向开了枪。"}},{"en":"not limited to a particular subject, use or activity","cn":"非专门的；一般性的；普通的","sc":"not limited","ex":{"en":"a general hospital","cn":"综合医院"}},{"en":"not limited to one part or aspect of a person or thing","cn":"整体的；全身的；全面的","sc":"not limited","ex":{"en":"a general anaesthetic","cn":"全身麻醉"}},{"en":"highest in rank; chief","cn":"首席的；总管的","g":"[only before noun]","sc":"highest in rank","ex":{"en":"the general manager","cn":"总经理"}},{"en":"an officer of very high rank in the army or (in the US) the air force; the officer with the highest rank in the marines","cn":"将军；（陆军、海军陆战队或美国空军）上将","ex":{"en":"a four-star general","cn":"四星上将"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT; N-TITLE; N-VOC可数名词；头衔名词；称呼名词","cn":"将军；（通常指陆军）上将","en":"A general is a high-ranking officer in the armed forces, usually in the army.","ex":{"en":"The General's visit to Sarajevo is part of preparations for the deployment of extra troops.","cn":"将军造访萨拉热窝是在为增加兵力部署做准备。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"全体的；总的；普遍的","en":"If you talk about the general situation somewhere or talk about something in general terms, you are describing the situation as a whole rather than considering its details or exceptions.","ex":{"en":"The figures represent a general decline in employment.","cn":"这些数字显示就业人数总体在下降。"}},{"pos":"ADJ 形容词","cn":"一般性的；普通的","en":"You use general to describe several items or activities when there are too many of them or when they are not important enough to mention separately.","ex":{"en":"£2,500 for software is soon swallowed up in general costs","cn":"用于软件方面的2,500英镑很快就被一般性费用耗光了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"广泛的；普遍的","en":"You use general to describe something that involves or affects most people, or most people in a particular group.","ex":{"en":"The project should raise general awareness about bullying.","cn":"这个项目将会提高民众对恃强凌弱行径的认识。"}},{"pos":"ADJ 形容词","cn":"整体的；全面的","en":"If you describe something as general, you mean that it is not restricted to any one thing or area.","ex":{"en":"...a general ache radiating from the back of the neck.","cn":"从后颈部扩散到全身的疼痛"}},{"pos":"ADJ 形容词","cn":"（企业）综合的，业务广泛的","en":"A general business offers a variety of services or goods rather than just one particular kind.","ex":{"en":"They ran the general store and the farm dairy.","cn":"他们经营着杂货店和农场的乳品店。"}},{"pos":"ADJ 形容词","cn":"（常用于头衔中）首席的，总管的，级别最高的","en":"General is used to describe a person's job, usually as part of their title, to indicate that they have complete responsibility for the administration of an organization or business.","ex":{"en":"He joined Sanders Roe, moving on later to become General Manager.","cn":"他加入了桑德斯·罗公司，后来一路晋升至总经理。"}},{"pos":"ADJ 形容词","cn":"（员工）普通的，非专业的，一般的","en":"General workers do a variety of jobs which require no special skill or training.","ex":{"en":"The farm employed a tractor driver and two general labourers.","cn":"农场雇用了一名拖拉机手和两名杂工。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（对某方面的知识或兴趣）一般的，泛泛的","en":"General is used to describe a person who has an average amount of knowledge or interest in a particular subject.","ex":{"en":"This book is intended for the general reader rather than the student.","cn":"这本书面向一般读者而非学生。"}},{"pos":"PHRASE 短语","cn":"总的来说；总体上来看；大体上","en":"You use in general to indicate that you are talking about something as a whole, rather than about part of it.","ex":{"en":"I think we need to improve our educational system in general","cn":"我认为有必要从整体上改进我们的教育体系。"}},{"pos":"PHRASE 短语","cn":"（指某一群体的大多数）总的来说，总体上","en":"You say in general to indicate that you are referring to most people or things in a particular group.","ex":{"en":"People in general will support us","cn":"总体而言，人们会支持我们的。"}},{"pos":"PHRASE 短语","cn":"通常；在多数情况下","en":"You say in general to indicate that a statement is true in most cases.","ex":{"en":"In general, it was the better-educated voters who voted Yes in the referendum.","cn":"通常是那些受教育程度较高的人在全民公决中投赞成票。"}}]},"examples":[{"en":"This is a crucial year for your relationships in general and your love life in particular.","cn":"这一年总体上对你们的关系，特别是你们的爱情生活是非常关键的。"},{"en":"I check the bookings to get a general idea of what activities to plan.","cn":"我核查预订情况以便对计划安排些什么活动有个大体的想法。"}]},"granting":{"lemma":"grant"},"got":{"lemma":"get","media":{"uk":"media/uk/got__gb_1.mp3","us":"media/us/got__us_1.mp3"}},"gladly":{"media":{"uk":"media/uk/gladly__gb_1.mp3","us":"media/us/gladly__us_1.mp3"},"oxford":{"phon":"ˈɡlædli","pos":"adverb","senses":[{"en":"willingly","cn":"乐意地；情愿地","ex":{"en":"I would gladly pay extra for a good seat.","cn":"我很愿意额外付费坐好座位。"}},{"en":"happily; with thanks","cn":"高兴地；欣然地；感激地","ex":{"en":"When I offered her my seat, she accepted it gladly.","cn":"我把座位让给她时，她欣然接受了。"}}]},"examples":[{"en":"When I offered her my seat, she accepted it gladly.","cn":"我把座位让给她时，她欣然接受了。"},{"en":"I would gladly pay extra for a good seat.","cn":"我情愿额外付费坐好座位。"}]},"grain":{"media":{"uk":"media/uk/grain__gb_1.mp3","us":"media/us/grain__us_1.mp3"},"oxford":{"phon":"ɡreɪn","pos":"noun","senses":[{"en":"the small hard seeds of food plants such as wheat, rice, etc.; a single seed of such a plant","cn":"谷物；谷粒","g":"[uncountable, countable]","ex":{"en":"Russia sold 12 million tons of grain abroad last year.","cn":"俄罗斯去年出口粮食 1 200 万吨。"}},{"en":"a small hard piece of particular substances","cn":"颗粒；细粒","g":"[countable]","ex":{"en":"a grain of salt/sand/sugar","cn":"一粒盐／沙／砂糖"}},{"en":"a very small amount","cn":"少量；微量；一点儿","g":"[countable]","ex":{"en":"There isn't a grain of truth in those rumours.","cn":"那些谣传一点也不可靠。"}},{"en":"a small unit of weight, equal to 0.00143 of a pound or 0.0648 of a gram, used for example for weighing medicines","cn":"格令（重量单位，等于 0.00143 磅或 0.0648 克，用于称量药物等）","g":"[countable]","ex":{"en":"The analysis showed a few grains of arsenic in the solution.","cn":"分析显示溶液中有几格令的砷。"}},{"en":"the natural direction of lines in wood, cloth, etc. or of layers of rock; the pattern of lines that you can see","cn":"（木、织物或石头等的）纹理","g":"[uncountable, singular]","ex":{"en":"to cut a piece of wood along/across the grain","cn":"顺着纹路劈木头；横对纹路把木头拦腰截断"}},{"en":"how rough or smooth a surface feels","cn":"（表面的）质地；触感","g":"[uncountable, countable]","ex":{"en":"wood of coarse/fine grain","cn":"质地粗／细的木头"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"谷粒","en":"A grain of wheat, rice, or other cereal crop is a seed from it.","ex":{"en":"...a grain of wheat.","cn":"一粒小麦"}},{"pos":"N-MASS 物质名词","cn":"谷物（尤指小麦或玉米）","en":"Grain is a cereal crop, especially wheat or corn, that has been harvested and is used for food or in trade.","ex":{"en":"...a bag of grain.","cn":"一袋谷物"}},{"pos":"N-COUNT 可数名词","cn":"细粒;微粒;小颗粒","en":"A grain of something such as sand or salt is a tiny hard piece of it.","ex":{"en":"...a grain of sand.","cn":"一粒沙子"}},{"pos":"N-SING 单数名词","cn":"一点；些微","en":"A grain of a quality is a very small amount of it.","ex":{"en":"There's more than a grain of truth in that.","cn":"其中含有很深刻的道理。"}},{"pos":"N-SING 单数名词","cn":"（木材表面的）纹理，纹路","en":"The grain of a piece of wood is the direction of its fibres. You can also refer to the pattern of lines on the surface of the wood as the grain.","ex":{"en":"Brush the paint generously over the wood in the direction of the grain.","cn":"顺着木材的纹理刷上厚厚的一层漆。"}},{"pos":"PHRASE 短语","cn":"违背本来的原则；与…格格不入","en":"If you say that an idea or action goes against the grain, you mean that it is very difficult for you to accept it or do it, because it conflicts with your previous ideas, beliefs, or principles.","ex":{"en":"Privatisation goes against the grain of their principle of opposition to private ownership of industry.","cn":"私有化有悖于他们反对工业私有的原则。"}}]},"examples":[{"en":"to cut a piece of wood along/across the grain","cn":"顺着纹路劈木头；横对纹路把木头拦腰截断"},{"en":"It really goes against the grain to have to work on a Sunday.","cn":"星期天还得上班的确不合常情。"}]},"grows":{"lemma":"grow","media":{"uk":"media/uk/grow__gb_1.mp3","us":"media/us/grow__us_1.mp3"}},"grapes":{"lemma":"grape","media":{"img":["media/ldoce/img/grapes.jpg","media/pic/fruit_comp.jpg"],"uk":"media/uk/grape__gb_1.mp3","us":"media/us/grape__us_1.mp3"}},"greatly":{"media":{"uk":"media/uk/greatly__gb_1.mp3","us":"media/us/greatly__us_1.mp3"},"oxford":{"phon":"ˈɡreɪtli","pos":"adverb","senses":[{"en":"very much","cn":"非常；很","ex":{"en":"People's reaction to the film has varied greatly.","cn":"人们对这部影片的反应大不一样。"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"非常地；极大地","en":"You use greatly to emphasize the degree or extent of something.","ex":{"en":"People would benefit greatly from a pollution-free vehicle","cn":"人们将享受到无污染汽车的诸多好处。"}}]},"examples":[{"en":"People's reaction to the film has varied greatly.","cn":"人们对这部影片的反应大不一样。"},{"en":"Your help would be greatly appreciated.","cn":"如蒙帮助，感激不尽。"}]},"guessed":{"lemma":"guess"},"gait":{"media":{"uk":"media/uk/gait__gb_1.mp3","us":"media/us/gait__us_1.mp3"},"oxford":{"phon":"ɡeɪt","pos":"noun","senses":[{"en":"a way of walking or running","cn":"步态；步法","ex":{"en":"He walked with a rolling gait.","cn":"他走起路来摇摇晃晃。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"步态；步法","en":"A particular kind of gait is a particular way of walking.","ex":{"en":"...a tubby little man in his fifties, with sparse hair and a rolling gait","cn":"一位50多岁的矮胖男子，头发稀疏，走路晃晃悠悠"}}]},"examples":[{"en":"He walked with a rolling gait.","cn":"他走起路来摇摇晃晃。"},{"en":"a slow shuffling gait","cn":"迟缓拖沓的步子"}]},"gas":{"media":{"uk":"media/uk/gas__gb_1.mp3","us":"media/us/gas__us_1.mp3"},"oxford":{"phon":"ɡæs","pos":"noun","senses":[{"en":"any substance like air that is neither a solid nor a liquid, for example hydrogen or oxygen","cn":"气体","g":"[countable, uncountable]","sc":"not solid/liquid","ex":{"en":"Air is a mixture of gases.","cn":"空气为混合气体。"}},{"en":"a particular type of gas or mixture of gases used as fuel for heating and cooking","cn":"气体燃料；煤气；天然气","g":"[uncountable]","lab":"British English","sc":"not solid/liquid","ex":{"en":"fossil fuels like oil and gas","cn":"石油和天然气等化石燃料"}},{"en":"a particular type of gas used during a medical operation, to make the patient unconscious or to make the pain less","cn":"（外科手术用）麻醉气","g":"[uncountable]","sc":"not solid/liquid","ex":{"en":"an anaesthetic gas","cn":"麻醉气体"}},{"en":"a particular type of gas used in war to kill or injure people, or used by the police to control people","cn":"（战争用）毒气；（警察用）瓦斯","g":"[uncountable]","sc":"not solid/liquid","ex":{"en":"a gas attack","cn":"毒气攻击"}},{"en":"a liquid obtained from petroleum, used as fuel in car engines, etc.","cn":"汽油","g":"[uncountable]","lab":"both North American English","sc":"in vehicle","ex":{"en":"to run out of gas","cn":"汽油用完了"}},{"en":"the pedal in a car or other vehicle that you press with your foot to control the speed of the engine","cn":"（汽车等的）油门踏板，加速装置","g":"[singular]","lab":"both especially North American English","sc":"in vehicle","ex":{"en":"Step on the gas, we're late.","cn":"踩油门开快点，我们要迟到了。"}},{"en":"a person or an event that is fun","cn":"有趣的人（或事物）","g":"[singular]","lab":"especially North American English","sc":"fun","ex":{"en":"The party was a real gas.","cn":"这次聚会真有趣。"}},{"en":"air that you swallow with food or drink; gas that is produced in your stomach or intestines that makes you feel uncomfortable","cn":"（随食物或饮料）吞下的气；胃气；肠气","g":"[uncountable]","lab":"North American English","sc":"in stomach"},{"en":"to kill or harm somebody by making them breathe poisonous gas","cn":"用毒气杀伤；使吸入毒气","g":"[transitive]","sc":"kill/harm with gas","ex":{"en":"She gassed herself with fumes from the car’s exhaust pipe.","cn":"她用汽车排气管排出的烟雾给自己加油。"},"pos":"verb"},{"en":"to talk for a long time about things that are not important","cn":"闲聊；空谈；瞎扯","g":"[intransitive]","lab":"old-fashioned, informal，，","sc":"talk","ex":{"en":"I thought he’d never stop gassing!","cn":"我以为他永远不会停止放气！"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"气体燃料；天然气；煤气","en":"Gas is a substance like air that is neither liquid nor solid and burns easily. It is used as a fuel for cooking and heating.","ex":{"en":"Coal is actually cheaper than gas","cn":"煤实际上比煤气便宜。"}},{"pos":"N-VAR 可变名词","cn":"气体","en":"A gas is any substance that is neither liquid nor solid, for example oxygen or hydrogen.","ex":{"en":"Helium is a very light gas.","cn":"氦是一种非常轻的气体。"}},{"pos":"N-MASS 物质名词","cn":"毒气，瓦斯（可用作武器）","en":"Gas is a poisonous gas that can be used as a weapon.","ex":{"en":"...mustard gas","cn":"芥子气"}},{"pos":"N-MASS 物质名词","cn":"（医用）麻醉气","en":"Gas is a gas used for medical purposes, for example to make patients feel less pain or go to sleep during an operation.","ex":{"en":"...an anaesthetic gas used by many dentists.","cn":"为许多牙医使用的一种麻醉气"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（车辆用的）汽油","en":"Gas is the fuel which is used to drive motor vehicles.","ex":{"en":"...a tank of gas.","cn":"一桶汽油"}},{"pos":"VERB 动词","cn":"用毒气杀死","en":"To gas a person or animal means to kill them by making them breathe poisonous gas.","ex":{"en":"Her husband ran a pipe from her car exhaust to the bedroom in an attempt to gas her.","cn":"她的丈夫将一根与她的汽车排气管相通的管子导入卧室，企图用毒气将她杀死。"}},{"pos":"N-SING 单数名词","cn":"活泼有趣的事；令人愉快的场面","en":"You can describe a situation or event as a gas when it is very lively, amusing, and enjoyable.","ex":{"en":"It was really a gas to find someone I could talk with.","cn":"找到一个能和我谈得来的人真是一件让人高兴的事。"}},{"pos":"PHRASE 短语","cn":"加大油门；加速","en":"If you step on the gas when you are driving a vehicle, you go faster."}]},"examples":[{"en":"During the birth she was given gas and air.","cn":"她分娩时医生给她吸了麻醉气。"},{"en":"Step on the gas, we're late.","cn":"加大油门，我们要迟到了。"}]},"greedy":{"media":{"uk":"media/uk/greedy__gb_1.mp3","us":"media/us/greedy__us_1.mp3"},"oxford":{"phon":"ˈɡriːdi","pos":"adjective","senses":[{"en":"wanting more money, power, food, etc. than you really need","cn":"贪婪的；贪心的；贪吃的","ex":{"en":"You greedy pig! You've already had two helpings!","cn":"你这个馋嘴！你已经吃了两份了！"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"贪婪的；贪心的；贪吃的","en":"If you describe someone as greedy, you mean that they want to have more of something such as food or money than is necessary or fair.","ex":{"en":"He attacked greedy bosses for awarding themselves big rises","cn":"他抨击那些贪心的老板为他们自己大幅加薪。"}}]},"examples":[{"en":"You greedy pig! You've already had two helpings!","cn":"你这个馋嘴！你已经吃了两份了！"},{"en":"He stared at the diamonds with greedy eyes.","cn":"他眼巴巴地盯着这些钻石。"}]},"gun":{"oxford":{"phon":"ɡʌn","pos":"noun","senses":[{"en":"a weapon that is used for firing bullets or shells","cn":"枪；炮","g":"[countable]","ex":{"en":"I have never fired a gun in my life.","cn":"我这辈子从没开过枪。"}},{"en":"a tool that uses pressure to send out a substance or an object","cn":"喷射器；喷枪","g":"[countable]","ex":{"en":"a staple gun","cn":"U 形钉枪"}},{"en":"the signal to begin a race, that is made by firing a special gun, called a starting pistol, into the air","cn":"起跑信号；发令枪声","g":"[singular]"},{"en":"a person who is paid to shoot somebody","cn":"受雇杀人的枪手","g":"[countable]","lab":"informal, especially North American English，，","ex":{"en":"a hired gun","cn":"雇用的枪手"}},{"en":"to run very quickly","cn":"快速运转","g":"[intransitive]","lab":"North American English","ex":{"en":"a line of motorcycles with their engines gunning","cn":"引擎狂转的一队摩托车"},"pos":"verb"},{"en":"to start driving a vehicle very fast","cn":"使（车辆）加速","g":"[transitive]","lab":"North American English","ex":{"en":"He gunned the cab through the red light.","cn":"他猛踩油门，开着出租车闯过了红灯。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"枪；炮","en":"A gun is a weapon from which bullets or other things are fired.","ex":{"en":"He produced a gun and he came into the house","cn":"他掏出枪来，走进房子。"}},{"pos":"N-COUNT 可数名词","cn":"发令枪","en":"A gun or a starting gun is an object like a gun that is used to make a noise to signal the start of a race.","ex":{"en":"The starting gun blasted and they were off.","cn":"发令枪响了，他们冲了出去。"}},{"pos":"VERB 动词","cn":"把…发动起来；给…加大油门；使加速","en":"To gun an engine or a vehicle means to make it start or go faster by pressing on the accelerator pedal.","ex":{"en":"He gunned his engine and drove off.","cn":"他发动引擎，驱车而去。"}},{"pos":"PHRASE 短语","cn":"全力以赴；鼓足干劲","en":"If you come out with guns blazing or with all guns blazing, you put all your effort and energy into trying to achieve something.","ex":{"en":"The company came out with guns blazing.","cn":"公司鼓足了劲要大干一番。"}},{"pos":"PHRASE 短语","cn":"抢先行动；过早地行动","en":"If you jump the gun, you do something before everyone else or before the proper or right time.","ex":{"en":"It wasn't due to be released until September 10, but some booksellers have jumped the gun and decided to sell it early.","cn":"这本书定于9月10号发行，但是一些书商已抢先一步，决定提前销售。"}},{"pos":"PHRASE 短语","cn":"坚持自己的立场；固执己见；一意孤行","en":"If you stick to your guns, you continue to have your own opinion about something even though other people are trying to tell you that you are wrong.","ex":{"en":"He should have stuck to his guns and refused to meet her.","cn":"他本应坚持己见，拒绝与她会面。"}},{"pos":"","cn":"","en":"相关词组：gun down gun for"}]},"media":{"uk":"media/uk/gun__gb_1.mp3","us":"media/us/gun__us_1.mp3"},"examples":[{"en":"He gunned the cab through the red light.","cn":"他猛踩油门，开着出租汽车闯过了红灯。"},{"en":"The champions came out (with) all guns blazing.","cn":"优胜者们神采奕奕地登场亮相。"}]},"guideline":{"oxford":{"phon":"ˈɡaɪdlaɪn","pos":"noun","senses":[{"en":"a set of rules or instructions that are given by an official organization telling you how to do something, especially something difficult","cn":"指导方针；指导原则；行动纲领；准则","g":"[plural]","ex":{"en":"The government has drawn up guidelines for schools during the pandemic.","cn":"政府为疫情期间的学校制定了指导方针。"}},{"en":"something that can be used to help you make a decision or form an opinion","cn":"参考","g":"[countable]","ex":{"en":"The figures are a useful guideline when buying a house.","cn":"买房时这些数据很有参考价值。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"指导方针；指导原则；准则","en":"If an organization issues guidelines on something, it issues official advice about how to do it.","ex":{"en":"The government should issue clear guidelines on the content of religious education","cn":"政府应当就宗教教育的内容颁布明确的指导方针。"}},{"pos":"N-COUNT 可数名词","cn":"参考","en":"A guideline is something that can be used to help you plan your actions or to form an opinion about something.","ex":{"en":"The effects of the sun can be significantly reduced if we follow certain guidelines","cn":"如果我们遵循某些建议，日晒的影响会大大降低。"}}]},"media":{"uk":"media/uk/guideline__gb_1.mp3","us":"media/us/guideline__us_1.mp3"},"examples":[{"en":"The government has drawn up guidelines on the treatment of the mentally ill.","cn":"政府制订了对待精神病人的指导方针。"},{"en":"The figures are a useful guideline when buying a house.","cn":"买房时这些数据很有参考价值。"}]},"granite":{"media":{"uk":"media/uk/granite__gb_1.mp3","us":"media/us/granite__us_1.mp3"},"oxford":{"phon":"ˈɡrænɪt","pos":"noun","senses":[{"en":"a type of hard grey stone, often used in building","cn":"花岗岩；花岗石"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"花岗石；花岗岩","en":"Granite is a very hard rock used in building."}]}},"grind":{"media":{"uk":"media/uk/grind__gb_1.mp3","us":"media/us/grind__us_1.mp3"},"oxford":{"phon":"ɡraɪnd","pos":"verb","senses":[{"en":"to break or press something into very small pieces between two hard surfaces or using a special machine","cn":"磨碎；碾碎；把…磨成粉","g":"[transitive]","sc":"food/flour/coffee","ex":{"en":"to grind coffee/corn","cn":"将咖啡／谷粒磨成粉"}},{"en":"to produce something such as flour by grinding","cn":"磨（粉）","g":"[transitive]","sc":"food/flour/coffee","ex":{"en":"The flour is ground using traditional methods.","cn":"这面粉是用传统方法磨制而成。"}},{"en":"to cut food, especially meat, into very small pieces using a special machine (called a mincer)","cn":"用绞肉机绞（食物，尤指肉）","g":"[transitive]","lab":"North American English","sc":"food/flour/coffee"},{"en":"to make something sharp or smooth by rubbing it against a hard surface","cn":"使锋利；磨快；磨光","g":"[transitive]","sc":"make sharp/smooth","ex":{"en":"a special stone for grinding knives","cn":"专门磨刀用的石头"}},{"en":"to press or rub something into a surface","cn":"用力挤压，用力擦（入表层）","g":"[transitive]","sc":"press into surface","ex":{"en":"He ground his cigarette into the ashtray.","cn":"他把香烟按在烟灰缸里捻灭。"}},{"en":"to rub together, or to make hard objects rub together, often producing an unpleasant noise","cn":"摩擦（发出刺耳声）","g":"[intransitive, transitive]","sc":"rub together","ex":{"en":"Parts of the machine were grinding together noisily.","cn":"机器零件摩擦发出刺耳的声音。"}},{"en":"to turn the handle of a machine that grinds something","cn":"摇动手柄（操纵压磨机器）","g":"[transitive]","sc":"machine","ex":{"en":"to grind a pepper mill","cn":"摇动胡椒磨"}},{"en":"an activity that is boring or makes you tired and takes a lot of time","cn":"令人疲劳（或厌倦）的工作；苦差事","g":"[singular]","lab":"informal","sc":"boring activity","ex":{"en":"the daily grind of family life","cn":"家庭生活中烦琐的家务劳动"},"pos":"noun"},{"en":"the unpleasant noise made by machines","cn":"刺耳的摩擦声","g":"[singular]","sc":"of machines","pos":"noun"},{"en":"a person who spends too much time studying","cn":"只知一味用功学习的人；书呆子","g":"[countable]","lab":"US English","sc":"swot","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"磨碎；碾碎； 将…磨成粉","en":"If you grind a substance such as corn, you crush it between two hard surfaces or with a machine until it becomes a fine powder.","ex":{"en":"Store the peppercorns in an airtight container and grind the pepper as you need it.","cn":"将胡椒粒储存在密封容器中，在需要的时候磨成粉。"}},{"pos":"VERB 动词","cn":"用力挤压；用劲擦","en":"If you grind something into a surface, you press and rub it hard into the surface using small circular or sideways movements.","ex":{"en":"'Well,' I said, grinding my cigarette nervously into the granite step.","cn":"“好吧，”我边说边紧张不安地把香烟在花岗岩台阶上捻灭。"}},{"pos":"VERB 动词","cn":"把…磨锋利；把…磨快；把…磨光","en":"If you grind something, you make it smooth or sharp by rubbing it against a hard surface.","ex":{"en":"...a shop where they grind knives","cn":"磨刀铺"}},{"pos":"VERB 动词","cn":"刺耳地缓慢移动","en":"If a vehicle grinds somewhere, it moves there very slowly and noisily.","ex":{"en":"Tanks had crossed the border at five fifteen and were grinding south.","cn":"坦克队于5点15分越过边境，正轰隆隆地缓慢向南开进。"}},{"pos":"N-SING 单数名词","cn":"（机器的）刺耳摩擦声","en":"The grind of a machine is the harsh, scraping noise that it makes, usually because it is old or is working too hard.","ex":{"en":"The grind of heavy machines could get on their nerves.","cn":"重型机器发出的刺耳的摩擦声会让他们心烦意乱。"}},{"pos":"N-SING 单数名词","cn":"枯燥乏味的事；苦差事","en":"If you refer to routine tasks or activities as the grind, you mean they are boring and take up a lot of time and effort.","ex":{"en":"The daily grind of government is done by Her Majesty's Civil Service","cn":"枯燥的日常政务都由女王陛下的政府行政部门来处理。"}},{"pos":"PHRASE 短语","cn":"逐渐停止；慢慢瘫痪","en":"If a country's economy or something such as a process grinds to a halt, it gradually becomes slower or less active until it stops.","ex":{"en":"The peace process has ground to a halt while Israel struggles to form a new government.","cn":"当以色列竭力组建新政府的时候，和平进程已经陷于停顿。"}},{"pos":"PHRASE 短语","cn":"（车辆）声音刺耳地缓缓停下","en":"If a vehicle grinds to a halt, it stops slowly and noisily.","ex":{"en":"The tanks ground to a halt after a hundred yards because the fuel had been siphoned out.","cn":"由于燃油被人抽走，这些坦克行驶了100码后又轰隆隆地缓缓停了下来。"}},{"pos":"","cn":"","en":"to have an axe to grind→see: ; to come to a grinding halt→see: ;"},{"pos":"","cn":"","en":"相关词组：grind down grind on grind out grind up"}]},"examples":[{"en":"It's a long grind to the top of that particular profession.","cn":"爬到那种行业的最高位置要经过漫长的艰苦奋斗。"},{"en":"She grinds out romantic novels at the rate of five a year.","cn":"她以一年五部的速度胡乱拼凑低劣的爱情小说。"}]},"girls":{"lemma":"girl"},"grade":{"media":{"uk":"media/uk/grade__gb_1.mp3","us":"media/us/grade__us_1.mp3"},"oxford":{"phon":"ɡreɪd","pos":"noun","senses":[{"en":"a mark given in an exam or for a piece of school work","cn":"成绩等级；评分等级","lab":"British English","ex":{"en":"She got good grades in her exams.","cn":"她考试成绩优良。"}},{"en":"(in the US school system) one of the levels in a school with children of similar age","cn":"（美国学制）年级","ex":{"en":"Sam is in (the) second grade.","cn":"萨姆读二年级。"}},{"en":"the quality of a particular product or material","cn":"（产品、材料的）等级，品级","ex":{"en":"All the materials used were of the highest grade.","cn":"使用的材料全是最高等级的。"}},{"en":"a level of ability or rank that somebody has in an organization","cn":"（官衔的）级别；职别","ex":{"en":"salary/pay grades (= levels of pay)","cn":"工资／薪酬级别"}},{"en":"how serious an illness is","cn":"（疾病的）程度，阶段","lab":"specialist","ex":{"en":"low/high grade fever","cn":"低烧；高烧"}},{"en":"a slope on a road or railway; the degree to which the ground slopes","cn":"（公路或铁路的）坡；坡度；斜率；倾斜度","lab":"especially North American English","ex":{"en":"The hill has a grade of 25 per cent.","cn":"这座山的坡度为25%。"}},{"en":"a level of exam in musical skill","cn":"（音乐考试的）级别，水平","lab":"British English","ex":{"en":"grade 6 piano","cn":"六级钢琴"}},{"en":"to give a grade to a student or to a piece of their written work","cn":"给…评分；给…分数","lab":"especially North American English","ex":{"en":"I spent all weekend grading papers.","cn":"我整个周末都在评阅试卷。"},"pos":"verb"},{"en":"to arrange people or things in groups according to their ability, quality, size, etc.","cn":"（按能力、质量、大小等）分级，分等，分类","g":"[usually passive]","ex":{"en":"The containers are graded according to size.","cn":"这些容器按大小分类。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"将…分等级","en":"If something is graded, its quality is judged, and it is often given a number or a name that indicates how good or bad it is.","ex":{"en":"Dust masks are graded according to the protection they offer","cn":"防尘口罩根据它们的防护效果分等级。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指正式评定的）等级，品级","en":"The grade of a product is its quality, especially when this has been officially judged.","ex":{"en":"...a grade II listed building.","cn":"列入二级文物保护的建筑"}},{"pos":"N-COUNT 可数名词","cn":"（用数字或字母表示的）成绩，评分","en":"Your grade in an examination or piece of written work is the mark you get, usually in the form of a letter or number, that indicates your level of achievement.","ex":{"en":"What grade are you hoping to get?","cn":"你希望得到什么样的成绩？"}},{"pos":"N-COUNT 可数名词","cn":"（职位的）级别，等级","en":"Your grade in a company or organization is your level of importance or your rank.","ex":{"en":"Staff turnover is particularly high among junior grades.","cn":"基层职员的流动率特别高。"}},{"pos":"N-COUNT 可数名词","cn":"（美国学校中的）年级","en":"In the United States, a grade is a group of classes in which all the children are of a similar age. When you are six years old you go into the first grade and you leave school after the twelfth grade.","ex":{"en":"Mr White teaches first grade in south Georgia.","cn":"怀特先生在佐治亚州南部教一年级。"}},{"pos":"N-COUNT 可数名词","cn":"斜坡","en":"A grade is a slope.","ex":{"en":"She drove up a steep grade and then began the long descent into the desert.","cn":"她驾车开上一个陡坡，然后沿着长长的下坡路驶入沙漠。"}},{"pos":"N-COUNT 可数名词","cn":"军衔","en":"Someone's grade is their military rank.","ex":{"en":"I was a naval officer, lieutenant junior grade.","cn":"我是一名海军中尉军官。"}},{"pos":"PHRASE 短语","cn":"成功；达到理想标准","en":"If someone makes the grade, they succeed, especially by reaching a particular standard.","ex":{"en":"She had a strong desire to be a dancer but failed to make the grade.","cn":"她非常渴望成为舞蹈演员，但却因为达不到标准而未能圆梦。"}}]},"examples":[{"en":"Responses were graded from 1 (very satisfied) to 5 (not at all satisfied).","cn":"回答按 1（非常满意）到 5（完全不满意）分类。"},{"en":"About 10% of trainees fail to make the grade.","cn":"接受培训的人大约有 10% 未达标。"}]},"gates":{"lemma":"gate"},"girlish":{"media":{"uk":"media/uk/girlish__gb_1.mp3","us":"media/us/girlish__us_1.mp3"},"oxford":{"phon":"ˈɡɜːlɪʃ","pos":"adjective","senses":[{"en":"like a girl; of a girl","cn":"像女孩子的；女孩子似的；女孩子的","ex":{"en":"a girlish giggle","cn":"女孩子气的咯咯笑"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"像女孩子的；少女似的","en":"If you describe a woman as girlish, you mean she behaves, looks, or sounds like a young girl, for example because she is shy, excited, or lively.","ex":{"en":"She gave a little girlish giggle.","cn":"她像个小女孩一样咯咯地笑了笑。"}}]},"examples":[{"en":"a girlish giggle","cn":"女孩子气的咯咯笑"},{"en":"a girlish figure","cn":"女孩儿的体形"}]},"grids":{"lemma":"grid"},"gardener":{"media":{"uk":"media/uk/gardener__gb_1.mp3","us":"media/us/gardener__us_1.mp3"},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"花匠；园丁；园艺工人","en":"A gardener is a person who is paid to work in someone else's garden."},{"pos":"N-COUNT 可数名词","cn":"喜欢干园艺活的人","en":"A gardener is someone who enjoys working in their own garden growing flowers or vegetables.","ex":{"en":"...enthusiastic amateur gardeners.","cn":"热衷园艺的业余爱好者"}}]},"examples":[{"en":"We employ a gardener two days a week.","cn":"我们雇了个花匠，每周工作两天。"},{"en":"My wife's a keen gardener.","cn":"我的妻子是个热衷园艺的人。"}],"oxford":{"phon":"ˈɡɑːdnə(r)","pos":"noun","senses":[{"en":"a person whose job is to work in a garden","cn":"园艺工人，园丁，花匠","ex":{"en":"We employ a gardener two days a week.","cn":"我们雇了个花匠，每周工作两天。"}},{"en":"a person who enjoys working in a garden","cn":"园艺爱好者","ex":{"en":"My wife's a keen gardener.","cn":"我妻子是个热衷园艺的人。"}}]}},"govern":{"oxford":{"phon":"ˈɡʌvn","pos":"verb","senses":[{"en":"to legally control a country or its people and be responsible for introducing new laws, organizing public services, etc.","cn":"统治；控制；管理；治理","g":"[transitive, intransitive]","ex":{"en":"The country is governed by elected representatives of the people.","cn":"这个国家由民选代表统治。"}},{"en":"to control or influence somebody/something or how something happens, functions, etc.","cn":"控制；影响；支配","g":"[transitive, often passive]","ex":{"en":"We need changes in the law governing school attendance.","cn":"我们需要对影响就学率的法规做些改动。"}},{"en":"if a word governs another word or phrase, it affects how that word or phrase is formed or used","cn":"支配（词或短语的形式或用法）","g":"[transitive]","lab":"grammar"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"统治；治理","en":"To govern a place such as a country, or its people, means to be officially in charge of the place, and to have responsibility for making laws, managing the economy, and controlling public services.","ex":{"en":"They go to the polls on Friday to choose the people they want to govern their country","cn":"星期五，他们去投票站投票选择他们所期望的国家管理者。"}},{"pos":"VERB 动词","cn":"支配；控制；影响","en":"If a situation or activity is governed by a particular factor, rule, or force, it is controlled by that factor, rule, or force.","ex":{"en":"Marine insurance is governed by a strict series of rules and regulations","cn":"关于海险有一系列严格的规章制度对其作了规定。"}}]},"media":{"uk":"media/uk/govern__gb_1.mp3","us":"media/us/govern__us_1.mp3"},"examples":[{"en":"We need changes in the law governing school attendance.","cn":"我们需要对影响就学率的法规做些改动。"},{"en":"All his decisions have been entirely governed by self-interest.","cn":"他的所有决定都受利己之心的支配。"}]},"graduation":{"oxford":{"phon":"ˌɡrædʒuˈeɪʃn","pos":"noun","senses":[{"en":"the act of successfully completing a university degree, or studies at an American high school","cn":"（大学或美国高中的）毕业","g":"[uncountable]","ex":{"en":"It was my first job after graduation.","cn":"那是我毕业后的第一个工作。"}},{"en":"a ceremony at which degrees, etc. are officially given out","cn":"毕业典礼","g":"[uncountable, countable]","ex":{"en":"graduation day","cn":"毕业典礼日"}},{"en":"a mark showing a division on a scale","cn":"刻度","g":"[countable]","ex":{"en":"The graduations are marked on the side of the flask.","cn":"烧瓶壁标有刻度。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"毕业","en":"Graduation is the successful completion of a course of study at a university, college, or school, for which you receive a degree or diploma.","ex":{"en":"They asked what his plans were after graduation","cn":"他们问他毕业之后有何打算。"}},{"pos":"N-COUNT 可数名词","cn":"毕业典礼","en":"A graduation is a special ceremony at university, college, or school, at which degrees and diplomas are given to students who have successfully completed their studies.","ex":{"en":"...the graduation ceremony at Yale","cn":"耶鲁大学的毕业典礼"}},{"pos":"N-COUNT 可数名词","cn":"刻度线；刻度","en":"A graduation is a line or number on a container or measuring instrument which marks a particular measurement.","ex":{"en":"...medicine bottles with graduations on them.","cn":"标有刻度线的药瓶"}}]},"media":{"uk":"media/uk/graduation__gb_1.mp3","us":"media/us/graduation__us_1.mp3"},"examples":[{"en":"My whole family came to my graduation.","cn":"我的家人都来参加了我的毕业典礼。"},{"en":"It was my first job after graduation.","cn":"那是我毕业后的第一个工作。"}]},"gatherings":{"lemma":"gather"},"gaudy":{"media":{"uk":"media/uk/gaudy__gb_1.mp3","us":"media/us/gaudy__us_1.mp3"},"oxford":{"phon":"ˈɡɔːdi","pos":"adjective","senses":[{"en":"too brightly coloured in a way that lacks taste","cn":"俗艳的；花哨的","ex":{"en":"gaudy clothes/colours","cn":"过于花哨的衣服／色彩"}},{"en":"the name used in some colleges at the universities of Oxford and Cambridge for the special dinner for former students that takes place each year","cn":"艳丽：每年在牛津大学和剑桥大学的一些大学中使用的名称，用于为前生举办的特别晚宴","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"花哨的；俗艳的","en":"If something is gaudy, it is very brightly-coloured and showy.","ex":{"en":"...her gaudy orange-and-purple floral hat.","cn":"她那顶饰有花卉的橙紫相间的花哨帽子"}}]},"examples":[{"en":"gaudy clothes/colours","cn":"过于花哨的衣服/色彩"},{"en":"gaudily dressed/painted","cn":"穿着/涂饰得太俗艳"}]},"greenery":{"media":{"uk":"media/uk/greenery__gb_1.mp3","us":"media/us/greenery__us_1.mp3"},"oxford":{"phon":"ˈɡriːnəri","pos":"noun","senses":[{"en":"attractive green leaves and plants","cn":"青枝绿叶；青葱的草木；绿色植物","ex":{"en":"The room was decorated with flowers and greenery.","cn":"房间里装点着花卉和绿叶植物。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"绿色植物；青葱的草木","en":"Plants that make a place look attractive are referred to as greenery .","ex":{"en":"They have ordered a bit of greenery to brighten up the new wing at Guy's Hospital.","cn":"他们订购了一些绿色植物，以给盖伊医院的新配楼增添一抹亮色。"}}]},"examples":[{"en":"The room was decorated with flowers and greenery.","cn":"房间里装点着花卉和绿叶植物。"},{"en":"the rich greenery of grass and trees","cn":"茂盛的绿色草木"}]},"goodbye":{"media":{"uk":"media/uk/goodbye__gb_1.mp3","us":"media/us/goodbye__us_1.mp3"},"oxford":{"phon":"ˌɡʊdˈbaɪ","pos":"exclamation, noun","senses":[{"en":"used when you are leaving somebody or when somebody else is leaving","cn":"再见；再会","lab":"figurative","ex":{"en":"Goodbye! It was great to meet you.","cn":"再见！认识你很高兴。"}}]},"collins":{"senses":[{"pos":"CONVENTION 惯用语","cn":"（告别用语）再见","en":"You say 'Goodbye' to someone when you or they are leaving, or at the end of a telephone conversation."},{"pos":"N-COUNT 可数名词","cn":"告别语；道别；再见","en":"When you say your goodbyes, you say something such as 'Goodbye' when you leave.","ex":{"en":"He said his goodbyes knowing that a long time would pass before he would see his child again","cn":"他道了别，知道要过很久才能再见到他的孩子。"}},{"pos":"PHRASE 短语","cn":"道别/ 挥手告别","en":"When you say goodbye to someone, you say something such as 'Goodbye', 'Bye', or 'See you', when you or they are leaving. You can also wave goodbye to someone.","ex":{"en":"He left without saying goodbye","cn":"他不辞而别。"}},{"pos":"PHRASE 短语","cn":"向…说再见；承认不会（或不再）拥有","en":"If you say goodbye or wave goodbye to something that you want or usually have, you accept that you are not going to have it.","ex":{"en":"He has probably said goodbye to his last chance of Olympic gold","cn":"他可能已经失去了夺取奥运会金牌的最后机会。"}},{"pos":"","cn":"","en":"to kiss something goodbye→see: ;"}]},"examples":[{"en":"( figurative ) Take out our service contract and say goodbye to costly repair bills.","cn":"接受我们的服务合同，告别昂贵的修理费吧。"},{"en":"She didn't even say goodbye to her mother .","cn":"她甚至没有向母亲道个别。"}]},"good":{"media":{"uk":"media/uk/good__gb_1.mp3","us":"media/us/good__us_1.mp3"},"oxford":{"phon":"ɡʊd","pos":"adjective","senses":[{"en":"of high quality or an acceptable standard","cn":"好的；优质的；符合标准的；可接受的","sc":"high quality","ex":{"en":"a good book","cn":"一本好书"}},{"en":"pleasant; that you enjoy or want","cn":"令人愉快的；令人满意的","sc":"pleasant","ex":{"en":"Did you have a good time in London?","cn":"你在伦敦过得愉快吗？"}},{"en":"sensible, logical or strongly supporting what is being discussed","cn":"合情理的；有说服力的；有充分根据的","sc":"sensible/strong","ex":{"en":"Thank you, good question.","cn":"谢谢，问题提得好。"}},{"en":"showing or getting approval or respect","cn":"赞同的；赢得赞许的；令人尊敬的","sc":"favourable","ex":{"en":"The play had good reviews.","cn":"这部戏受到好评。"}},{"en":"able to do something well","cn":"擅长的；精通的","sc":"skilful","ex":{"en":"a good player","cn":"优秀的选手"}},{"en":"able to use something or deal with people well","cn":"灵巧的；精明的；善于应付…的","sc":"skilful","ex":{"en":"She's good with her hands (= able to make things, etc.).","cn":"她手很巧。"}},{"en":"morally right; behaving in a way that is morally right","cn":"符合道德的；正派的；高尚的","sc":"morally right","ex":{"en":"She has tried to lead a good life.","cn":"她努力规规矩矩地生活。"}},{"en":"following strictly a set of rules or principles","cn":"循规蹈矩的；守规矩的","sc":"following rules","ex":{"en":"It is good practice to supply a written report to the buyer.","cn":"向买主提供书面报告是诚信的做法。"}},{"en":"willing to help; kind to other people","cn":"乐于助人的；心地善良的；好心的","sc":"kind","ex":{"en":"You've always been such a good friend.","cn":"你一直都是我的好朋友。"}},{"en":"behaving well or politely","cn":"温顺的；乖的；有礼貌的","sc":"child/animal","ex":{"en":"You can stay up late if you're good.","cn":"你要是听话就可以晚一点睡觉。"}},{"en":"healthy or strong","cn":"健康的；强健的；健壮的","sc":"healthy","ex":{"en":"Can you speak into my good ear?","cn":"对着我这只没毛病的耳朵说好吗？"}},{"en":"having a useful or helpful effect on somebody/something","cn":"（对…）有用，有好处","lab":"informal","sc":"useful/helpful","ex":{"en":"Living so close to a chemicals factory can't be good.","cn":"住得离化工厂这么近可不是什么好事。"}},{"en":"suitable or appropriate","cn":"合适的；适宜的；恰当的；适合…的","sc":"suitable","ex":{"en":"Now is a good time to buy a house.","cn":"现在买房子正是时候。"}},{"en":"used in speaking to show that you approve of or are pleased about something that has been said or done, or to show that you want to move on to a new topic of conversation","cn":"（用于口语，表示赞同、满意或转换话题）","sc":"showing approval","ex":{"en":"‘Dinner's ready.’ ‘Good—I'm starving.’","cn":"“晚饭好了。”“太好了，我正饿得很。”"}},{"en":"used as a form of praise","cn":"（用作赞语）","g":"[only before noun]","lab":"informal","sc":"showing approval","ex":{"en":"Good old Jack!","cn":"好心的杰克！"}},{"en":"used in exclamations","cn":"（用于感叹）","lab":"informal","sc":"in exclamations","ex":{"en":"Good heavens!","cn":"天啊！"}},{"en":"great in number, amount or degree","cn":"（数量或程度）相当大的，相当多的","g":"[only before noun]","sc":"large","ex":{"en":"a good number of people","cn":"相当多的人"}},{"en":"not less than; rather more than","cn":"不少于；稍多于","sc":"at least","ex":{"en":"We waited for a good hour.","cn":"我们等了至少一小时。"}},{"en":"done to a high level or a great degree; complete","cn":"彻底的；完全的","g":"[only before noun]","sc":"complete","ex":{"en":"We had a good laugh about it afterwards.","cn":"我们后来对此笑了个痛快。"}},{"en":"funny or clever","cn":"有趣的；巧妙的","g":"[usually before noun]","lab":"informal","sc":"amusing","ex":{"en":"a good story/joke","cn":"有趣的故事／笑话"}},{"en":"having enough energy, health, strength, etc. to last for a particular length of time or distance","cn":"（精力、健康、力量等）足以维持…的，能持续…的","sc":"for particular time/distance","ex":{"en":"You're good for (= you will live) a few years yet.","cn":"你还可以活上几年。"}},{"en":"acceptable for something","cn":"有效的；可接受的","sc":"for particular time/distance","ex":{"en":"The ticket is good for three months.","cn":"这张票三个月内有效。"}},{"en":"likely to provide something","cn":"能提供…的","sc":"likely to provide","ex":{"en":"He's always good for a laugh.","cn":"他总能逗人发笑。"}},{"en":"behaviour that is morally right or acceptable","cn":"合乎道德的行为；正直的行为；善行","g":"[uncountable]","sc":"morally right","ex":{"en":"Do they even know the difference between good and evil?","cn":"他们到底知不知道善与恶的区别？"},"pos":"noun"},{"en":"people who live a moral life; people who are admired for the work they do to help other people","cn":"有道德的人；高尚的人；好人","g":"[plural]","sc":"morally right","ex":{"en":"a gathering of the great and the good","cn":"群贤荟萃"},"pos":"noun"},{"en":"something that helps somebody/something","cn":"用处；好处；益处","g":"[uncountable]","sc":"something helpful","ex":{"en":"Cuts have been made for the good of the company.","cn":"实行裁减是为了公司的利益。"},"pos":"noun"},{"en":"well","cn":"好","ex":{"en":"‘How's it going?’ ‘Pretty good.’","cn":"“事情进展如何？”“非常好。”"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"愉快的；有趣的；令人愉快的","en":"Good means pleasant or enjoyable.","ex":{"en":"We had a really good time together","cn":"我们一起玩得真痛快。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"好的；高品质的；高水准的","en":"Good means of a high quality, standard, or level.","ex":{"en":"Exercise is just as important to health as good food","cn":"锻炼与合理膳食对健康同等重要。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"擅长的；精通的；能干的","en":"If you are good at something, you are skilful and successful at doing it.","ex":{"en":"He was very good at his work","cn":"他工作非常出色。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有利的；有益的","en":"If you describe a piece of news, an action, or an effect as good, you mean that it is likely to result in benefit or success.","ex":{"en":"On balance biotechnology should be good news for developing countries","cn":"总的来说，生物技术对发展中国家应该是有利的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"合情理的；理由充足的；有根据的","en":"A good idea, reason, method, or decision is a sensible or valid one.","ex":{"en":"They thought it was a good idea to make some offenders do community service","cn":"他们认为让一些违法者去社区做义工是个好主意。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人满意的；合适的；正确的","en":"If you say that it is good that something should happen or good to do something, you mean it is desirable, acceptable, or right.","ex":{"en":"I think it's good that some people are going","cn":"我认为一些人要去是好事情。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"精确的；准确的","en":"A good estimate or indication of something is an accurate one.","ex":{"en":"We have a fairly good idea of what's going on","cn":"我们对正在发生的事有着相当清楚的认识。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"划算的；收益可观的","en":"If you get a good deal or a good price when you buy or sell something, you receive a lot in exchange for what you give.","ex":{"en":"Whether such properties are a good deal will depend on individual situations","cn":"这样的地产是否可获得大笔收益还要视具体情形而定。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有利的；有益的","en":"If something is good for a person or organization, it benefits them.","ex":{"en":"Rain water was once considered to be good for the complexion","cn":"雨水曾一度被认为可以滋养皮肤。"}},{"pos":"N-SING 单数名词","cn":"好处；利益","en":"If something is done for the good of a person or organization, it is done in order to benefit them.","ex":{"en":"Furlaud urged him to resign for the good of the country","cn":"弗劳德敦促他为了国家的利益辞职。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"差强人意；低劣；不好","en":"If someone or something is no good or is not any good, they are not satisfactory or are of a low standard.","ex":{"en":"If the weather's no good then I won't take any pictures","cn":"如果天气不好，我就不拍照了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"没好处；没用处","en":"If you say that doing something is no good or does not do any good, you mean that doing it is not of any use or will not bring any success.","ex":{"en":"It's no good worrying about it now","cn":"现在就为此发愁根本没用。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"善行；美德；合乎道德的行为","en":"Good is what is considered to be right according to moral standards or religious beliefs.","ex":{"en":"Good and evil may co-exist within one family.","cn":"善与恶可能并存于一体。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"正直的；高尚的；品行好的","en":"Someone who is good is morally correct in their attitudes and behaviour.","ex":{"en":"The president is a good man","cn":"总统是个品行端正的人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（尤指小孩）乖的，恭顺的，有礼貌的","en":"Someone, especially a child, who is good obeys rules and instructions and behaves in a socially correct way.","ex":{"en":"The children were very good","cn":"孩子们非常听话。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"好心的；体贴的","en":"Someone who is good is kind and thoughtful.","ex":{"en":"You are good to me","cn":"你对我很体贴。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（心情）愉快的","en":"Someone who is in a good mood is cheerful and pleasant to be with.","ex":{"en":"People were in a pretty good mood","cn":"人们的心情十分舒畅。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"亲密的；友好的","en":"If people are good friends, they get on well together and are very close.","ex":{"en":"She and Gavin are good friends","cn":"她与加文是好朋友。"}},{"pos":"ADJ 形容词","cn":"（身体部位或器官）健全的，强健的","en":"A person's good eye, arm, or leg is the one that is healthy and strong, if the other one is injured or weak.","ex":{"en":"He turned his good eye on me and laughed.","cn":"他用那只健全的眼睛看着我笑了。"}},{"pos":"ADJ 形容词","cn":"相当的；非常的","en":"You use good to emphasize the great extent or degree of something.","ex":{"en":"We waited a good fifteen minutes","cn":"我们等了足足15分钟。"}},{"pos":"CONVENTION 惯用语","cn":"好；很好","en":"You say 'Good' or 'Very good' to express pleasure, satisfaction, or agreement with something that has been said or done, especially when you are in a position of authority.","ex":{"en":"'Are you all right?' — 'I'm fine.' — 'Good. So am I.'","cn":"“你还好吗？”——“我挺好。”——“那就好。我也还不错。”"}},{"pos":"PHRASE 短语","cn":"几乎；差不多","en":"'As good as' can be used to mean 'almost.'","ex":{"en":"His career is as good as over","cn":"他的事业差不多完蛋了。"}},{"pos":"PHRASE 短语","cn":"为了共同利益","en":"If you do something for the common good, you do it for the benefit or advantage of everyone.","ex":{"en":"...communities working together for the common good","cn":"为共同利益而团结协作的社区"}},{"pos":"PHRASE 短语","cn":"对…有好处（或有帮助）","en":"If you say that something will do someone good, you mean that it will benefit them or improve them.","ex":{"en":"The outing will do me good","cn":"这次远足对我会有所助益。"}},{"pos":"PHRASE 短语","cn":"永远；永久","en":"If something changes or disappears for good, it never changes back or comes back as it was before.","ex":{"en":"The days of big-time racing at Herne Hill had gone for good","cn":"在赫恩山举行盛大赛马会的日子早已一去不复返了。"}},{"pos":"CONVENTION 惯用语","cn":"（称赞某人）真行，真棒","en":"People say 'Good for you' to express approval of your actions.","ex":{"en":"'He has a girl now, who he lives with.' — 'Good for him.'","cn":"“他现在有女朋友了，他们住在一起。”——“他可真行啊。”"}},{"pos":"PHRASE 短语","cn":"善于做；精通于","en":"If someone is good for something, you can rely on them to provide that thing.","ex":{"en":"Joe was always good for a colorful quote","cn":"乔总能绘声绘色地旁征博引。"}},{"pos":"PHRASE 短语","cn":"庆幸的是，幸运的是（英国英语中作 it's a good job, that）","en":"If you say it's a good thing, or in British English it's a good job ,that something is the case, you mean that it is fortunate.","ex":{"en":"It's a good thing you aren't married","cn":"幸好你没有结婚。"}},{"pos":"PHRASE 短语","cn":"修复；恢复；偿付；赔偿","en":"If you make good some damage, a loss, or a debt, you try to repair the damage, replace what has been lost, or repay the debt.","ex":{"en":"It may cost several billion roubles to make good the damage.","cn":"也许要花上几十亿卢布才能赔偿这一损失。"}},{"pos":"PHRASE 短语","cn":"兑现，履行（诺言等）","en":"If someone makes good a threat or promise or makes good on it, they do what they have threatened or promised to do.","ex":{"en":"Certain that he was going to make good his threat to kill her, she lunged for the gun","cn":"他曾威胁要杀了她，而她确定他这次就要向她索命，便冲上前去拿枪。"}},{"pos":"PHRASE 短语","cn":"获得成功；出名；发迹","en":"If someone makes good, they become successful, famous, or rich.","ex":{"en":"Both men are poor boys made good.","cn":"两人都是出身贫穷，最终干出了一番事业。"}},{"pos":"PHRASE 短语","cn":"（尤指在康复或修复后）同以前一样好","en":"If you say that something or someone is as good as new, you mean that they are in a very good condition or state, especially after they have been damaged or ill.","ex":{"en":"I only ever use that on special occasions so it's as good as new","cn":"我只在特别的场合下才使用它，所以它跟新的一样。"}},{"pos":"PHRASE 短语","cn":"（用于人名、地名或事物名前表示喜爱）亲爱的，可爱的","en":"You use good old before the name of a person, place, or thing when you are referring to them in an affectionate way.","ex":{"en":"Good old Harry. Reliable to the end","cn":"亲爱的哈里。永远值得信赖。"}},{"pos":"PHRASE 短语","cn":"优裕的生活；奢华安逸的生活","en":"If you say that someone is living the good life, you mean that they are living in comfort and luxury with few problems or worries."},{"pos":"","cn":"","en":"to be in someone's good books→see: ; good deal→see: ; in good faith→see: ; so far so good→see: ; a good few→see: ; good as gold→see: ; good gracious→see: ; good grief→see: ; good heavens→see: ; for good or ill→see: ; good job→see: ; good lord→see: ; for good measure→see: ; the good old days→see: ; good question→see: ; in good shape→see: ; to stand someone in good stead→see: ; in good time→see: ; too good to be true→see: ; to be as good as one's word→see: ;"}]},"examples":[{"en":"If these measures also reduce unemployment, that is all to the good.","cn":"要是这些措施也能降低失业率，那就不失为好事。"},{"en":"Can we change our meeting? Monday isn't good (= convenient) for me.","cn":"我们把见面时间改改吧，星期一我不方便。"}]},"graceful":{"media":{"uk":"media/uk/graceful__gb_1.mp3","us":"media/us/graceful__us_1.mp3"},"oxford":{"phon":"ˈɡreɪsfl","pos":"adjective","senses":[{"en":"moving in an attractive way that shows control; having a smooth, attractive form","cn":"优美的；优雅的；雅致的","ex":{"en":"The dancers were all tall and graceful.","cn":"这些舞蹈演员都个子高高的，动作十分优雅。"}},{"en":"polite and kind in your behaviour, especially in a difficult situation","cn":"（尤指在困境中）得体的，有风度的","ex":{"en":"His father had always taught him to be graceful in defeat.","cn":"他父亲总是教导他输了也要有风度。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"优美的;优雅的","en":"Someone or something that is graceful moves in a smooth and controlled way which is attractive to watch.","ex":{"en":"His movements were so graceful they seemed effortless.","cn":"他的动作优美自如，看起来毫不费劲。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"优美的；动人的；雅致的","en":"Something that is graceful is attractive because it has a pleasing shape or style.","ex":{"en":"A graceful medieval cathedral","cn":"典雅的中世纪大教堂"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"优雅的；得体的；有风度的","en":"If a person's behaviour is graceful, it is polite, kind, and pleasant, especially in a difficult situation.","ex":{"en":"Aubrey could think of no graceful way to escape Corbet's company","cn":"奥布里想不出有什么得体的办法能摆脱科比特。"}}]},"examples":[{"en":"The dancers were all tall and graceful.","cn":"这些舞蹈演员都个子高高的，动作十分优雅。"},{"en":"The cathedral's white towers climb gracefully into the sky.","cn":"大教堂白色的塔楼优雅庄重地耸入云霄。"}]},"graduate":{"media":{"uk":"media/uk/graduate__gb_1.mp3","us":"media/us/graduate__us_1.mp3"},"oxford":{"phon":"ˈɡrædʒuət","pos":"noun","senses":[{"en":"a person who has a university degree","cn":"大学毕业生；学士学位获得者","lab":"North American English","ex":{"en":"job prospects for graduates","cn":"毕业生就业前景"}},{"en":"a person who has completed their school studies","cn":"毕业生","lab":"North American English","ex":{"en":"a high school graduate","cn":"中学毕业生"}},{"en":"to get a degree, especially your first degree, from a university or college","cn":"获得学位（尤指学士）；大学毕业","g":"[intransitive, transitive]","lab":"North American English","ex":{"en":"She taught in France after she graduated.","cn":"她大学毕业后在法国任教。"},"pos":"verb"},{"en":"to complete a course in education, especially at high school","cn":"毕业（尤指中学）","g":"[intransitive, transitive]","lab":"North American English","ex":{"en":"He flunked math and never graduated.","cn":"他数学不及格，中学没毕业。"},"pos":"verb"},{"en":"to give a degree, diploma, etc. to somebody","cn":"授予（某人）学位（或毕业文凭等）","g":"[transitive]","lab":"North American English","ex":{"en":"The college graduated 50 students last year.","cn":"去年这所学院有 50 名毕业生。"},"pos":"verb"},{"en":"to start doing something more difficult or important than what you were doing before","cn":"逐渐发展（或变化、进展、上升）","g":"[intransitive]","ex":{"en":"She recently graduated from being a dancer to having a small role in a movie.","cn":"她最近从一个舞蹈演员逐步过渡到在电影里扮演小角色。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（英国的）大学毕业生，学士学位获得者","en":"In Britain, a graduate is a person who has successfully completed a degree at a university or college and has received a certificate that shows this.","ex":{"en":"In 1973, the first Open University graduates received their degrees.","cn":"1973年，第一批开放大学的毕业生获得了学位。"}},{"pos":"N-COUNT 可数名词","cn":"（美国的）高中（或学院、大学）毕业生","en":"In the United States, a graduate is a student who has successfully completed a course at a high school, college, or university.","ex":{"en":"The top one-third of all high school graduates are entitled to an education at the California State University.","cn":"高中毕业生当中排名前1/3的学生可以进入加利福尼亚州立大学深造。"}},{"pos":"VERB 动词","cn":"（英国）大学毕业","en":"In Britain, when a student graduates from university, they have successfully completed a degree course.","ex":{"en":"She graduated in English and Drama from Manchester University.","cn":"她毕业于曼彻斯特大学的英语和戏剧专业。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（美国）中学（或大学）毕业，授予…学位（或毕业文凭）","en":"In the United States, when a student graduates, they complete their studies successfully and leave their school or university. You can also say that a school or university graduates a student or students.","ex":{"en":"When the boys graduated from high school, Ann moved to a small town in Vermont","cn":"当儿子们高中毕业后，安搬到佛蒙特州的一个小镇上居住。"}},{"pos":"VERB 动词","cn":"晋升；升职；升级","en":"If you graduate from one thing to another, you go from a less important job or position to a more important one.","ex":{"en":"Bruce graduated to chef at the Bear Hotel","cn":"布鲁斯晋升为大熊饭店的厨师长。"}}]},"examples":[{"en":"She recently graduated from being a dancer to having a small role in a movie.","cn":"她最近从一个舞蹈演员逐步过渡到在电影里扮演小角色。"},{"en":"Only three students graduated in Czech studies last year.","cn":"去年只有三名学生获得捷克研究学士学位。"}]},"generous":{"media":{"uk":"media/uk/generous__gb_1.mp3","us":"media/us/generous__us_1.mp3"},"oxford":{"phon":"ˈdʒenərəs","pos":"adjective","senses":[{"en":"giving or willing to give freely; given freely","cn":"慷慨的；大方的；慷慨给予的","ex":{"en":"The gallery was named after its most generous benefactor.","cn":"该画廊以其最慷慨的捐助者的名字命名。"}},{"en":"more than is necessary; large","cn":"丰富的；充足的；大的","ex":{"en":"a generous helping of meat","cn":"一大份肉"}},{"en":"kind in the way you treat people; willing to see what is good about somebody/something","cn":"宽厚的；宽宏大量的；仁慈的","ex":{"en":"a generous mind","cn":"宽阔的胸怀"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（尤指在钱财上）慷慨的，大方的","en":"A generous person gives more of something, especially money, than is usual or expected.","ex":{"en":"German banks are more generous in their lending","cn":"德国银行的借贷条件更为宽松。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"宽厚的；仁慈的；宽宏大量的","en":"A generous person is friendly, helpful, and willing to see the good qualities in someone or something.","ex":{"en":"He was always generous in sharing his enormous knowledge","cn":"他从不吝啬与人分享自己渊博的知识。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"丰富的；大量的；充足的","en":"A generous amount of something is much larger than is usual or necessary.","ex":{"en":"...a generous six weeks of annual holiday","cn":"充裕的6个星期长的年假"}}]},"examples":[{"en":"He wrote a very generous assessment of my work.","cn":"他给我写的工作评价多有赞誉之词。"},{"en":"It was generous of him to offer to pay for us both.","cn":"他主动为我们俩付钱，真是大方。"}]},"gonna":{"media":{"uk":"media/uk/gonna__gb_1.mp3","us":"media/us/gonna__us_1.mp3"},"oxford":{"phon":"ˈɡənə","pos":"","senses":[{"en":"a way of saying or writing ‘going to’ in informal speech, when it refers to the future","cn":"即将，将要（非正式用语，即 going to）","ex":{"en":"What's she gonna do now?","cn":"她现在要干什么？"}}]},"collins":{"senses":[{"pos":"","cn":"（用于书面英语中表示going to的非正式发音形式）","en":"Gonna is used in written English to represent the words 'going to' when they are pronounced informally.","ex":{"en":"Then, what am I gonna do?","cn":"那么，我该怎么办呢？"}}]},"examples":[{"en":"What's she gonna do now?","cn":"她现在要干什么？"},{"en":"This isn’t gonna be easy.","cn":"这事不容易。"}]},"genuine":{"media":{"uk":"media/uk/genuine__gb_1.mp3","us":"media/us/genuine__us_1.mp3"},"oxford":{"phon":"ˈdʒenjuɪn","pos":"adjective","senses":[{"en":"real; exactly what it appears to be; not artificial","cn":"真的；名副其实的","ex":{"en":"Is the painting a genuine Picasso?","cn":"这幅画是毕加索的真迹吗？"}},{"en":"sincere and honest; that can be trusted","cn":"真诚的；真心的；可信赖的","ex":{"en":"He made a genuine attempt to improve conditions.","cn":"他真心实意地努力改善环境。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"真正的；非伪造的；名副其实的","en":"Genuine is used to describe people and things that are exactly what they appear to be, and are not false or an imitation.","ex":{"en":"There was a risk of genuine refugees being returned to Vietnam.","cn":"存在将真正的难民遣返回越南的风险。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"真挚的；真诚的；诚挚的","en":"Genuine refers to things such as emotions that are real and not pretended.","ex":{"en":"There was genuine joy in this room","cn":"房间里洋溢着发自内心的快乐。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"真诚的；诚实可靠的；诚恳的","en":"If you describe a person as genuine, you approve of them because they are honest, truthful, and sincere in the way they live and in their relationships with other people.","ex":{"en":"She is very caring and very genuine.","cn":"她非常体贴，非常诚实可靠。"}}]},"examples":[{"en":"Fake designer watches are sold at a fraction of the price of the genuine article.","cn":"伪造的名牌手表以真品若干分之一的价格出售。"},{"en":"Only genuine refugees can apply for asylum.","cn":"只有真正的难民才能申请政治避难。"}]},"guidebooks":{"lemma":"guidebook","media":{"uk":"media/uk/guidebook__gb_1.mp3","us":"media/us/guidebook__us_1.mp3"}},"grams":{"lemma":"gram"},"generated":{"lemma":"generate"},"goals":{"lemma":"goal"},"gets":{"lemma":"get"},"glanced":{"lemma":"glance"},"gourmets":{"oxford":{"phon":"ˈɡʊəmeɪ","pos":"noun","senses":[{"en":"a person who knows a lot about good food and wines and who enjoys choosing, eating and drinking them","cn":"美食家；讲究饮食的人；美酒美食品尝家"}]}},"globes":{"lemma":"globe"},"gorillas":{"lemma":"gorilla"},"graced":{"lemma":"grace"},"gleamed":{"lemma":"gleam"},"grounds":{"lemma":"ground"},"governors":{"lemma":"governor"},"graduates":{"lemma":"graduate"},"grasses":{"lemma":"grass"},"giants":{"lemma":"giant"},"glances":{"lemma":"glance"},"groped":{"lemma":"grope"},"generating":{"lemma":"generate"},"grains":{"lemma":"grain"},"greater":{"lemma":"great"},"gardens":{"lemma":"garden"},"giving":{"lemma":"give","media":{"uk":"media/ldoce/hwd/bre/b/ld41giving.mp3","us":"media/ldoce/hwd/ame/b/laadgiving.mp3"}},"glasses":{"lemma":"glass","media":{"img":["media/ldoce/img/glasses.jpg"]}},"gifts":{"lemma":"gift"},"greens":{"lemma":"green"},"gratings":{"lemma":"grate"},"garages":{"lemma":"garage"},"guides":{"lemma":"guide"},"gasping":{"lemma":"gasp"},"genres":{"oxford":{"phon":"ˈʒɒ̃rə","pos":"noun","senses":[{"en":"a particular type or style of literature, art, film or music that you can recognize because of its special features （","cn":"文学、艺术、电影或音乐的）体裁，类型"}]}},"glimpses":{"lemma":"glimpse"},"guests":{"lemma":"guest"},"generations":{"lemma":"generation"},"gallons":{"lemma":"gallon"},"guaranteeing":{"lemma":"guarantee"},"globalized":{"oxford":{"phon":"ˈɡləʊbəlaɪz","pos":"verb","senses":[{"en":"( economics","cn":"经 ) if sth, for example a business company, globalizes or is globalized , it operates all around the world （使）全球化，全世界化"}]}},"gained":{"lemma":"gain"},"greeted":{"lemma":"greet"},"gangs":{"lemma":"gang"},"gambler":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"赌徒；赌棍","en":"A gambler is someone who gambles regularly, for example in card games or horse racing."},{"pos":"N-COUNT 可数名词","cn":"冒险主义者；投机者","en":"If you describe someone as a gambler, you mean that they are ready to take risks in order to gain advantages or success.","ex":{"en":"He had never been afraid of failure: he was a gambler, ready to go off somewhere else and start all over again.","cn":"他从来都不害怕失败：他是个冒险家，随时准备到别处从头再来。"}}]},"media":{"uk":"media/ldoce/hwd/bre/e/gamble_v0205.mp3","us":"media/ldoce/hwd/ame/1/gamble1.mp3"},"examples":[{"en":"Their religion forbids them to drink or gamble.","cn":""},{"en":"Jack loves gambling on the horses.","cn":""}],"oxford":{"phon":"ˈɡæmblə(r)","pos":"noun","senses":[{"en":"a person who risks money on a card game, horse race, etc.","cn":"（牌戏、赛马等中）赌博，打赌","ex":{"en":"He was a compulsive gambler (= found it difficult to stop).","cn":"他嗜赌成性。"}},{"en":"a person who is willing to risk losing something in the hope of being successful","cn":"冒风险；碰运气；以…为赌注","ex":{"en":"She is an eternal optimist and gambler at heart.","cn":"她是一个永远的乐观主义者和内心的赌徒。"}}]}},"gains":{"lemma":"gain"},"gazing":{"lemma":"gaze"},"gardeners":{"lemma":"gardener"},"gathered":{"lemma":"gather"},"glimpsed":{"lemma":"glimpse"},"grandsons":{"lemma":"grandson"},"greeks":{"lemma":"greek"},"gossips":{"lemma":"gossip"},"glided":{"lemma":"glide"},"germans":{"lemma":"german"},"guaranteed":{"lemma":"guarantee"},"gives":{"lemma":"give"},"gentlemen":{"lemma":"gentleman"},"grades":{"lemma":"grade"},"grooms":{"lemma":"groom"},"goes":{"lemma":"go"},"garnished":{"oxford":{"phon":"ˈɡɑːnɪʃ","pos":"verb","senses":[{"en":"to decorate a dish of food with a small amount of another food （","cn":"用菜）为（食物）加装饰；加饰菜于"},{"en":"a small amount of food that is used to decorate a larger dish of food （","cn":"食物上的）装饰菜"}]}},"glassed":{"lemma":"glass"},"groups":{"lemma":"group"},"generates":{"lemma":"generate"},"greatest":{"lemma":"great"},"governments":{"lemma":"government"},"groping":{"lemma":"grope"},"gazed":{"lemma":"gaze"},"greener":{"lemma":"green"},"guarantees":{"lemma":"guarantee"},"glistening":{"oxford":{"phon":"ˈɡlɪsn","pos":"verb","senses":[{"en":"to shine","cn":"闪光；闪亮"}]}},"games":{"lemma":"game"},"gash":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"深长的伤口（或切口）","en":"A gash is a long, deep cut in your skin or in the surface of something.","ex":{"en":"There was an inch-long gash just above his right eye.","cn":"就在他右眼的上方有一条一英寸长的伤口。"}},{"pos":"VERB 动词","cn":"划伤；砍伤","en":"If you gash something, you accidentally make a long and deep cut in it.","ex":{"en":"He gashed his leg while felling trees.","cn":"他砍树的时候砍伤了腿。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"damage to part of your body caused by an accident or an attack","cn":""},{"en":"an injury, especially a deep cut in your skin made by a knife, bullet, or bomb","cn":""},{"en":"a small injury made when a sharp object cuts your skin","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"A gash is a deep cut, like a gash on your knee from a biking accident, or a gash in the earth caused by workers who are digging up a broken sewer."}]},"collocations":{"phrases":["ADJ. deep, great, long | nasty, terrible","VERB + GASH get, have","PREP. on the ~ She got a nasty gash on the head. 2 large hole","ADJ. deep, great, long","VERB + GASH carve, cut, tear The bulldozers carved a great gash through the forest. The rocks tore a long gash in the ship's hull."]},"media":{"uk":"media/ldoce/hwd/bre/1/gash0205.mp3","us":"media/ldoce/hwd/ame/8/gash.mp3"},"examples":[{"en":"He gashed his hand on a sharp piece of rock.","cn":"他的手在一块尖石头上划了一个大口子。"},{"en":"Blood poured from a deep gash in her forehead.","cn":"鲜血从她额头上一道很深的伤口汩汩地流出来。"}],"oxford":{"phon":"ɡæʃ","pos":"noun","senses":[{"en":"a long deep cut in the surface of something, especially a person’s skin","cn":"深长的切口（或伤口、划伤）","ex":{"en":"He needed an operation to close a nasty gash in his arm.","cn":"他需要接受手术来缝合手臂上的一道严重伤口。"}},{"en":"to make a long deep cut in something, especially a person’s skin","cn":"划伤，砍伤（尤指人的皮肤）","ex":{"en":"He gashed his hand on a sharp piece of rock.","cn":"他的手在一块尖石头上划了一个大口子。"},"pos":"verb"}]}},"gangrene":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"坏疽","en":"Gangrene is the decay that can occur in a part of a person's body if the blood stops flowing to it, for example as a result of illness or injury.","ex":{"en":"Once gangrene has developed the tissue is dead.","cn":"一旦出现坏疽，机体组织便已死亡。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a condition in which your flesh decays in part of your body, because blood has stopped flowing there as a result of illness or injury","cn":"坏疽"}]},"vocab":{"pos":"n v","senses":[{"en":"You don't want gangrene, that's for sure. It's the infection that can develop around a wound that kills the tissue, turning it into a terrible stinking sore."}]},"collocations":{"phrases":["VERB + GANGRENE have, suffer from | develop","GANGRENE + VERB set in The wound was not properly disinfected and gangrene set in. •"]},"media":{"uk":"media/ldoce/hwd/bre/2/gangrene0205.mp3","us":"media/ldoce/hwd/ame/4/gangrene.mp3"},"examples":[{"en":"Gangrene set in and he had to have his leg amputated.","cn":"他的腿生了坏疽，必须截除。"}],"oxford":{"phon":"ˈɡæŋɡriːn","pos":"noun","senses":[{"en":"the decay (= a process of being destroyed) that takes place in a part of the body when the blood supply to it has been stopped because of an illness or injury","cn":"坏疽","ex":{"en":"Gangrene set in and he had to have his leg amputated.","cn":"他的腿生了坏疽，必须截除。"}}]}},"gloss":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"光泽；色泽；光亮","en":"A gloss is a bright shine on the surface of something.","ex":{"en":"Rain produced a black gloss on the asphalt.","cn":"雨后的柏油路面显得黑亮黑亮的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"虚假的外表；假象；虚饰","en":"Gloss is an appearance of attractiveness or good quality which sometimes hides less attractive features or poor quality.","ex":{"en":"Television commercials might seem more professional but beware of mistaking the gloss for the content.","cn":"电视广告看上去或许更加专业，但要当心，不要把表象误以为真。"}},{"pos":"N-SING 单数名词","cn":"粉饰；掩饰","en":"If you put a gloss on a bad situation, you try to make it seem more attractive or acceptable by giving people a false explanation or interpretation of it.","ex":{"en":"He used his diary to put a fine gloss on the horrors the regime perpetrated","cn":"他假借日记对该政权犯下的恐怖罪行巧加粉饰。"}},{"pos":"N-MASS 物质名词","cn":"同gloss paint","en":"Gloss is the same as gloss paint ."},{"pos":"N-MASS 物质名词","cn":"唇彩；亮彩化妆品","en":"Gloss is a type of shiny make-up.","ex":{"en":"She brushed gloss on to her eyelids.","cn":"她在眼睑上涂了些亮彩眼影。"}},{"pos":"VERB 动词","cn":"解释；诠释；说明","en":"If you gloss a difficult word or idea, you provide an explanation of it.","ex":{"en":"Older editors glossed 'drynke' as 'love-potion'.","cn":"老编辑将drynke注释为love-potion（春药）。"}},{"pos":"","cn":"","en":"相关词组：gloss over"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a soft, smooth, shiny appearance","cn":""},{"en":"the shiny appearance of something that is of good quality or in good condition","cn":""},{"en":"a soft, attractive, shiny appearance","cn":""}]},"vocab":{"pos":"1 n v 2 v n","senses":[{"en":"A gloss is a shiny finish on an object. It’s also an explanation about a word or phrase. Right now, you’re reading a gloss on the word gloss ."}]},"collocations":{"phrases":["ADJ. clear, high Use a high gloss paint. | healthy, natural Your hair has lost its natural gloss.","VERB + GLOSS add We used a gel to add gloss to her hair. | lose","GLOSS + NOUN finish, paint, varnish furniture with a dark gloss finish"]},"media":{"uk":"media/ldoce/hwd/bre/d/gloss_n0205.mp3","us":"media/ldoce/hwd/ame/5/gloss1.mp3"},"examples":[{"en":"Beneath the gloss of success was a tragic private life.","cn":"在成功的外表下面却隐藏着悲惨的私人生活。"},{"en":"You can have the photos with either a gloss or a matt finish.","cn":"你可选择用光面或布面相纸洗印这些照片。"}],"oxford":{"phon":"ɡlɒs","pos":"noun","senses":[{"en":"a shine on a smooth surface","cn":"（平滑表面上的）光泽，光亮","g":"[uncountable, singular]","ex":{"en":"paper with a high gloss on one side","cn":"单面上光纸"}},{"en":"a substance designed to make something shiny","cn":"用以产生光泽的物质","g":"[uncountable]","ex":{"en":"lip gloss","cn":"唇彩"}},{"en":"paint which, when dry, has a hard shiny surface","cn":"光泽涂料；亮光漆","g":"[uncountable]","ex":{"en":"two coats of gloss","cn":"两层亮光漆"}},{"en":"an attractive appearance that is only on the surface and hides what is not so attractive","cn":"虚假的外表；虚饰","g":"[uncountable, singular]","ex":{"en":"Beneath the gloss of success was a tragic private life.","cn":"在成功的外表下面却隐藏着悲惨的私人生活。"}},{"en":"a way of explaining something to make it seem more attractive or acceptable","cn":"精彩的解释（或阐述）","g":"[countable]","ex":{"en":"The director puts a Hollywood gloss on the civil war.","cn":"导演对内战作了一番好莱坞式的精彩阐述。"}},{"en":"a note or comment added to a piece of writing to explain a difficult word or phrase","cn":"注释；评注","g":"[countable]"},{"en":"to add a note or comment to a piece of writing to explain a difficult word or idea","cn":"在…上作注释（或评注）","pos":"verb"}]}},"gland":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"腺","en":"A gland is an organ in the body which produces chemical substances for the body to use or get rid of.","ex":{"en":"...the hormones secreted by our endocrine glands.","cn":"人体内分泌腺分泌的荷尔蒙"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an organ of the body which produces a substance that the body needs, such as hormone s , sweat , or saliva","cn":"腺"}]},"collocations":{"phrases":["ADJ. enlarged, swollen She's gone to bed with swollen glands and a temperature. | adrenal, endocrine, exocrine, pineal, pituitary, prostate,","GLAND + VERB release sth, secrete sth"]},"media":{"uk":"media/ldoce/hwd/bre/1/gland0205.mp3","us":"media/ldoce/hwd/ame/2/gland.mp3"},"examples":[{"en":"Her glands are swollen.","cn":"她的腺体肿胀。"},{"en":"a snake's poison glands","cn":"蛇的毒腺"}],"oxford":{"phon":"ɡlænd","pos":"noun","senses":[{"en":"an organ in a person’s or an animal’s body that produces a substance for the body to use; a part in the body that is similar to this, especially a lymph node","cn":"腺","ex":{"en":"a snake’s poison glands","cn":"蛇的毒腺"}}]}},"generalize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"概括；归纳；作出类推","en":"If you generalize, you say something that seems to be true in most situations or for most people, but that may not be completely true in all cases.","ex":{"en":"'In my day, children were a lot better behaved'. — 'It's not true, you're generalizing'","cn":"“我们那个时候，孩子们要比现在听话许多。”——“不一定，你只是在一概而论。”"}},{"pos":"VERB 动词","cn":"推广；普及；扩大…的运用","en":"If you generalize something such as an idea, you apply it more widely than its original context, as if it was true in many other situations.","ex":{"en":"A child first labels the household pet cat as a 'cat' and then generalises this label to other animals that look like it.","cn":"孩子会先把家中的宠物猫称为“猫”，然后将其他像猫的动物都称为“猫”。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"an opinion or way of thinking about something that is simplistic treats difficult things in too simple a way","cn":""},{"en":"to say that something is true of all the people in a group simply because it is true of some of them","cn":""},{"en":"if someone sees things in black and white , they tend to judge people in a very simple way as being either completely bad or completely good, completely right or completely wrong etc","cn":""}]},"vocab":{"pos":"1 v 2 v 3 v","senses":[{"en":"To generalize is to use specific examples to make broader points. Generalizing makes large points, though they aren't always necessarily true."}]},"collocations":{"phrases":["VERB + GENERALIZE can/could | be easy to, be possible to | be difficult to, be hard to, be impossible to | be dangerous to, be unsafe to, be","PREP. about It is impossible to generalize about such a complicated subject. | from We cannot generalize from these few examples."]},"media":{"uk":"media/ldoce/hwd/bre/4/generalize0205.mp3","us":"media/ldoce/hwd/ame/a/laadgeneralize.mp3"},"examples":[{"en":"It would be foolish to generalize from a single example.","cn":"仅从一个事例进行归纳的做法是愚蠢的。"},{"en":"It is dangerous to generalize about the poor.","cn":"对穷人一概而论是危险的。"}],"oxford":{"phon":"ˈdʒenrəlaɪz","pos":"verb","senses":[{"en":"to use a particular set of facts or ideas in order to form an opinion that is considered relevant to a different situation","cn":"概括；归纳","g":"[intransitive]","ex":{"en":"It would be foolish to generalize from a single example.","cn":"仅从一个事例进行归纳的做法是愚蠢的。"}},{"en":"to make a general statement about something and not look at the details","cn":"笼统地讲；概括地谈论","g":"[intransitive]","ex":{"en":"It is dangerous to generalize about the poor.","cn":"对穷人一概而论是危险的。"}},{"en":"to apply a theory, idea, etc. to a wider group or situation than the original one","cn":"扩大…的运用；将…类推到（较大的范围）","g":"[transitive, often passive]","lab":"formal","ex":{"en":"These conclusions cannot be generalized to the whole country.","cn":"这些结论不能推及全国。"}}]}},"gender":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"性；性别","en":"A person's gender is the fact that they are male or female.","ex":{"en":"Women are sometimes denied opportunities solely because of their gender.","cn":"妇女有时仅仅因为性别而无法获得种种机会。"}},{"pos":"N-COUNT 可数名词","cn":"（统称）男性，女性","en":"You can refer to all male people or all female people as a particular gender.","ex":{"en":"While her observations may be true about some men, they could hardly apply to the entire gender.","cn":"虽然她的评论就某些男人而言可能是正确的，但绝不适用于所有男性。"}},{"pos":"N-VAR 可变名词","cn":"（语法中名词、代词或形容词的）性","en":"In grammar, the gender of a noun, pronoun, or adjective is whether it is masculine, feminine, or neuter. A word's gender can affect its form and behaviour. In English, only personal pronouns such as 'she', reflexive pronouns such as 'itself', and possessive determiners such as 'his' have gender.","ex":{"en":"In both Welsh and Irish the word for 'moon' is of feminine gender.","cn":"在威尔士语和爱尔兰语中，表示“月亮”的词是阴性的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone's sex is whether they are male or female","cn":""},{"en":"someone's gender is whether they are male or female - used especially in writing about politics and society, or in job advertisements","cn":""},{"en":"relating to the differences between male and female or the characteristics of men or women","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"The noun gender refers to the state of being male or female. Danica Patrick is someone who has broken many gender barriers by being a successful female race-car driver in a male-dominated sport."}]},"collocations":{"phrases":["GENDER + NOUN relations | differences, divisions She examines the interplay between changing gender divisions and urban change. | bias, imba"]},"media":{"uk":"media/ldoce/hwd/bre/f/gender0205.mp3","us":"media/ldoce/hwd/ame/4/gender.mp3"},"examples":[{"en":"If in doubt, ask your doctor. He/she can give you more information.","cn":"如有疑问请向你的医生咨询，他/她会给你更多的信息。"},{"en":"In French the adjective must agree with the noun in number and gender.","cn":"法语中形容词必须在数和性上与名词一致。"}],"oxford":{"phon":"ˈdʒendə(r)","pos":"noun","senses":[{"en":"the fact of being male or female, especially when considered with reference to social and cultural differences, rather than differences in biology; members of a particular gender as a group","cn":"性别（尤指社会和文化差异，而非生理差异）","g":"[uncountable, countable]","lab":"British English","ex":{"en":"issues of class, race and gender","cn":"阶级、种族和性别问题"}},{"en":"each of the classes (masculine, feminine and sometimes neuter) into which nouns, pronouns and adjectives are divided; the division of nouns, pronouns and adjectives into these different genders. Different genders may have different endings, etc.","cn":"性（阳性、阴性和中性，不同的性有不同的词尾等）","g":"[countable, uncountable]","lab":"grammar","ex":{"en":"In French the adjective must agree with the noun in number and gender.","cn":"法语中形容词必须在数和性上与名词一致。"}}]}},"gibraltarian":{"lemma":"gibraltar","media":{"uk":"media/ldoce/hwd/bre/9/lpd_gibraltar.mp3","us":"media/ldoce/hwd/ame/6/p028-000005374.mp3"}},"gunfire":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"炮火；炮击","en":"Gunfire is the repeated shooting of guns.","ex":{"en":"The sound of gunfire and explosions grew closer.","cn":"枪炮声和爆炸声越来越近。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the noise made by a gun when it is fired","cn":""},{"en":"the sound made by several guns being fired, especially in a war","cn":""},{"en":"an attempt to shoot someone or something","cn":""}]},"collocations":{"phrases":["ADJ. heavy, intense | scattered, sporadic | indiscriminate Seventy protesters were killed by indiscriminate gunfire. | distant | automatic W","QUANT. burst A burst of gunfire echoed across the square.","VERB + GUNFIRE hear | spray sb/sth with The terrorists boarded the bus and sprayed the passengers with gunfire. | be hit/wounded by A convoy","GUNFIRE + VERB break out Heavy gunfire broke out in the capital last night. | echo","PHRASES the crack/crackle/rattle/sound of gunfire, an exchange of gunfire They were killed in an exchange of gunfire between riot police and"]},"media":{"uk":"media/ldoce/hwd/bre/e/gunfire0205.mp3","us":"media/ldoce/hwd/ame/3/gunfire.mp3"},"examples":[{"en":"I could hear gunfire.","cn":"我可以听到炮声。"},{"en":"an exchange of gunfire with the police","cn":"与警方的交火"}],"oxford":{"phon":"ˈɡʌnfaɪə(r)","pos":"noun","senses":[{"en":"the repeated firing of guns; the sound of guns firing","cn":"（接连不断的）炮火，炮火声","ex":{"en":"an exchange of gunfire with the police","cn":"与警方的交火"}}]}},"gull":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（海）鸥","en":"A gull is a common sea bird."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large common black and white sea bird that lives near the sea","cn":"海鸥"}]},"vocab":{"pos":"1 n 2 n v","senses":[{"en":"You know those birds that hang out by the ocean, and grab your sandwich if you aren't paying attention? Those are gulls , also known as sea gulls. Gulls are found in every continent, including Antarctica."}]},"media":{"img":["media/ldoce/img/gull.jpg","media/thumb/gull.jpg"],"uk":"media/ldoce/hwd/bre/7/gull0205.mp3","us":"media/ldoce/hwd/ame/c/gull1.mp3"},"oxford":{"phon":"ɡʌl","pos":"noun","senses":[{"en":"a seabird with long wings and usually white and grey or black feathers. There are several types of gull.","cn":"海鸥","ex":{"en":"a black-headed gull","cn":"黑头鸥"}}]}},"grimace":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（因厌恶、痛苦等）做鬼脸，扮怪相，脸部扭曲","en":"If you grimace, you twist your face in an ugly way because you are annoyed, disgusted, or in pain.","ex":{"en":"She started to sit up, grimaced, and sank back weakly against the pillow","cn":"她坐了起来，露出痛苦的表情，又有气无力地倒在枕头上。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to twist your face in an ugly way because you do not like something, because you are feeling pain, or because you are trying to be funny 〔","cn":"因不喜欢某物﹑感到疼痛或开玩笑时〕做鬼脸﹐扮怪相"},{"en":"the expression on your face when you move your eyebrows together because you are angry, unhappy, or confused","cn":""},{"en":"an expression in which your mouth curves upwards, when you are being friendly or are happy or amused","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"The grimace on her face when he asked her to the prom told him her answer was \"no\" before she said a word. A grimace is a facial expression that usually suggests disgust or pain, but sometimes comic exaggeration."}]},"collocations":{"phrases":["ADJ. little, slight, small | ugly | rueful, wry | facial","VERB + GRIMACE give, make She made a wry grimace. | twist into His face twisted into a grimace.","GRIMACE + VERB twist sth An ugly grimace twisted her face.","PREP. with a ~ He acknowledged his mistake with a wry grimace. | ~ of a grimace of disgust/pain"]},"media":{"uk":"media/ldoce/hwd/bre/1/grimace_las3_br.mp3","us":"media/ldoce/hwd/ame/6/grimace1.mp3"},"examples":[{"en":"‘What's that?’ she asked with a grimace. “","cn":"那是什么？”她皱着眉头问道。"},{"en":"He grimaced at the bitter taste.","cn":"他一尝那苦味，做了个怪相。"}],"oxford":{"phon":"ˈɡrɪməs","pos":"verb","senses":[{"en":"to make an ugly expression with your face to show pain, dislike, etc.","cn":"（因痛苦、厌恶等）做鬼脸，做怪相","ex":{"en":"He grimaced at the bitter taste.","cn":"他一尝那苦味就做了个怪相。"}},{"en":"an ugly expression made by twisting your face, used to show pain, dislike, etc. or to make somebody laugh","cn":"怪相；鬼脸；脸部扭曲","ex":{"en":"to make/give a grimace of pain","cn":"做出／露出痛苦的表情"},"pos":"noun"}]}},"gallop":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）（马）飞奔；（使）（马）疾驰","en":"When a horse gallops, it runs very fast so that all four legs are off the ground at the same time. If you gallop a horse, you make it gallop.","ex":{"en":"The horses galloped away","cn":"群马飞奔而去。"}},{"pos":"VERB 动词","cn":"骑马奔驰；策马飞奔","en":"If you gallop, you ride a horse that is galloping.","ex":{"en":"Major Winston galloped into the distance.","cn":"温斯顿少校策马疾驰而去。"}},{"pos":"N-SING 单数名词","cn":"骑马奔驰","en":"A gallop is a ride on a horse that is galloping.","ex":{"en":"I was forced to attempt a gallop.","cn":"我被迫试着骑马飞奔。"}},{"pos":"VERB 动词","cn":"飞速发展；高速增长","en":"If something such as a process gallops, it develops very quickly and is often difficult to control.","ex":{"en":"In spite of the recession, profits have galloped ahead.","cn":"尽管还处于萧条期，利润却迅猛增长。"}},{"pos":"VERB 动词","cn":"迅速奔跑；飞奔","en":"If you gallop, you run somewhere very quickly.","ex":{"en":"They are galloping around the garden playing football.","cn":"他们在园子里飞跑着踢足球。"}},{"pos":"PHRASE 短语","cn":"迅速地；飞快地","en":"If you do something at a gallop, you do it very quickly.","ex":{"en":"I read the book at a gallop.","cn":"我飞快地读完了这本书。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to run fairly slowly, taking short steps – used especially about horses and dogs","cn":""},{"en":"if a horse gallops, it runs very quickly","cn":""},{"en":"to suddenly run somewhere very fast, especially in order to escape","cn":""}]},"collocations":{"phrases":["ADJ. fast, good, head-down, mad | steady","VERB + GALLOP break into The horses broke into a mad gallop when they heard the gunshot.","PREP. at a ~ They reached the farm at a gallop. | into a ~ The noise startled the horse into a gallop. | ~ through (figurative) The programm","PHRASES at full gallop riders coming at full gallop"]},"media":{"uk":"media/ldoce/hwd/bre/f/gallop0703.mp3","us":"media/ldoce/hwd/ame/9/gallop1.mp3"},"examples":[{"en":"Jo galloped across the field towards him.","cn":"乔骑马穿过田野向他奔去。"},{"en":"My horse suddenly broke into a gallop.","cn":"我的马突然飞奔起来。"}],"oxford":{"phon":"ˈɡæləp","pos":"verb","senses":[{"en":"when a horse or similar animal gallops, it moves very fast and each stride includes a stage when all four feet are off the ground together","cn":"（马等）飞奔，奔驰，疾驰","g":"[intransitive]","ex":{"en":"The terrified horse galloped off.","cn":"那匹受惊的马飞奔而去。"}},{"en":"to ride a horse very fast, usually at a gallop","cn":"骑马奔驰；使（马）飞奔","g":"[intransitive, transitive]","ex":{"en":"Jo galloped across the field towards him.","cn":"乔骑马穿过田野向他奔去。"}},{"en":"to run very quickly","cn":"飞跑；奔跑","g":"[intransitive]","lab":"informal","ex":{"en":"She came galloping down the street.","cn":"她沿街飞奔而来。"}},{"en":"the fastest speed at which a horse can run, with a stage in which all four feet are off the ground together","cn":"（马的）飞奔，奔驰，疾驰","g":"[singular]","ex":{"en":"He rode off at a gallop.","cn":"他骑马疾驰而去。"},"pos":"noun"},{"en":"a ride on a horse at its fastest speed","cn":"骑马奔驰","g":"[countable]","ex":{"en":"to go for a gallop","cn":"去骑马奔驰一番"},"pos":"noun"},{"en":"an unusually fast speed; the act of doing something at an unusually fast speed","cn":"高速度；极快的动作","g":"[singular]","ex":{"en":"She always lives life at a gallop.","cn":"她一直过着快节奏的生活。"},"pos":"noun"}]}},"grunt":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（尤指因为烦恼或不感兴趣）咕噜，嘟哝着说","en":"If you grunt, you make a low sound, especially because you are annoyed or not interested in something.","ex":{"en":"The driver grunted, convinced that Michael was crazy","cn":"司机嘟哝了一声，认定迈克尔是发疯了。"}},{"pos":"VERB 动词","cn":"（动物）发出哼声，发出咕噜声","en":"When an animal grunts, it makes a low rough noise.","ex":{"en":"...the sound of a pig grunting.","cn":"猪发出的呼噜声"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say something very quietly, using your breath rather than your voice","cn":""},{"en":"to say something quietly, especially when you are annoyed but do not want someone to hear you complaining","cn":""},{"en":"to say something quietly without pronouncing the words clearly, so that it is difficult to understand","cn":""}]},"vocab":{"pos":"1 v n 2 n 3 n","senses":[{"en":"If your younger brother is particularly grouchy, he might simply grunt in answer to your question about whose turn it is to take out the garbage. A grunt is a short, deep sound."}]},"collocations":{"phrases":["ADJ. little | low | non-committal He gave a non-committal grunt in reply.","VERB + GRUNT give, let out | hear","PREP. with a ~ He lifted the heavy box with a grunt. | ~ of a grunt of pain • Note at SOUND"]},"media":{"uk":"media/ldoce/hwd/bre/e/grunt_v0205.mp3","us":"media/ldoce/hwd/ame/e/grunt1.mp3"},"examples":[{"en":"When I told her what had happened she just grunted and turned back to her book.","cn":"我告诉她出了什么事，她只哼了一声就又看起书来了。"},{"en":"He pulled harder on the rope, grunting with the effort.","cn":"他边用力边哼声，使出更大的力气拉绳子。"}],"oxford":{"phon":"ɡrʌnt","pos":"verb","senses":[{"en":"to make a short, low sound in the throat","cn":"发出呼噜声","g":"[intransitive]"},{"en":"to make a short, low sound in your throat, especially to show that you are in pain, annoyed or not interested; to say something using this sound","cn":"发出哼声；咕哝；嘟哝","g":"[intransitive, transitive]","ex":{"en":"He pulled harder on the rope, grunting with the effort.","cn":"他边用力边哼声，使出更大的力气拉绳子。"}},{"en":"a short, low sound made by a person or an animal (especially a pig)","cn":"哼声；咕哝声；嘟哝声；（尤指猪的）呼噜声","ex":{"en":"to give a grunt of effort/pain","cn":"发出费力／痛苦的哼声"},"pos":"noun"},{"en":"a worker who does boring tasks for low pay","cn":"工作乏味收入低的工人","lab":"North American English, informal，，","pos":"noun"},{"en":"a soldier of low rank","cn":"士兵；步兵","lab":"North American English, informal，，","pos":"noun"}]}},"grief":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"悲伤；悲痛","en":"Grief is a feeling of extreme sadness.","ex":{"en":"...a huge outpouring of national grief for the victims of the shootings","cn":"举国上下对枪击事件中的遇害者所表现出的万分悲痛之情"}},{"pos":"PHRASE 短语","cn":"（事情）失败；（人）受挫，遭到不幸","en":"If something comes to grief, it fails. If someone comes to grief, they fail in something they are doing, and may be hurt.","ex":{"en":"So many marriages have come to grief over lack of money","cn":"许多婚姻都因缺钱而以失败告终。"}},{"pos":"EXCLAM 感叹语","cn":"（表示惊奇或震惊）哎呀，天哪","en":"Some people say 'Good grief' when they are surprised or shocked.","ex":{"en":"'He's been arrested for theft and burglary.' — 'Good grief!'","cn":"“他因为偷窃和入室盗窃而被逮捕了。”——“我的天哪！”"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sad feeling, caused especially when a happy time is ending, or when you feel sorry about someone else’s unhappiness","cn":""},{"en":"the unhappy feeling you have when you are in a very difficult or unpleasant situation, especially when this lasts for a long time","cn":""},{"en":"the feeling of being very sad, especially because someone has died or because terrible things have happened to you","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Grief means intense sorrow. You feel grief if something terribly sad happens, like if your dog dies or if your childhood sweetheart breaks up with you."}]},"collocations":{"phrases":["ADJ. considerable, deep, great, inconsolable, real | private I felt awkward at intruding on their private grief.","VERB + GRIEF be overcome with, be stricken with, experience, feel Her parents were stricken with grief. | express, show | die from/of | come","PREP. ~ at Children can feel real grief at the loss of a pet. | ~ for her grief for her dead husband","PHRASES a feeling/sense of grief"]},"media":{"uk":"media/ldoce/hwd/bre/6/grief0205.mp3","us":"media/ldoce/hwd/ame/2/grief.mp3"},"examples":[{"en":"Several pedestrians came to grief on the icy pavement.","cn":"好几个人都在结了冰的人行道上摔伤了。"},{"en":"It was a grief to them that they had no children.","cn":"没有孩子是他们的一块心病。"}],"oxford":{"phon":"ɡriːf","pos":"noun","senses":[{"en":"a very sad feeling, especially when somebody dies","cn":"（尤指因某人去世引起的）悲伤，悲痛，伤心","g":"[uncountable, countable]","ex":{"en":"She was overcome with grief when her husband died.","cn":"丈夫去世时她悲痛欲绝。"}},{"en":"something that makes you feel very sad","cn":"伤心事；痛苦","g":"[countable, usually singular]","ex":{"en":"It was a grief to them that they had no children.","cn":"没有孩子是他们的一块心病。"}},{"en":"problems and worry","cn":"担心；忧虑","g":"[uncountable]","lab":"informal","ex":{"en":"He caused his parents a lot of grief.","cn":"他没少让父母操心。"}}]}},"glint":{"collins":{"senses":[{"pos":"VERB 动词","cn":"闪闪发光；闪亮","en":"If something glints, it produces or reflects a quick flash of light.","ex":{"en":"The sea glinted in the sun","cn":"阳光下的海面波光粼粼。"}},{"pos":"N-COUNT 可数名词","cn":"闪光；闪烁","en":"A glint is a quick flash of light.","ex":{"en":"...a glint of silver.","cn":"银光闪闪"}},{"pos":"VERB 动词","cn":"（眼睛）闪光，闪动，闪亮","en":"If someone's eyes glint, they shine and express a particular emotion.","ex":{"en":"Her eyes glinted wildly","cn":"她眼里流露出激动的神情。"}},{"pos":"N-SING 单数名词","cn":"（眼神的）闪光，闪动，闪亮","en":"A glint in someone's eyes is a brightness that expresses a particular emotion.","ex":{"en":"He came up to me with the glint of triumph in his eye.","cn":"他向我走来，眼里闪现出一丝胜利的神情。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something sparkles, it shines with many small bright points when light is on it","cn":""},{"en":"to shine by reflecting the light – used especially about smooth clean surfaces, or about someone’s eyes or teeth","cn":""},{"en":"to shine with quick flashes of light","cn":""}]},"vocab":{"pos":"1 n v 2 v","senses":[{"en":"A glint is a brief flash or flicker of light. You might enjoy gazing at the glint of light on the water as you lie on the beach in the summer time."}]},"collocations":{"phrases":["ADV. angrily His eyes glinted angrily.","PREP. with Her eyes glinted with amusement."]},"media":{"uk":"media/ldoce/hwd/bre/1/glint_n0205.mp3","us":"media/ldoce/hwd/ame/3/glint1.mp3"},"examples":[{"en":"Her eyes glinted angrily.","cn":"她眼睛里闪射着愤怒的目光。"},{"en":"The sun glinted on the windows.","cn":"太阳照在窗户上闪闪发光。"}],"oxford":{"phon":"ɡlɪnt","pos":"verb","senses":[{"en":"to produce small bright flashes of light","cn":"闪光；闪亮","g":"[intransitive]","ex":{"en":"The sea glinted in the moonlight.","cn":"月色中海面上波光粼粼。"}},{"en":"if a person’s eyes glint with a particular emotion, or an emotion glints in a person’s eyes, the person shows that emotion, which is usually a strong one","cn":"（眼睛）流露出（强烈情感）；（强烈情感在眼中）闪现","g":"[intransitive]","ex":{"en":"Her eyes glinted angrily.","cn":"她眼睛里闪射着愤怒的目光。"}},{"en":"a sudden flash of light or colour shining from a bright surface","cn":"闪光；闪亮","ex":{"en":"the glint of the sun on the water","cn":"太阳照在水上的闪光"},"pos":"noun"},{"en":"an expression in somebody’s eyes showing a particular emotion, often a negative one","cn":"（眼睛里某种感情，常指负面感情的）闪现","ex":{"en":"He had a wicked glint in his eye.","cn":"他眼睛里闪着邪恶的神色。"},"pos":"noun"}]}},"gymnast":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"体操运动员","en":"A gymnast is someone who is trained in gymnastics."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is good at gymnastics and competes against other people in gymnastics competitions","cn":"体操运动员"}]},"collocations":{"phrases":["ADJ. brilliant, expert, good | Olympic","GYMNAST + VERB train young gymnasts who have to train for up to five hours a day | compete, perform"]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41gymnast.mp3","us":"media/ldoce/hwd/ame/a/gymnast.mp3"},"oxford":{"phon":"ˈdʒɪmnæst","pos":"noun","senses":[{"en":"a person who performs gymnastics, especially in a competition","cn":"体操运动员","ex":{"en":"Young gymnasts have to train for up to five hours a day.","cn":"年轻的体操运动员每天必须训练长达五个小时。"}}]}},"gig":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"演唱会；演奏会；现场演出","en":"A gig is a live performance by someone such as a musician or a comedian.","ex":{"en":"The two bands join forces for a gig at the Sheffield Arena on November 28","cn":"11月28日，这两支乐队将携手在谢菲尔德剧场举办一场演唱会。"}},{"pos":"VERB 动词","cn":"（公开）表演，演奏","en":"When musicians or other performers gig, they perform live in public.","ex":{"en":"By the time he was 15, Scott had gigged with a handful of well-known small bands.","cn":"到15岁的时候，斯科特已经与几支闻名遐迩的小乐队同台演出过。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a performance given by musicians","cn":""},{"en":"to go to see a particular singer or band perform - use this especially about going to see modern popular musicians","cn":""},{"en":"when a musician or group of musicians performs a piece of music","cn":""}]},"collocations":{"phrases":["ADJ. benefit, charity | free | live | pub","VERB + GIG do, play (in) They're doing a gig in Leeds tonight. | go to","PREP. at a/the ~ They're performing at a local pub gig."]},"media":{"uk":"media/ldoce/hwd/bre/8/gig_n0205.mp3","us":"media/ldoce/hwd/ame/e/gig1.mp3"},"examples":[{"en":"a gig as a basketball coach","cn":"临时篮球教练"},{"en":"to do a gig","cn":"举行流行音乐演唱会"}],"oxford":{"phon":"ɡɪɡ","pos":"noun","senses":[{"en":"a performance by musicians playing popular music or jazz in front of an audience; a similar performance by a comedian","cn":"（流行音乐、爵士乐或喜剧）现场演出，现场表演","lab":"British English","ex":{"en":"They're doing a gig in Boston tonight.","cn":"他们今晚在波士顿表演。"}},{"en":"a job, especially a temporary one","cn":"（尤指临时的）工作","lab":"especially North American English, informal，，","ex":{"en":"She landed her first gig on a kids' TV show.","cn":"她在儿童电视节目中获得了第一场演出。"}},{"en":"a unit of computer memory or data, equal to 109, or 1 0003, (= 1000000000) bytes","cn":"十亿字节，吉字节，千兆字节（十进制计算机内存或数据单位，等于 1 000 000 000 字节）","lab":"informal"},{"en":"a unit of computer memory or data, equal to 230, or 1 0243, (= 1073741824) bytes","cn":"吉字节，千兆字节（二进制计算机内存或数据单位，等于 1 073 741 824 字节）","lab":"informal"},{"en":"a small light carriage with two wheels, pulled by one horse","cn":"单马双轮轻便马车"},{"en":"to give musical performances in front of audiences, especially of modern music like rock, pop or jazz","cn":"举办现场演出；进行现场表演","ex":{"en":"We were gigging two or three nights a week.","cn":"我们一周有两三个晚上要演出。"},"pos":"verb"}]}},"gradient":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"斜坡；坡度；倾斜度","en":"A gradient is a slope, or the degree to which the ground slopes.","ex":{"en":"...a gradient of 1 in 3","cn":"1比3的倾斜度"}},{"pos":"N-COUNT 可数名词","cn":"变化率","en":"The gradient of a graph or series of measurements is the rate at which one set of amounts changes in relation to another."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a slope or a degree of slope, especially in a road or railway 〔","cn":"尤指道路或铁路的〕斜坡﹐坡度"}]},"vocab":{"pos":"n","senses":[{"en":"The gradient of a surface is its slope. If you're a daredevil and you're looking for a road to fly down on your skateboard, you'll want to find one with a fairly steep gradient ."}]},"collocations":{"phrases":["ADJ. steep | gentle, slight | downhill, uphill","VERB + GRADIENT have The road has a fairly steep gradient.","PREP. on a ~ The football pitch was on a slight gradient."]},"media":{"uk":"media/ldoce/hwd/bre/9/gradient0205.mp3","us":"media/ldoce/hwd/ame/8/gradient.mp3"},"examples":[{"en":"a hill with a gradient of 1 in 4 (or 25%)","cn":"倾斜度为 1:4（或 25%）的小山"},{"en":"a steep gradient","cn":"陡峭的坡度"}],"oxford":{"phon":"ˈɡreɪdiənt","pos":"noun","senses":[{"en":"a slope on a road or railway; the degree to which the ground slopes","cn":"（公路或铁路的）坡；坡度；斜率；倾斜度","lab":"especially in North American English","ex":{"en":"The route includes some steep gradients.","cn":"该路线包括一些陡峭的坡度。"}},{"en":"the rate at which temperature, pressure, etc. changes, or increases and decreases, between one region and another","cn":"（温度、压力等的）变化率，梯度变化曲线","lab":"specialist"}]}},"gamut":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"整个范围；全部","en":"The gamut of something is the complete range of things of that kind, or a wide variety of things of that kind.","ex":{"en":"Varied though the anthology may claim to be, it does not cover the whole gamut of Scottish poetry","cn":"该诗集虽然可能号称收录广泛，但并未涵盖所有苏格兰诗歌。"}},{"pos":"PHRASE 短语","cn":"涉及…的全部范围","en":"To run the gamut of something means to include, express, or experience all the different things of that kind, or a wide variety of them.","ex":{"en":"The show runs the gamut of 20th century design","cn":"展览涵盖20世纪的各种设计。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a set of many different things of the same general type that are available in the same place for the same use","cn":""},{"en":"a complete range of different types of things or people, especially when those at one end of the range are the opposite of those at the other end","cn":""},{"en":"a number of different things of the same kind that are available for you to choose or use","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A visit with a long-lost cousin might arouse emotions that run the gamut of joy, regret, sorrow, and excitement. A gamut is a full or complete range."}]},"collocations":{"phrases":["ADJ. complete, entire, full, whole","VERB + GAMUT cover, run (through)","PREP. ~ of The exhibition runs the whole gamut of artistic styles."]},"media":{"uk":"media/ldoce/hwd/bre/a/gamut0205.mp3","us":"media/ldoce/hwd/ame/0/gamut.mp3"},"examples":[{"en":"The network will provide the gamut of computer services to your home.","cn":"这个网络将为家庭提供全方位的计算机服务。"},{"en":"She felt she had run the (whole) gamut of human emotions from joy to despair.","cn":"她感到自己尝遍了从喜到悲的七情六欲。"}]},"gasp":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指惊讶、震惊或疼痛时的）喘息，喘气，倒抽气","en":"A gasp is a short quick breath of air that you take in through your mouth, especially when you are surprised, shocked, or in pain.","ex":{"en":"An audible gasp went round the court as the jury announced the verdict","cn":"陪审团宣布判决的时候，听到法庭上有人倒抽了一口气。"}},{"pos":"VERB 动词","cn":"（尤指惊讶、震惊或疼痛时）喘息，喘气，倒抽气","en":"When you gasp, you take a short quick breath through your mouth, especially when you are surprised, shocked, or in pain.","ex":{"en":"She gasped for air and drew in a lungful of water","cn":"她喘了口气，吸入了一大口水。"}},{"pos":"PHRASE 短语","cn":"最终阶段；最后时刻","en":"You describe something as the last gasp to emphasize that it is the final part of something or happens at the last possible moment.","ex":{"en":"...the last gasp of a dying system of censorship","cn":"行将就木的审查制度的最终时刻"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to take air into your lungs and send it out again","cn":""},{"en":"to breathe out slowly and make a noise that shows you are disappointed, tired, relieved etc","cn":""},{"en":"to breathe quickly and noisily through your mouth, because you have been using a lot of effort","cn":""}]},"collocations":{"phrases":["ADJ. big, great | little, short, small | quick, sharp, sudden | loud | low | audible | shocked | strangled | involuntary","VERB + GASP give, let out | stifle | bring The stunt brought shocked gasps from the audience. | hear | take (in) taking in great gasps of ai","GASP + VERB escape sb","PREP. between ~s &lsquo;Listen carefully,&rsquo; he said, between gasps of breath. | in ~s He leant against the railing, his breath coming i"]},"media":{"uk":"media/ldoce/hwd/bre/c/gasp_v0205.mp3","us":"media/ldoce/hwd/ame/9/gasp1.mp3"},"examples":[{"en":"to give a gasp of horror/surprise/relief","cn":"惊恐得/吃惊得倒抽一口气；如释重负地松一口气"},{"en":"They gasped in astonishment at the news.","cn":"他们听到这消息惊讶得倒抽了一口气。"}],"oxford":{"phon":"ɡɑːsp","pos":"verb","senses":[{"en":"to take a quick deep breath with your mouth open, especially because you are surprised or in pain","cn":"（尤指由于惊讶或疼痛而）喘气，喘息，倒抽气","g":"[intransitive, transitive]","ex":{"en":"She gasped at the wonderful view.","cn":"如此美景使她惊讶得倒吸了一口气。"}},{"en":"to have difficulty breathing or speaking","cn":"透不过气；气喘吁吁地说","g":"[intransitive, transitive]","ex":{"en":"He came to the surface of the water gasping for air.","cn":"他浮出水面急促地喘着气。"}},{"en":"to want or need something very badly, especially a drink or a cigarette","cn":"渴望，很想要（尤指饮料或香烟）","g":"[intransitive]","lab":"British English, informal，，"},{"en":"a quick deep breath, usually caused by a strong emotion","cn":"（常指由强烈情感引起的）深吸气，喘息，倒抽气","ex":{"en":"to give a gasp of horror/surprise/relief","cn":"惊恐得／吃惊得倒抽一口气；如释重负地松一口气"},"pos":"noun"}]}},"glamorous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"富有魅力的；迷人的；令人向往的","en":"If you describe someone or something as glamorous, you mean that they are more attractive, exciting, or interesting than ordinary people or things.","ex":{"en":"...some of the world's most beautiful and glamorous women","cn":"全世界最漂亮迷人的一些女性"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"use this about a woman who is extremely attractive in a way that is fairly unusual and special, so that people notice and admire her","cn":""},{"en":"use this about a woman who is nice to look at and has an attractive face and body","cn":""},{"en":"use this about a young woman or girl who has an attractive face and is good-looking, but not in an unusual way","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Movie stars look glamorous when they walk down the red carpet in their designer gowns. Glamorous means full of glamour, beauty, and excitement."}]},"collocations":{"phrases":["VERBS be, feel, look, seem, sound | become | consider sth, regard sth as, see sth as Canoeing is not seen as glamorous in the way that skiin","ADV. really, very | less than, not exactly, not in the least Working in publishing turned out to be less than glamorous. | quite, rather"]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdeglamorous.mp3","us":"media/ldoce/hwd/ame/7/laadglamorous.mp3"},"examples":[{"en":"glamorous movie stars","cn":"富有魅力的影星"},{"en":"a glamorous job","cn":"令人向往的工作"}],"oxford":{"phon":"ˈɡlæmərəs","pos":"adjective","senses":[{"en":"especially attractive and exciting, and different from ordinary things or people","cn":"特别富有魅力的；富于刺激的；独特的","ex":{"en":"glamorous movie stars","cn":"富有魅力的影星"}}]}},"gut":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"内脏","en":"A person's or animal's guts are all the organs inside them.","ex":{"en":"By the time they finish, the crewmen are standing ankle-deep in fish guts.","cn":"到他们完工时，船员站的地方鱼内脏已堆至脚踝。"}},{"pos":"VERB 动词","cn":"取出（动物或鱼）的内脏（以备烹饪）","en":"When someone guts a dead animal or fish, they prepare it for cooking by removing all the organs from inside it.","ex":{"en":"It is not always necessary to gut the fish prior to freezing.","cn":"冷冻鱼之前并不总是需要先把内脏掏空。"}},{"pos":"N-SING 单数名词","cn":"肠；消化道","en":"The gut is the tube inside the body of a person or animal through which food passes while it is being digested."},{"pos":"N-UNCOUNT 不可数名词","cn":"勇气；胆量；决心","en":"Guts is the will and courage to do something which is difficult or unpleasant, or which might have unpleasant results.","ex":{"en":"The new Chancellor has the guts to push through unpopular tax increases","cn":"新总理有勇气推动不受欢迎的增税方案获得通过。"}},{"pos":"N-SING 单数名词","cn":"直觉；本能；感性","en":"A gut feeling is based on instinct or emotion rather than reason.","ex":{"en":"Let's have your gut reaction to the facts as we know them.","cn":"请告诉我们你对我们所了解的这些事实的本能反应。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指大而凸出的）肚子","en":"You can refer to someone's stomach as their gut, especially when it is very large and sticks out.","ex":{"en":"His gut sagged out over his belt.","cn":"他肚子上的赘肉堆在皮带上方。"}},{"pos":"N-PLURAL 复数名词","cn":"核心成分；本质；实质","en":"The guts of something, for example a subject or a machine, are the key elements of it, which make it work.","ex":{"en":"She has a reputation for getting at the guts of a subject and never pulling her punches","cn":"她以善抓问题实质、说话一针见血著称。"}},{"pos":"VERB 动词","cn":"损毁（建筑物）的内部","en":"To gut a building means to destroy the inside of it so that only its outside walls remain.","ex":{"en":"Over the weekend, a firebomb gutted a building where 60 people lived","cn":"本周，一颗燃烧弹炸毁了一栋有60位居民的楼房。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（用于制作球拍的网线、小提琴弦等的）肠线","en":"Gut is string made from part of the stomach of an animal. Traditionally, it is used to make the strings of sports rackets or musical instruments such as violins."},{"pos":"PHRASE 短语","cn":"努力（做…)","en":"To bust a gut means to work very hard trying to achieve something.","ex":{"en":"You can bust a gut sixteen hours a day, seven days a week, but if your product is lousy, you've wasted your time.","cn":"你可以一周7天、一天16小时地拼命劳作，但是如果产品质量低劣，你就白费时间了。"}},{"pos":"PHRASE 短语","cn":"对…恨之入骨","en":"If you hate someone's guts, you dislike them very much indeed.","ex":{"en":"We hate each other's guts.","cn":"我们彼此恨之入骨。"}},{"pos":"PHRASE 短语","cn":"告密；把所知和盘托出；倾诉心里话","en":"If someone spills their guts, they tell you everything about something secret or private.","ex":{"en":"People call in and just spill their guts about whatever's bothering them on the job or in a relationship.","cn":"人们打进电话，就是要将工作或感情上的所有困扰倾诉出来。"}},{"pos":"PHRASE 短语","cn":"拼命工作；拼命干活","en":"If you say that you are working your guts out or slogging your guts out, you are emphasizing that you are working as hard as you can.","ex":{"en":"Most have worked their guts out and made sacrifices.","cn":"大部分人都拼命工作，作出了很大的牺牲。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a man who has a paunch has a large stomach","cn":""},{"en":"a round stomach that sticks out at the front, especially when this is the result of eating or drinking too much","cn":""},{"en":"a fat stomach caused by drinking too much beer","cn":""}]},"collocations":{"phrases":["ADV. completely The hotel was completely gutted by fire last year."]},"media":{"uk":"media/ldoce/hwd/bre/9/gut_v0205.mp3","us":"media/ldoce/hwd/ame/e/gut1.mp3"},"examples":[{"en":"He doesn't have the guts to walk away from a well-paid job.","cn":"他没胆量辞去一份报酬优厚的工作。"},{"en":"I slogged my guts out for the exam.","cn":"我为这次考试命都豁出去了。"}],"oxford":{"phon":"ɡʌt","pos":"noun","senses":[{"en":"the tube in the body through which food passes when it leaves the stomach","cn":"肠道；消化道","g":"[countable]","ex":{"en":"It can take up to 72 hours for food to pass through the gut.","cn":"食物需经多达72小时才能通过消化道。"}},{"en":"the organs in and around the stomach, especially in an animal","cn":"（尤指动物的）内脏","g":"[plural]","ex":{"en":"I'll only cook fish if the guts have been removed.","cn":"鱼若已收拾干净，我只需烧一下即可。"}},{"en":"a person’s stomach, especially when it is large","cn":"（尤指大的）胃，肚子","g":"[countable]","lab":"informal","ex":{"en":"Have you seen the gut on him!","cn":"你看到他那大肚子了吧！"}},{"en":"the courage and strength of mind that it takes to do something difficult or unpleasant","cn":"勇气；胆量；决心；魄力","g":"[plural]","lab":"informal","ex":{"en":"He doesn't have the guts to walk away from a well-paid job.","cn":"他没胆量辞去一份报酬优厚的工作。"}},{"en":"the place where your natural feelings that make you react in a particular way are thought to be","cn":"内心；直觉；本能","g":"[countable, usually plural]","ex":{"en":"I had a feeling in my guts that something was wrong.","cn":"我本能地感到出了事。"}},{"en":"the most important part of something","cn":"核心；实质；要点","g":"[plural]","ex":{"en":"the guts of the problem","cn":"问题的实质"}},{"en":"thin strong string made from animals' intestines and used in making musical instruments, tennis rackets and medical equipment","cn":"肠线（用于制作乐器、球拍的弦和医疗用品）","g":"[uncountable]"},{"en":"to destroy the inside or contents of a building or room","cn":"损毁（建筑物或房屋的）内部","g":"[usually passive]","ex":{"en":"The hotel was completely gutted by fire last year.","cn":"该旅馆去年被大火完全烧空了。"},"pos":"verb"},{"en":"to remove the organs from inside a fish or an animal to prepare it for cooking","cn":"取出…的内脏（以便烹饪）","ex":{"en":"The fish was already cleaned and gutted.","cn":"鱼已经清洗干净，去内脏了。"},"pos":"verb"},{"en":"based on feelings and emotions rather than thought and reason","cn":"以感情为基础的；非理性的；本能的","ex":{"en":"a gut feeling/reaction","cn":"本能的感觉／反应"},"pos":"adjective"}]}},"giggle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"咯咯地笑；傻笑","en":"If someone giggles, they laugh in a childlike way, because they are amused, nervous, or embarrassed.","ex":{"en":"Both girls began to giggle","cn":"两个女孩都咯咯地笑了起来。"}},{"pos":"N-PLURAL 复数名词","cn":"傻笑","en":"If you say that someone has the giggles, you mean they cannot stop giggling.","ex":{"en":"I was so nervous I got the giggles","cn":"我紧张得傻笑起来。"}},{"pos":"N-SING 单数名词","cn":"趣事；玩笑","en":"If you say that something is a giggle, you mean it is fun or is amusing.","ex":{"en":"I might buy one for a friend's birthday as a giggle.","cn":"我可能会买一件送给朋友当生日礼物，逗他开心。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make sounds with your voice and move your face, because you think that something is funny","cn":""},{"en":"to laugh quickly in a high voice, especially in a slightly silly way, or because you are nervous or embarrassed","cn":""},{"en":"to laugh quietly, especially because you are thinking about or reading something funny","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"If you laugh with a dainty tee-hee-hee, you giggle . Children giggle a lot. Big strong men are more likely to guffaw or issue a big belly laugh."}]},"collocations":{"phrases":["ADV. helplessly, hysterically, nervously The children giggled hysterically.","PREP. about They giggled about their teacher's accident. | at We giggled at the picture. | over giggling over old photographs | with The chi","PHRASES a fit of giggling"]},"media":{"uk":"media/ldoce/hwd/bre/0/giggle_v0205.mp3","us":"media/ldoce/hwd/ame/3/giggle1.mp3"},"examples":[{"en":"Matt collapsed into giggles and hung up the phone.","cn":"马特突然咯咯笑起来，然后挂断了电话。"},{"en":"She had a fit of the giggles and had to leave the room.","cn":"她突然咯咯笑了起来，不得不走出房间。"}],"oxford":{"phon":"ˈɡɪɡl","pos":"verb","senses":[{"en":"to laugh in a silly way because you are embarrassed or nervous or you think that something is funny","cn":"（因感到有趣、窘迫或紧张而）咯咯地笑，傻笑","ex":{"en":"The girls giggled at the joke.","cn":"女孩子们给这笑话逗得咯咯笑。"}},{"en":"a slight, silly, repeated laugh","cn":"咯咯笑；傻笑","g":"[countable]","ex":{"en":"She gave a nervous giggle.","cn":"她发出紧张的傻笑。"},"pos":"noun"},{"en":"a thing that you think is funny","cn":"趣事；玩笑；可笑的事","g":"[singular]","lab":"British English, informal，，","ex":{"en":"We only did it for a giggle.","cn":"我们做那件事只是开个玩笑而已。"},"pos":"noun"},{"en":"continuous giggling that you cannot control or stop","cn":"止不住的咯咯笑","g":"[plural]","lab":"informal","ex":{"en":"I get the giggles when I'm nervous.","cn":"我紧张时就不停地咯咯大笑。"},"pos":"noun"}]}},"generosity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"慷慨；大方","en":"If you refer to someone's generosity, you mean that they are generous, especially in doing or giving more than is usual or expected.","ex":{"en":"There are stories about his generosity, the massive amounts of money he gave to charities.","cn":"有传闻说他向慈善机构慷慨解囊，捐献巨款。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is generous gives money or presents to other people, and you think it is kind and good of them to do this","cn":""},{"en":"generous behaviour","cn":""},{"en":"a generous attitude, or generous behaviour","cn":"慷慨﹐大方"}]},"vocab":{"pos":"n","senses":[{"en":"Generosity is a quality that's a lot like unselfishness — someone showing generosity is happy to give to or share time, money, food, or whatever with others."}]},"collocations":{"phrases":["ADJ. extraordinary, great, unusual","VERB + GENEROSITY show (sb) He thanked them for the extraordinary generosity they had shown. | take advantage of Their guests took advantage","PREP. ~ to/towards their great generosity to the school","PHRASES an act of generosity, generosity of spirit She showed an unusual generosity of spirit to those who had opposed her. | thanks to the "]},"media":{"uk":"media/ldoce/hwd/bre/b/generosity0205.mp3","us":"media/ldoce/hwd/ame/5/generosity.mp3"},"examples":[{"en":"He treated them with generosity and thoughtfulness.","cn":"他待他们宽容大度、体贴周到。"},{"en":"I shall never forget the generosity shown by the people of Bataisk.","cn":"我永远也不会忘记巴泰斯克人的慷慨大方。"}],"oxford":{"phon":"ˌdʒenəˈrɒsəti","pos":"noun","senses":[{"en":"the fact of being generous (= willing to do kind things or give somebody money, gifts or time freely)","cn":"慷慨；大方；宽宏大量","ex":{"en":"He treated them with generosity and thoughtfulness.","cn":"他待他们宽容大度、体贴周到。"}}]}},"gag":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（使人不能说话的）封口布，塞口物","en":"A gag is something such as a piece of cloth that is tied around or put inside someone's mouth in order to stop them from speaking.","ex":{"en":"His captors had put a gag of thick leather in his mouth.","cn":"劫持者用一块厚厚的皮革堵住了他的嘴。"}},{"pos":"VERB 动词","cn":"（用布）封住（或堵住）…的嘴","en":"If someone gags you, they tie a piece of cloth around your mouth in order to stop you from speaking or shouting.","ex":{"en":"I gagged him with a towel.","cn":"我用一条毛巾堵住他的嘴。"}},{"pos":"VERB 动词","cn":"压制…的言论自由；迫使…缄默","en":"If a person is gagged by someone in authority, they are prevented from expressing their opinion or from publishing certain information.","ex":{"en":"Judges must not be gagged.","cn":"法官的言论自由不能受到压制。"}},{"pos":"VERB 动词","cn":"噎住；噎得作呕","en":"If you gag, you cannot swallow and nearly vomit.","ex":{"en":"I knelt by the toilet and gagged.","cn":"我跪在马桶边，一阵恶心。"}},{"pos":"N-COUNT 可数名词","cn":"笑话；玩笑；插科打诨","en":"A gag is a joke.","ex":{"en":"...a gag about policemen giving evidence in court.","cn":"关于警察在法庭作证的一则笑话"}},{"pos":"VERB 动词","cn":"渴望拥有；期盼做","en":"If you say that someone is gagging for something or is gagging to do something, you are emphasizing that they want to have it or do it very much.","ex":{"en":"Girls everywhere are gagging for a car like this","cn":"天底下的女孩儿都对这种车梦寐以求。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"bring food or drink up from your stomach out through your mouth because you are ill, drunk, shocked etc","cn":""},{"en":"to bring food or drink up from your stomach out through your mouth - used especially in medical contexts","cn":""},{"en":"to bring food or drink up from your stomach out through your mouth because you are ill, drunk etc","cn":""}]},"collocations":{"phrases":["PHRASES bind and gag sb The men left the security guards bound and gagged."]},"media":{"uk":"media/ldoce/hwd/bre/d/gag_v0205.mp3","us":"media/ldoce/hwd/ame/b/gag1.mp3"},"examples":[{"en":"It was just a gag — we didn't mean to upset anyone.","cn":"这只是逗着玩，我们并未想使任何人不高兴。"},{"en":"The new laws are seen as an attempt to gag the press.","cn":"人们认为新法律企图压制新闻界的言论自由。"}],"oxford":{"phon":"ɡæɡ","pos":"noun","senses":[{"en":"a piece of cloth that is put over or in somebody’s mouth to stop them speaking","cn":"（使人不能说话的）封口布；塞口布","ex":{"en":"They tied him up and put a gag on him.","cn":"他们把他绑起来并用布堵住了他的嘴。"}},{"en":"an order that prevents something from being publicly reported or discussed","cn":"禁刊令（阻止公开报道或讨论某事的法令）","ex":{"en":"a press gag","cn":"新闻禁刊令"}},{"en":"a joke or a funny story, especially one told by a professional comedian","cn":"（尤指专业喜剧演员的）插科打诨，笑话，噱头","lab":"informal","ex":{"en":"to tell/crack a gag","cn":"讲笑话"}},{"en":"a trick you play on somebody","cn":"恶作剧；诡计；花招","lab":"especially North American English","ex":{"en":"It was just a gag—we didn't mean to upset anyone.","cn":"这只是逗着玩，我们没想让人不高兴。"}},{"en":"to put a piece of cloth in or over somebody’s mouth to prevent them from speaking or shouting","cn":"捂住，塞住（某人的嘴）","g":"[transitive]","ex":{"en":"The hostages were bound and gagged.","cn":"人质被绑起来并被人用东西塞住了嘴。"},"pos":"verb"},{"en":"to prevent somebody from speaking freely or expressing their opinion","cn":"压制…的言论自由；使缄默","g":"[transitive]","ex":{"en":"The new laws are seen as an attempt to gag the press.","cn":"人们认为新法律企图压制新闻界的言论自由。"},"pos":"verb"},{"en":"to have the unpleasant feeling in your mouth and stomach as if you are going to vomit","cn":"作呕","g":"[intransitive]","ex":{"en":"She gagged on the blood that filled her mouth.","cn":"她因嘴里充满了血而作呕。"},"pos":"verb"}]}},"graph":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"图；图表；曲线图","en":"A graph is a mathematical diagram which shows the relationship between two or more sets of numbers or measurements."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a drawing that uses a line or lines to show how two or more sets of measurements are related to each other","cn":"图表﹐曲线图"}]},"vocab":{"pos":"n v","senses":[{"en":"A graph is a visual plotting of the relationship between two or more quantities, like a math map. To graph is to create such a chart."}]},"collocations":{"phrases":["ADJ. bar, line","VERB + GRAPH draw, produce | depict sth as/on, show sth as/in/on The statistics can be depicted as a graph. | plot sth on The figures are al","GRAPH + VERB show sth She drew a graph showing the relationship between costs and sales.","GRAPH + NOUN paper","PREP. in a/the ~ I decided to show the results in a bar graph. | on a/the ~ We can see on this graph how the company has grown over the last","PHRASES in graph form Results can be shown in numeric or graph form."]},"media":{"uk":"media/ldoce/hwd/bre/8/brelasdegraph.mp3","us":"media/ldoce/hwd/ame/6/graph.mp3","img":["media/thumb/graph.jpg"]},"examples":[{"en":"The graph shows how house prices have risen since the 1980s.","cn":"此图表明了自 20 世纪 80 年代以来房价上涨的情况。"},{"en":"Plot a graph of height against age.","cn":"绘制一张身高与年龄对照的曲线图。"}],"oxford":{"phon":"ɡrɑːf","pos":"noun","senses":[{"en":"a diagram consisting of a line or lines, showing how two or more sets of numbers are related to each other","cn":"图；图表；曲线图","ex":{"en":"Plot a graph of height against age.","cn":"绘制一张身高与年龄对照的曲线图。"}}]}},"grandeur":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"宏伟；堂皇；壮丽","en":"If something such as a building or a piece of scenery has grandeur, it is impressive because of its size, its beauty, or its power.","ex":{"en":"...the grandeur and natural beauty of South America","cn":"南美洲壮丽的自然美景"}},{"pos":"N-UNCOUNT 不可数名词","cn":"高贵；显赫；自命不凡","en":"Someone's grandeur is the great importance and social status that they have, or think they have.","ex":{"en":"He is wholly concerned with his own grandeur.","cn":"他只关心自己的显赫地位。"}},{"pos":"","cn":"","en":"delusions of grandeur→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"impressive beauty, power, or size","cn":"壮丽﹐雄伟"}]},"vocab":{"pos":"n","senses":[{"en":"Use the noun grandeur to describe something that is splendid or magnificent, such as a lofty idea or an impressive building: “The gilded domes and ornate detail added to the grandeur of the church on Red Square.”"}]},"collocations":{"phrases":["ADJ. rugged the rugged grandeur of the mountains | breathtaking, dramatic, majestic, sheer the breathtaking grandeur of the cathedral | fade"]},"media":{"uk":"media/ldoce/hwd/bre/8/grandeur0205.mp3","us":"media/ldoce/hwd/ame/c/grandeur.mp3"},"examples":[{"en":"The hotel had an air of faded grandeur.","cn":"这家旅馆给人一种繁华已逝的感觉。"},{"en":"She is clearly suffering from delusions of grandeur (= thinks she is more important than she really is).","cn":"她显然是犯了妄自尊大的毛病。"}],"oxford":{"phon":"ˈɡrændʒə(r)","pos":"noun","senses":[{"en":"the quality of being great and impressive in appearance","cn":"宏伟；壮丽；堂皇","ex":{"en":"We admired the grandeur and simplicity of the Roman architecture.","cn":"我们欣赏罗马建筑的宏伟和简洁。"}},{"en":"the importance or social status somebody has or thinks they have","cn":"高贵；显赫；伟大","ex":{"en":"He has a sense of grandeur about him.","cn":"他觉得自己很了不起。"}}]}},"gay":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"同性恋的","en":"A gay person is homosexual.","ex":{"en":"The quality of life for gay men has improved over the last two decades.","cn":"同性恋者的生活质量在过去20年里有了改善。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"快乐的；愉快的","en":"A gay person is fun to be with because they are lively and cheerful.","ex":{"en":"I am happy and free, in good health, gay and cheerful.","cn":"我快活自由，身体健康，积极乐观。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"鲜艳的；艳丽的","en":"A gay object is brightly coloured and pretty to look at.","ex":{"en":"I like gay, relaxing paintings.","cn":"我喜欢色彩鲜艳、让人放松的画。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"sexually attracted to people of the same sex","cn":""},{"en":"a woman who is sexually attracted to other women","cn":""},{"en":"sexually attracted to people of the same sex","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"Gay is a word with many meanings. A gay person is homosexual, but if we describe something like a scene or a party as gay , that means it's bright, merry, and happy."}]},"collocations":{"phrases":["VERBS be, look, sound","ADV. openly He is now openly gay."]},"media":{"uk":"media/ldoce/hwd/bre/4/gay_adj0205.mp3","us":"media/ldoce/hwd/ame/1/gay1.mp3"},"examples":[{"en":"She didn't like the ringtone — said it was gay.","cn":"她不喜欢那个手机铃声，说它不时尚。"},{"en":"The garden was gay with red geraniums.","cn":"花园里红色的天竺葵花色彩艳丽。"}],"oxford":{"phon":"ɡeɪ","pos":"adjective","senses":[{"en":"sexually attracted to people of the same sex","cn":"同性恋的","ex":{"en":"gay men","cn":"同性恋的男人"}},{"en":"connected with people who are gay","cn":"与同性恋者有关的","g":"[only before noun]","ex":{"en":"a gay club/bar","cn":"同性恋者俱乐部／酒吧"}},{"en":"(used especially by young people) an offensive way to describe something you find boring, stupid or not attractive","cn":"（尤为年轻人用语）无聊，不时尚，没吸引力","g":"[not before noun]","lab":"slang, disapproving, offensive，，，，"},{"en":"happy and full of fun","cn":"愉快的；快乐的；充满乐趣的","lab":"old-fashioned","ex":{"en":"gay laughter","cn":"欢快的笑声"}},{"en":"brightly coloured","cn":"鲜艳的；艳丽的","lab":"old-fashioned","ex":{"en":"The garden was gay with red geraniums.","cn":"花园里红色的天竺葵花色彩艳丽。"}},{"en":"a person who is gay, especially a man","cn":"同性恋者（尤指男性）","pos":"noun"}]}},"groundwork":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"基础；根基","en":"The groundwork for something is the early work on it which forms the basis for further work.","ex":{"en":"Yesterday's meeting was to lay the groundwork for the task ahead","cn":"昨天的会议是为以后的工作做准备。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to make plans or arrangements for something that will happen in the future, so that you will be ready when it happens","cn":""},{"en":"to do all the things you need to do to prepare for a special occasion or event","cn":""},{"en":"to do all the things you must do in order to prepare for an important event","cn":""}]},"collocations":{"phrases":["ADJ. basic","VERB + GROUNDWORK do, lay, prepare, provide (sb with) The first meeting laid the groundwork for the final agreement. The first year provides","PREP. ~ for We are already doing the groundwork for the introduction of the scheme next year."]},"media":{"uk":"media/ldoce/hwd/bre/7/groundwork0205.mp3","us":"media/ldoce/hwd/ame/0/groundwork.mp3"},"examples":[{"en":"Officials are laying the groundwork for a summit conference of world leaders.","cn":"官员们正在为世界首脑峰会做准备工作。"},{"en":"His speech laid the groundwork for independence.","cn":"他的演说为独立打下了基础。"}],"oxford":{"phon":"ˈɡraʊndwɜːk","pos":"noun","senses":[{"en":"work that is done as preparation for other work that will be done later","cn":"基础工作；准备工作","ex":{"en":"Officials are laying the groundwork for a summit conference of world leaders.","cn":"官员们正在为世界首脑峰会做准备工作。"}}]}},"gleam":{"collins":{"senses":[{"pos":"VERB 动词","cn":"闪光；闪烁","en":"If an object or a surface gleams, it reflects light because it is shiny and clean.","ex":{"en":"His black hair gleamed in the sun.","cn":"他的黑发在阳光下闪着光泽。"}},{"pos":"N-SING 单数名词","cn":"反光；闪光","en":"You can refer to the light reflected from something as a gleam .","ex":{"en":"...the gleam of the dark river","cn":"黑黝黝的河流上闪烁的波光"}},{"pos":"VERB 动词","cn":"（日、月等）发微光；闪烁","en":"If a light or the sun or moon gleams, it shines faintly.","ex":{"en":"Neon lights gleamed in the deepening mists.","cn":"霓虹灯在渐浓的雾霭中隐约闪烁。"}},{"pos":"N-COUNT 可数名词","cn":"微光；一丝光线","en":"A gleam of light is a pale, clear light.","ex":{"en":"...the gleam of the headlights.","cn":"汽车头灯的微光"}},{"pos":"VERB 动词","cn":"（眼睛）闪闪发亮，闪烁着光芒","en":"If your eyes gleam, they look bright and show that you are excited or happy.","ex":{"en":"His eyes gleamed almost wickedly.","cn":"他狡黠的双眼闪闪发亮。"}},{"pos":"N-SING 单数名词","cn":"（情感的）表露，闪现","en":"If someone has a gleam in their eye, their eyes show a particular feeling.","ex":{"en":"There was a gleam in her eye when she looked at me.","cn":"她朝我看时眼中流露出某种神情。"}},{"pos":"N-COUNT 可数名词","cn":"一丝；一线；少许","en":"A gleam of something is a faint sign of it.","ex":{"en":"There was a gleam of hope for a peaceful settlement.","cn":"还有一线和平解决的希望。"}},{"pos":"PHRASE 短语","cn":"尚未成形的想法；蒙眬的想法","en":"If you say that something is only a gleam in someone's eye at present, you mean that it is only being planned or considered, and has not yet been properly begun.","ex":{"en":"The product is still only a gleam in an engineer's eye.","cn":"该产品还只是工程师头脑中尚未成形的想法。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something sparkles, it shines with many small bright points when light is on it","cn":""},{"en":"to shine by reflecting the light – used especially about smooth clean surfaces, or about someone’s eyes or teeth","cn":""},{"en":"to shine with quick flashes of light","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A gleam is a bright flash of light. If you were lost on a dark, stormy night, you'd be hugely relieved to see the gleam of a roadside diner's sign up ahead."}]},"collocations":{"phrases":["ADV. dully, faintly, softly Th e knife's blade gleamed dully in th e dark .","PREP. with The long oak table gleamed with polish.","PHRASES gleam golden, white, etc. The pebble beach gleamed white in the moonlight."]},"media":{"uk":"media/ldoce/hwd/bre/2/gleam_n0205.mp3","us":"media/ldoce/hwd/ame/1/gleam1.mp3"},"examples":[{"en":"Her teeth gleamed white against the tanned skin of her face.","cn":"她的牙齿在褐色脸膛映衬下显得洁白明亮。"},{"en":"The house was gleaming with fresh white paint.","cn":"房子刚刷过白漆，显得光洁明亮。"}],"oxford":{"phon":"ɡliːm","pos":"verb","senses":[{"en":"to shine with a pale clear light","cn":"发微光；隐约闪光；闪烁","g":"[intransitive]","ex":{"en":"The moonlight gleamed on the water.","cn":"月光照在水面上泛起粼粼波光。"}},{"en":"to look very clean or bright","cn":"显得光洁明亮","g":"[intransitive]","ex":{"en":"The house was gleaming with fresh white paint.","cn":"房子刚刷过白漆，显得光洁明亮。"}},{"en":"if a person’s eyes gleam with a particular emotion, or an emotion gleams in a person’s eyes, the person shows that emotion","cn":"（眼睛）表露出，流露出；（在眼中）闪现","g":"[intransitive]","ex":{"en":"His eyes gleamed with amusement.","cn":"他眼睛里流露出愉悦的神情。"}},{"en":"a pale clear light, often reflected from something","cn":"微光（常指反光）","ex":{"en":"We could see the gleam of moonlight on the water.","cn":"我们看见水面上荡漾的月光。"},"pos":"noun"},{"en":"a small amount of something","cn":"少量；一丝；一线","ex":{"en":"a faint gleam of hope","cn":"微弱的一线希望"},"pos":"noun"},{"en":"an expression of a particular feeling or emotion that shows in somebody’s eyes","cn":"（感情在眼中的）表露，闪现","ex":{"en":"a gleam of triumph in her eyes","cn":"她眼里闪烁着胜利的光芒"},"pos":"noun"}]}},"gimmick":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（引人注意或关注的）噱头，花招","en":"A gimmick is an unusual and unnecessary feature or action whose purpose is to attract attention or publicity.","ex":{"en":"It is just a public relations gimmick","cn":"这只不过是一种公关伎俩。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a trick or something unusual that you do to make people notice someone or something – used to show disapproval","cn":"引人注意的花招﹐噱头〔含贬义〕"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A gimmick is a trick intended to attract attention. If you lure crowds to your bake sale by having cute football players handing out samples in front of your booth, that’s a gimmick ."}]},"collocations":{"phrases":["ADJ. latest, new a new gimmick to encourage people to go to the cinema | election, marketing, publicity, sales The promise of lower taxation","PHRASES just/nothing more than/only a gimmick He dismissed the event as just a publicity gimmick."]},"media":{"uk":"media/ldoce/hwd/bre/e/gimmick0205.mp3","us":"media/ldoce/hwd/ame/f/gimmick.mp3"},"examples":[{"en":"a promotional/publicity/sales gimmick","cn":"以推销/宣传/销售为目的的花招"},{"en":"a gimmicky idea","cn":"鬼主意"}],"oxford":{"phon":"ˈɡɪmɪk","pos":"noun","senses":[{"en":"an unusual trick or unnecessary device that is intended to attract attention or to persuade people to buy something","cn":"（为引人注意或诱人购买而搞的）花招，把戏，噱头","ex":{"en":"a promotional/publicity/sales gimmick","cn":"以推销／宣传／销售为目的的花招"}}]}},"grate":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"炉栅；炉格；炉排；炉箅","en":"A grate is a framework of metal bars in a fireplace, which holds the coal or wood.","ex":{"en":"A wood fire burned in the grate.","cn":"木柴在炉栅中燃烧着。"}},{"pos":"VERB 动词","cn":"磨碎,擦碎（食物）","en":"If you grate food such as cheese or carrots, you rub it over a metal tool called a grater so that the food is cut into very small pieces.","ex":{"en":"Grate the cheese into a mixing bowl.","cn":"将干酪磨碎放进搅拌碗中。"}},{"pos":"VERB 动词","cn":"发出吱吱嘎嘎的摩擦声；发出刺耳的摩擦声","en":"When something grates, it rubs against something else making a harsh, unpleasant sound.","ex":{"en":"His chair grated as he got to his feet","cn":"他起身时椅子发出吱吱嘎嘎的声音。"}},{"pos":"VERB 动词","cn":"使烦躁；使气恼；使难受","en":"If something such as someone's behaviour grates on you or grates, it makes you feel annoyed.","ex":{"en":"His manner always grated on me","cn":"他的态度总是让我感到气恼。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to cut cheese, carrot etc into small pieces by rubbing it against a special tool","cn":""},{"en":"to make butter, chocolate etc become liquid","cn":""},{"en":"to put flour or other powders through a sieve (= tool like a net made of wire, which you use for removing larger grains or pieces )","cn":""}]},"vocab":{"pos":"1 v n 2 n v","senses":[{"en":"When you grate something you rip it to shreds, like a pound of solid cheese that you shred for a recipe."}]},"collocations":{"phrases":["ADV. coarsely | finely Sprinkle the top of the dish with some finely grated cheese.","PHRASES freshly grated a teaspoon of freshly grated nutmeg 2 make a sharp unpleasant sound","ADV. harshly","PREP. against The steel of the helmet grated against the door. | on The grit beneath her soles grated harshly on the wooden deck."]},"media":{"uk":"media/ldoce/hwd/bre/6/grate_n0205.mp3","us":"media/ldoce/hwd/ame/a/grate1.mp3","img":["media/thumb/grate.jpg"]},"examples":[{"en":"The rusty hinges grated as the gate swung back.","cn":"大门荡了回去，生锈的铰链发出吱嘎吱嘎的刺耳声。"},{"en":"It grated with him when people implied he wasn't really British.","cn":"当有人暗示他不是地道的英国人时，他很是恼火。"}],"oxford":{"phon":"ɡreɪt","pos":"noun","senses":[{"en":"a metal frame for holding the wood or coal in a fireplace","cn":"炉条；炉箅","ex":{"en":"A huge log fire was burning in the grate.","cn":"壁炉里熊熊燃烧着大火。"}},{"en":"a frame of metal bars over the opening to a drain in the ground","cn":"下水道孔盖","lab":"both US English"},{"en":"to rub food against a grater in order to cut it into small pieces","cn":"擦碎，磨碎（食物）","g":"[transitive]","lab":"British English","ex":{"en":"grated apple/carrot/cheese, etc.","cn":"擦成细丝的苹果、胡萝卜、干酪等"},"pos":"verb"},{"en":"to annoy somebody","cn":"激怒（某人）；招惹（某人）","g":"[intransitive]","ex":{"en":"Her voice really grates on me.","cn":"她的声音真叫我难受。"},"pos":"verb"},{"en":"when two hard surfaces grate as they rub together, they make a sharp unpleasant sound; somebody can also make one thing grate against another","cn":"（使）发出刺耳的声音，发出吱吱嘎嘎的摩擦声","g":"[intransitive, transitive]","ex":{"en":"The rusty hinges grated as the gate swung back.","cn":"大门荡了回去，生锈的铰链发出吱嘎吱嘎的刺耳声。"},"pos":"verb"}]}},"glamour":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"魅力；吸引力；诱惑力","en":"Glamour is the quality of being more attractive, exciting, or interesting than ordinary people or things.","ex":{"en":"...the glamour of show biz.","cn":"娱乐界的诱惑"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a feature or quality that makes people like, want, or feel interested in something","cn":""},{"en":"a quality that makes people like something or someone","cn":""},{"en":"a very attractive quality that makes you want something very much – often used about something that has a bad effect or influence","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"Glamour is the quality of being fascinating, alluring, or charming If you've watched Marilyn Monroe on a movie screen, then you've witnessed glamour !"}]},"collocations":{"phrases":["QUANT. touch Several film stars were invited to add a touch of glamour to the occasion.","VERB + GLAMOUR have He had a glamour about him that she found very attractive. | lack Jumbo jets somehow lack the glamour of the transatlant","PHRASES a certain glamour"]},"media":{"uk":"media/ldoce/hwd/bre/3/glamor0205.mp3","us":"media/ldoce/hwd/ame/e/laadglamour.mp3"},"examples":[{"en":"Now that she's a flight attendant, foreign travel has lost its glamour for her.","cn":"她现在是空中乘务员了，去国外旅行对她已失去魅力。"},{"en":"hopeful young actors and actresses dazzled by the glamour of Hollywood","cn":"为好莱坞的魅力神魂颠倒时刻怀抱希望的年轻演员"}],"oxford":{"phon":"ˈɡlæmə(r)","pos":"noun","senses":[{"en":"the attractive and exciting quality that makes a person, a job or a place seem special, often because of wealth or status","cn":"吸引力，魅力，诱惑力（多因财富或地位所致）","ex":{"en":"hopeful young actors dazzled by the glamour of Hollywood","cn":"满怀希望的年轻演员为好莱坞的魅力神魂颠倒"}},{"en":"physical beauty that also suggests wealth or success","cn":"（暗示财富或成功的）迷人的美，魅力","ex":{"en":"Her long dark hair lent her a certain glamour.","cn":"乌黑长发赋予她某种魅力。"}},{"en":"a US women's magazine published by Condé Nast. It began in 1939 and covers fashion, beauty, health and news about famous people. It also has articles about other interests, such as business, politics, travel, food and relationships. Each year it holds the Glamour Woman of the Year Awards. There has been a British version of the magazine since 2001, and there are also versions in several other countries.","cn":"魅力：康泰纳仕（CondéNast）发行的美国女性杂志。它始于1939年，涵盖时尚，美容，健康和名人新闻。它还有关于其他兴趣的文章，例如商业，政治，旅行，饮食和人际关系。每年，它都会获得“年度魅力女人”奖。自2001年以来，该杂志已发行了英文版本，在其他几个国家也发行了该版本。","pos":""}]}},"gaol":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large building where people are kept as a punishment for a crime or while they are waiting to go to court for their trial","cn":""},{"en":"a prison, or a similar smaller building where prisoners are kept for a short time","cn":""},{"en":"another way of spelling jail","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41gaol.mp3","us":"media/ldoce/hwd/ame/b/ld41gaol.mp3"},"oxford":{"phon":"dʒeɪl","pos":"noun","senses":[{"en":"jail (= a prison)","cn":"监狱"},{"en":"jail (= to put somebody in prison)","cn":"监狱","pos":"verb"}]}},"growl":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（狗等）低声吼叫","en":"When a dog or other animal growls, it makes a low noise in its throat, usually because it is angry.","ex":{"en":"The dog was biting, growling and wagging its tail.","cn":"那条狗在一边撕咬一边低声吼叫，尾巴也跟着摇摆。"}},{"pos":"VERB 动词","cn":"（人）发出低沉的怒吼，咆哮","en":"If someone growls something, they say something in a low, rough, and angry voice.","ex":{"en":"His fury was so great he could hardly speak. He growled some unintelligible words at Pete","cn":"他气得几乎说不出话来，冲着皮特不知咆哮些什么。"}},{"pos":"VERB 动词","cn":"隆隆作响；轰鸣","en":"If you say that something growls, you mean that it makes a deep low noise.","ex":{"en":"My stomach growled","cn":"我的肚子咕咕叫。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say something very quietly, using your breath rather than your full voice","cn":""},{"en":"to say something quietly without pronouncing the words clearly","cn":""},{"en":"to say something quietly, especially when you are annoyed but do not want someone to hear you complaining","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"To growl is to make a low, guttural, aggressive sound, like “grrrrrrrrrrr.” If you’ve ever gotten too close to an angry dog, you’ve probably heard a growl ."}]},"collocations":{"phrases":["ADV. angrily, savagely &lsquo;I'm a desperate man,&rsquo; he growled savagely. | softly, throatily","PREP. at The dog growled softly at me. | with Her stomach was growling with hunger."]},"media":{"uk":"media/ldoce/hwd/bre/7/growl0205.mp3","us":"media/ldoce/hwd/ame/2/growl.mp3"},"examples":[{"en":"She growled a sarcastic reply.","cn":"她以讥讽的口吻咬牙切齿地回答。"},{"en":"‘Who are you?’ he growled at the stranger. “","cn":"你是谁？”他向陌生人怒吼道。"}],"oxford":{"phon":"ɡraʊl","pos":"verb","senses":[{"en":"to make a low sound in the throat, usually as a sign of anger","cn":"低声吼叫","g":"[intransitive]","lab":"figurative","ex":{"en":"The dog growled at them.","cn":"狗对着他们咆哮。"}},{"en":"to say something in a low angry voice","cn":"发出低沉的怒吼；咆哮","g":"[transitive]","ex":{"en":"‘Who are you?’ he growled at the stranger.","cn":"“你是谁？”他向陌生人怒吼道。"}},{"en":"a deep angry sound made when somebody/something growls","cn":"怒吼声；咆哮","ex":{"en":"The dog gave a threatening growl.","cn":"那只狗发出了一声威胁的低吼。"},"pos":"noun"}]}},"grievance":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"委屈；不满；不平；抱怨","en":"If you have a grievance about something that has happened or been done, you believe that it was unfair.","ex":{"en":"They had a legitimate grievance","cn":"他们的抱怨是合乎情理的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that you say or write when you are complaining, especially to someone in an official position","cn":""},{"en":"when someone complains publicly about something that they think is wrong or unfair and should not be allowed to happen","cn":""},{"en":"something that you feel unhappy about because you think that you have been treated unfairly – use this especially about an official complaint you make about the place where you work","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A grievance is a complaint. It can be formal, like an employee files grievance because of unsafe working conditions, or more of an emotional matter, like a grievance against an old friend who betrayed you."}]},"collocations":{"phrases":["ADJ. genuine, legitimate, real Some people will complain even if they have no genuine grievance. | imaginary, imagined | long-standing, old ","VERB + GRIEVANCE harbour, have, nurse She still nursed her old grievance. | air, express, vent, voice | hear (formal) , listen to MPs spend ","PREP. ~ about/over The meeting will be a chance to air your grievances about the organization. | ~ against He had a personal grievance again","PHRASES a sense of grievance"]},"media":{"uk":"media/ldoce/hwd/bre/0/grievance0205.mp3","us":"media/ldoce/hwd/ame/6/grievance.mp3"},"examples":[{"en":"Parents were invited to air their grievances (= express them) at the meeting.","cn":"家长们应邀在会上诉说他们的苦衷。"},{"en":"He had been nursing a grievance against his boss for months.","cn":"他几个月来一直对老板心怀不满。"}],"oxford":{"phon":"ˈɡriːvəns","pos":"noun","senses":[{"en":"something that you think is unfair and that you complain or protest about; a feeling that you have been badly treated","cn":"不平的事；委屈；抱怨；牢骚","ex":{"en":"Parents were invited to air their grievances (= express them) at the meeting.","cn":"家长们应邀在会上诉说他们的苦衷。"}}]}},"grace":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"优美；优雅","en":"If someone moves with grace, they move in a smooth, controlled, and attractive way.","ex":{"en":"He moved with the grace of a trained boxer","cn":"他的动作带着一种训练有素的拳击手的风采。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"修养；涵养","en":"If someone behaves with grace, they behave in a pleasant, polite, and dignified way, even when they are upset or being treated unfairly.","ex":{"en":"The new King seemed to be carrying out his duties with grace and due decorum","cn":"新国王在履行职责时看起来举止得体、端庄稳重。"}},{"pos":"N-PLURAL 复数名词","cn":"风度；体面","en":"The graces are the ways of behaving and doing things which are considered polite and well-mannered.","ex":{"en":"She didn't fit in and she had few social graces.","cn":"她不适合这种场合，对社交礼仪所知甚少。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"宽限期；延缓期","en":"Grace is used in expressions such as a day's grace and a month's grace to say that you are allowed that amount of extra time before you have to finish something.","ex":{"en":"She wanted a couple of days' grace to get the maisonette cleaned before she moved in","cn":"她想延缓几天，等到把这套复式公寓清理干净后再搬进去。"}},{"pos":"VERB 动词","cn":"为…增色；使更加优美","en":"If you say that something graces a place or a person, you mean that it makes them more attractive.","ex":{"en":"He went to the beautiful old Welsh dresser that graced this homely room","cn":"他走到为这间舒适的房间增色不少的漂亮的旧威尔士碗橱前。"}},{"pos":"VERB 动词","cn":"给…增光;使生辉","en":"If you say that someone important will grace an event or an organization, you mean that they have agreed to be present at the event or to be part of the organization.","ex":{"en":"He had been invited to grace a function at the evening college.","cn":"他应邀为这所夜校的活动捧场。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（上帝的）恩宠，恩典","en":"In Christianity and some other religions, grace is the kindness that God shows to people because he loves them.","ex":{"en":"It was only by the grace of God that no one died.","cn":"承蒙上帝保佑才无人死亡。"}},{"pos":"N-VAR 可变名词","cn":"（饭前或饭后的）谢恩祷告","en":"When someone says grace before or after a meal, they say a prayer in which they thank God for the food and ask Him to bless it.","ex":{"en":"Leo, will you say grace?","cn":"利奥，你来做饭前祷告吧？"}},{"pos":"N-VOC; N-PROPER 称呼名词；专有名词","cn":"（对公爵、公爵夫人或大主教的尊称）大人，阁下，夫人","en":"You use expressions such as Your Grace and His Grace when you are addressing or referring to a duke, duchess, or archbishop.","ex":{"en":"Your Grace, I have a great favour to ask of you.","cn":"大人，我想请您施以大惠。"}},{"pos":"PHRASE 短语","cn":"突然失利；过气；受冷落","en":"If someone falls from grace, they suddenly stop being successful or popular.","ex":{"en":"All went well at first, and I was in high favour; but presently I fell from grace","cn":"我最初一帆风顺，备受器重，但现在却失宠了。"}},{"pos":"PHRASE 短语","cn":"通情达理地做;知趣地做","en":"If someone has the good grace to do something, they are polite enough or honest enough to do it.","ex":{"en":"He did not even have the grace to apologise","cn":"他甚至连一个道歉都没有。"}},{"pos":"PHRASE 短语","cn":"若非上帝保佑，要不是我福大命大（我也会遭此不幸）","en":"If you are talking about someone who is in a bad situation and you say 'There but for the grace of God go I', you mean that you are lucky not to be in the same situation as them and you feel sympathy for them."},{"pos":"PHRASE 短语","cn":"情愿地/ 不情愿地；欣然地/不乐意地","en":"If you do something unpleasant with good grace or with a good grace, you do it cheerfully and without complaining. If you do something with bad grace or with a bad grace, you do it unwillingly and without enthusiasm.","ex":{"en":"He accepted the decision with good grace, and wished me the very best of luck","cn":"他欣然接受这一决定并祝我好运。"}},{"pos":"PHRASE 短语","cn":"为…所赞同;得到…的欢心","en":"If you are in someone's good graces, they are pleased with you.","ex":{"en":"You're so eager to stay in the good graces of the King that nothing else matters to you.","cn":"你如此急于博得国王的欢心，以致其他事情都不管不顾了。"}},{"pos":"","cn":"","en":"airs and graces→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the one good quality that something or someone has that saves it from being completely bad, useless, or unacceptable","cn":""},{"en":"something, often the only thing, that makes someone or something not completely bad","cn":""},{"en":"a graceful and attractive manner or appearance","cn":""}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"Grace commonly refers to a smooth and pleasing way of moving, or a polite and thoughtful way of behaving. But when someone says they were late to the airport and only made it onto their plane by the grace of God, they're talking about grace in the context of God's favor."}]},"collocations":{"phrases":["ADJ. easy, lithe, supple | natural | feline","VERB + GRACE have, move with","PREP. with ~ Ann moved with easy grace."]},"media":{"uk":"media/ldoce/hwd/bre/1/grace_v0205.mp3","us":"media/ldoce/hwd/ame/5/grace1.mp3"},"examples":[{"en":"She is one of the finest players ever to have graced the game.","cn":"她是曾使这场比赛生辉的最杰出的运动员之一。"},{"en":"She moves with the natural grace of a ballerina.","cn":"她的动作具有芭蕾舞演员自然优雅的丰姿。"}],"oxford":{"phon":"ɡreɪs","pos":"noun","senses":[{"en":"an attractive quality of movement that is smooth and done with control; a simple and beautiful quality","cn":"优美；优雅","g":"[uncountable]","sc":"of movement","ex":{"en":"She moves with the natural grace of a ballerina.","cn":"她的动作具有芭蕾舞演员自然优雅的丰姿。"}},{"en":"a quality of behaviour that is polite and pleasant and deserves respect","cn":"文雅；高雅","g":"[uncountable]","sc":"behaviour","ex":{"en":"He conducted himself with grace and dignity throughout the trial.","cn":"在整个审讯过程中他表现得文雅而有尊严。"}},{"en":"ways of behaving that people think are polite and acceptable","cn":"风度；体面","g":"[plural]","lab":"especially British English","sc":"behaviour","ex":{"en":"He was not particularly well versed in the social graces.","cn":"他对社交礼节并不特别熟悉。"}},{"en":"extra time that is given to somebody to enable them to pay a bill, finish a piece of work, etc.","cn":"宽限期；延缓期","g":"[uncountable]","sc":"extra time","ex":{"en":"They've given me a month's grace to get the money.","cn":"他们宽限我一个月弄到这笔钱。"}},{"en":"the love that God shows towards the human race","cn":"恩宠；恩典","g":"[uncountable]","lab":"North American English","sc":"of God","ex":{"en":"the power of divine grace","cn":"神恩的力量"}},{"en":"a short prayer that is usually said before a meal to thank God for the food","cn":"（饭前的）谢恩祈祷","g":"[uncountable, countable]","sc":"prayer","ex":{"en":"Let's say grace.","cn":"我们做饭前祷告吧。"}},{"en":"used as a title of respect when talking to or about an archbishop, a duke or a duchess","cn":"（对大主教、公爵、公爵夫人、女公爵的尊称）大人，阁下，夫人","g":"[countable]","sc":"title","ex":{"en":"Good Morning, Your Grace.","cn":"早上好，阁下。"}},{"en":"to make something more attractive; to decorate something","cn":"为…增色；为…锦上添花；装饰","ex":{"en":"The table had once graced a duke's drawing room.","cn":"这张桌子曾一度为公爵的起居室增色不少。"},"pos":"verb"},{"en":"to bring honour to somebody/something; to be kind enough to attend or take part in something","cn":"使荣耀；使生辉；承蒙光临","lab":"ironic","ex":{"en":"She is one of the finest players ever to have graced the game.","cn":"她是曾使这项运动生辉的最杰出的运动员之一。"},"pos":"verb"},{"en":"a first name for girls","cn":"格雷斯（女子名）","pos":""}]}},"galaxy":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"星系","en":"A galaxy is an extremely large group of stars and planets that extends over many billions of light years.","ex":{"en":"Astronomers have discovered a distant galaxy.","cn":"天文学家们发现了一个遥远的星系。"}},{"pos":"N-PROPER 专有名词","cn":"银河；银河系","en":"The Galaxy is the extremely large group of stars and planets to which the Earth and the Solar System belong.","ex":{"en":"The Galaxy consists of 100 billion stars.","cn":"银河系由1,000亿颗恒星组成。"}},{"pos":"N-SING 单数名词","cn":"一群（名人）；（人才）荟萃","en":"If you talk about a galaxy of people from a particular profession, you mean a group of them who are all famous or important.","ex":{"en":"He is one of a small galaxy of Dutch stars on German television.","cn":"出现在德国电视上的荷兰明星为数不多，他是其中一位。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large ball of burning gas in space, which can be seen at night as a point of light in the sky","cn":""},{"en":"one of the large objects that goes around the Sun, for example the Earth, Saturn, Mercury, or Mars","cn":""},{"en":"the star that gives us light and heat, around which the planets move. There are also many millions of other suns in the universe","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A galaxy is a collection of stars and planets that are held together by gravity. In a galaxy , the celestial bodies rotate around a central object."}]},"collocations":{"phrases":["ADJ. distant | nearby, nearest, neighbouring","PREP. in a/the ~ scientists observing phenomena in nearby galaxies"]},"media":{"uk":"media/ldoce/hwd/bre/4/galaxy0205.mp3","us":"media/ldoce/hwd/ame/6/galaxy.mp3"},"examples":[{"en":"a galaxy of Hollywood stars","cn":"好莱坞影星的荟萃"},{"en":"a galaxy of British artistic talent","cn":"灿若星汉的英国艺术人才"}],"oxford":{"phon":"ˈɡæləksi","pos":"noun","senses":[{"en":"any of the large systems of stars, etc. in outer space","cn":"星系","g":"[countable]","ex":{"en":"scientists observing phenomena in nearby galaxies","cn":"观察邻近星系现象的科学家"}},{"en":"the system of stars that contains our sun and its planets, seen as a band of light in the night sky","cn":"银河；银河系","g":"[singular]"},{"en":"a group of famous people, or people with a particular skill","cn":"群英；人才荟萃","g":"[countable]","lab":"informal","ex":{"en":"a galaxy of Hollywood stars","cn":"好莱坞影星的荟萃"}},{"en":"a popular make of chocolate bar in Britain, sold as Dove in the US and other countries","cn":"在英国流行的巧克力棒品牌，在美国和其他国家/地区以Dove的形式出售"}]}},"graft":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"移植的皮肤（或骨骼）;移植的器官","en":"A graft is a piece of healthy skin or bone, or a healthy organ, which is attached to a damaged part of your body by a medical operation in order to replace it.","ex":{"en":"I am having a skin graft on my arm soon.","cn":"我马上就要接受手臂的皮肤移植手术。"}},{"pos":"VERB 动词","cn":"将（皮肤等）移植到","en":"If a piece of healthy skin or bone or a healthy organ is grafted onto a damaged part of your body, it is attached to that part of your body by a medical operation.","ex":{"en":"The top layer of skin has to be grafted onto the burns.","cn":"必须将表层皮肤移植到烫伤处。"}},{"pos":"VERB 动词","cn":"将…嫁接（到）","en":"If a part of one plant or tree is grafted onto another plant or tree, they are joined together so that they will become one plant or tree, often in order to produce a new variety.","ex":{"en":"Pear trees are grafted on quince rootstocks.","cn":"梨树被嫁接到榅的根茎上。"}},{"pos":"VERB 动词","cn":"将…接入（到另一思想或制度）","en":"If you graft one idea or system on to another, you try to join one to the other.","ex":{"en":"The Japanese tried to graft their own methods on to this different structure.","cn":"日本人试图将自己的方法移植到这种不同的体制中。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"劳累的工作；重活","en":"Graft means hard work.","ex":{"en":"His career has been one of hard graft.","cn":"他从事的职业劳动强度很大。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"贪污；受贿","en":"In politics, graft is used to refer to the activity of using power or authority to obtain money dishonestly.","ex":{"en":"...another politician accused of graft.","cn":"又一位被控贪污的政界人物"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"dishonest behaviour","cn":""},{"en":"when someone who works for the government, the police etc uses their power dishonestly to get money or gain an advantage","cn":""},{"en":"when someone offers money to a politician or government official in order to persuade them to do something","cn":""}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"Graft can mean bribery or corruption. It's also a way of transplanting skin or bones in medicine, as in a skin graft ."}]},"collocations":{"phrases":["ADJ. bone, skin","VERB + GRAFT do Doctors are hoping to do a bone graft to repair the damaged bone.","GRAFT + VERB take If the skin graft takes, then surgeons will do another operation a few weeks later. 2 hard work","ADJ. hard Starting a new business involves a lot of hard graft.","VERB + GRAFT do Most of the graft was done for them by their assistants."]},"media":{"uk":"media/ldoce/hwd/bre/7/graft_v0205.mp3","us":"media/ldoce/hwd/ame/7/graft1.mp3"},"examples":[{"en":"Old values are being grafted onto a new social class.","cn":"旧的价值观念正植根于新的社会阶层。"},{"en":"Their success was the result of years of hard graft.","cn":"他们的成功是多年艰苦奋斗的结果。"}],"oxford":{"phon":"ɡrɑːft","pos":"noun","senses":[{"en":"a piece cut from a living plant and fixed in a cut made in another plant, so that it grows there; the process or result of doing this","cn":"接穗；嫁接","g":"[countable]","ex":{"en":"A healthy shoot should form a strong graft.","cn":"健康的嫩枝可作强壮的接穗。"}},{"en":"a piece of skin, bone, etc. removed from a living body and placed in another part of the body that has been damaged; the process or result of doing this","cn":"移植物，移植片（皮肤、骨骼等）；移植","g":"[countable]","ex":{"en":"Linda had to undergo four skin grafts.","cn":"琳达必须接受 4 次植皮手术。"}},{"en":"hard work","cn":"艰苦的工作","g":"[uncountable]","lab":"British English, informal，，","ex":{"en":"Their success was the result of years of hard graft.","cn":"他们的成功是多年艰苦奋斗的结果。"}},{"en":"the use of illegal or unfair methods, especially bribery, to gain advantage in business, politics, etc.; money obtained in this way","cn":"行贿；贿赂；受贿；赃款","g":"[uncountable]","lab":"especially North American English","ex":{"en":"He promised an end to graft and corruption in public life.","cn":"他承诺结束公共事务中的贿赂和腐败行为。"}},{"en":"to take a piece of skin, bone, etc. from a living body and attach it to a damaged part","cn":"移植（皮肤、骨骼等）","g":"[transitive]","ex":{"en":"newly grafted tissue","cn":"新移植的组织"},"pos":"verb"},{"en":"to cut a piece from a living plant and attach it to another plant","cn":"嫁接","g":"[transitive]","pos":"verb"},{"en":"to make one idea, system, etc. become part of another one","cn":"使（思想、制度等）成为（…的一部分）；植根","g":"[transitive]","ex":{"en":"Old values are being grafted onto a new social class.","cn":"旧的价值观念正植根于新的社会阶层。"},"pos":"verb"},{"en":"to work hard","cn":"卖力地工作","g":"[intransitive]","lab":"British English, informal，，","ex":{"en":"She’s been grafting all day.","cn":"她整天都在努力工作。"},"pos":"verb"}]}},"guerrilla":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"游击队员","en":"A guerrilla is someone who fights as part of an unofficial army, usually against an official army or police force.","ex":{"en":"The guerrillas threatened to kill their hostages.","cn":"这些游击队员威胁要杀死人质。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who takes part in or supports an attempt to change the government by using violence","cn":""},{"en":"someone who fights in an unofficial military group, trying to remove their country's existing government, especially by making surprise military attacks","cn":""},{"en":"someone who is fighting to try to remove their country's existing government - use this if you think that this is the right thing to do","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If your brother says he’s going to become a guerrilla , don't worry, he's not planning to become a hairy animal. Guerrilla fighters band together in a small underground army, usually trying to overcome a larger and more organized force."}]},"collocations":{"phrases":["ADJ. armed | urban Urban guerrillas detonated a car bomb in front of the company's headquarters. | communist, opposition, right-wing, separa","GUERRILLA + NOUN army, band, force, group, movement, organization, unit | commander, fighter, leader | activity, attack, campaign, offensive"]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdeguerrilla.mp3","us":"media/ldoce/hwd/ame/6/laadguerrilla.mp3"},"examples":[{"en":"guerrilla marketing (= marketing that uses unusual methods in order to achieve the greatest effect for the smallest amount of money)","cn":"游击营销（用不一般的方式以最少金钱取得最大成效）"},{"en":"Guerrilla actors took to the streets in army fatigues to protest against the war.","cn":"非正式演员穿着军服走上街头举行反战示威。"}],"oxford":{"phon":"ɡəˈrɪlə","pos":"noun","senses":[{"en":"a member of a small group of soldiers who are not part of an official army and who fight against official soldiers, usually to try to change the government","cn":"游击队员","ex":{"en":"urban guerrillas (= those who fight in towns)","cn":"城市游击队员"}},{"en":"organized in an informal way and without official permission or approval","cn":"游击的；非正式的；没有官方认可的","ex":{"en":"Guerrilla actors took to the streets in army fatigues to protest against the war.","cn":"非正式演员穿着士兵服走上街头举行反战示威。"},"pos":"adjective"}]}},"gape":{"collins":{"senses":[{"pos":"VERB 动词","cn":"目瞪口呆地凝视；张口结舌地看","en":"If you gape, you look at someone or something in surprise, usually with an open mouth.","ex":{"en":"His secretary stopped taking notes to gape at me","cn":"他的秘书停止了记录，目瞪口呆地望着我。"}},{"pos":"VERB 动词","cn":"（洞、伤口等）张开，裂开","en":"If you say that something such as a hole or a wound gapes, you are emphasizing that it is big or wide.","ex":{"en":"The front door was missing. A hole gaped in the roof.","cn":"前门不翼而飞，屋顶豁开了一个洞。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to turn your eyes towards someone or something, so that you can see them","cn":""},{"en":"to look at something quickly, especially in order to find or check something","cn":""},{"en":"to look at someone or something for a short time and then look quickly away","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"If Bigfoot walked down your street wearing a tutu, you might gape or stare at the man-ape with your mouth open. You'd really gape if the tutu had a gaping, or wide open, hole."}]},"collocations":{"phrases":["PREP. at What are you gaping at?","PHRASES gape open She watched him, her mouth gaping open. (figurative) The empty cash box lay gaping open in one corner."]},"media":{"uk":"media/ldoce/hwd/bre/4/gape0205.mp3","us":"media/ldoce/hwd/ame/5/gape.mp3"},"examples":[{"en":"He stood yawning, his pyjama jacket gaping open.","cn":"他敞开睡衣站着打哈欠。"},{"en":"a gaping hole/mouth/wound","cn":"豁开的洞；张大的嘴；裂开的伤口"}],"oxford":{"phon":"ɡeɪp","pos":"noun","senses":[{"en":"an act of staring at somebody/something with your mouth open because you are shocked or surprised","cn":"目瞪口呆","ex":{"en":"She climbed into her sports car to the gapes of passers-by.","cn":"行人目瞪口呆地看着她爬进她的跑车里。"}},{"en":"a large wide open mouth or beak","cn":"大张着的嘴（或喙）","ex":{"en":"The perch has the large eye and wide gape of an active hunter.","cn":"鲈鱼有着大眼睛和张大的嘴巴，就像活跃的猎人一样。"}},{"en":"to stare at somebody/something with your mouth open because you are shocked or surprised","cn":"张口结舌地看；目瞪口呆地凝视","g":"[intransitive]","ex":{"en":"Isabel gaped at him, horrified.","cn":"伊莎贝尔惊恐地目瞪口呆地看着他。"},"pos":"verb"},{"en":"to be or become wide open","cn":"张开；裂开；豁开","g":"[intransitive]","ex":{"en":"a gaping hole/mouth/wound","cn":"豁开的洞；张大的嘴；裂开的伤口"},"pos":"verb"}]}},"gifted":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有天赋的；有天才的；有天资的","en":"Someone who is gifted has a natural ability to do something well.","ex":{"en":"...one of the most gifted players in the world","cn":"世界上最有天赋的运动员之一"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（儿童）天资聪颖的","en":"A gifted child is much more intelligent or talented than average.","ex":{"en":"...a state program for gifted children.","cn":"国家培养天才儿童的方案"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having a high level of mental ability, and good at thinking clearly and understanding ideas","cn":""},{"en":"intelligent, so that you can think and learn quickly and find ways to solve problems","cn":""},{"en":"intelligent – used especially about children and young people","cn":""}]},"collocations":{"phrases":["VERBS be","ADV. exceptionally, extremely, highly, immensely, prodigiously, supremely, very | undeniably | naturally a naturally gifted sportswoman | un","PREP. at He's very gifted at maths. | in gifted in the art of healing | with Their helpers are gifted with amazing powers of patience."]},"media":{"uk":"media/ldoce/hwd/bre/5/gifted0205.mp3","us":"media/ldoce/hwd/ame/3/gifted.mp3"},"examples":[{"en":"a gifted musician/player, etc.","cn":"天才的音乐家、运动员等"},{"en":"He was gifted with a charming smile.","cn":"他有一副迷人的微笑。"}],"oxford":{"phon":"ˈɡɪftɪd","pos":"adjective","senses":[{"en":"having a lot of natural ability or intelligence","cn":"有天才的；有天赋的；天资聪慧的","ex":{"en":"a gifted musician/player, etc.","cn":"天才的音乐家、运动员等"}},{"en":"having something pleasant","cn":"具有（令人愉快的特质）","ex":{"en":"He was gifted with a charming smile.","cn":"他有迷人的微笑。"}}]},"base":"gift"},"graze":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（动物）吃青草；放牛；放羊；放牧","en":"When animals graze or are grazed, they eat the grass or other plants that are growing in a particular place. You can also say that a field is grazed by animals.","ex":{"en":"Five cows graze serenely around a massive oak","cn":"5头奶牛在一棵大橡树旁悠闲自在地啃着青草。"}},{"pos":"VERB 动词","cn":"擦伤（身体部位）","en":"If you graze a part of your body, you injure your skin by scraping against something.","ex":{"en":"I had grazed my knees a little.","cn":"我的膝盖擦破了一点皮。"}},{"pos":"N-COUNT 可数名词","cn":"擦伤","en":"A graze is a small wound caused by scraping against something."},{"pos":"VERB 动词","cn":"轻擦；轻触；蹭","en":"If something grazes another thing, it touches that thing lightly as it passes by.","ex":{"en":"A bullet had grazed his arm","cn":"一颗子弹擦过他的手臂。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to cut part of your body very slightly leaving a long very thin cut","cn":""},{"en":"to slightly break the surface of your skin by rubbing against something, for example when you fall on the ground","cn":""},{"en":"a large, deep cut in someone's skin","cn":""}]},"vocab":{"pos":"1 v n 2 v n","senses":[{"en":"Cows graze on grass people graze on snacks and finger-foods, like when you keep grabbing a handful of chips every time you pass by the table at a get-together."}]},"collocations":{"phrases":["ADV. peacefully, quietly Sheep were grazing peacefully in the fields.","VERB + GRAZE allow sth to, turn sth out to The cattle were turned out to graze.","PREP. on/upon lambs grazing on the rough moorland pasture 2 break the surface of your skin","ADV. badly She had grazed her elbow quite badly.","PREP. on He fell and grazed his knees on a rock"]},"media":{"uk":"media/ldoce/hwd/bre/7/graze_v0205.mp3","us":"media/ldoce/hwd/ame/4/graze1.mp3"},"examples":[{"en":"Adam walked away from the crash with just cuts and grazes.","cn":"亚当在撞车事故中平安脱险，只受了点划伤和擦伤。"},{"en":"I have this really bad habit of grazing on junk food.","cn":"我有个特别不好的习惯，就是吃垃圾食品。"}],"oxford":{"phon":"ɡreɪz","pos":"verb","senses":[{"en":"to eat grass that is growing in a field","cn":"（在草地上）吃青草","g":"[intransitive, transitive]","ex":{"en":"There were cows grazing beside the river.","cn":"有些牛在河边吃青草。"}},{"en":"to put cows, sheep, etc. in a field so that they can eat the grass there","cn":"放牧；放牛；放羊","g":"[transitive]","lab":"North American English","ex":{"en":"The land is used by local people to graze their animals.","cn":"这块地当地人用来放牧。"}},{"en":"to eat small amounts of food many times during the day, often while doing other things, instead of eating three meals","cn":"吃零食（代替正餐）","g":"[intransitive]","lab":"informal","ex":{"en":"I have this really bad habit of grazing on junk food.","cn":"我有个特别不好的习惯，就是吃垃圾食品。"}},{"en":"to break the surface of your skin by rubbing it against something rough","cn":"擦伤，擦破（皮肤）","g":"[transitive]","lab":"especially British English","ex":{"en":"I fell and grazed my knee.","cn":"我摔了一跤擦伤了膝盖。"}},{"en":"to touch something lightly while passing it","cn":"（经过时）轻擦，轻触，蹭","g":"[transitive]","ex":{"en":"The bullet grazed his cheek.","cn":"子弹从他的脸颊擦过。"}},{"en":"a small injury where the surface of the skin has been slightly broken by rubbing against something","cn":"（表皮）擦伤","ex":{"en":"Adam walked away from the crash with just cuts and grazes.","cn":"亚当在撞车事故中平安脱险，只受了点划伤和擦伤。"},"pos":"noun"}]}},"grieve":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（尤指因某人的亡故而）悲痛，悲伤，伤心","en":"If you grieve over something, especially someone's death, you feel very sad about it.","ex":{"en":"He's grieving over his dead wife and son","cn":"他因丧妻失子而悲痛不已。"}},{"pos":"VERB 动词","cn":"使难过；使悲伤","en":"If you are grieved by something, it makes you unhappy or upset.","ex":{"en":"He was deeply grieved by the sufferings of the common people","cn":"百姓的困苦使他痛心不已。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to feel extremely sad because someone that you love has died","cn":""},{"en":"to feel sadness and respect for someone who has died, and to show this by the way you behave publicly, the clothes you wear etc","cn":""},{"en":"to feel very sad because someone has died, and to show this in the way you behave","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To grieve is to feel sorrow over something, especially people who have died."}]},"collocations":{"phrases":["ADV. deeply She had grieved deeply for her father. | still","PREP. for They are still grieving for their child. | over grieving over the loss of his daughter"]},"media":{"uk":"media/ldoce/hwd/bre/f/grieve0205.mp3","us":"media/ldoce/hwd/ame/3/grieve.mp3"},"examples":[{"en":"They are still grieving for their dead child.","cn":"他们还在为死去的孩子伤心。"},{"en":"Their lack of interest grieved her.","cn":"他们不感兴趣使她很痛心。"}],"oxford":{"phon":"ɡriːv","pos":"verb","senses":[{"en":"to feel very sad, especially because somebody has died","cn":"（尤指因某人的去世而）悲伤，悲痛，伤心","g":"[intransitive, transitive]","ex":{"en":"They are still grieving for their dead child.","cn":"他们还在为死去的孩子伤心。"}},{"en":"to make you feel very sad","cn":"使悲伤；使悲痛；使伤心","g":"[transitive]","lab":"formal","ex":{"en":"It grieved him that he could do nothing to help her.","cn":"他因无法帮助她而伤心。"}}]}},"guy":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"男人；小伙子；家伙","en":"A guy is a man.","ex":{"en":"I was working with a guy from Manchester.","cn":"我与一个来自曼彻斯特的小伙子一起工作。"}},{"pos":"N-VOC; N-PLURAL 称呼名词；复数名词","cn":"（美国英语）伙计们，兄弟们，姐妹们","en":"Americans sometimes address a group of people, whether they are male or female, as guys or you guys.","ex":{"en":"Hi, guys. How are you doing?","cn":"嗨，伙计们，大家还好吧？"}},{"pos":"N-COUNT 可数名词","cn":"同guy rope","en":"A guy is the same as a guy rope ."},{"pos":"N-COUNT 可数名词","cn":"盖伊模拟像（英国庆祝篝火之夜焚烧的身着古装的人像）","en":"In Britain, a guy is a model of a man that is made from old clothes filled with straw or paper. Guys are burned on bonfires as part of the celebrations for Guy Fawkes Night."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an adult male human","cn":""},{"en":"a man","cn":"男人﹐家伙"},{"en":"a man – used as a very polite way of talking about a man","cn":""}]},"vocab":{"pos":"1 n 2 n v 3 v","senses":[{"en":"When you're casually talking about a man or a boy, you can call him a guy . It's an informal way to refer to a person, especially a male."}]},"collocations":{"phrases":["ADJ. decent, friendly, funny, good, great, nice, sweet, wonderful | bad | ordinary, regular Neighbours described the killer as &lsquo;just a"]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdeguy.mp3","us":"media/ldoce/hwd/ame/5/guy1.mp3"},"examples":[{"en":"At the end of the film the bad guy gets shot.","cn":"这坏蛋在影片结尾时被击毙。"},{"en":"Come on, you guys, let's get going!","cn":"快点，伙计们，咱们走吧！"}],"oxford":{"phon":"ɡaɪ","pos":"noun","senses":[{"en":"a man","cn":"男人；小伙子；家伙","g":"[countable]","lab":"informal","ex":{"en":"a big/little guy","cn":"大个子；小个子"}},{"en":"a group of people of either sex","cn":"一群男人（或女人）；伙计们；兄弟（或姐妹）们","g":"[plural]","lab":"informal","ex":{"en":"Come on, you guys, let's get going!","cn":"快点，伙计们，咱们走吧！"}},{"en":"(in the UK) a model of a man dressed in old clothes that is burned on a bonfire on 5 November during the celebrations for Bonfire Night","cn":"盖伊模拟像（英国每年 11 月 5 日庆祝篝火之夜焚烧的身着古装的人体模型）","g":"[countable]"},{"en":"a rope used to keep a pole or tent in a secure position","cn":"（立杆子或架帐篷用的）支索，牵索，拉索","g":"[countable]"},{"en":"a first name for boys","cn":"盖伊（男子名）","pos":""}]}},"gale":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"大风；强风","en":"A gale is a very strong wind.","ex":{"en":"...forecasts of fierce gales over the next few days.","cn":"预报未来几天有超强大风"}},{"pos":"N-COUNT 可数名词","cn":"一阵（大笑声）","en":"You can refer to the loud noise made by a lot of people all laughing at the same time as a gale of laughter or gales of laughter.","ex":{"en":"This was greeted with gales of laughter from the audience.","cn":"观众对此报以阵阵笑声。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very strong wind","cn":"大风"},{"en":"a storm that has very strong fast winds and that moves over water – used about storms in the North Atlantic Ocean","cn":""},{"en":"a violent tropical storm – used about storms in the Western Pacific Ocean","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If there’s a gale coming your way, you better hold onto your new hat and your little dog, Toto, too, because this is an extremely strong wind."}]},"collocations":{"phrases":["ADJ. fierce, full, great, heavy, howling, severe, strong | Force 9, Force 10, etc. | northerly, westerly, etc. | autumn, winter, etc. | equi","VERB + GALE blow It was blowing a gale outside. | get caught in We got caught in a howling gale.","GALE + VERB blow A severe gale was blowing along the coast.","GALE + NOUN force gale force winds | warning","PREP. in ~ The tree had come down in a fierce gale the night before."]},"media":{"uk":"media/ldoce/hwd/bre/e/gale0205.mp3","us":"media/ldoce/hwd/ame/f/gale.mp3"},"examples":[{"en":"His speech was greeted with gales of laughter.","cn":"人们对他的演讲报以阵阵笑声。"},{"en":"The gale blew down hundreds of trees.","cn":"大风吹倒了数百棵树。"}],"oxford":{"phon":"ɡeɪl","pos":"noun","senses":[{"en":"an extremely strong wind","cn":"大风；8 级风","lab":"British English","ex":{"en":"The gale blew down hundreds of trees.","cn":"大风吹倒了数百棵树。"}}]}},"gist":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"（发言、谈话或文章的）主旨，要点","en":"The gist of a speech, conversation, or piece of writing is its general meaning.","ex":{"en":"He related the gist of his conversation to Naseby.","cn":"他将他谈话的要点告诉了纳斯比。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the main ideas or the basic meaning of a speech, piece of writing etc","cn":""},{"en":"the general meaning of a speech, argument, piece of writing etc, without all the details","cn":""},{"en":"the main aim or purpose of an argument, speech, or political action","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When you need a quick summary of the essentials, rather than the whole story or a thorough explanation, you're looking for the gist ."}]},"collocations":{"phrases":["ADJ. general","VERB + GIST convey, give (sb) It is difficult to convey the gist of Reich's ideas simply. | follow, get, understand","PREP. ~ of I could follow the general gist of their conversation."]},"media":{"uk":"media/ldoce/hwd/bre/e/gist0205.mp3","us":"media/ldoce/hwd/ame/b/gist.mp3"},"examples":[{"en":"I missed the beginning of the lecture — can you give me the gist of what he said?","cn":"我错过了讲座的开头，给我讲讲他说话的要点好吗？"},{"en":"I'm afraid I don't quite follow your gist (= what you really mean).","cn":"对不起，我还不太明白你的意思。"}],"oxford":{"phon":"dʒɪst","pos":"noun","senses":[{"en":"the main or general meaning of a piece of writing, a speech or a conversation","cn":"要点；主旨；大意","ex":{"en":"to get (= understand) the gist of an argument","cn":"理解辩论的主旨"}}]}},"guesswork":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"猜测；推测","en":"Guesswork is the process of trying to guess or estimate something without knowing all the facts or information.","ex":{"en":"The question of who planted the bomb remains a matter of guesswork.","cn":"到底是谁安放了炸弹依然只是猜测。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an attempt to guess something","cn":""},{"en":"an opinion about the value, size, speed etc of something that is formed partly by calculating and partly by guessing","cn":""},{"en":"when you try to understand something or find the answer to something by guessing, because you do not have all the information you need","cn":""}]},"collocations":{"phrases":["ADJ. pure | informed, inspired Their results owe more to informed guesswork than to actual knowledge.","VERB + GUESSWORK be based on Their price estimates are based on pure guesswork.","PHRASES a matter of guesswork Long-term forecasts were largely a matter of guesswork."]},"media":{"uk":"media/ldoce/hwd/bre/1/guesswork0205.mp3","us":"media/ldoce/hwd/ame/9/guesswork.mp3"},"examples":[{"en":"It was pure guesswork on our part.","cn":"这纯属我们的猜测。"},{"en":"There’s a lot of guesswork in these calculations.","cn":"这些计算中有多处都是推测。"}],"oxford":{"phon":"ˈɡeswɜːk","pos":"noun","senses":[{"en":"the process of trying to find an answer by guessing when you do not have enough information to be sure","cn":"猜想；猜测","ex":{"en":"It was pure guesswork on our part.","cn":"这纯属我们的猜测。"}}]}},"guitar":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"吉他；六弦琴","en":"A guitar is a musical instrument with six strings and a long neck. You play the guitar by plucking or strumming the strings."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a musical instrument usually with six strings that you play by pulling the strings with your fingers or with a plectrum (= small piece of plastic, metal etc )","cn":"吉他"}]},"collocations":{"phrases":["ADJ. acoustic, electric | bass, lead, rhythm | classical, jazz, rock | 6/12-string","VERB + GUITAR strum (on) As she sang, she strummed her guitar. | tune (up) | build, make","GUITAR + NOUN string | lick, riff •"]},"media":{"img":["media/ldoce/img/guitar.jpg"],"uk":"media/ldoce/hwd/bre/a/guitar0205.mp3","us":"media/ldoce/hwd/ame/4/guitar.mp3"},"examples":[{"en":"an acoustic/an electric/a classical, etc. guitar","cn":"原声吉他、电吉他、古典吉他等"},{"en":"She plays guitar in a band.","cn":"她在乐队里弹奏吉他。"}],"oxford":{"phon":"ɡɪˈtɑː(r)","pos":"noun","senses":[{"en":"a musical instrument that usually has six strings and that you play with your fingers or with a plectrum","cn":"吉他","ex":{"en":"an acoustic/electric guitar","cn":"原声吉他；电吉他"}}]}},"gust":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一阵强风；一阵狂风","en":"A gust is a short, strong, sudden rush of wind.","ex":{"en":"A gust of wind drove down the valley","cn":"一阵狂风刮过山谷。"}},{"pos":"VERB 动词","cn":"猛刮；劲吹","en":"When the wind gusts, it blows with short, strong, sudden rushes.","ex":{"en":"The wind gusted again","cn":"风再次猛烈地刮了起来。"}},{"pos":"N-COUNT 可数名词","cn":"（感情的）迸发，爆发","en":"If you feel a gust of emotion, you feel the emotion suddenly and intensely.","ex":{"en":"...a small gust of pleasure.","cn":"短暂的一阵欢喜"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sudden strong movement of wind, air, rain etc","cn":"一阵狂风﹔一阵暴雨"},{"en":"a sound of loud laughter","cn":"一阵狂笑"},{"en":"if the wind gusts, it blows strongly with sudden short movements 〔","cn":"狂风〕一阵阵劲吹"}]},"vocab":{"pos":"n","senses":[{"en":"A gust is a strong, short burst of air. If you're walking around on a brisk, cold day, hold on to your papers tightly — a gust of wind could sweep in and send your notes flying into the air."}]},"collocations":{"phrases":["ADJ. great | little | strong | sudden | occasional","PREP. ~ of a sudden gust of wind","PHRASES blow/come in gusts The wind came in great gusts off the Pacific."]},"media":{"uk":"media/ldoce/hwd/bre/2/gust_n0205.mp3","us":"media/ldoce/hwd/ame/e/gust1.mp3"},"examples":[{"en":"winds gusting up to 60 mph","cn":"风速达每小时 60 英里的狂风"},{"en":"A gust of wind blew his hat off.","cn":"一阵狂风把他的帽子刮掉了。"}],"oxford":{"phon":"ɡʌst","pos":"noun","senses":[{"en":"a sudden strong increase in the amount and speed of wind that is blowing","cn":"一阵强风；一阵狂风","ex":{"en":"A gust of wind blew his hat off.","cn":"一阵狂风把他的帽子刮掉了。"}},{"en":"a sudden strong expression of emotion","cn":"（感情的）迸发，爆发，发作","ex":{"en":"a gust of laughter","cn":"一阵笑声"}},{"en":"to suddenly blow very hard","cn":"猛刮；劲吹","ex":{"en":"winds gusting up to 60 mph","cn":"风速达每小时 60 英里的狂风"},"pos":"verb"}]}},"girlfriend":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"女朋友；女情人","en":"Someone's girlfriend is a girl or woman with whom they are having a romantic or sexual relationship.","ex":{"en":"He had been going out with his girlfriend for seven months","cn":"他同女朋友已经交往7个月了。"}},{"pos":"N-COUNT 可数名词","cn":"女伴；女友","en":"A girlfriend is a female friend.","ex":{"en":"I met a girlfriend for lunch.","cn":"我同一位女友共进了午餐。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a girl or woman that you have a romantic relationship with, especially for a fairly long time","cn":""},{"en":"the person you are married to, or the person you are living with and having a sexual relationship with","cn":""},{"en":"someone who was your girlfriend or boyfriend in the past","cn":""}]},"collocations":{"phrases":["ADJ. current, latest, new | ex-, former, old | long-standing, long-term, serious, steady | live-in | pregnant | jealous | jilted","QUANT. string, succession","VERB + GIRLFRIEND have | meet | live with | sleep with | propose to | marry"]},"media":{"uk":"media/ldoce/hwd/bre/7/girlfriend0205.mp3","us":"media/ldoce/hwd/ame/d/girlfriend.mp3"},"examples":[{"en":"I had lunch with a girlfriend.","cn":"我同女友一起吃了午饭。"},{"en":"He’s never had a girlfriend .","cn":"他从来没有交过女朋友。"}],"oxford":{"phon":"ˈɡɜːlfrend","pos":"noun","senses":[{"en":"a girl or a woman that somebody is having a romantic relationship with","cn":"女朋友","ex":{"en":"He’s got a new girlfriend.","cn":"他有了新女友。"}},{"en":"a female friend","cn":"女性朋友","ex":{"en":"I had lunch with a girlfriend.","cn":"我同女友一起吃的午饭。"}}]}},"golfer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"打高尔夫球的人；高尔夫球运动员","en":"A golfer is a person who plays golf for pleasure or as a profession."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a game in which the players hit a small white ball into holes in the ground with a set of golf clubs, using as few hits as possible","cn":""}]},"collocations":{"phrases":["ADJ. brilliant, good | experienced | handicap a low handicap golfer | champion, top | keen | amateur, professional | club","GOLFER + VERB play"]},"media":{"uk":"media/ldoce/hwd/bre/b/golf_las2_br.mp3","us":"media/ldoce/hwd/ame/6/golf.mp3"},"examples":[{"en":"He plays golf on Sundays.","cn":""},{"en":"a round of golf (= complete game of golf )","cn":""}],"oxford":{"phon":"ˈɡɒlfə(r)","pos":"noun","senses":[{"en":"a person who plays golf","cn":"高尔夫球运动员","ex":{"en":"a low handicap golfer","cn":"超过标准杆数不多的高尔夫球手"}}]}},"grab":{"collins":{"senses":[{"pos":"VERB 动词","cn":"抓住；攫取","en":"If you grab something, you take it or pick it up suddenly and roughly.","ex":{"en":"I managed to grab her hand","cn":"我抓到了她的手。"}},{"pos":"VERB 动词","cn":"（试图）抓住,夺取","en":"If you grab at something, you try to grab it.","ex":{"en":"He was clumsily trying to grab at Alfred's arms.","cn":"他笨手笨脚地想抓住艾尔弗雷德的手臂。"}},{"pos":"VERB 动词","cn":"引起…的注意；吸引","en":"If you grab someone who is walking past, you succeed in getting their attention.","ex":{"en":"Grab that waiter, Mary Ann.","cn":"玛丽·安，叫那位侍者过来。"}},{"pos":"VERB 动词","cn":"吸引（某人的注意）","en":"If you grab someone's attention, you do something in order to make them notice you.","ex":{"en":"I jumped on the wall to grab the attention of the crowd.","cn":"为了吸引那群人的注意，我纵身跃上墙头。"}},{"pos":"VERB 动词","cn":"（匆忙地）拿，取；抓紧（吃、睡等）","en":"If you grab something such as food, drink, or sleep, you manage to get some quickly.","ex":{"en":"Grab a beer.","cn":"拿瓶啤酒来。"}},{"pos":"VERB 动词","cn":"抓住（机会等）","en":"If you grab something such as a chance or opportunity, or grab at it, you take advantage of it eagerly.","ex":{"en":"She grabbed the chance of a job interview","cn":"她抓住了一次求职面试的机会。"}},{"pos":"N-COUNT 可数名词","cn":"攫取；争取；赚取","en":"A grab for something such as power or fame is an attempt to gain it.","ex":{"en":"...a grab for personal power.","cn":"对个人权力的巧取豪夺"}},{"pos":"See also:","cn":"","en":"to grab hold of→see: ;"},{"pos":"PHRASE 短语","cn":"供人竞购的；供争夺的","en":"If something is up for grabs, it is available to anyone who is interested.","ex":{"en":"The famous Ritz hotel is up for grabs for £100m.","cn":"著名的里兹饭店开价1亿英镑供各方竞购。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to have something in your hand, hands, or arms","cn":""},{"en":"to hold something very tightly and not let it go","cn":""},{"en":"to hold something tightly, especially because you do not want to drop or lose it","cn":""}]},"collocations":{"phrases":["ADV. suddenly","VERB + GRAB try to | manage to He managed to grab a couple of hours' sleep.","PREP. at I grabbed at his arm as he ran past. | by As he walked past the boys, one of them grabbed him by the arm. | from Somebody tried to ","PHRASES grab hold of sth He grabbed hold of a handrail to save himself from falling."]},"media":{"uk":"media/ldoce/hwd/bre/1/grab_n0205.mp3","us":"media/ldoce/hwd/ame/d/grab1.mp3"},"examples":[{"en":"There are £25 000 worth of prizes up for grabs in our competition!","cn":"在我们的比赛中有价值 25 000 英镑的奖品供人争夺！"},{"en":"I'll see if I can grab the waitress and get the bill.","cn":"我要看能不能引起服务员的注意，让她拿账单来。"}],"oxford":{"phon":"ɡræb","pos":"verb","senses":[{"en":"to take or hold somebody/something with your hand suddenly or roughly","cn":"抓住；攫取","g":"[transitive, intransitive]","ex":{"en":"She grabbed his arm as he got up to leave.","cn":"他起身准备离开时，她一把抓住他的胳膊。"}},{"en":"to try to take hold of something","cn":"（试图）抓住，夺得","g":"[intransitive]","ex":{"en":"She grabbed at the branch, missed and fell.","cn":"她抓树枝，可没抓着，就跌倒了。"}},{"en":"to take advantage of an opportunity to do or have something","cn":"利用，抓住（机会）","g":"[transitive, intransitive]","ex":{"en":"This was my big chance and I grabbed it with both hands.","cn":"这是我的大好机会，我紧紧抓住。"}},{"en":"to have or take something quickly, especially because you are in a hurry","cn":"（尤指匆忙地）取，拿，吃，喝","g":"[transitive]","ex":{"en":"Let's grab a sandwich before we go.","cn":"咱们赶快吃个三明治就走吧。"}},{"en":"to take something for yourself, especially in a selfish or greedy way","cn":"（尤指自私、贪婪地）捞取，赚取，抢占","g":"[transitive]","ex":{"en":"By the time we arrived, someone had grabbed all the good seats.","cn":"我们到达时，所有的好位子都给人占了。"}},{"en":"to get somebody’s attention","cn":"引人注意；吸引","g":"[transitive]","ex":{"en":"I'll see if I can grab the waitress and get the bill.","cn":"我要看能不能引起服务员的注意，让她拿账单来。"}},{"en":"to take a picture from a television or video film, or from a computer screen, and store it as an image on a computer","cn":"抓取（或截获、采集）的图像","g":"[transitive]","ex":{"en":"You can use this keyboard shortcut to grab part of the screen.","cn":"您可以使用此键盘快捷键来抓取屏幕的一部分。"}},{"en":"a sudden attempt to take or hold somebody/something","cn":"猛然的抓取；突然的抢夺","g":"[usually singular]","ex":{"en":"He made a grab for her bag.","cn":"他突然去抢她的手提包。"},"pos":"noun"},{"en":"a picture taken from a television or video film, or from a computer screen, stored as an image on a computer","cn":"截屏；截图","lab":"computing","ex":{"en":"a frame grab from CCTV","cn":"从闭路电视抓取的一帧图像"},"pos":"noun"},{"en":"a piece of equipment that lifts and holds goods, for example the equipment that hangs from a crane","cn":"抓斗；抓具","pos":"noun"}]}},"grope":{"collins":{"senses":[{"pos":"VERB 动词","cn":"摸索；探寻","en":"If you grope for something that you cannot see, you try to find it by moving your hands around in order to feel it.","ex":{"en":"With his left hand he groped for the knob, turned it, and pulled the door open","cn":"他左手摸索着门把手，转动一下，然后推开门。"}},{"pos":"VERB 动词","cn":"摸索着走","en":"If you grope your way to a place, you move there, holding your hands in front of you and feeling the way because you cannot see anything.","ex":{"en":"I didn't turn on the light, but groped my way across the room.","cn":"我没有开灯，而是一路摸黑走过房间。"}},{"pos":"VERB 动词","cn":"探索；努力寻求","en":"If you grope for something, for example the solution to a problem, you try to think of it, when you have no real idea what it could be.","ex":{"en":"He groped for solutions to the problems facing the country","cn":"他在探求国家所面临问题的解决办法。"}},{"pos":"VERB 动词","cn":"抚摸；猥亵","en":"If one person gropes another, they touch or take hold of them in a rough, sexual way.","ex":{"en":"He would try to grope her breasts and put his hand up her skirt.","cn":"他会试图摸她的胸部，还把手从她的裙子上向上移。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to put your fingers or hand onto someone or something for a very short time","cn":""},{"en":"to touch something with your fingers in order to find out about it","cn":""},{"en":"to touch something and pick it up and hold it in your hands","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"When you grope for something, you try to get a grip on it. If you drop your flashlight in a dark cave, you might grope around for it. Beware of snakes!"}]},"collocations":{"phrases":["ADV. blindly | vaguely | about/around/round","PREP. for She groped blindly for the door handle.","PHRASES grope your way I groped my way across the pitch-black stage."]},"media":{"uk":"media/ldoce/hwd/bre/6/grope_n0205.mp3","us":"media/ldoce/hwd/ame/e/grope1.mp3"},"examples":[{"en":"( figurative ) ‘It's so … , so … ’ I was groping for the right word to describe it. “","cn":"它是那么 … ，那么 … ”我想找一个恰当的字眼来描述它。"},{"en":"He groped around in the dark for his other sock.","cn":"他在黑暗中到处瞎摸找另一只袜子。"}],"oxford":{"phon":"ɡrəʊp","pos":"verb","senses":[{"en":"to try and find something that you cannot see, by feeling with your hands","cn":"摸索；搜索；搜寻；探寻","g":"[intransitive]","lab":"figurative","ex":{"en":"He groped around in the dark for his other sock.","cn":"他在黑暗中到处摸找另一只袜子。"}},{"en":"to try and reach a place by feeling with your hands because you cannot see clearly","cn":"（用手）摸索着往前走","g":"[transitive, intransitive]","ex":{"en":"He groped his way up the staircase in the dark.","cn":"他摸黑走上楼梯。"}},{"en":"to touch somebody sexually, especially when they do not want you to","cn":"猥亵；对（某人）毛手毛脚","g":"[transitive]","lab":"informal","ex":{"en":"She described how he had groped her whenever they were alone.","cn":"她述说了他每次和她单独相处时是怎样猥亵她的。"}},{"en":"an act of groping somebody (= touching them sexually)","cn":"猥亵；摸","pos":"noun"}]}},"gibraltar":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a town and port on the Rock of Gibraltar on the southern coast of Spain. It has belonged to the UK since 1713, but the Spanish government would like it to belong to Spain. Many tourists visit Gibraltar.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/lpd_gibraltar.mp3","us":"media/ldoce/hwd/ame/6/p028-000005374.mp3"},"oxford":{"phon":"dʒɪˈbrɔːltə(r)","pos":"","senses":[{"en":"a large rock at the western end of the Mediterranean Sea, connected to the south coast of Spain. There is a small town and a large military base on Gibraltar, which is owned by Britain but claimed by Spain. It used to be an important centre for the Royal Navy and the RAF, guarding the area where the Mediterranean flows into the Atlantic, but many of the armed forces have left Gibraltar, and tourism is becoming a more important industry. Many monkeys, called Barbary apes, live on the Rock of Gibraltar, and there is a legend that the British will leave Gibraltar when the monkeys die or stop living there.","cn":"直布罗陀：位于地中海西端的一块大岩石，与西班牙的南海岸相连。在直布罗陀拥有一个小镇和一个大型军事基地，该基地归英国所有，但西班牙宣称拥有主权。它曾经是皇家海军和皇家空军的重要中心，守卫着地中海流入大西洋的地区，但是许多武装部队已经离开直布罗陀，旅游业正变得越来越重要。许多叫做“巴巴里猿”的猴子生活在直布罗陀岩上，有传说说，当猴子死或停止在那里生活时，英国人将离开直布罗陀。"}]}},"genocide":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"种族灭绝；大屠杀","en":"Genocide is the deliberate murder of a whole community or race.","ex":{"en":"They have alleged that acts of genocide and torture were carried out.","cn":"他们声称实施了大屠杀和酷刑。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when a large number of people are easily killed, because they are not able to defend themselves","cn":""},{"en":"when a large number of people are killed in a very cruel or violent way","cn":""},{"en":"when a large number of people are violently killed, especially in a war - used especially in newspapers","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Genocide refers to the systematic destruction of a race or cultural group. In the Rwandan genocide of 1994, members of one ethnic group, the Hutus, killed some 850,000 Tutsis in an attempt to wipe them out completely."}]},"collocations":{"phrases":["ADJ. mass Refugees gave accounts of the mass genocide. | cultural","PREP. ~ against genocide against ethnic minorities • Note at CRIME (for verbs)"]},"media":{"uk":"media/ldoce/hwd/bre/8/genocide0205.mp3","us":"media/ldoce/hwd/ame/0/genocide.mp3"},"examples":[{"en":"The military leaders were accused of genocide.","cn":"军方领导人被指控实施种族大屠杀。"}],"oxford":{"phon":"ˈdʒenəsaɪd","pos":"noun","senses":[{"en":"the murder of a large number of people from a particular nation or ethnic group, with the aim of destroying that nation or group","cn":"种族灭绝；大屠杀","ex":{"en":"Refugees gave accounts of the mass genocide.","cn":"难民们描述了大规模种族屠杀的场面。"}}]}},"gospel":{"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"福音书（《圣经·新约》中记录耶稣基督生平和教诲的四卷书）","en":"In the New Testament of the Bible, the Gospels are the four books which describe the life and teachings of Jesus Christ.","ex":{"en":"...the parable in St Matthew's Gospel.","cn":"《马太福音》中的寓言故事"}},{"pos":"N-SING 单数名词","cn":"福音（耶稣的启示和教义）","en":"In the Christian religion, the gospel refers to the message and teachings of Jesus Christ, as explained in the New Testament.","ex":{"en":"I didn't shirk my duties. I visited the sick and I preached the gospel.","cn":"我没有逃避职责，我探望病人，也宣讲福音。"}},{"pos":"N-COUNT 可数名词","cn":"教义；信条","en":"You can use gospel to refer to a particular way of thinking that a person or group believes in very strongly and that they try to persuade others to accept.","ex":{"en":"It taught only materialism, the gospel of mammon.","cn":"它只是宣扬金钱至上的物欲主义。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"福音音乐（尤流行于美国南部黑人基督徒中）","en":"Gospel or gospel music is a style of religious music that uses strong rhythms and vocal harmony. It is especially popular among black Christians in the southern United States of America.","ex":{"en":"I had to go to church, so I grew up singing gospel","cn":"我必须去教堂做礼拜，因此我是唱着福音歌长大的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"绝对真理","en":"If you take something as gospel, or as gospel truth, you believe that it is completely true.","ex":{"en":"The results were not to be taken as gospel","cn":"别以为这些结果就一定是正确的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"definitely true, so that no one could argue or disagree about it","cn":""},{"en":"use this to emphasize that something is definitely true","cn":""},{"en":"one of the four books in the Bible about Christ’s life","cn":"福音书〔《圣经》中有关耶稣生平的四福音书之一〕"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Follow advice like gospel and you're following it as though it was the final word or authority on the matter."}]},"collocations":{"phrases":["ADJ. Christian","VERB + GOSPEL bring, preach, proclaim, spread, take She preached the Christian gospel to the poor and destitute. | hear Thousands came to he","GOSPEL + NOUN message, story"]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdegospel.mp3","us":"media/ldoce/hwd/ame/c/gospel1.mp3"},"examples":[{"en":"Don't take his word as gospel.","cn":"别把他的话当作绝对真理。"},{"en":"He preached a gospel of military strength.","cn":"他鼓吹军事实力主义。"}],"oxford":{"phon":"ˈɡɒspl","pos":"noun","senses":[{"en":"one of the four books in the Bible about the life and teaching of Jesus","cn":"福音（《圣经》中关于耶稣生平和教诲的四福音书之一）","g":"[countable]","ex":{"en":"the Gospel according to St John","cn":"约翰福音"}},{"en":"the life and teaching of Jesus as explained in the Bible","cn":"福音（耶稣的事迹和教诲）","g":"[singular]","lab":"North American English","ex":{"en":"preaching/spreading the gospel","cn":"宣讲／传布福音"}},{"en":"a set of ideas that somebody believes in and tries to persuade others to accept","cn":"（个人的）信念，信仰","g":"[countable, usually singular]","ex":{"en":"He preached a gospel of military strength.","cn":"他鼓吹军事实力主义。"}},{"en":"the complete truth","cn":"绝对真理","g":"[uncountable]","lab":"informal","ex":{"en":"Is that gospel?","cn":"那是绝对真理吗？"}},{"en":"a style of religious singing developed by African Americans","cn":"福音音乐（最初在非裔美国人中间传唱的宗教音乐）","g":"[uncountable]","ex":{"en":"a gospel choir","cn":"福音唱诗班"}}]}},"groove":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"沟；槽；辙","en":"A groove is a deep line cut into a surface.","ex":{"en":"Their wheels left grooves in the ground.","cn":"他们的车轮在地面上留下了车辙印。"}},{"pos":"N-COUNT 可数名词","cn":"（流行音乐的）节奏","en":"In popular music, a groove is a rhythm.","ex":{"en":"...Latin and African grooves.","cn":"拉丁乐和非洲音乐的节奏"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long thin mark on a piece of paper, the ground, or another surface","cn":""},{"en":"a thin line that has been cut into a surface","cn":""},{"en":"a deep line in the ground which has been made by the wheels of vehicles","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A groove is an indentation or rut in something — like the grooves on an old record."}]},"collocations":{"phrases":["ADJ. deep, shallow | narrow, wide","VERB + GROOVE carve, cut, make Running water had carved a groove down the face of the wall.","PREP. ~ in a deep groove in the surface of the rock"]},"media":{"uk":"media/ldoce/hwd/bre/e/groove0205.mp3","us":"media/ldoce/hwd/ame/0/groove.mp3"},"examples":[{"en":"a jazz groove","cn":"爵士乐节奏"},{"en":"The bolt slid easily into the groove.","cn":"插销顺畅地滑入凹槽。"}],"oxford":{"phon":"ɡruːv","pos":"noun","senses":[{"en":"a long narrow cut in the surface of something hard","cn":"沟；槽；辙；纹","ex":{"en":"Cut a groove 3 cm from the top of the piece of wood.","cn":"在距离木头顶部 3 厘米处切出一个凹槽。"}},{"en":"a particular type of musical rhythm","cn":"（某种）音乐节奏（或律动）","lab":"informal","ex":{"en":"a jazz groove","cn":"爵士乐节奏"}}]}},"geneva":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a city in Switzerland which is the main base for the red cross , the world health organization , and several other important international organizations. It is on the shore of Lake Geneva, one of the largest lakes in Europe.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/lpd_geneva.mp3","us":"media/ldoce/hwd/ame/f/p028-000005328.mp3"}},"gem":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"宝石","en":"A gem is a jewel or stone that is used in jewellery.","ex":{"en":"...a gold mask inset with emeralds and other gems.","cn":"一张镶有翡翠和其他宝石的金面具"}},{"pos":"N-COUNT 可数名词","cn":"难能可贵的人（或物）；令人非常惬意的人（或事物）；精品","en":"If you describe something or someone as a gem, you mean that they are especially pleasing, good, or helpful.","ex":{"en":"...a gem of a hotel, Castel Clara","cn":"卡斯特尔·克拉拉酒店，酒店中的明珠"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a valuable stone, such as a diamond","cn":""},{"en":"a rare and valuable jewel such as a diamond or an emerald","cn":""},{"en":"a jewel that has been cut into a special shape","cn":""}]},"collocations":{"phrases":["ADJ. precious, priceless","PHRASES dripping with gems a millionairess dripping with gems and pearls | encrusted/studded with gems a belt studded with priceless gems 2 ","ADJ. little | absolute, real The second side of their new album contains some real gems. | hidden She worked in the antiques trade, searchin","PHRASES a gem of a sth This is a little gem of a flower."]},"media":{"uk":"media/ldoce/hwd/bre/c/gem0205.mp3","us":"media/ldoce/hwd/ame/f/gem.mp3"},"examples":[{"en":"This picture is the gem (= the best) of the collection.","cn":"这幅画是收藏中的极品。"},{"en":"She's a real gem!","cn":"她真是难能可贵！"}],"oxford":{"phon":"dʒem","pos":"noun","senses":[{"en":"a precious stone that has been cut and polished and is used in jewellery","cn":"（经切割打磨的）宝石","lab":"less frequent","ex":{"en":"a crown studded with gems","cn":"镶有宝石的皇冠"}},{"en":"a person, place or thing that is especially good","cn":"难能可贵的人；风景优美的地方；美妙绝伦的事物","ex":{"en":"This picture is the gem (= the best) of the collection.","cn":"这幅画是收藏中的极品。"}}]}},"gymnastics":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"体操；体操训练","en":"Gymnastics consists of physical exercises that develop your strength, co-ordination, and ease of movement.","ex":{"en":"...the British Amateur Gymnastics Association.","cn":"英国业余体操协会"}},{"pos":"ADJ 形容词","cn":"体操的","en":"Gymnastic is used to describe things relating to gymnastics.","ex":{"en":"...gymnastic exercises.","cn":"体操训练"}},{"pos":"N-UNCOUNT 不可数名词","cn":"技巧；绝技","en":"You can use gymnastics to refer to activities which require skills such as speed and adaptability.","ex":{"en":"Hers is the kind of voice that excels at vocal gymnastics","cn":"她的嗓音擅长演绎有难度的歌曲。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sport involving physical exercises and movements that need skill, strength, and control, and that are often performed in competitions","cn":"体操"},{"en":"very clever thinking","cn":"头脑/智力/道德训练"},{"en":"using words in a very clever way","cn":"遣词造句的高超技巧"}]},"collocations":{"phrases":["ADJ. rhythmic","VERB + GYMNASTICS do She does gymnastics at school.","GYMNASTICS + NOUN display, exhibition | championships | coach","PREP. in (the) ~ •"]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdegymnastics.mp3","us":"media/ldoce/hwd/ame/6/gymnastics.mp3","img":["media/thumb/gymnastics.jpg"]},"examples":[{"en":"( figurative ) mental/verbal gymnastics (= quick or clever thinking or use of words)","cn":"智力/表达能力训练"},{"en":"mental/verbal gymnastics (= quick or clever thinking or use of words)","cn":""}],"oxford":{"phon":"dʒɪmˈnæstɪks","pos":"noun","senses":[{"en":"physical exercises, often using special equipment, that develop and show the body’s strength and ability to move and bend easily, often done as a sport in competitions","cn":"体操；体操训练","lab":"figurative","ex":{"en":"a gymnastics competition","cn":"体操比赛"}}]}},"grandparent":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（外）祖父母","en":"Your grandparents are the parents of your father or mother.","ex":{"en":"Tammy was raised by her grandparents.","cn":"塔米是爷爷奶奶抚养大的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"grandfather","cn":""},{"en":"grandmother","cn":""},{"en":"grandfather","cn":""}]},"collocations":{"phrases":["ADJ. maternal, paternal | doting a present from his doting grandparents","QUANT. set I've sent photos of the children to both sets of grandparents."]},"media":{"uk":"media/ldoce/hwd/bre/8/grandparent0205.mp3","us":"media/ldoce/hwd/ame/3/grandparent.mp3"},"examples":[{"en":"The children are staying with their grandparents.","cn":"孩子们与祖父母住在一起。"},{"en":"My grandparents live in Sussex.","cn":"我的祖父母住在萨塞克斯郡。"}],"oxford":{"phon":"ˈɡrænpeərənt","pos":"noun","senses":[{"en":"the father or mother of your father or mother","cn":"祖父；祖母；外祖父；外祖母","ex":{"en":"The children are staying with their grandparents.","cn":"孩子们与祖父母住在一起。"}}]}},"groundless":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（恐惧、指控、报道等）无理由的，无根据的","en":"If you say that a fear, accusation, or story is groundless, you mean that it is not based on evidence and is unlikely to be true or valid.","ex":{"en":"Fears that the world was about to run out of fuel proved groundless","cn":"事实证明对于世界燃料即将耗尽的担忧毫无根据。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"use this to say that there is no reason for someone to think or behave in a particular way","cn":""},{"en":"use this to say that there is no acceptable reason for someone to think or behave in a bad or unfair way. Be no justification is more formal than be no excuse","cn":""},{"en":"groundless fears, suspicions etc that are unnecessary because there are no facts to base them on","cn":""}]},"collocations":{"phrases":["VERBS be, prove, seem","ADV. completely, entirely, quite, totally, utterly Our fears proved totally groundless. | largely"]},"media":{"uk":"media/ldoce/hwd/bre/d/groundless0205.mp3","us":"media/ldoce/hwd/ame/7/groundless.mp3"},"examples":[{"en":"Our fears proved groundless.","cn":"我们的担心证明是毫无道理的。"},{"en":"groundless allegations","cn":"毫无根据的指控"}],"oxford":{"phon":"ˈɡraʊndləs","pos":"adjective","senses":[{"en":"not based on reason or evidence","cn":"无理由的；无根据的","ex":{"en":"They denied what they called completely groundless allegations.","cn":"他们否认了他们称之为毫无根据的指控。"}}]}},"grease":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"润滑油","en":"Grease is a thick, oily substance which is put on the moving parts of cars and other machines in order to make them work smoothly.","ex":{"en":"...grease-stained hands.","cn":"沾满油渍的手"}},{"pos":"VERB 动词","cn":"给…加润滑油；为…涂（或抹）油","en":"If you grease a part of a car, machine, or device, you put grease on it in order to make it work smoothly.","ex":{"en":"I greased front and rear hubs and adjusted the brakes.","cn":"我在前后轮毂上都抹了润滑油，还调校了刹车。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（皮肤分泌的）油脂","en":"Grease is an oily substance that is produced by your skin.","ex":{"en":"His hair is thick with grease.","cn":"他的头发油乎乎的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"动物油脂","en":"Grease is animal fat that is produced by cooking meat. You can use grease for cooking.","ex":{"en":"He could smell the bacon grease.","cn":"他闻到一股腌肉的油脂味儿。"}},{"pos":"VERB 动词","cn":"给…涂上油（以防粘锅）","en":"If you grease a dish, you put a small amount of fat or oil around the inside of it in order to prevent food sticking to it during cooking.","ex":{"en":"Grease two sturdy baking sheets and heat the oven to 400 degrees","cn":"在两块结实的烤板上抹些油，把烤炉加热到400度。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a fatty or oily substance that comes off meat when it is cooked, or off food made using butter or oil 〔","cn":"肉或食物中的〕油脂"},{"en":"a thick oily substance that is put on the moving parts of a car, machine etc to make it run or move smoothly","cn":"润滑油"},{"en":"an oily substance that is produced by your skin 〔","cn":"皮肤上的〕油脂"}]},"collocations":{"phrases":["ADV. well | lightly Place the cakes on a lightly greased baking tray."]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdegrease.mp3","us":"media/ldoce/hwd/ame/1/grease1.mp3"},"examples":[{"en":"Grease marks can be removed with liquid detergent.","cn":"用洗涤液可除去油渍。"},{"en":"Her hands were covered with oil and grease.","cn":"她满手油垢。"}],"oxford":{"phon":"ɡriːs","pos":"noun","senses":[{"en":"any thick oily substance, especially one that is used to make machines run smoothly","cn":"油脂；润滑脂","ex":{"en":"Grease marks can be removed with liquid detergent.","cn":"用洗涤液可除去油渍。"}},{"en":"animal fat that has been made softer by cooking or heating","cn":"（炼过的）动物油脂","ex":{"en":"He collected the plates, which were covered with grease.","cn":"他收走那些油腻的盘子。"}},{"en":"to rub grease or fat on something","cn":"给…加润滑油；在…上涂油（或抹油、擦油）","ex":{"en":"to grease a cake tin/pan","cn":"在蛋糕烤盘上抹油"},"pos":"verb"},{"en":"a US musical play about the love affairs of young people, especially Danny and Sandy, in a high school in the early days of rock and roll. The title refers to the hair oil used by the boys. In the successful film version (1978) John Travolta and Olivia Newton-John played the main parts. Grease 2 (1982) with different actors was less successful.","cn":"油脂：这是一部关于音乐的音乐剧，讲述了摇滚乐时代初期年轻人在高中时的爱情，尤其是丹尼和桑迪。标题是指男孩使用的发油。在成功的电影版本（1978年）中，约翰·特拉沃尔塔和奥利维亚·牛顿·约翰扮演了主要角色。油脂2（1982）由不同的演员完成，效果不佳。","pos":""}]}},"gum":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"口香糖","en":"Gum is a substance, usually tasting of mint, which you chew for a long time but do not swallow."},{"pos":"N-COUNT 可数名词","cn":"牙龈；齿龈；牙床","en":"Your gums are the areas of firm, pink flesh inside your mouth, which your teeth grow out of.","ex":{"en":"The toothbrush gently removes plaque without damaging the gums.","cn":"这种牙刷可以温和去除牙菌斑而不损伤齿龈。"}},{"pos":"N-MASS 物质名词","cn":"黏胶；黏合剂","en":"Gum is a type of glue that is used to stick two pieces of paper together.","ex":{"en":"He was holding up a pound note that had been torn in half and stuck together with gum.","cn":"他举着一张被撕成两半后又用胶粘在一起的一英镑的钞票。"}},{"pos":"ADJ 形容词","cn":"黏合的","en":"If two things are gummed together, they are stuck together.","ex":{"en":"It is a mild infection in which a baby's eyelashes can become gummed together.","cn":"这是一种轻微感染，会导致婴儿睫毛粘在一起。"}},{"pos":"N-MASS 物质名词","cn":"树胶；树脂","en":"Gum is a sticky substance which comes from the eucalyptus tree or from various other trees and shrubs."},{"pos":"","cn":"","en":"相关词组：gum up"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"your gums are the two areas of firm pink flesh at the top and bottom of your mouth, in which your teeth are fixed","cn":"齿龈﹐牙龈"},{"en":"chewing gum","cn":"口香糖"},{"en":"a type of glue used to stick light things such as paper together","cn":"黏胶"}]},"collocations":{"phrases":["ADJ. lower, upper | toothless The old man smiled to reveal toothless gums. | bleeding, swollen","GUM + NOUN disease"]},"media":{"uk":"media/ldoce/hwd/bre/9/brelasdegum.mp3","us":"media/ldoce/hwd/ame/3/gum1.mp3"},"examples":[{"en":"A large address label was gummed to the package.","cn":"包装袋上贴着一大张地址签条。"},{"en":"fruit gums","cn":"水果软糖"}],"oxford":{"phon":"ɡʌm","pos":"noun","senses":[{"en":"either of the areas of flesh in the mouth to which the teeth are attached","cn":"牙龈；齿龈；牙床","g":"[countable, usually plural]","ex":{"en":"gum disease","cn":"牙龈病"}},{"en":"a sticky substance produced by some types of tree","cn":"树胶；树脂","g":"[uncountable]"},{"en":"a type of glue used for sticking light things together, such as paper","cn":"黏胶，胶质物（用以粘轻东西，如纸等）","g":"[uncountable]"},{"en":"a sweet that you chew (= bite many times) but do not eat","cn":"口香糖","g":"[uncountable]"},{"en":"a fairly hard, coloured sweet that tastes of fruit and that you chew","cn":"水果糖","g":"[countable]","ex":{"en":"fruit gums","cn":"水果糖"}},{"en":"to spread glue on the surface of something; to stick two things together with glue","cn":"在…上涂胶；用黏胶粘","ex":{"en":"A large address label was gummed to the package.","cn":"包装袋上贴着一大张地址签条。"},"pos":"verb"}]}},"germ":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"细菌；病菌","en":"A germ is a very small organism that causes disease.","ex":{"en":"Chlorine is widely used to kill germs.","cn":"氯气被广泛用于杀菌。"}},{"pos":"N-SING 单数名词","cn":"起源；发端；萌芽","en":"The germ of something such as an idea is something which developed or might develop into that thing.","ex":{"en":"The germ of an idea took root in Rosemary's mind","cn":"罗斯玛丽心里萌生了一个念头。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very small living thing that can make you ill","cn":"病菌﹐细菌"},{"en":"the early stage of an idea, feeling etc that may develop into something bigger and more important","cn":"观念/理论/感情等的萌芽"},{"en":"the part of a plant or animal that can develop into a new plant or animal","cn":"胚原基﹐胚芽"}]},"vocab":{"pos":"n","senses":[{"en":"A germ is a tiny life form that spreads disease. Germs are also small things that grow into larger things — whether animals, plants, or ideas."}]},"collocations":{"phrases":["ADJ. virulent The epidemic was caused by a particularly virulent flu germ. | flu, typhoid, etc.","VERB + GERM carry Children carry all kinds of germs home from school. | harbour Cracks and scratches in work surfaces can harbour germs. | d","GERM + NOUN warfare"]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdegerm.mp3","us":"media/ldoce/hwd/ame/b/germ.mp3"},"examples":[{"en":"Here was the germ of a brilliant idea.","cn":"一个绝妙的主意就是从这里萌发的。"},{"en":"Dirty hands can be a breeding ground for germs.","cn":"脏手可能滋生病菌。"}],"oxford":{"phon":"dʒɜːm","pos":"noun","senses":[{"en":"a very small living thing that can cause infection and disease","cn":"微生物；细菌；病菌","g":"[countable, usually plural]","ex":{"en":"Disinfectant kills germs.","cn":"消毒剂可杀菌。"}},{"en":"an early stage of the development of something","cn":"起源；发端；萌芽","g":"[singular]","ex":{"en":"Here was the germ of a brilliant idea.","cn":"一个绝妙的主意就是从这里萌发的。"}},{"en":"the part of a plant or an animal that can develop into a new one","cn":"胚芽；胚原基；芽孢；胚胎","g":"[countable]","lab":"biology","ex":{"en":"The germ is the embryo of the new plant.","cn":"胚芽是新植物的胚胎。"}}]}},"glimmer":{"collins":{"senses":[{"pos":"VERB 动词","cn":"发微光；隐约闪烁","en":"If something glimmers, it produces or reflects a faint, gentle, often unsteady light.","ex":{"en":"The moon glimmered faintly through the mists.","cn":"月亮透过薄雾洒下微光。"}},{"pos":"N-COUNT 可数名词","cn":"（常指闪烁的）微光","en":"A glimmer is a faint, gentle, often unsteady light.","ex":{"en":"In the east there is the slightest glimmer of light.","cn":"东方闪现出一丝微光。"}},{"pos":"N-COUNT 可数名词","cn":"一丝；少许","en":"A glimmer of something is a faint sign of it.","ex":{"en":"Despite an occasional glimmer of hope, this campaign has not produced any results","cn":"虽然偶尔会闪现一丝希望，但是这场宣传活动目前并无任何效果。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"making you feel more confident and hopeful","cn":""},{"en":"seeming likely to be good or successful","cn":""},{"en":"if something such as a new situation or discovery offers hope , it makes it possible for people to feel more hopeful that a bad situation will improve","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A glimmer is a tiny glint of light or the sliver of an idea. Either way, it's a sign of a lot more going on behind the scenes."}]},"collocations":{"phrases":["ADJ. faint, tiny In the east we could see the first faint glimmer of dawn. (figurative) The faint glimmer of an idea had crept into his mind","PREP. ~ of"]},"media":{"uk":"media/ldoce/hwd/bre/7/glimmer_n0205.mp3","us":"media/ldoce/hwd/ame/2/glimmer1.mp3"},"examples":[{"en":"We could see a glimmer of light on the far shore.","cn":"我们可以看到对岸远处微微闪烁的灯光。"},{"en":"I caught the glimmer of a smile in his eyes.","cn":"我看到他眼里闪现出一丝笑意。"}],"oxford":{"phon":"ˈɡlɪmə(r)","pos":"noun","senses":[{"en":"a small unsteady light","cn":"微弱的闪光；闪烁的微光","ex":{"en":"We could see a glimmer of light on the far shore.","cn":"我们可以看到远处岸上微微闪烁的灯光。"}},{"en":"a small sign of something","cn":"微弱的迹象；一丝；一线","ex":{"en":"a glimmer of hope","cn":"一线希望"}},{"en":"to shine with a small unsteady light","cn":"隐约地闪烁；发出微弱的闪光","lab":"figurative","ex":{"en":"The candles glimmered in the corner.","cn":"烛光在角落里忽明忽暗地闪烁。"},"pos":"verb"}]}},"gp":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"全科医生；普通医生","en":"A GP is a doctor who does not specialize in any particular area of medicine, but who has a medical practice in which he or she treats all types of illness. GP is an abbreviation for (缩略=) 'general practitioner'.","ex":{"en":"Her husband called their local GP.","cn":"她的丈夫打电话叫来了当地的全科医生。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who treats people who are ill, who has completed a long course of study at medical school","cn":""},{"en":"a doctor who is trained in general medicine and who treats the people who live in a local area","cn":""},{"en":"a doctor","cn":""}]},"collocations":{"phrases":["ADJ. excellent, good | qualified | experienced | family, local Who is your local GP?","VERB + GP register with You should register with a GP as soon as possible.","GP + VERB refer sb The GP referred her to a specialist. • Note at DOCTOR (for more verbs)"]},"media":{"uk":"media/ldoce/hwd/bre/8/brelasdegp.mp3","us":"media/ldoce/hwd/ame/3/gp.mp3"},"examples":[{"en":"There are four GPs in our local practice.","cn":"在我们地区诊所有四个全科医生。"},{"en":"Go and see your GP as soon as possible.","cn":"尽早去看你的全科医生。"}],"oxford":{"phon":"ˌdʒiː ˈpiː","pos":"noun","senses":[{"en":"a doctor who is trained in general medicine and who works in the local community, not in a hospital (the abbreviation for general practitioner)","cn":"（社区）全科医生，家庭医生（全写为 general practitioner）","lab":"especially British English","ex":{"en":"Go and see your GP as soon as possible.","cn":"尽早去看你的全科医生。"}}]}},"george":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"used when you are pleasantly surprised","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/george_n.mp3","us":"media/ldoce/hwd/ame/d/laadgeorge.mp3"},"examples":[{"en":"By George, I think you're right!","cn":""}],"oxford":{"phon":"dʒɔːdʒ","pos":"","senses":[{"en":"a first name for boys","cn":"乔治（男子名）"}]}},"gala":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"庆典；演出；盛会","en":"A gala is a special public celebration, entertainment, performance, or festival.","ex":{"en":"...a gala evening at the Royal Opera House.","cn":"在皇家歌剧院举行的盛大晚会"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a public entertainment or performance to celebrate a special occasion","cn":"庆典﹐演出盛会"},{"en":"a sports competition, especially in swimming","cn":"运动会〔尤指游泳比赛〕"}]},"vocab":{"pos":"n","senses":[{"en":"A gala is a big party. If you're going to a gala, you'll want to wear your fanciest ball gown — you'll want to look great for the best party of the year."}]},"collocations":{"phrases":["ADJ. charity, Royal | swimming","VERB + GALA have, hold | attend, go to","GALA + NOUN concert, day, dinner, evening, event, night, occasion, performance, weekend"]},"media":{"uk":"media/ldoce/hwd/bre/d/gala0205.mp3","us":"media/ldoce/hwd/ame/9/gala.mp3"},"examples":[{"en":"a gala dinner/night","cn":"盛宴；晚会"},{"en":"a charity gala","cn":"慈善义演"}],"oxford":{"phon":"ˈɡɑːlə","pos":"noun","senses":[{"en":"a special public celebration or entertainment","cn":"庆典；盛会；演出","ex":{"en":"a charity gala","cn":"慈善义演"}},{"en":"a sports competition, especially in swimming","cn":"体育运动会，体育竞赛（尤指游泳）","lab":"British English","ex":{"en":"a swimming gala","cn":"游泳比赛"}}]}},"gunshot":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（射出的）枪弹","en":"Gunshot is used to refer to bullets that are fired from a gun.","ex":{"en":"They had died of gunshot wounds.","cn":"他们死于枪伤。"}},{"pos":"N-COUNT 可数名词","cn":"枪炮射击；枪炮声","en":"A gunshot is the firing of a gun or the sound of a gun being fired.","ex":{"en":"They heard thousands of gunshots","cn":"他们听到密集的枪炮声。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the noise made by a gun when it is fired","cn":""},{"en":"the sound made by several guns being fired, especially in a war","cn":""},{"en":"the action of shooting a gun, or the sound that this makes","cn":"枪炮射击﹔枪炮声"}]},"collocations":{"phrases":["VERB + GUNSHOT hear We heard gunshots round about midnight.","GUNSHOT + NOUN wound He died of gunshot wounds to the chest.","PHRASES the noise/sound of a gunshot"]},"media":{"uk":"media/ldoce/hwd/bre/4/gunshot0205.mp3","us":"media/ldoce/hwd/ame/9/gunshot.mp3"},"examples":[{"en":"I heard the sound of gunshots out in the street.","cn":"我听到外面街上有枪炮声。"},{"en":"He was out of/within gunshot.","cn":"他在射程之外/内。"}],"oxford":{"phon":"ˈɡʌnʃɒt","pos":"noun","senses":[{"en":"the bullets that are fired from a gun","cn":"（射出的）炮弹，枪弹","g":"[uncountable]","ex":{"en":"He died of a single gunshot wound to the chest.","cn":"他死于胸部仅有的一处枪伤。"}},{"en":"the firing of a gun; the sound of it being fired","cn":"枪炮射击；枪炮声","g":"[countable]","ex":{"en":"I heard the sound of gunshots out in the street.","cn":"我听到外面街上有枪炮声。"}},{"en":"the distance that a bullet from a gun can travel","cn":"（枪炮的）射程","g":"[uncountable]","lab":"old-fashioned","ex":{"en":"He was out of gunshot.","cn":"他在射程之外。"}}]}},"gurgle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"潺潺地流；汩汩地流","en":"If water is gurgling, it is making the sound that it makes when it flows quickly and unevenly through a narrow space.","ex":{"en":"...a narrow stone-edged channel along which water gurgles unseen.","cn":"暗流潺潺的石砌狭窄水道"}},{"pos":"VERB 动词","cn":"（尤指婴儿）发咯咯声","en":"If someone, especially a baby, is gurgling, they are making a sound in their throat similar to the gurgling of water.","ex":{"en":"Henry gurgles happily in his baby chair.","cn":"亨利在婴儿椅里开心地咯咯笑。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"the sound that a liquid makes when it falls from a height, hits something hard, or is moved rapidly around","cn":""},{"en":"to make a sound like someone walking in soft, wet mud, or to move somewhere making this sound","cn":""},{"en":"if something such as a stream gurgles , it makes a low irregular sound like water flowing through a pipe","cn":""}]},"collocations":{"phrases":["ADJ. little | low","VERB + GURGLE give, let out | hear","PREP. with a ~ The water emptied with a gurgle. | ~ of He gave a low gurgle of laughter. • Note at SOUND"]},"media":{"uk":"media/ldoce/hwd/bre/5/gurgle_v0205.mp3","us":"media/ldoce/hwd/ame/b/gurgle1.mp3"},"examples":[{"en":"Water gurgled through the pipes.","cn":"水汩汩地从管道中流过。"},{"en":"a gurgling stream","cn":"潺潺溪流"}],"oxford":{"phon":"ˈɡɜːɡl","pos":"verb","senses":[{"en":"to make a sound like water flowing quickly through a narrow space","cn":"发汩汩声；发潺潺流水声","g":"[intransitive]","ex":{"en":"Water gurgled through the pipes.","cn":"水汩汩地从管道中流过。"}},{"en":"if a baby gurgles, it makes a noise in its throat when it is happy","cn":"（婴儿高兴时）发出咯咯声","g":"[intransitive]","ex":{"en":"The baby gurgled happily.","cn":"婴儿高兴地咯咯做声。"}},{"en":"a sound like water flowing quickly through a narrow space","cn":"汩汩声；潺潺声","ex":{"en":"The water emptied with a gurgle.","cn":"水汩汩地流光了。"},"pos":"noun"},{"en":"the sound that babies make in the throat, especially when they are happy","cn":"（婴儿高兴时发出的）咯咯声","ex":{"en":"The baby gave a little gurgle of laughter.","cn":"婴儿发出咯咯的笑声。"},"pos":"noun"}]}},"groomed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"打扮得（干净利落或邋遢）的","en":"You use groomed in expressions such as well groomed and badly groomed to say how neat, clean, and smart a person is.","ex":{"en":"...a very well groomed man","cn":"衣着整洁得体的男子"}}]},"collocations":{"phrases":["VERBS be, look She is always perfectly groomed.","ADV. well | immaculately, impeccably, meticulously, perfectly | beautifully | sleekly, smoothly"]},"examples":[{"en":"She is always perfectly groomed.","cn":"她总是打扮得干净利落。"}],"oxford":{"phon":"ɡruːmd","pos":"adjective","senses":[{"en":"used to describe the way in which a person cares for their clothes and hair","cn":"（描述穿着打扮情况）","ex":{"en":"She is always perfectly groomed.","cn":"她总是打扮得干净利落。"}}]},"base":"groom"},"grounding":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"基础训练；基础知识；基础","en":"If you have a grounding in a subject, you know the basic facts or principles of that subject, especially as a result of a particular course of training or instruction.","ex":{"en":"The degree provides a thorough grounding in both mathematics and statistics.","cn":"该学位课程将为数学和统计学打下扎实的基础。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a training in the basic parts of a subject or skill","cn":"基础训练"},{"en":"a punishment for a child’s bad behaviour in which they are not allowed to go out with their friends for a period of time","cn":"禁足〔罚小孩一段时间内不准与朋友出门〕"},{"en":"the process of officially stopping an aircraft from flying, especially because it is not safe to fly","cn":"飞机停飞"}]},"collocations":{"phrases":["ADJ. good, solid, thorough | basic","VERB + GROUNDING have All applicants for the job should have a basic grounding in computer skills. | get | give (sb), provide (sb with) The ","PREP. ~ in to get a good grounding in science"]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdegrounding.mp3","us":"media/ldoce/hwd/ame/8/grounding.mp3"},"examples":[{"en":"a good grounding in grammar","cn":"扎实的语法基本功训练"},{"en":"A basic grounding in math is essential for the economics course.","cn":"对经济学这门课程来说﹐基本的数学功底是必不可少的。"}],"oxford":{"phon":"ˈɡraʊndɪŋ","pos":"noun","senses":[{"en":"the teaching of the basic parts of a subject","cn":"基础训练；基础教学","g":"[singular]","ex":{"en":"He has a good grounding in grammar.","cn":"他有良好的语法基础。"}},{"en":"the act of keeping a plane on the ground or a ship in a port, especially because it is not in a good enough condition to travel","cn":"（尤指因机件故障等）（飞机的）留地停飞，（船的）留港停航","g":"[uncountable, countable]"}]},"base":"ground"},"gadget":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小器具；精巧的小玩意","en":"A gadget is a small machine or device which does something useful. You sometimes refer to something as a gadget when you are suggesting that it is complicated and unnecessary.","ex":{"en":"...kitchen gadgets including toasters, kettles and percolators.","cn":"烤面包机、水壶、滴滤式咖啡壶等厨用小家电"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of equipment with moving parts that uses power such as electricity to do a particular job","cn":""},{"en":"a machine or piece of electrical equipment, usually a large one, that people use in the home","cn":""},{"en":"a piece of equipment, usually a small electronic one, that does a special job","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A gadget is a tool or device, especially one that works remarkably well for a specific task. Your dad's favorite kitchen gadget might be his special knife that cuts vegetables into spirals."}]},"collocations":{"phrases":["ADJ. little | clever, neat, nifty | useless | latest, modern, new | electrical, electronic | kitchen","VERB + GADGET invent","PREP. ~ for She has invented a nifty little gadget for undoing stubborn nuts and bolts."]},"media":{"uk":"media/ldoce/hwd/bre/8/gadget0205.mp3","us":"media/ldoce/hwd/ame/d/gadget.mp3"},"examples":[{"en":"a neat gadget for sharpening knives","cn":"精巧的磨刀工具"}],"oxford":{"phon":"ˈɡædʒɪt","pos":"noun","senses":[{"en":"a small tool or device that does something useful","cn":"小器具；小装置","ex":{"en":"We live in a world filled with high-tech gadgets.","cn":"我们生活的世界满是高科技小器具。"}}]}},"good-looking":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"漂亮的；好看的","en":"Someone who is good-looking has an attractive face. →see usage note at:","ex":{"en":"Cassandra noticed him because he was good-looking.","cn":"卡桑德拉注意到他因为他长得帅气。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a beautiful woman or child has perfect good looks","cn":""},{"en":"a good-looking person looks nice. Good-looking is very common in spoken English","cn":""},{"en":"an attractive person looks nice, especially in a way that makes you feel sexually interested in them","cn":""}]},"collocations":{"phrases":["VERBS be","ADV. extraordinarily, extremely, really, strikingly, terribly, very | not exactly, not particularly She was not exactly good-looking, but de"]},"media":{"uk":"media/ldoce/hwd/bre/7/good_looking0205.mp3","us":"media/ldoce/hwd/ame/1/good-looking.mp3"},"examples":[{"en":"She's strikingly good-looking.","cn":"她非常漂亮。"},{"en":"a good-looking man/couple","cn":"俊美的男子；漂亮的一对"}],"oxford":{"phon":"ˌɡʊd ˈlʊkɪŋ","pos":"adjective","senses":[{"en":"physically attractive","cn":"漂亮的；好看的","ex":{"en":"a good-looking man/couple","cn":"俊美的男子；漂亮的一对"}}]}},"graffiti":{"collins":{"senses":[{"pos":"N-UNCOUNT-COLL 不可数集合名词","cn":"（在公共场所的）涂画，涂鸦","en":"Graffiti is words or pictures that are written or drawn in public places, for example on walls or posters.","ex":{"en":"Buildings old and new are thickly covered with graffiti","cn":"新老建筑上都有密密麻麻的涂鸦。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a picture drawn with a pencil, pen, crayon etc","cn":""},{"en":"a drawing that is done quickly and has few details","cn":""},{"en":"a shape or pattern that you draw when you are bored or thinking about other things","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Graffiti is a word, phrase, or image painted or drawn somewhere in public, like on the side of a building or on the walls in a restroom."}]},"collocations":{"phrases":["ADJ. political, racist","QUANT. piece","VERB + GRAFFITI daub, draw, scrawl, scribble, spray, write Graffiti was scribbled all over the walls. | be covered with, be daubed with, be ","GRAFFITI + NOUN artist a fashionable graffiti artist"]},"media":{"uk":"media/ldoce/hwd/bre/6/graffiti0205.mp3","us":"media/ldoce/hwd/ame/b/graffiti.mp3"},"examples":[{"en":"The subway was covered in graffiti.","cn":"过街地道里涂满了乱七八糟的图画和文字。"},{"en":"The walls are daubed with graffiti.","cn":"墙上满是乱七八糟的涂鸦。"}],"oxford":{"phon":"ɡrəˈfiːti","pos":"noun","senses":[{"en":"drawings or writing on a wall, etc. in a public place","cn":"（公共场所墙上等处的）涂鸦，胡写乱画","ex":{"en":"The subway was covered in graffiti.","cn":"地下通道里到处是涂鸦。"}}]}},"generator":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"发电机","en":"A generator is a machine which produces electricity."},{"pos":"N-COUNT 可数名词","cn":"促使…发生的人（或事物）；产生者","en":"A generator of something is a person, organization, product, or situation which produces it or causes it to happen.","ex":{"en":"The US economy is still an impressive generator of new jobs","cn":"美国经济依然在创造着数量惊人的新就业机会。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a machine that produces electricity","cn":"发电机"},{"en":"a company that produces electricity","cn":"电力公司"},{"en":"something that produces something else","cn":"产生者"}]},"collocations":{"phrases":["ADJ. diesel, gas, petrol, steam, wind | electrical, electricity, power","VERB + GENERATOR drive, power A water turbine drives the generator.","GENERATOR + VERB deliver sth The wind generator delivers 120 watts in a strong breeze."]},"media":{"uk":"media/ldoce/hwd/bre/d/generator0205.mp3","us":"media/ldoce/hwd/ame/2/generator.mp3"},"examples":[{"en":"The museum uses smells and smoke generators to create atmosphere.","cn":"博物馆利用气味和烟雾生成器制造气氛。"},{"en":"The factory's emergency generators were used during the power cut.","cn":"工厂应急发电机在停电期间用上了。"}],"oxford":{"phon":"ˈdʒenəreɪtə(r)","pos":"noun","senses":[{"en":"a machine for producing electricity","cn":"发电机","ex":{"en":"The factory's emergency generators were used during the power cut.","cn":"工厂应急发电机在停电期间用上了。"}},{"en":"a machine for producing a particular substance","cn":"发生器","ex":{"en":"The museum uses smells and smoke generators to create atmosphere.","cn":"博物馆利用气味和烟雾发生器制造气氛。"}},{"en":"a person or thing that creates something","cn":"生成者；创造者","ex":{"en":"The company is a major generator of jobs.","cn":"这家公司创造了相当多的就业机会。"}},{"en":"a company that produces electricity to sell to the public","cn":"电力公司","lab":"British English","ex":{"en":"the UK’s major electricity generator","cn":"英国的主要电力公司"}}]}},"greed":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"贪婪；贪心；贪欲","en":"Greed is the desire to have more of something, such as food or money, than is necessary or fair.","ex":{"en":"...an insatiable greed for personal power","cn":"对个人权力的贪得无厌"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is greedy wants more money, possessions, power etc than they need, or wants more than their share","cn":""},{"en":"very greedy so that you are not at all generous and treat other people very badly","cn":""},{"en":"believing that having a lot of money and possessions is the most important thing in life","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Greed is an overwhelming urge to have more of something, usually more than you really need. Watching kids at a birthday party furiously grabbing for candy from a piñata, you might find yourself surprised at their greed ."}]},"collocations":{"phrases":["ADJ. pure, sheer, simple | human, personal","VERB + GREED satisfy She killed him to satisfy her greed. | be consumed by, be driven by","PREP. ~ for He was driven by greed for money and power."]},"media":{"uk":"media/ldoce/hwd/bre/d/greed0205.mp3","us":"media/ldoce/hwd/ame/8/greed.mp3"},"examples":[{"en":"I had another helping of ice cream out of pure greed.","cn":"我纯粹是因为嘴馋贪吃，又吃了一份冰淇淋。"},{"en":"His actions were motivated by greed.","cn":"他的作为是贪婪之心所驱使的。"}],"oxford":{"phon":"ɡriːd","pos":"noun","senses":[{"en":"a strong desire for more wealth, possessions, power, etc. than a person needs","cn":"贪婪；贪心；贪欲","ex":{"en":"His actions were motivated by greed.","cn":"他的所作所为是受贪婪之心所驱使。"}},{"en":"a strong desire for more food or drink when you are no longer hungry or thirsty","cn":"贪食；贪吃","ex":{"en":"I had another helping of ice cream out of pure greed.","cn":"我纯粹是因为嘴馋贪吃，又吃了一份冰激凌。"}}]}},"giddy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"头晕的；眩晕的","en":"If you feel giddy, you feel unsteady and think that you are about to fall over, usually because you are not well.","ex":{"en":"He felt giddy and light-headed.","cn":"他感到头晕目眩。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（高兴或激动得）发狂的，举止反常的","en":"If you feel giddy with delight or excitement, you feel so happy or excited that you find it hard to think or act normally.","ex":{"en":"Anthony was giddy with self-satisfaction","cn":"安东尼自鸣得意，忘乎所以。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"feeling as if everything is spinning around you and unable to balance","cn":""},{"en":"feeling unsteady and unable to balance, sometimes with the result that you want to be sick","cn":""},{"en":"if someone's head is swimming they feel unsteady, unable to see properly, and as though the room is spinning around them very quickly, for example because they are ill or drunk","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you've ever spun in circles until you fell to the ground laughing, you know how it feels to be giddy . This adjective can mean dizzy, elated, or — as in the spinning around example –- a lightheaded, lighthearted combination of the two."}]},"collocations":{"phrases":["VERBS be, feel | become, come over all (informal) , get My mum came over all giddy and had to sit down. | leave sb, make sb Steep stairs may","ADV. quite | a bit, rather, slightly","PREP. from He felt tired and giddy from the sleeping pill. | with I was giddy with the heat."]},"media":{"uk":"media/ldoce/hwd/bre/6/giddy0205.mp3","us":"media/ldoce/hwd/ame/f/giddy.mp3"},"examples":[{"en":"The kids were pushing the roundabout at a giddy speed.","cn":"孩子们推动着旋转平台快得令人眩晕。"},{"en":"When I looked down from the top floor, I felt giddy.","cn":"我从顶楼朝下看时感到头晕目眩。"}],"oxford":{"phon":"ˈɡɪdi","pos":"adjective","senses":[{"en":"feeling that everything is moving and that you are going to fall","cn":"头晕；眩晕","g":"[not usually before noun]","ex":{"en":"When I looked down from the top floor, I felt giddy.","cn":"我从顶楼朝下看时感到头晕目眩。"}},{"en":"so happy and excited that you cannot behave normally","cn":"（高兴或激动得）发狂，举止反常","g":"[not usually before noun]","ex":{"en":"She was giddy with happiness.","cn":"她高兴得忘乎所以。"}},{"en":"making you feel as if you are about to fall","cn":"令人眩晕的；使人头昏眼花的","g":"[usually before noun]","lab":"figurative","ex":{"en":"The kids were pushing the roundabout at a giddy speed.","cn":"孩子们推动着旋转平台快得令人眩晕。"}},{"en":"not serious","cn":"轻率的；轻浮的；不稳重的","lab":"old-fashioned","ex":{"en":"Isabel’s giddy young sister","cn":"伊莎贝尔轻浮的小妹"}}]}},"grenade":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"手榴弹；榴弹","en":"A grenade or a hand grenade is a small bomb that can be thrown by hand.","ex":{"en":"A hand grenade was thrown at an army patrol.","cn":"一枚手榴弹掷向了陆军巡逻队。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a weapon that explodes","cn":""},{"en":"bombs or substances that can cause explosions","cn":""},{"en":"a bomb – used especially in news reports","cn":""}]},"collocations":{"phrases":["ADJ. hand, smoke, stun | rocket-propelled | live","VERB + GRENADE be armed with, carry, have The hijackers were armed with hand grenades. | hold She was holding the grenade above her head, re","GRENADE + VERB fall, land | explode, go off","GRENADE + NOUN attack | launcher"]},"media":{"uk":"media/ldoce/hwd/bre/2/grenade0205.mp3","us":"media/ldoce/hwd/ame/9/grenade.mp3"},"examples":[{"en":"a hand grenade","cn":"手榴弹"}],"oxford":{"phon":"ɡrəˈneɪd","pos":"noun","senses":[{"en":"a small bomb that can be thrown by hand or fired from a gun","cn":"榴弹；手榴弹；枪榴弹","ex":{"en":"His vehicle was damaged by a rocket-propelled grenade.","cn":"他的车毁于火箭榴弹。"}}]}},"grit":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"沙粒；沙砾","en":"Grit is very small pieces of stone. It is often put on roads in winter to make them less slippery.","ex":{"en":"He felt tiny bits of grit and sand peppering his knees.","cn":"他感到细小的沙砾不断打在膝盖上。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"勇气；坚毅；果敢","en":"If someone has grit, they have the determination and courage to continue doing something even though it is very difficult.","ex":{"en":"You've got to admire her grit.","cn":"你不得不佩服她的勇气。"}},{"pos":"N-PLURAL 复数名词","cn":"粗玉米粉，玉米渣（美国南部常食用）","en":"Grits are coarsely ground grains of corn which are cooked and eaten for breakfast or as part of a meal in the southern United States."},{"pos":"VERB 动词","cn":"（通常指因愤怒而）咬紧牙关，咬牙切齿","en":"If you grit your teeth, you press your upper and lower teeth tightly together, usually because you are angry about something.","ex":{"en":"Gritting my teeth, I did my best to stifle one or two remarks","cn":"我咬紧牙关，硬是吞回了几句话。"}},{"pos":"PHRASE 短语","cn":"下定决心；鼓起勇气","en":"If you grit your teeth, you make up your mind to carry on even if the situation is very difficult.","ex":{"en":"There is going to be hardship, but we have to grit our teeth and get on with it.","cn":"未来会很艰难，但是我们必须咬牙坚持下去。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"very small pieces of stone or sand","cn":"沙砾﹔沙粒"},{"en":"determination and courage","cn":"坚毅﹐勇气"},{"en":"a type of grain that is roughly crushed and cooked, and often eaten for breakfast","cn":"粗磨的谷物〔常于早餐食用〕"}]},"vocab":{"pos":"1 n v 2 v n","senses":[{"en":"Grit is a coarse, gravelly dust. If you don't rinse dried beans before you cook them, you may end up crunching grit between your teeth."}]},"collocations":{"phrases":["QUANT. bit, piece A bit of grit had got into my eye. 2 courage/determination","ADJ. sheer, true","VERB + GRIT have Don't give in yet. You have more grit than that. | display, show The team showed their true grit and played a magnificent g"]},"media":{"uk":"media/ldoce/hwd/bre/f/grit_v0205.mp3","us":"media/ldoce/hwd/ame/9/grit1.mp3"},"examples":[{"en":"It started to rain harder, but we gritted our teeth and carried on.","cn":"雨开始大起来，可我们鼓起勇气继续下去。"},{"en":"They were spreading grit and salt on the icy roads.","cn":"他们在结冰的路上撒沙子和盐。"}],"oxford":{"phon":"ɡrɪt","pos":"noun","senses":[{"en":"very small pieces of stone or sand","cn":"沙粒；沙砾；细沙","ex":{"en":"I had a piece of grit in my eye.","cn":"我眼睛里进了一粒沙子。"}},{"en":"the courage and strength of mind that makes it possible for somebody to continue doing something difficult or unpleasant","cn":"勇气；毅力","ex":{"en":"It takes sheer grit to stand up to a bully like that.","cn":"挺身而出对抗那样一个恃强凌弱者需要极大的勇气。"}},{"en":"to spread grit, salt or sand on a road that is covered with ice","cn":"（在结冰的路上）撒沙砾，撒盐，撒沙子","pos":"verb"}]}},"groan":{"collins":{"senses":[{"pos":"VERB 动词","cn":"呻吟；叹息","en":"If you groan, you make a long, low sound because you are in pain, or because you are upset or unhappy about something.","ex":{"en":"Slowly, he opened his eyes. As he did so, he began to groan with pain","cn":"他慢慢地睁开眼睛，并发出痛苦的呻吟。"}},{"pos":"VERB 动词","cn":"不高兴地低声说；咕哝","en":"If you groan something, you say it in a low, unhappy voice.","ex":{"en":"'My leg — I think it's broken,' Eric groaned.","cn":"“我的腿——我想是断了，”埃里克咕哝着说。"}},{"pos":"VERB 动词","cn":"抱怨；发牢骚","en":"If you groan about something, you complain about it.","ex":{"en":"His parents were beginning to groan about the price of college tuition.","cn":"他的父母开始抱怨大学的学费太贵。"}},{"pos":"VERB 动词","cn":"（树木等）发出嘎吱声","en":"If wood or something made of wood groans, it makes a loud sound when it moves.","ex":{"en":"The timbers groan and creak and the floorboards shift.","cn":"这些木头在吱吱嘎嘎作响，木地板有些摇晃。"}},{"pos":"VERB 动词","cn":"堆满，摆满，装满（食物）","en":"If you say that something such as a table groans under the weight of food, you are emphasizing that there is a lot of food on it.","ex":{"en":"The bar counter groans under the weight of huge plates of the freshest fish.","cn":"吧台上摆满了大碟大碟非常新鲜的鱼。"}},{"pos":"VERB 动词","cn":"受…重压；受…折磨；不堪重负","en":"If you say that someone or something is groaning under the weight of something, you think there is too much of that thing.","ex":{"en":"Consumers were groaning under the weight of high interest rates","cn":"高利率令消费者不堪重负。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make a long deep sound because you are in pain, upset, or disappointed, or because something is very enjoyable 〔","cn":"因疼痛﹑心烦或失望而〕呻吟﹔〔因快乐而〕哼哼"},{"en":"to complain about something","cn":"抱怨﹐发牢骚"},{"en":"to make a low deep sound","cn":"发出低沉的声音"}]},"vocab":{"pos":"n v","senses":[{"en":"A groan is a sound of pain or disapproval that doesn't consist of words, usually heard after homework is assigned or bad jokes are told."}]},"collocations":{"phrases":["ADJ. loud He let out a loud groan of frustration. | little, small | deep, low | harsh, hoarse | muffled","VERB + GROAN give, let out, utter | stifle, suppress | hear","PREP. with a ~ He stood up slowly with a groan of pain. | ~ of • Note at SOUND"]},"media":{"uk":"media/ldoce/hwd/bre/b/groan_v0205.mp3","us":"media/ldoce/hwd/ame/b/groan1.mp3"},"examples":[{"en":"We all groaned at his terrible jokes.","cn":"他讲的笑话很糟糕，我们都发出不满的抱怨声。"},{"en":"The house was filled with the cello's dismal squeaks and groans.","cn":"房子里回荡着大提琴低沉而凄厉的声音。"}],"oxford":{"phon":"ɡrəʊn","pos":"verb","senses":[{"en":"to make a long deep sound because you are annoyed, upset or in pain, or with pleasure","cn":"呻吟；叹息；哼哼","g":"[intransitive, transitive]","ex":{"en":"He lay on the floor groaning.","cn":"他躺在地板上呻吟。"}},{"en":"to complain about something, especially in an annoying way","cn":"抱怨；发牢骚","g":"[intransitive, transitive]","ex":{"en":"They were all moaning and groaning about the amount of work they had.","cn":"他们都对工作量太大怨声载道。"}},{"en":"to make a sound like a person groaning","cn":"发出似呻吟的声音","g":"[intransitive]","ex":{"en":"The trees creaked and groaned in the wind.","cn":"树在风中嘎吱作响。"}},{"en":"a long deep sound made when somebody/something groans","cn":"呻吟声；叹息声；哼哼声；嘎吱声","ex":{"en":"She let out a groan of dismay.","cn":"她发出沮丧的叹息声。"},"pos":"noun"},{"en":"a complaint","cn":"怨言；牢骚","ex":{"en":"I don't have time to listen to your moans and groans.","cn":"我没时间听你唧唧歪歪发牢骚。"},"pos":"noun"}]}},"genetics":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"遗传学","en":"Genetics is the study of heredity and how qualities and characteristics are passed on from one generation to another by means of genes."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the study of how the qualities of living things are passed on in their gene s","cn":"遗传学"}]},"vocab":{"pos":"n","senses":[{"en":"Genetics is the study of the traits people and other animals inherit from their family through DNA."}]},"collocations":{"phrases":["ADJ. evolutionary | molecular | medical | human, plant | population | Mendelian","PHRASES the science of genetics • Note at SUBJECT (for verbs and nouns)"]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdegenetics.mp3","us":"media/ldoce/hwd/ame/3/genetics.mp3"},"oxford":{"phon":"dʒəˈnetɪks","pos":"noun","senses":[{"en":"the scientific study of the ways in which different characteristics are passed from each generation of living things to the next","cn":"遗传学"}]}},"garlic":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"蒜；大蒜","en":"Garlic is the small, white, round bulb of a plant that is related to the onion plant. Garlic has a very strong smell and taste and is used in cooking.","ex":{"en":"...a clove of garlic.","cn":"一瓣蒜"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a plant like a small onion, used in cooking to give a strong taste （","cn":"大）蒜"}]},"collocations":{"phrases":["ADJ. wild","QUANT. clove","VERB + GARLIC peel | chop, crush","GARLIC + NOUN clove | bread | sausage •"]},"media":{"img":["media/ldoce/img/garlic.jpg","media/thumb/garlic.jpg"],"uk":"media/ldoce/hwd/bre/4/garlic0205.mp3","us":"media/ldoce/hwd/ame/4/garlic.mp3"},"examples":[{"en":"a clove of garlic (= one section of it)","cn":"一瓣蒜"},{"en":"garlicky breath/food","cn":"带大蒜味的气息；加有大蒜的食物"}],"oxford":{"phon":"ˈɡɑːlɪk","pos":"noun","senses":[{"en":"a vegetable of the onion family with a very strong taste and smell, used in cooking to add taste to food","cn":"蒜；大蒜","ex":{"en":"a clove of garlic (= one section of it)","cn":"一瓣蒜"}}]}},"grudge":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"不满；积怨；怨恨","en":"If you have or bear a grudge against someone, you have unfriendly feelings towards them because of something they did in the past.","ex":{"en":"He appears to have a grudge against certain players","cn":"他看来对某些选手怀恨在心。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to refuse to forgive someone, because they have done something very bad","cn":""},{"en":"to continue to feel angry with someone for a long time because they treated you badly in the past","cn":""},{"en":"to dislike someone because of something they did in the past, even though it is no longer important","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"If you tend to hold a grudge , you don't let it go when you feel someone's insulted or wronged you. I hope you won't hold a grudge against me for bringing it up."}]},"collocations":{"phrases":["ADJ. long-standing, old It's time to forget old grudges. | personal","VERB + GRUDGE bear, harbour, have, hold, nurse I don't hold grudges for very long.","PREP. ~ against Do you know anyone who might harbour a grudge against you?"]},"media":{"uk":"media/ldoce/hwd/bre/7/grudge_n0205.mp3","us":"media/ldoce/hwd/ame/c/grudge1.mp3"},"examples":[{"en":"England beat New Zealand in a grudge match (= a match where there is strong dislike between the teams).","cn":"英格兰队在一场势不两立的比赛中打败了新西兰队。"},{"en":"He grudges the time he spends travelling to work.","cn":"他不情愿上班花这么多时间在路上。"}],"oxford":{"phon":"ɡrʌdʒ","pos":"noun","senses":[{"en":"a feeling of anger or dislike towards somebody because of something bad they have done to you in the past","cn":"积怨；怨恨；嫌隙","ex":{"en":"I bear him no grudge.","cn":"我对他不怀任何积怨。"}},{"en":"to do or give something unwillingly","cn":"勉强做；不情愿地给；吝惜","ex":{"en":"I grudge having to pay so much tax.","cn":"得付这么多的税，我很不情愿。"},"pos":"verb"},{"en":"to think that somebody does not deserve to have something","cn":"认为…不应得到","ex":{"en":"You surely don't grudge her her success?","cn":"她获得成功，你没有不以为然吧？"},"pos":"verb"}]}},"gown":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"女裙；女礼服；女长服","en":"A gown is a dress, usually a long dress, which women wear on formal occasions.","ex":{"en":"The new ball gown was a great success.","cn":"这种新款舞会礼服很畅销。"}},{"pos":"N-COUNT 可数名词","cn":"（律师、学者等在正式场合穿的）礼袍,长袍","en":"A gown is a loose black garment worn on formal occasions by people such as lawyers and academics.","ex":{"en":"...an old headmaster in a flowing black gown.","cn":"身着宽松黑礼袍的老校长"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long dress that a woman wears on formal occasions","cn":"女礼服"},{"en":"a long loose piece of clothing worn for special ceremonies by judges, teachers, lawyers, and members of universities 〔","cn":"法官﹑教师﹑律师﹑大学成员在特殊仪式上穿的〕长袍"},{"en":"a long loose piece of clothing worn in a hospital by someone doing or having an operation","cn":"外科手术服"}]},"collocations":{"phrases":["ADJ. long | flowing She was dressed in a long flowing gown. | ball, bridal, evening, wedding","GOWN + VERB be trimmed with sth She wore a white satin gown trimmed with lace.","PREP. in a/the ~ 2 worn by judges, surgeons, etc.","ADJ. academic | hospital, surgical","PREP. in a/the ~","PHRASES town and gown (= the permanent members of a university town and the members of its university) •"]},"media":{"uk":"media/ldoce/hwd/bre/8/gown0205.mp3","us":"media/ldoce/hwd/ame/3/gown.mp3"},"examples":[{"en":"an evening/wedding gown","cn":"女晚礼服；新娘的结婚礼服"},{"en":"a surgeon's gown","cn":"外科医生穿的罩衣"}],"oxford":{"phon":"ɡaʊn","pos":"noun","senses":[{"en":"a woman’s dress, especially a long one for special occasions","cn":"（尤指特别场合穿的）女裙，女长服，女礼服","ex":{"en":"an evening/a wedding gown","cn":"晚礼服；婚纱"}},{"en":"a long loose piece of clothing that is worn over other clothes by judges and (in the UK) by other lawyers, and by members of universities (at special ceremonies)","cn":"（法官、英国律师、大学师生在特别仪式上穿的）长袍","ex":{"en":"a graduation gown","cn":"毕业礼服"}},{"en":"a piece of clothing worn in a hospital, either by medical staff during surgery or by a patient, especially as protection against infection","cn":"（医护人员或患者穿的，尤指用于感染防护的）罩衣，防护服","ex":{"en":"a surgeon’s gown","cn":"外科手术服"}}]}},"goalkeeper":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"守门员","en":"A goalkeeper is the player in a sports team whose job is to guard the goal."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the player in a sports team whose job is to try to stop the ball going into the goal","cn":"守门员"}]},"collocations":{"phrases":["ADJ. brilliant, excellent, good | England, Liverpool, etc. The England goalkeeper played brilliantly. | international | reserve, substitute ","PREP. ~ for He now plays as goalkeeper for Liverpool."]},"media":{"uk":"media/ldoce/hwd/bre/a/goalkeeper_las2_br.mp3","us":"media/ldoce/hwd/ame/c/goalkeeper.mp3"},"examples":[{"en":"goalkeeping techniques","cn":"守门的技巧"}],"oxford":{"phon":"ˈɡəʊlkiːpə(r)","pos":"noun","senses":[{"en":"a player whose job is to stop the ball from going into his or her own team’s goal","cn":"守门员","ex":{"en":"He now plays as goalkeeper for Liverpool.","cn":"目前他在利物浦队担任守门员。"}}]}},"garment":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（一件）衣服（尤用于谈及服装的制作和销售时）","en":"A garment is a piece of clothing; used especially in contexts where you are talking about the manufacture or sale of clothes. →see usage note at:","ex":{"en":"Many of the garments have the customers' name tags sewn into the linings.","cn":"这些衣服有很多内衬上缝有顾客的姓名签。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"things that you wear, for example coats, shirts, and dresses","cn":""},{"en":"clothes in general - use this either to talk about a particular type of clothes, or to talk about a large quantity of clothes","cn":""},{"en":"clothes, especially clothes for a particular event or occasion","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A garment is a piece of clothing. The area of New York City where clothes are manufactured is known as the Garment District."}]},"collocations":{"phrases":["ADJ. heavy | shapeless | knitted, woollen","VERB + GARMENT have on, wear She wore a shapeless knitted garment."]},"media":{"uk":"media/ldoce/hwd/bre/5/garment0205.mp3","us":"media/ldoce/hwd/ame/3/garment.mp3"},"examples":[{"en":"a strange shapeless garment that had once been a jacket","cn":"用夹克衫改成的不成形的一件怪衣服"},{"en":"woollen/winter/outer garments","cn":"毛衣；冬装；外衣"}],"oxford":{"phon":"ˈɡɑːmənt","pos":"noun","senses":[{"en":"a piece of clothing","cn":"（一件）衣服","ex":{"en":"a strange shapeless garment that had once been a jacket","cn":"用夹克衫改成的不成形的一件怪衣服"}}]}},"gamble":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"冒险；投机；赌博","en":"A gamble is a risky action or decision that you take in the hope of gaining money, success, or an advantage over other people.","ex":{"en":"Yesterday, he named his cabinet and took a big gamble in the process.","cn":"昨天他冒了很大的风险任命了内阁成员。"}},{"pos":"VERB 动词","cn":"冒险；碰运气；以…为赌注","en":"If you gamble on something, you take a risky action or decision in the hope of gaining money, success, or an advantage over other people.","ex":{"en":"Few firms will be willing to gamble on new products","cn":"很少有公司愿意冒险开发新产品。"}},{"pos":"VERB 动词","cn":"（在纸牌、赛马等中）赌（钱）；赌博","en":"If you gamble an amount of money, you bet it in a game such as cards or on the result of a race or competition. People who gamble usually do it frequently.","ex":{"en":"Most people visit Las Vegas to gamble their hard-earned money","cn":"大多数人拿着辛苦挣来的钱去拉斯维加斯赌博。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to try to win money, for example by playing cards or guessing which horse will win a race","cn":""},{"en":"to try to win money by guessing who will win a race or game","cn":""},{"en":"to gamble £10, $20 etc on the horse or team that you think will win a race or competition","cn":""}]},"collocations":{"phrases":["ADJ. big, huge, major | calculated | desperate It was time for a last desperate gamble. | political","VERB + GAMBLE take","GAMBLE + VERB pay off, work I took a calculated gamble and it paid off.","PREP. ~ on Backpackers with a heavy load should resist taking a gamble on the weather.","PHRASES a bit/something of a gamble Trying to find the right pension can be a bit of a gamble."]},"media":{"uk":"media/ldoce/hwd/bre/e/gamble_v0205.mp3","us":"media/ldoce/hwd/ame/1/gamble1.mp3"},"examples":[{"en":"They invested money in the company right at the start and the gamble paid off (= brought them success).","cn":"他们一开始就把资金投到这家公司，结果这一冒险获得了成功。"},{"en":"She knew she was taking a gamble but decided it was worth it.","cn":"她知道是在冒险，但她认为冒这个险值得。"}],"oxford":{"phon":"ˈɡæmbl","pos":"verb","senses":[{"en":"to risk money on a card game, horse race, etc.","cn":"（牌戏、赛马等中）赌博，打赌","g":"[intransitive, transitive]","ex":{"en":"to gamble at cards","cn":"赌纸牌"}},{"en":"to risk losing something in the hope of being successful","cn":"冒风险；碰运气；以…为赌注","g":"[transitive, intransitive]","ex":{"en":"He's gambling his reputation on this deal.","cn":"他在以自己的声誉为这笔交易作赌注。"}},{"en":"an action that you take when you know there is a risk but when you hope that the result will be a success","cn":"赌博；打赌；冒险","ex":{"en":"She knew she was taking a gamble but decided it was worth it.","cn":"她知道是在冒险，但她认为冒这个险值得。"},"pos":"noun"}]}},"glitter":{"collins":{"senses":[{"pos":"VERB 动词","cn":"闪烁；闪亮","en":"If something glitters, light comes from or is reflected off different parts of it.","ex":{"en":"The bay glittered in the sunshine","cn":"海湾在阳光下闪闪发光。"}},{"pos":"VERB 动词","cn":"（激动、感兴趣等情感）闪现，流露","en":"If someone's eyes glitter, they are bright and express a particular emotion such as excitement or interest.","ex":{"en":"His eyes glittered with a tense amusement.","cn":"他眼里流露出一丝紧张和愉悦。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（粘在物体上作装饰用的）小发光物","en":"Glitter consists of tiny shining pieces of metal. It is glued to things for decoration.","ex":{"en":"Decorate the tunic with sequins or glitter.","cn":"用些圆形小金属片或发光小亮片装饰这件女式短上衣。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"外在的吸引力；魅力","en":"You can use glitter to refer to superficial attractiveness or to the excitement connected with something.","ex":{"en":"She was blinded by the glitter and the glamour of her own life.","cn":"她被自己的生活中表面上的光鲜与奢华所蒙蔽。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something sparkles, it shines with many small bright points when light is on it","cn":""},{"en":"to shine by reflecting the light – used especially about smooth clean surfaces, or about someone’s eyes or teeth","cn":""},{"en":"to shine with quick flashes of light","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A glitter is a sparkle or flash of light. To glitter is to gleam or shine, as if glistening with moisture."}]},"collocations":{"phrases":["ADV. brightly Crystal chandeliers glittered brightly above them.","PREP. in His metal buttons glittered in the sunlight. | with Trees and grass glittered with dew. 2 show emotion","ADV. coldly, dangerously, darkly, fiercely, strangely His deep-set eyes glittered coldly.","PREP. with Her eyes glittered with delight."]},"media":{"uk":"media/ldoce/hwd/bre/f/glitter_n0205.mp3","us":"media/ldoce/hwd/ame/7/glitter1.mp3"},"examples":[{"en":"His eyes glittered with greed.","cn":"他眼睛里闪现出贪婪的神色。"},{"en":"There was a triumphant glitter in his eyes.","cn":"他眼睛里闪烁着胜利的光辉。"}],"oxford":{"phon":"ˈɡlɪtə(r)","pos":"verb","senses":[{"en":"to shine brightly with little flashes of light, like a diamond","cn":"闪亮；闪耀；光彩夺目","g":"[intransitive]","ex":{"en":"The ceiling of the cathedral glittered with gold.","cn":"大教堂的天花板金光闪闪。"}},{"en":"to shine brightly with a particular emotion, usually a strong one","cn":"闪现（某种强烈情感）","g":"[intransitive]","ex":{"en":"His eyes glittered with greed.","cn":"他眼睛里闪现出贪婪的神色。"}},{"en":"bright light consisting of many little flashes","cn":"灿烂的光辉；闪烁；闪耀","g":"[uncountable]","ex":{"en":"the glitter of diamonds","cn":"钻石的光彩"},"pos":"noun"},{"en":"a bright expression in somebody’s eyes showing a particular emotion","cn":"（眼睛里某种感情的）闪现，流露","g":"[singular]","ex":{"en":"There was a triumphant glitter in his eyes.","cn":"他眼睛里闪烁着胜利的光辉。"},"pos":"noun"},{"en":"the attractive, exciting qualities that somebody/something, especially a rich and famous person or place, seems to have","cn":"吸引力；魅力；诱惑力","g":"[uncountable]","ex":{"en":"the superficial glitter of show business","cn":"演艺业表面上的光彩迷人"},"pos":"noun"},{"en":"very small shiny pieces of thin metal or paper that are stuck to things as a decoration","cn":"（装饰用的）小发光物","g":"[uncountable]","ex":{"en":"gold/silver glitter","cn":"金色的／银色的闪光装饰物"},"pos":"noun"}]}},"gruesome":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人厌恶的；恐怖的；令人震惊的","en":"Something that is gruesome is extremely unpleasant and shocking.","ex":{"en":"There has been a series of gruesome murders in the capital.","cn":"在首都发生了一连串让人毛骨悚然的谋杀案。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very unpleasant or shocking, and involving someone being killed or badly injured","cn":"令人毛骨悚然的﹐可怕的〔涉及有人被杀或受重伤〕"}]},"vocab":{"pos":"adj","senses":[{"en":"Gothic novels, horror movies, and crime dramas don't shy away from showing gruesome scenes of death, pictures that inspire fright and repulsion. Synonyms include \"ghastly,\" \"grisly,\" \"loathsome,\" and \"macabre.\""}]},"collocations":{"phrases":["VERBS be","ADV. horribly, particularly, truly | pretty, rather a rather gruesome sight"]},"media":{"uk":"media/ldoce/hwd/bre/b/gruesome0205.mp3","us":"media/ldoce/hwd/ame/a/gruesome.mp3"},"examples":[{"en":"( humorous ) We spent a week in a gruesome apartment in Miami.","cn":"我们在迈阿密一套糟糕透顶的公寓里住了一星期。"},{"en":"We spent a week in a gruesome apartment in Miami.","cn":""}],"oxford":{"phon":"ˈɡruːsəm","pos":"adjective","senses":[{"en":"very unpleasant and filling you with horror, usually because it is connected with death or injury","cn":"令人厌恶的；恐怖的；可怕的","lab":"humorous","ex":{"en":"a gruesome murder","cn":"骇人听闻的谋杀案"}}]}},"grill":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（烤炉内的）烤架","en":"A grill is a part of a stove which produces strong heat to cook food that has been placed underneath it.","ex":{"en":"Place the omelette under a gentle grill until the top is set.","cn":"将煎蛋饼放在烤架下用文火烘烤，直到表面凝固。"}},{"pos":"N-COUNT 可数名词","cn":"（置于火上的）烤架","en":"A grill is a flat frame of metal bars on which food can be cooked over a fire."},{"pos":"V-ERG 及物/不及物动词","cn":"烧烤；烤炙","en":"When you grill food, or when it grills, you cook it using very strong heat directly above or below it.","ex":{"en":"Grill the meat for 20 minutes each side","cn":"将肉的每一面各烤20分钟。"}},{"pos":"VERB 动词","cn":"追问；盘问；审问","en":"If you grill someone about something, you ask them a lot of questions for a long period of time.","ex":{"en":"Grill your travel agent about the facilities for families with children","cn":"请仔细询问旅行代办人会为带孩子的家庭提供何种设施。"}},{"pos":"N-COUNT 可数名词","cn":"烤肉餐馆；烤肉店","en":"A grill is a restaurant that serves grilled food."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to cook things such as bread or cakes in an oven","cn":""},{"en":"to cook meat or vegetables in an oven","cn":""},{"en":"to cook food in hot oil","cn":""}]},"vocab":{"pos":"1 v n 2 v","senses":[{"en":"Not all grilling involves fire and delicious food. Sometimes, to grill means to ask a person really intense questions, like when you suspect them of doing something wrong and you want to make them confess the truth."}]},"collocations":{"phrases":["ADJ. hot Cook under a hot grill for 7 minutes. | eye-level | electric, gas","VERB + GRILL preheat Preheat the grill to medium.","GRILL + NOUN pan","PREP. under a/the ~ Place the chops in the grill pan, and put it under the grill. 2 framework of metal bars that you cook food on","ADJ. charcoal","PREP. on a/the ~ Once the charcoal is glowing, place the food on the grill, turning it regularly."]},"media":{"uk":"media/ldoce/hwd/bre/2/grill_v0205.mp3","us":"media/ldoce/hwd/ame/c/grill1.mp3"},"examples":[{"en":"They grilled her about where she had been all night.","cn":"他们盘问她整个夜晚待在什么地方。"},{"en":"Grill the sausages for ten minutes.","cn":"把香肠烤十分钟。"}],"oxford":{"phon":"ɡrɪl","pos":"noun","senses":[{"en":"the part of a cooker that directs heat downwards to cook food that is placed under it","cn":"（炊具、烤炉内的）烘烤器","lab":"British English","ex":{"en":"Put it under a hot grill to brown for two minutes.","cn":"将其放在热烤架下烤两分钟至棕色。"}},{"en":"a flat metal frame that you put food on to cook over a fire","cn":"（置于火上的）烤架","ex":{"en":"Once the charcoal is glowing, place the food on the grill, turning it regularly.","cn":"木炭发红后，将食物放到烧烤架上，并不时翻转。"}},{"en":"a dish of grilled food, especially meat","cn":"一盘烧烤食物（尤指烤肉）"},{"en":"a restaurant serving grilled food","cn":"烤肉餐馆；烧烤店","ex":{"en":"Harry’s Bar and Grill","cn":"哈里烤肉酒吧"}},{"en":"a screen made of metal bars or wire that is placed in front of a window, door or machine in order to protect it","cn":"（置于窗、门、机器前面的）铁栅栏，金属网罩"},{"en":"to cook food under a very strong heat","cn":"（在高温下方）烧烤，炙烤","lab":"British English","ex":{"en":"Grill the sausages for ten minutes.","cn":"把香肠烤十分钟。"},"pos":"verb"},{"en":"to cook food over a fire, especially outdoors","cn":"（在火上，尤指户外）烧，烤，焙","ex":{"en":"grilled meat and shrimp","cn":"烤肉和烤虾"},"pos":"verb"},{"en":"to ask somebody a lot of questions about their ideas, actions, etc., often in an unpleasant way","cn":"盘问；追问；审问；责问","ex":{"en":"They grilled her about where she had been all night.","cn":"他们盘问她整个晚上去哪里了。"},"pos":"verb"}]}},"grandson":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（外）孙子;（外）孙女","en":"Someone's grandson is the son of their son or daughter.","ex":{"en":"My grandson's birthday was on Tuesday.","cn":"星期二是我孙子的生日。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the son of your son or daughter","cn":"孙子﹔外孙"}]},"media":{"uk":"media/ldoce/hwd/bre/9/grandson0205.mp3","us":"media/ldoce/hwd/ame/6/grandson.mp3"},"oxford":{"phon":"ˈɡrænsʌn","pos":"noun","senses":[{"en":"a son of your son or daughter","cn":"孙子；外孙"}]}}});
